INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11049, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "习惯性", "is_correct": true, "explanation": "正确。“习惯性迟到”指长期重复形成的迟到倾向，与“普遍抵触”和“推行严格打卡制度”的背景相符。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”指偶尔发生，与“推行严格打卡制度”所针对的普遍、长期迟到矛盾。"}, {"text": "突发性", "is_correct": false, "explanation": "搭配：“突发性”多修饰突然发生的事件，一般不说“突发性迟到”这种长期问题。"}, {"text": "一次性", "is_correct": false, "explanation": "语义：“一次性”指只发生一次，无法支撑为此推行严格打卡制度这一长期措施。"}], "explanations": {"习惯性": "正确。“习惯性迟到”指长期重复形成的迟到倾向，与“普遍抵触”和“推行严格打卡制度”的背景相符。", "偶然": "语义：“偶然”指偶尔发生，与“推行严格打卡制度”所针对的普遍、长期迟到矛盾。", "突发性": "搭配：“突发性”多修饰突然发生的事件，一般不说“突发性迟到”这种长期问题。", "一次性": "语义：“一次性”指只发生一次，无法支撑为此推行严格打卡制度这一长期措施。"}, "sentence_index": 0, "correct_answer": "习惯性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他习惯性迟到了一次。", "explanation": "这里应该用〈偶然〉。习惯性指长期重复形成的行为，不能描述只发生过一次的事。"}, {"text": "这是习惯性的纸杯。", "explanation": "这里应该用〈一次性〉。习惯性形容人的行为或倾向，不修饰纸杯这类物品。"}, {"text": "他习惯性地在地震中幸存下来。", "explanation": "这里应该用〈侥幸〉。习惯性指长期重复形成的行为，不能描述一次偶然的脱险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11049, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "习惯性", "is_correct": true, "explanation": "正确。“习惯性地说“不””表示孩子反复这样做，与“妈妈很头疼”相符。"}, {"text": "香甜", "is_correct": false, "explanation": "搭配：“香甜”形容睡觉或味道，不能修饰说话的样子，句子不成立。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能修饰说话的样子。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”多形容外貌或做事出色，不说“漂亮地说“不””。"}], "explanations": {"习惯性": "正确。“习惯性地说“不””表示孩子反复这样做，与“妈妈很头疼”相符。", "香甜": "搭配：“香甜”形容睡觉或味道，不能修饰说话的样子，句子不成立。", "高大": "体貌：“高大”形容身材，不能修饰说话的样子。", "漂亮": "搭配：“漂亮”多形容外貌或做事出色，不说“漂亮地说“不””。"}, "sentence_index": 6, "correct_answer": "习惯性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他习惯性地收到了录取通知书，非常惊喜。", "explanation": "这里应该用〈意外〉。习惯性指长期重复、几乎不经意的行为，不能描述一次出乎意料的收获。"}, {"text": "她习惯性地在二十岁那年结了婚。", "explanation": "这里应该用〈恰好〉。习惯性指长期重复形成的行为，不能描述结婚这种一生通常只发生一次的事。"}, {"text": "他习惯性登上珠峰，非常激动。", "explanation": "这里应该用〈首次〉。习惯性表示经常重复，不能描述只发生过一次的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹习惯性的咬铅笔。", "corrected_sentence": "妹妹习惯性地咬铅笔。", "error_description": "错误：“习惯性”作状语修饰动词“咬”时应用“地”，不能用“的”。正确说法：“妹妹习惯性地咬铅笔。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她习惯性的把包放在椅子上。", "corrected_sentence": "她习惯性地把包放在椅子上。", "error_description": "错误：“习惯性”修饰动词“放”，作状语时应用“地”，不能用“的”。正确说法：“她习惯性地把包放在椅子上。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
