INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11051, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指到某个地点或活动场所记录自己的到达，常用于上班、上课或参加活动时。", "primary_collocate": null, "pronunciation": "dǎ kǎ", "ipa": "ta²¹⁴ kʰa²¹⁴", "syllable_count": 2, "sentences": [{"text": "在东南亚某国的合资工厂中，德国管理者因本地员工“习惯性迟到”而推行严格打卡制度，结果引发普遍抵触与士气低落。", "target_word": "打卡", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司要求员工每天上班时打卡。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早上八点到公司，先去打卡。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了打卡，所以老板扣了他的钱。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课前，学生要在教室门口打卡。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加活动的人都要先打卡，再进场。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天系统坏了，大家没办法打卡。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨天下班的时候打卡了吗？", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的工人下班前要打卡，证明自己来过。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天到学校后第一件事就是打卡。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了卡", "label": "体标"}, {"form": "打过卡", "label": "体标"}, {"form": "打卡机", "label": "复合"}], "register": "中性", "sense_fingerprint": "打卡：上班、上课或活动时记录到达", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '620cf61b-9fe1-441f-be7f-b8453433329c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11051, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打卡", "is_correct": true, "explanation": "正确。“严格打卡制度”指规定员工上班时记录到达，与“迟到”的背景相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”与迟到问题无关，句中的制度针对的是准时到岗。"}, {"text": "报销", "is_correct": false, "explanation": "语义：“报销”指报账，与因迟到而推行的管理制度无关。"}, {"text": "辞职", "is_correct": false, "explanation": "搭配：“辞职”是离开工作的动作，一般不修饰“制度”，也与严格管理迟到的语境不合。"}], "explanations": {"打卡": "正确。“严格打卡制度”指规定员工上班时记录到达，与“迟到”的背景相符。", "考试": "语义：“考试”与迟到问题无关，句中的制度针对的是准时到岗。", "报销": "语义：“报销”指报账，与因迟到而推行的管理制度无关。", "辞职": "搭配：“辞职”是离开工作的动作，一般不修饰“制度”，也与严格管理迟到的语境不合。"}, "sentence_index": 0, "correct_answer": "打卡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在合同上打卡，表示同意。", "explanation": "这里应该用〈签名〉。打卡指到达某地时记录，不用于在文件上签字。"}, {"text": "小王在电脑上打卡，把文件发给了老板。", "explanation": "这里应该用〈发送〉。打卡表示到达某地点或活动场所的记录，不能用于发送文件。"}, {"text": "他向老板打卡了今天的工作进度。", "explanation": "这里应该用〈汇报〉。打卡的宾语是地点或活动，不能是工作进度这类内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11051, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打卡", "is_correct": true, "explanation": "正确。“系统坏了，大家没办法打卡”说明无法记录到达，与句意相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“系统坏了”没有关系，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与系统故障无关，句子不成立。"}, {"text": "就寝", "is_correct": false, "explanation": "语域：“就寝”是书面化说法，与口语化的“大家没办法”语气不合。"}], "explanations": {"打卡": "正确。“系统坏了，大家没办法打卡”说明无法记录到达，与句意相符。", "睡觉": "语义：“睡觉”与“系统坏了”没有关系，句意不通。", "游泳": "语义：“游泳”与系统故障无关，句子不成立。", "就寝": "语域：“就寝”是书面化说法，与口语化的“大家没办法”语气不合。"}, "sentence_index": 6, "correct_answer": "打卡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前台让我先打卡身份信息。", "explanation": "这里应该用〈登记〉。打卡只表示到场记录，不能用于登记身份信息。"}, {"text": "快递员让我打卡包裹。", "explanation": "这里应该用〈签收〉。打卡的宾语是地点或活动，不能用于包裹。"}, {"text": "医生给他做了身体打卡。", "explanation": "这里应该用〈检查〉。打卡是到达记录，不能作为体检这类活动的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天对门口打卡。", "corrected_sentence": "我每天在门口打卡。", "error_description": "错误：表示地点的介词应用“在”，不能用“对”。“对门口”不能作打卡的地点状语。正确说法：“我每天在门口打卡。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天下班前了都要打卡。", "corrected_sentence": "他每天下班前都要打卡。", "error_description": "错误：“了”位置不当，不能紧跟时间状语“下班前”。应删去“了”。正确说法：“他每天下班前都要打卡。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
