INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11053, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指与他人或事物发生矛盾、冲突，或内心反对、抗拒。", "primary_collocate": null, "pronunciation": "dǐ chù", "ipa": "ti²¹⁴ tʂʰu⁵¹", "syllable_count": 2, "sentences": [{"text": "在东南亚某国的合资工厂中，德国管理者因本地员工“习惯性迟到”而推行严格打卡制度，结果引发普遍抵触与士气低落。", "target_word": "抵触", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个规定与国家法律抵触，不能使用。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话和事实互相抵触，大家都不信。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "员工抵触这个新制度，没有人愿意用。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人抵触新技术，不肯学用手机。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个条款互相抵触，律师建议修改。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一听到“考试”就很抵触，马上不想说话了。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生抵触老师的做法，所以不想听课。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我并不抵触工作，只是最近太累了。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的新要求和合同内容相抵触，员工不同意。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵触了", "label": "体标"}, {"form": "抵触情绪", "label": "复合"}], "register": "书面", "sense_fingerprint": "抵触：与人或事物矛盾冲突，或内心反对抗拒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '620cf61b-9fe1-441f-be7f-b8453433329c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11053, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抵触", "is_correct": true, "explanation": "抵触（dǐchù）：与他人或事物发生矛盾冲突，或内心反对、抗拒。"}, {"text": "低处", "is_correct": false, "explanation": "低处（dīchù）与抵触只有第一个音节声调不同：低为第一声，抵为第三声，意思是低的地方。"}, {"text": "地处", "is_correct": false, "explanation": "地处（dìchǔ）与抵触的两个音节声调都不同：地为第四声，处为第三声，意思是位于某地。"}, {"text": "递出", "is_correct": false, "explanation": "递出（dìchū）与抵触的两个音节声调都不同：递为第四声，出为第一声，意思是交给别人。"}, {"text": "抵住", "is_correct": false, "explanation": "抵住（dǐzhù）与抵触只有第二个音节的声母不同：zh 与 ch 不同，意思是顶住、挡住。"}], "explanations": {"抵触": "抵触（dǐchù）：与他人或事物发生矛盾冲突，或内心反对、抗拒。", "低处": "低处（dīchù）与抵触只有第一个音节声调不同：低为第一声，抵为第三声，意思是低的地方。", "地处": "地处（dìchǔ）与抵触的两个音节声调都不同：地为第四声，处为第三声，意思是位于某地。", "递出": "递出（dìchū）与抵触的两个音节声调都不同：递为第四声，出为第一声，意思是交给别人。", "抵住": "抵住（dǐzhù）与抵触只有第二个音节的声母不同：zh 与 ch 不同，意思是顶住、挡住。"}, "sentence_index": null, "correct_answer": "抵触"}, "level_3": {"options": [{"text": "抵触", "is_correct": true, "explanation": "抵触：内心反对、抗拒，符合“引发普遍……”的语境，与后面的“士气低落”前后呼应。"}, {"text": "支持", "is_correct": false, "explanation": "语义：“支持”是赞同，与后面“士气低落”的结果相矛盾。"}, {"text": "合作", "is_correct": false, "explanation": "语义：“合作”是积极的配合，与后半句“士气低落”相矛盾，句意不通。"}, {"text": "奖励", "is_correct": false, "explanation": "搭配：“奖励”是正面的给予，不能与“引发”搭配，也与“士气低落”矛盾。"}], "explanations": {"抵触": "抵触：内心反对、抗拒，符合“引发普遍……”的语境，与后面的“士气低落”前后呼应。", "支持": "语义：“支持”是赞同，与后面“士气低落”的结果相矛盾。", "合作": "语义：“合作”是积极的配合，与后半句“士气低落”相矛盾，句意不通。", "奖励": "搭配：“奖励”是正面的给予，不能与“引发”搭配，也与“士气低落”矛盾。"}, "sentence_index": 0, "correct_answer": "抵触"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵用盾牌抵触了飞来的箭雨。", "explanation": "这里应该用〈抵挡〉。抵触表示矛盾冲突或内心抗拒，不能表示用东西挡住。"}, {"text": "我们要抵触外敌的入侵。", "explanation": "这里应该用〈抵御〉。抵御指用力挡住外来的侵犯，抵触没有抵挡侵略的意思。"}, {"text": "这笔收入正好可以抵触前面的亏损。", "explanation": "这里应该用〈抵销〉。抵销指互相冲抵、相互消除，抵触表示矛盾冲突或内心抗拒，没有这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11053, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抵触", "is_correct": true, "explanation": "抵触：心里反对、抗拒，与“一听到考试”后的反应相符。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“很喜欢”与后半句“马上不想说话了”的反应相矛盾。"}, {"text": "热爱", "is_correct": false, "explanation": "配价：“热爱”需要带宾语，不能单独说“很热爱”。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”需要带宾语，单独说“很欢迎”不完整，且与“不想说话”的反应矛盾。"}], "explanations": {"抵触": "抵触：心里反对、抗拒，与“一听到考试”后的反应相符。", "喜欢": "语义：“很喜欢”与后半句“马上不想说话了”的反应相矛盾。", "热爱": "配价：“热爱”需要带宾语，不能单独说“很热爱”。", "欢迎": "配价：“欢迎”需要带宾语，单独说“很欢迎”不完整，且与“不想说话”的反应矛盾。"}, "sentence_index": 6, "correct_answer": "抵触"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机已经抵触了机场。", "explanation": "这里应该用〈抵达〉。抵达表示到达某地，抵触表示矛盾冲突或内心抗拒，不能用于表示到达。"}, {"text": "他用房子抵触了这笔贷款。", "explanation": "这里应该用〈抵押〉。抵押是把财产作为担保，抵触没有担保的意思。"}, {"text": "他想用钱抵触损失。", "explanation": "这里应该用〈抵偿〉。抵偿指用钱或物补偿损失，抵触没有补偿的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方案和原来的计划抵触地，需要重新讨论。", "corrected_sentence": "这个方案和原来的计划抵触了，需要重新讨论。", "error_description": "错误：“抵触”作谓语时其后不能加“地”。应去掉“地”，可说“抵触”或“抵触了”。正确说法：“这个方案和原来的计划抵触了，需要重新讨论。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11053, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两种说法抵触的很厉害，我们得再核对一下。", "corrected_sentence": "这两种说法抵触得很厉害，我们得再核对一下。", "error_description": "补语错误：动词后的程度补语要用“得”引出，不能用“的”。正确说法：“这两种说法抵触得很厉害，我们得再核对一下。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
