INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11054, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在团队或集体中，成员表现出的积极、勇敢、团结的精神状态。", "primary_collocate": null, "pronunciation": "shì qì", "ipa": "ʂʅ˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "在东南亚某国的合资工厂中，德国管理者因本地员工“习惯性迟到”而推行严格打卡制度，结果引发普遍抵触与士气低落。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "比赛前，教练给队员打气，大家的士气很高。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连输三场后，球队士气受到了影响。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板发了奖金，公司的士气明显提高了。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导的一番话鼓舞了全队的士气。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太累又没有奖励，员工的士气越来越差。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们赢了第一场，士气大振。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理常常请大家吃饭，是为了提高团队士气。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气不好，路又远，队伍的士气有点低。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很团结，所以公司的士气一直很好。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "士气高涨", "label": "复合"}], "register": "中性", "sense_fingerprint": "团队成员积极团结的精神状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '620cf61b-9fe1-441f-be7f-b8453433329c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11054, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "士气", "is_correct": true, "explanation": "士气（shìqì）：团队成员积极、团结的精神状态。"}, {"text": "湿气", "is_correct": false, "explanation": "湿气（shīqì）与士气的第一个音节声调不同：湿为第一声，士为第四声，意思是潮湿的气。"}, {"text": "志气", "is_correct": false, "explanation": "志气（zhìqì）与士气只有第一个音节的声母不同：zh 与 sh 不同，意思是远大的理想和抱负。"}, {"text": "死气", "is_correct": false, "explanation": "死气（sǐqì）与士气的第一个音节声调不同：死为第三声，士为第四声，意思是没有生气。"}], "explanations": {"士气": "士气（shìqì）：团队成员积极、团结的精神状态。", "湿气": "湿气（shīqì）与士气的第一个音节声调不同：湿为第一声，士为第四声，意思是潮湿的气。", "志气": "志气（zhìqì）与士气只有第一个音节的声母不同：zh 与 sh 不同，意思是远大的理想和抱负。", "死气": "死气（sǐqì）与士气的第一个音节声调不同：死为第三声，士为第四声，意思是没有生气。"}, "sentence_index": null, "correct_answer": "士气"}, "level_3": {"options": [{"text": "士气", "is_correct": true, "explanation": "士气：集体的积极精神状态，与“低落”搭配，符合“抵触与……低落”的语境。"}, {"text": "工期", "is_correct": false, "explanation": "搭配：“工期”是完成工作的期限，不能与“低落”搭配，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气低落”没有意义，与“普遍抵触”的语境不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不与“低落”搭配，体重可以说增加或减少。"}], "explanations": {"士气": "士气：集体的积极精神状态，与“低落”搭配，符合“抵触与……低落”的语境。", "工期": "搭配：“工期”是完成工作的期限，不能与“低落”搭配，句意不通。", "天气": "语义：“天气低落”没有意义，与“普遍抵触”的语境不符。", "体重": "搭配：“体重”不与“低落”搭配，体重可以说增加或减少。"}, "sentence_index": 0, "correct_answer": "士气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的士气很旺，每天都排长队。", "explanation": "这里应该用〈人气〉。人气指受欢迎的程度，士气是团队的精神状态，不用于形容餐厅。"}, {"text": "晚会上的士气很热烈，大家都在唱歌。", "explanation": "这里应该用〈气氛〉。气氛指场合中的情调，士气是团队的精神状态，不用来形容晚会。"}, {"text": "他对比赛很有士气，已经决定明年再来一次。", "explanation": "这里应该用〈决心〉。决心指个人下定的意志，士气是集体的精神状态，不用于个人打算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11054, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "士气", "is_correct": true, "explanation": "士气：集体的精神状态，与“大振”搭配，符合“赢了第一场”的语境。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子大振”不成立，与“赢了第一场”的语境无关。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试大振”没有意义，与语境不符。"}, {"text": "球鞋", "is_correct": false, "explanation": "语义：“球鞋”是物品，不能“大振”，与“赢了第一场”的语境无关，句子不成立。"}], "explanations": {"士气": "士气：集体的精神状态，与“大振”搭配，符合“赢了第一场”的语境。", "房子": "语义：“房子大振”不成立，与“赢了第一场”的语境无关。", "考试": "语义：“考试大振”没有意义，与语境不符。", "球鞋": "语义：“球鞋”是物品，不能“大振”，与“赢了第一场”的语境无关，句子不成立。"}, "sentence_index": 6, "correct_answer": "士气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从小就有很强的士气，不肯轻易认输。", "explanation": "这里应该用〈志气〉。士气指团队的精神状态，个人的上进心要用“志气”。"}, {"text": "这台机器的士气很好，运转很稳定。", "explanation": "这里应该用〈性能〉。性能指机器的工作表现，士气指集体成员的精神状态，不能用来形容机器。"}, {"text": "他说话的士气很足，大家都被他吸引了。", "explanation": "这里应该用〈气势〉。士气指集体的精神状态，不用于描述个人说话时的声势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师的一番话能鼓舞一个士气，大家重新振作起来。", "corrected_sentence": "老师的一番话能鼓舞士气，大家重新振作起来。", "error_description": "量词错误：“士气”是抽象名词，前面不能用“个”，这里应直接说“鼓舞士气”，去掉“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "连续失败后，队员的士气低落的厉害。", "corrected_sentence": "连续失败后，队员的士气低落得厉害。", "error_description": "补语错误：动词后的程度补语要用“得”引出，不能用“的”。正确说法：“连续失败后，队员的士气低落得厉害。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11055, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高涨", "is_correct": true, "explanation": "反义：“低落”指情绪、士气下降，“高涨”指情绪、士气上升，二者相对。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容明晰，与“低落”没有反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "无关：“坚硬”形容质地，与情绪、士气无关。"}, {"text": "宽敞", "is_correct": false, "explanation": "无关：“宽敞”形容空间，与“低落”没有反义关系。"}], "correct_answer": "高涨", "explanations": {"高涨": "反义：“低落”指情绪、士气下降，“高涨”指情绪、士气上升，二者相对。", "清楚": "无关：“清楚”形容明晰，与“低落”没有反义关系。", "坚硬": "无关：“坚硬”形容质地，与情绪、士气无关。", "宽敞": "无关：“宽敞”形容空间，与“低落”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11055, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高涨", "is_correct": true, "explanation": "反义：“低落”指士气下降，“高涨”指士气上升，二者构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线充足，与“低落”没有反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "无关：“狭窄”形容空间，与“低落”没有反义关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "无关：“潮湿”形容环境或物体的含水状态，与情绪、士气无关。"}], "correct_answer": "高涨", "explanations": {"高涨": "反义：“低落”指士气下降，“高涨”指士气上升，二者构成反义。", "明亮": "无关：“明亮”形容光线充足，与“低落”没有反义关系。", "狭窄": "无关：“狭窄”形容空间，与“低落”没有反义关系。", "潮湿": "无关：“潮湿”形容环境或物体的含水状态，与情绪、士气无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11055, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "情绪、士气等下降，变得不积极。", "primary_collocate": null, "pronunciation": "dī luò", "ipa": "ti˥ lu̯ɔ˥˩", "syllable_count": 2, "sentences": [{"text": "在东南亚某国的合资工厂中，德国管理者因本地员工“习惯性迟到”而推行严格打卡制度，结果引发普遍抵触与士气低落。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "考试没考好，他这几天情绪很低落。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，我的心情总是有点低落。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资一直不涨，员工的士气越来越低落。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "输了比赛，队员们都很低落，没人说话。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她失去了工作，整个人显得非常低落。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板批评了大家，办公室里的气氛有些低落。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到坏消息，他的情绪一下子低落了。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友搬走以后，我一连几天情绪低落。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的士气不再低落，工作效率也提高了。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "情绪低落", "label": "复合"}, {"form": "士气低落", "label": "复合"}], "register": "中性", "sense_fingerprint": "情绪士气下降而不积极", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '620cf61b-9fe1-441f-be7f-b8453433329c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11055, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高涨", "is_correct": false, "explanation": "语义：“高涨”表示士气昂扬，与前文“普遍抵触”的语境相矛盾。"}, {"text": "低落", "is_correct": true, "explanation": "低落：情绪、士气下降、变得不积极，与“普遍抵触”的语境相符。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不能用来形容士气。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”说明明晰程度，不能修饰士气。"}], "explanations": {"高涨": "语义：“高涨”表示士气昂扬，与前文“普遍抵触”的语境相矛盾。", "低落": "低落：情绪、士气下降、变得不积极，与“普遍抵触”的语境相符。", "宽敞": "搭配：“宽敞”形容空间，不能用来形容士气。", "清楚": "搭配：“清楚”说明明晰程度，不能修饰士气。"}, "sentence_index": 0, "correct_answer": "低落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的气温低落到零下五度。", "explanation": "这里应该用〈降低〉。低落只用于情绪、士气等精神状态，气温这类数值下降要用降低。"}, {"text": "这学期班里的人数低落了不少。", "explanation": "这里应该用〈减少〉。低落用于情绪、士气，人数减少要用减少。"}, {"text": "今年的股价低落了百分之十。", "explanation": "这里应该用〈下跌〉。低落用于情绪、士气，股价、价格下跌要用下跌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11055, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清秀", "is_correct": false, "explanation": "体貌：“清秀”形容人的相貌，不能用来形容气氛。"}, {"text": "低落", "is_correct": true, "explanation": "低落：气氛、情绪下降、不热烈，与“老板批评了大家”的语境相符。"}, {"text": "笔直", "is_correct": false, "explanation": "搭配：“笔直”形容线条或姿态，不能修饰气氛。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不能用来说气氛。"}], "explanations": {"清秀": "体貌：“清秀”形容人的相貌，不能用来形容气氛。", "低落": "低落：气氛、情绪下降、不热烈，与“老板批评了大家”的语境相符。", "笔直": "搭配：“笔直”形容线条或姿态，不能修饰气氛。", "雪白": "搭配：“雪白”形容颜色，不能用来说气氛。"}, "sentence_index": 6, "correct_answer": "低落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的风力低落了不少。", "explanation": "这里应该用〈减弱〉。低落用于情绪、士气，风力、力度减弱要用减弱。"}, {"text": "今年的产量低落了百分之五。", "explanation": "这里应该用〈下降〉。低落用于情绪、士气，产量这类数量下降要用下降。"}, {"text": "列车的速度低落了不少。", "explanation": "这里应该用〈减慢〉。低落用于情绪、士气，速度降低要用减慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11055, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛输了以后，队员们的士气低落地很厉害。", "corrected_sentence": "比赛输了以后，队员们的士气低落得很厉害。", "error_description": "“低落”作程度补语时要用“得”，不能用“地”。“地”用在动词、形容词前作状语，不能接在“低落”后面表示程度。正确形式是“低落得很厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11055, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次失利之后，大家的情绪被明显低落。", "corrected_sentence": "这次失利之后，大家的情绪明显低落。", "error_description": "被字句错误：“低落”是表示状态的不及物词，不能放在“被”字句中，应说“情绪明显低落”，去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
