INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11056, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "研究人类文化、社会、生物和历史的学者。", "primary_collocate": null, "pronunciation": "rén lèi xué jiā", "ipa": "ɻən˧˥ lei˥˩ ɕɥe˧˥ tɕja˥", "syllable_count": 4, "sentences": [{"text": "人类学家介入后发现，当地社区的时间观根植于农业周期与集体节庆，精确的分钟概念是殖民与现代化强加的外来框架。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这位人类学家在山里住了五年。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学家研究不同民族的生活方式。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想成为一名人类学家。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学家常常要去很远的地方做调查。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位人类学家写了一本关于村子的书。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学家问老人很多关于节日的问题。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位人类学家会说三种当地的语言。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学家发现，两个村子的习惯不一样。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的叔叔是人类学家，他常常去非洲。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "研究人类文化社会历史的学者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '620cf61b-9fe1-441f-be7f-b8453433329c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "律师", "is_correct": false, "explanation": "语义：律师研究法律事务，不研究人类文化，不能说“律师介入后发现时间观”。"}, {"text": "人类学家", "is_correct": true, "explanation": "人类学家：研究人类文化、社会的学者，与“介入后发现社区时间观”的语境相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师从事烹饪，不做社区文化的田野调查，与语境不符。"}, {"text": "学霸", "is_correct": false, "explanation": "语域：“学霸”是口语词，指成绩优秀的学生，不用于这种客观的学术叙述。"}], "explanations": {"律师": "语义：律师研究法律事务，不研究人类文化，不能说“律师介入后发现时间观”。", "人类学家": "人类学家：研究人类文化、社会的学者，与“介入后发现社区时间观”的语境相符。", "厨师": "语义：厨师从事烹饪，不做社区文化的田野调查，与语境不符。", "学霸": "语域：“学霸”是口语词，指成绩优秀的学生，不用于这种客观的学术叙述。"}, "sentence_index": 0, "correct_answer": "人类学家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我大学的专业是人类学家。", "explanation": "这里应该用〈人类学〉。“人类学”是学科名，作专业要说“人类学”，“人类学家”指从事研究的人。"}, {"text": "这位人类学家在实验室里研究蝴蝶的基因。", "explanation": "这里应该用〈生物学家〉。研究蝴蝶的基因属于生物学家的工作，人类学家研究的是人类的文化、社会。"}, {"text": "这位人类学家发明了一种新疫苗。", "explanation": "这里应该用〈医学家〉。医学家研究疾病与药物，人类学家研究人类的文化与社会，不研发疫苗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "搭配：“石头”不能施行“问”的动作，不能说“石头问老人问题”。"}, {"text": "人类学家", "is_correct": true, "explanation": "人类学家：研究人类文化的学者，能够向老人提问并调查节日习俗，与语境相符。"}, {"text": "教堂", "is_correct": false, "explanation": "搭配：“教堂”是建筑，不能作“问”的施事。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“夏天”是时间词，不能作发问的主体。"}], "explanations": {"石头": "搭配：“石头”不能施行“问”的动作，不能说“石头问老人问题”。", "人类学家": "人类学家：研究人类文化的学者，能够向老人提问并调查节日习俗，与语境相符。", "教堂": "搭配：“教堂”是建筑，不能作“问”的施事。", "夏天": "语义：“夏天”是时间词，不能作发问的主体。"}, "sentence_index": 6, "correct_answer": "人类学家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人类学家的历史已经有几百万年了。", "explanation": "这里应该用〈人类〉。“人类”指全体人，表示历史的主体要用“人类”，“人类学家”指研究人的专业人员。"}, {"text": "人类学家在山顶架设了一台雷达，用来预报降雨。", "explanation": "这里应该用〈气象学家〉。架设雷达、预报降雨属于气象学家的工作，人类学家研究的是人类的文化与社会。"}, {"text": "人类学家在天文台观测到一颗彗星。", "explanation": "这里应该用〈天文学家〉。观测彗星属于天文学家的工作，人类学家研究的是人类的文化与社会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表姐大学毕业后当了一人类学家。", "corrected_sentence": "我表姐大学毕业后当了一名人类学家。", "error_description": "数词与名词之间缺少量词。“一人类学家”应为“一名人类学家”，“名”是指人的常用量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我堂哥很人类学家，他经常去国外调查。", "corrected_sentence": "我堂哥是人类学家，他经常去国外调查。", "error_description": "名词“人类学家”不能被“很”修饰，应用判断动词“是”。正确形式是“我堂哥是人类学家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
