INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11060, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "比喻深深扎根于某处，牢固地树立或建立。", "primary_collocate": null, "pronunciation": "gēn zhí", "ipa": "kən˥ ʈʂɹ̩˧˥", "syllable_count": 2, "sentences": [{"text": "一个中国玩家可能与北欧、南美队员在共同目标下形成临时共同体，其凝聚力不依赖血缘或国籍，而根植于角色互补性与互信契约。", "target_word": "根植", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "人类学家介入后发现，当地社区的时间观根植于农业周期与集体节庆，精确的分钟概念是殖民与现代化强加的外来框架。", "target_word": "根植", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种习惯根植于他童年的生活。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱国的感情根植于每个人的心中。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日根植于中国的传统文化。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法根植于多年的工作经验。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的故事都根植于真实的生活。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些歌根植于当地人的生活，大家都爱唱。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的善良根植于父母的教育。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的饮食习惯根植于它的历史。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "根植：比喻思想、感情、习惯等深深扎根于某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcdeda5-d8c7-49c0-8c4a-eb7c9e6fe46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根植", "is_correct": true, "explanation": "根植：扎根，与“角色互补性与互信契约”搭配，说明凝聚力牢固的根基。"}, {"text": "瓦解", "is_correct": false, "explanation": "语义：“瓦解”指崩溃、分裂，与“凝聚力”和“互信契约”的意思相反。"}, {"text": "背离", "is_correct": false, "explanation": "语义：“背离”指违背，与以互信契约为基础的凝聚力相悖。"}, {"text": "分散", "is_correct": false, "explanation": "搭配：“分散”指散开，与需要聚合的“凝聚力”搭配不当。"}], "explanations": {"根植": "根植：扎根，与“角色互补性与互信契约”搭配，说明凝聚力牢固的根基。", "瓦解": "语义：“瓦解”指崩溃、分裂，与“凝聚力”和“互信契约”的意思相反。", "背离": "语义：“背离”指违背，与以互信契约为基础的凝聚力相悖。", "分散": "搭配：“分散”指散开，与需要聚合的“凝聚力”搭配不当。"}, "sentence_index": 0, "correct_answer": "根植"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在农村根植多年，从未离开。", "explanation": "这里应该用〈扎根〉。根植多用于思想、习惯等抽象事物，人长期在某地生活工作要说扎根。"}, {"text": "医生给他根植了一个心脏起搏器。", "explanation": "这里应该用〈植入〉。根植指植物的根扎进土里，医疗器械放入体内应说植入。"}, {"text": "农民把玉米根植在田里。", "explanation": "这里应该用〈种〉。根植指植物自己的根扎进土里，人把种子或秧苗放进田里应说种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根植", "is_correct": true, "explanation": "根植：深深扎根，与“真实的生活”搭配，说明好故事的基础。"}, {"text": "夭折", "is_correct": false, "explanation": "搭配：“夭折”多指计划、生命等未成就而中止，不用来描述故事与生活的关系。"}, {"text": "脱离", "is_correct": false, "explanation": "语义：“脱离”指与某物分开，与“好的故事”的正面评价相矛盾。"}, {"text": "枯萎", "is_correct": false, "explanation": "搭配：“枯萎”多用于植物或生机，与故事和生活的关系不搭配。"}], "explanations": {"根植": "根植：深深扎根，与“真实的生活”搭配，说明好故事的基础。", "夭折": "搭配：“夭折”多指计划、生命等未成就而中止，不用来描述故事与生活的关系。", "脱离": "语义：“脱离”指与某物分开，与“好的故事”的正面评价相矛盾。", "枯萎": "搭配：“枯萎”多用于植物或生机，与故事和生活的关系不搭配。"}, "sentence_index": 6, "correct_answer": "根植"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车根植于停车场。", "explanation": "这里应该用〈停放〉。根植用于植物的根扎进土里，或思想、习惯等抽象事物深深扎根，汽车没有根，说车停在某处要用停放。"}, {"text": "这座城市根植于大河的南岸。", "explanation": "这里应该用〈位于〉。根植形容思想、习惯等扎根于某处，城市的位置应说位于。"}, {"text": "这条河根植于山里。", "explanation": "这里应该用〈发源〉。根植指植物的根扎进土里，河流的源头应说发源于山里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种信念深深根植于在他的心中。", "corrected_sentence": "这种信念深深根植于他的心中。", "error_description": "“根植于”里的“于”已经是介词，后面不能再加“在”，两个介词重复。应去掉“在”，说“深深根植于他的心中”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种尊重根植了于彼此的信任。", "corrected_sentence": "这种尊重根植于彼此的信任。", "error_description": "“根植于”是固定结构，“根植”与“于”之间不能加“了”，应去掉“了”，说“根植于彼此的信任”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
