INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11062, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指强国向弱国或地区移民，并建立政治、经济控制，使其成为自己的殖民地。", "primary_collocate": null, "pronunciation": "zhí mín", "ipa": "ʈʂʐ̩˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "英国曾经殖民过印度很多年。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十九世纪，欧洲强国到处殖民弱小的国家。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西班牙当年殖民了南美洲的大片土地。", "target_word": "殖民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "强国想殖民别的国家，是为了资源和市场。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小国曾经遭到强国殖民，失去了独立。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不但殖民这片土地，还控制了当地的经济。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候，很多国家都想殖民非洲。", "target_word": "殖民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史老师说，殖民别国是不公平的。", "target_word": "殖民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "葡萄牙曾经殖民过澳门四百多年。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "荷兰人为了香料，先后殖民了东南亚的一些地方。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "殖民了", "label": "体标"}, {"form": "殖民过", "label": "体标"}, {"form": "殖民地", "label": "复合"}, {"form": "殖民者", "label": "复合"}], "register": "书面", "sense_fingerprint": "强国向外移民并控制弱国或地区的殖民行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '382a3983-b0b3-4d55-b760-74b0ee0cab2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "殖民", "is_correct": true, "explanation": "殖民指强国迁入并控制他国，与“曾经……过印度很多年”的叙述相符。"}, {"text": "访问", "is_correct": false, "explanation": "语义：“访问”是短暂拜访，与“很多年”的持续时间矛盾。"}, {"text": "旅游", "is_correct": false, "explanation": "配价：“旅游”是不及物动词，不能直接带“印度”作宾语。"}, {"text": "留学", "is_correct": false, "explanation": "语义：“留学”的主体须是求学的人，“英国”是国家，不能留学。"}], "explanations": {"殖民": "殖民指强国迁入并控制他国，与“曾经……过印度很多年”的叙述相符。", "访问": "语义：“访问”是短暂拜访，与“很多年”的持续时间矛盾。", "旅游": "配价：“旅游”是不及物动词，不能直接带“印度”作宾语。", "留学": "语义：“留学”的主体须是求学的人，“英国”是国家，不能留学。"}, "sentence_index": 0, "correct_answer": "殖民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "很多中国人殖民到了美国，在那里找到了工作。", "explanation": "这里应该用〈移民〉。殖民指强国对别的地方建立政治、经济控制，普通人迁居要用移民。"}, {"text": "他殖民了一家新公司，决定明年扩大规模。", "explanation": "这里应该用〈创办〉。殖民指强国向别处移民并建立政治、经济控制，殖民的对象是国家或地区，不能用于公司。"}, {"text": "校长殖民了全校的学生，大家都很害怕。", "explanation": "这里应该用〈管理〉。殖民的对象是地区或国家，不能用于管理学生这类人群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "殖民", "is_correct": true, "explanation": "殖民：强国迁入并控制别国，与“那时候很多国家都想……非洲”的历史背景相符。"}, {"text": "摆脱", "is_correct": false, "explanation": "搭配：“摆脱”后接的是控制、困境等，不能直接接地区作宾语，“想摆脱非洲”不成立。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”针对别人的帮助，与“很多国家都想……非洲”的语义不符。"}, {"text": "冒犯", "is_correct": false, "explanation": "语义：“冒犯”指伤害别人的感情，与句中国家对地区的意图不相合。"}], "explanations": {"殖民": "殖民：强国迁入并控制别国，与“那时候很多国家都想……非洲”的历史背景相符。", "摆脱": "搭配：“摆脱”后接的是控制、困境等，不能直接接地区作宾语，“想摆脱非洲”不成立。", "感谢": "语义：“感谢”针对别人的帮助，与“很多国家都想……非洲”的语义不符。", "冒犯": "语义：“冒犯”指伤害别人的感情，与句中国家对地区的意图不相合。"}, "sentence_index": 6, "correct_answer": "殖民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去非洲殖民了一个月，玩得很开心。", "explanation": "这里应该用〈旅游〉。殖民指强国长期控制别国，不能用来描述短期游玩。"}, {"text": "博物馆里的展品很多，我们殖民了整整一个下午。", "explanation": "这里应该用〈参观〉。殖民的对象是国家或地区，不能用于参观博物馆这类活动。"}, {"text": "科学家殖民了这种植物的生长过程，记录了每一天的变化。", "explanation": "这里应该用〈研究〉。殖民的对象是国家或地区，不能用于研究生长过程这类对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法国曾经在越南殖民者过一段时间。", "corrected_sentence": "法国曾经在越南殖民过一段时间。", "error_description": "“殖民者”是名词，指施行殖民的人；这里要用动词“殖民”，应说“在越南殖民过一段时间”，不能说“在越南殖民者过一段时间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那时候，西班牙和葡萄牙都想殖民了美洲。", "corrected_sentence": "那时候，西班牙和葡萄牙都想殖民美洲。", "error_description": "“想”之后的动词不能带“了”，应说“想殖民美洲”；“殖民了”表示已经完成，与“想”的意愿语义冲突。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
