INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11064, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11064, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某种事物或看法硬是加给别人，让人必须接受。", "primary_collocate": null, "pronunciation": "qiáng jiā", "ipa": "tɕʰjɑŋ˧˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "人类学家介入后发现，当地社区的时间观根植于农业周期与集体节庆，精确的分钟概念是殖民与现代化强加的外来框架。", "target_word": "强加", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "不要把你的想法强加给别人。", "target_word": "强加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母不应该把自己的愿望强加给孩子。", "target_word": "强加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是把自己的看法强加于人。", "target_word": "强加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个规定是公司强加给员工的。", "target_word": "强加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人的想法都不同，不能强加给别人。", "target_word": "强加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板把不合理的任务强加给了新同事。", "target_word": "强加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很讨厌别人强加给她的建议。", "target_word": "强加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好朋友之间要互相尊重，不能强加自己的意见。", "target_word": "强加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的习惯强加给室友，大家都不高兴。", "target_word": "强加", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "强加了", "label": "体标"}, {"form": "强加过", "label": "体标"}], "register": "中性", "sense_fingerprint": "硬把想法、规定等加给别人，让人不得不接受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '382a3983-b0b3-4d55-b760-74b0ee0cab2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强加", "is_correct": true, "explanation": "强加：硬加给他人的外来框架，与“殖民与现代化”的强制性相符。"}, {"text": "保护", "is_correct": false, "explanation": "搭配：“保护”不能修饰“外来框架”来表示被硬加，“保护的外来框架”不成立。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，不能用来修饰“外来框架”。"}, {"text": "放松", "is_correct": false, "explanation": "语义：“放松”指紧张状态的缓和，与“外来框架”的强制义不符。"}], "explanations": {"强加": "强加：硬加给他人的外来框架，与“殖民与现代化”的强制性相符。", "保护": "搭配：“保护”不能修饰“外来框架”来表示被硬加，“保护的外来框架”不成立。", "提高": "搭配：“提高”用于水平、质量，不能用来修饰“外来框架”。", "放松": "语义：“放松”指紧张状态的缓和，与“外来框架”的强制义不符。"}, "sentence_index": 0, "correct_answer": "强加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司把这项新规定强加给员工，员工们都很乐意遵守。", "explanation": "这里应该用〈宣布〉。强加指硬加给人不想要的东西，员工乐意遵守的规定不能用强加。"}, {"text": "孩子把自己的玩具强加给妹妹，妹妹很开心。", "explanation": "这里应该用〈借给〉。强加指硬加给人不想要的东西，与“妹妹很开心”矛盾。"}, {"text": "朋友把生日礼物强加给我，我非常开心。", "explanation": "这里应该用〈送〉。强加指硬把不想要的东西加给别人，与“我非常开心”的语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强加", "is_correct": true, "explanation": "强加：把任务硬加给同事，与“老板把不合理的任务……给了新同事”相符。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”的宾语是话题，不能用来转交任务，“讨论给了新同事”不成立。"}, {"text": "解决", "is_correct": false, "explanation": "搭配：“解决”的对象是问题，不能把任务“解决给”别人。"}, {"text": "完成", "is_correct": false, "explanation": "语义：“完成”是自己做完工作，不能转交给别人。"}], "explanations": {"强加": "强加：把任务硬加给同事，与“老板把不合理的任务……给了新同事”相符。", "讨论": "配价：“讨论”的宾语是话题，不能用来转交任务，“讨论给了新同事”不成立。", "解决": "搭配：“解决”的对象是问题，不能把任务“解决给”别人。", "完成": "语义：“完成”是自己做完工作，不能转交给别人。"}, "sentence_index": 6, "correct_answer": "强加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把借的书强加给了图书馆，图书馆很满意。", "explanation": "这里应该用〈归还〉。强加指硬加给别人一个不想要的东西，归还借的书是履行义务。"}, {"text": "老人把自己的经验强加给年轻人，年轻人都是自愿听的。", "explanation": "这里应该用〈传授〉。强加指硬加给人不想要的东西，与“年轻人都是自愿听的”矛盾。"}, {"text": "我们把快乐强加给大家，大家都很高兴。", "explanation": "这里应该用〈分享〉。强加指硬加给人不想要的东西，快乐是好事，不能用强加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不肯听别人的意见，非要把计划强加对大家。", "corrected_sentence": "他不肯听别人的意见，非要把计划强加给大家。", "error_description": "“强加”引出接受者多用“给”（也可用“于”，如“强加于人”），不能用“对”，应说“强加给大家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经不再把观点强加了给别人。", "corrected_sentence": "他已经不再把观点强加给别人。", "error_description": "“强加给”是一个整体动词，“了”不能插在“强加”与“给”之间；句中“不再”表示停止习惯，不需要“了”，应说“强加给别人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
