INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11068, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指某一段特定的时间范围。", "primary_collocate": null, "pronunciation": "shí duàn", "ipa": "ʂʐ̩˧˥ twan˥˩", "syllable_count": 2, "sentences": [{"text": "最终，企业调整策略，把每天固定的时段制度化，而非苛求分秒不差，既保障生产效率，又尊重文化惯性。", "target_word": "时段", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "北欧部分企业开始推行“无会议星期五”，并在每天下午划出不被打扰的时段，试图从内部解构过度时间规训，重新拥抱一种更具人文温度的时间哲学。", "target_word": "时段", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "每天下班那个时段，路上都堵车。", "target_word": "时段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个时段路上车很少，你可以放心开。", "target_word": "时段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一天可以分成早、中、晚三个时段。", "target_word": "时段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请选一个你方便的时段来看房子。", "target_word": "时段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "九点到十一点这个时段，医生不接电话。", "target_word": "时段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店在不同的时段，打折也不一样。", "target_word": "时段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "半夜是网速最快的时段，下载很方便。", "target_word": "时段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想把会议放在哪个时段，上午还是下午？", "target_word": "时段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "高峰时段", "label": "复合"}, {"form": "時段", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一天或一段时间里划出来的特定时间范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '382a3983-b0b3-4d55-b760-74b0ee0cab2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时段", "is_correct": true, "explanation": "时段指一段特定的时间范围，“每天固定的时段”指规定好的一段工作时间，符合句意。"}, {"text": "人员", "is_correct": false, "explanation": "语义：“分秒不差”说的是时间的精确程度，“人员”不是时间范围，与“制度化”所指的时间安排对不上。"}, {"text": "场所", "is_correct": false, "explanation": "语义：“场所”指地点，不能与“分秒不差”所说的时间精确度搭配。"}, {"text": "设备", "is_correct": false, "explanation": "搭配：“制度化”针对的是工作时间的规定，不能说把“设备”制度化，与句中的时间要求不合。"}], "explanations": {"时段": "时段指一段特定的时间范围，“每天固定的时段”指规定好的一段工作时间，符合句意。", "人员": "语义：“分秒不差”说的是时间的精确程度，“人员”不是时间范围，与“制度化”所指的时间安排对不上。", "场所": "语义：“场所”指地点，不能与“分秒不差”所说的时间精确度搭配。", "设备": "搭配：“制度化”针对的是工作时间的规定，不能说把“设备”制度化，与句中的时间要求不合。"}, "sentence_index": 0, "correct_answer": "时段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我花了很多时段写作业。", "explanation": "这里应该用〈时间〉。时段指划分出来的某一段时间范围，不用来泛指做事所花的时间；“花了很多时段”不自然。"}, {"text": "出发的时段到了，我们快上车吧。", "explanation": "这里应该用〈时刻〉。时刻指一个具体的时间点，“出发”是一个点；时段指一段时间范围，不能用来指一个时间点。"}, {"text": "他的童年时段在农村度过，很快乐。", "explanation": "这里应该用〈时期〉。时期指较长的一个阶段，如童年时期；时段指较短的、划分出来的时间范围，不能用来指一个人整个童年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时段", "is_correct": true, "explanation": "时段指一段时间范围，“九点到十一点这个时段”指这一段固定的时间，符合句意。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“九点到十一点”是时间范围，“地点”不是时间，与“这个”所指的时段对不上。"}, {"text": "病房", "is_correct": false, "explanation": "语义：“病房”是场所，不能与“九点到十一点”这样的时间范围搭配。"}, {"text": "药品", "is_correct": false, "explanation": "语义：“药品”是物品，不表示时间范围，“这个药品”与“九点到十一点”搭配不通。"}], "explanations": {"时段": "时段指一段时间范围，“九点到十一点这个时段”指这一段固定的时间，符合句意。", "地点": "语义：“九点到十一点”是时间范围，“地点”不是时间，与“这个”所指的时段对不上。", "病房": "语义：“病房”是场所，不能与“九点到十一点”这样的时间范围搭配。", "药品": "语义：“药品”是物品，不表示时间范围，“这个药品”与“九点到十一点”搭配不通。"}, "sentence_index": 6, "correct_answer": "时段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要抓住时段，尽快签约。", "explanation": "这里应该用〈时机〉。“抓住”搭配的是机会或时机；时段指时间范围，不能被“抓住”。"}, {"text": "这条路的第三时段最窄。", "explanation": "这里应该用〈路段〉。路段指道路上划分出来的一段，是空间范围；时段指时间上的一段范围，不能用来说道路的一段。"}, {"text": "他按下快门的时段，阳光正好照在脸上。", "explanation": "这里应该用〈瞬间〉。按快门是一个瞬间的动作，指一个时间点；时段指一段时间范围，不能用于指瞬间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条时段大家都在家里休息。", "corrected_sentence": "这个时段大家都在家里休息。", "error_description": "量词错误：“时段”的量词应用“个”，不能用“条”（“条”多用于河、路、鱼等）；应说“这个时段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上这个的时段，楼下很安静。", "corrected_sentence": "晚上这个时段，楼下很安静。", "error_description": "语法错误：“这个”与名词之间不能加“的”，应说“这个时段”；“的”加在“这个”后面会破坏量词短语的结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
