INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11069, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对别人提出过高、过严的要求。", "primary_collocate": null, "pronunciation": "kē qiú", "ipa": "kʰɤ˥ tɕʰiou˧˥", "syllable_count": 2, "sentences": [{"text": "最终，企业调整策略，将“核心工作时段”制度化，而非苛求分秒不差，既保障生产效率，又尊重文化惯性。", "target_word": "苛求", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师不应该苛求学生每次都考满分。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他苛求同事一点错也不能犯。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母不要苛求孩子样样都得第一。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是苛求别人，从不看自己。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能苛求新来的同事马上做好所有工作。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理苛求大家每天加班，很多人都不满。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别苛求他了，他已经尽力了。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要苛求朋友和你想得一模一样。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛才刚开始，不必苛求队员零失误。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "苛求了", "label": "体标"}, {"form": "苛求着", "label": "体标"}, {"form": "苛求过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "对他人提出过高过严的要求，不近人情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '382a3983-b0b3-4d55-b760-74b0ee0cab2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11069, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苛求", "is_correct": true, "explanation": "苛求指对别人提出过高过严的要求，“而非苛求分秒不差”指不对时间提出过严的精确要求，符合句意。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”的对象是别人的错误，“原谅分秒不差”说不通，与句中对时间精确度的要求不合。"}, {"text": "尊重", "is_correct": false, "explanation": "搭配：“尊重”的对象是人或文化，不与“分秒不差”搭配。"}, {"text": "调整", "is_correct": false, "explanation": "搭配：“调整”针对的是策略、计划等，“分秒不差”不能被调整。"}], "explanations": {"苛求": "苛求指对别人提出过高过严的要求，“而非苛求分秒不差”指不对时间提出过严的精确要求，符合句意。", "原谅": "语义：“原谅”的对象是别人的错误，“原谅分秒不差”说不通，与句中对时间精确度的要求不合。", "尊重": "搭配：“尊重”的对象是人或文化，不与“分秒不差”搭配。", "调整": "搭配：“调整”针对的是策略、计划等，“分秒不差”不能被调整。"}, "sentence_index": 0, "correct_answer": "苛求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我苛求老师给我一次机会。", "explanation": "这里应该用〈请求〉。苛求指对他人提出过高过严的要求，含贬义；请别人给机会应说“请求”，不能用“苛求”。"}, {"text": "他苛求一场好雨，盼了整整一个夏天。", "explanation": "这里应该用〈盼望〉。苛求的对象是人，指对他人提出过高要求；对天气的期待应说“盼望”。"}, {"text": "我们苛求春天的到来。", "explanation": "这里应该用〈期盼〉。苛求的对象是人，表示要求别人做到很难的事；春天不能被要求，表达期待应说“期盼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苛求", "is_correct": true, "explanation": "苛求指对别人提出过高过严的要求，“经理苛求大家每天加班”指经理对大家提出过高的加班要求，符合句意。"}, {"text": "体谅", "is_correct": false, "explanation": "语义：“体谅”表示理解别人的难处，与后半句“很多人都不满”的意思相矛盾。"}, {"text": "照顾", "is_correct": false, "explanation": "搭配：“照顾”的对象应是需要关照的人，不能与“每天加班”搭配构成通顺的句子。"}, {"text": "赞扬", "is_correct": false, "explanation": "语义：“赞扬”表示称赞，与“很多人都不满”的语境相矛盾。"}], "explanations": {"苛求": "苛求指对别人提出过高过严的要求，“经理苛求大家每天加班”指经理对大家提出过高的加班要求，符合句意。", "体谅": "语义：“体谅”表示理解别人的难处，与后半句“很多人都不满”的意思相矛盾。", "照顾": "搭配：“照顾”的对象应是需要关照的人，不能与“每天加班”搭配构成通顺的句子。", "赞扬": "语义：“赞扬”表示称赞，与“很多人都不满”的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "苛求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他虔诚地苛求神灵保佑家人平安。", "explanation": "这里应该用〈祈求〉。祈求是恳切地向神明或他人请求，不含对他人施加过高要求的意思；苛求不能用于神灵。"}, {"text": "我们正在苛求解决问题的办法。", "explanation": "这里应该用〈寻求〉。寻求指努力去找，用于办法、答案等；“苛求”指对他人提出过高要求，不能用于找办法。"}, {"text": "我衷心苛求他的帮助。", "explanation": "这里应该用〈感谢〉。感谢表示对别人的帮助表示谢意，“苛求”含贬义，不能用来表达对帮助的感激。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家长不应该苛求了孩子每科都考满分。", "corrected_sentence": "家长不应该苛求孩子每科都考满分。", "error_description": "“了”误加在动词“苛求”后。“了”表示动作已完成，与“不应该”表达的劝诫语境不符，应删去，说“不应该苛求孩子每科都考满分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试很难，老师不必苛求了学生拿满分。", "corrected_sentence": "这次考试很难，老师不必苛求学生拿满分。", "error_description": "“了”误加在动词“苛求”后，与“不必”表达的劝止语境不符，应删去，说“老师不必苛求学生拿满分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
