INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11070, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容时间或事情非常准确，没有丝毫差错。", "primary_collocate": null, "pronunciation": "fēn miǎo bù chā", "ipa": "fən˥ miɑʊ˨˩ pu˥˩ tʂʰa˥", "syllable_count": 4, "sentences": [{"text": "最终，企业调整策略，将“核心工作时段”制度化，而非苛求分秒不差，既保障生产效率，又尊重文化惯性。", "target_word": "分秒不差", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这趟火车到站的时间分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上分秒不差地走出家门。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始时，裁判的计时分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做饭很准，出锅的时间分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻每晚七点开始，分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约好八点见面，他到得分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块表很准，走了一年还是分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出结束的时间与计划分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老钟走得分秒不差，全城人都信它。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "时间或事情极其准确，一点差错也没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '382a3983-b0b3-4d55-b760-74b0ee0cab2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分秒不差", "is_correct": true, "explanation": "“分秒不差”形容时间或事情精确到秒，与“苛求”搭配，表示对时间要求极严。"}, {"text": "粗枝大叶", "is_correct": false, "explanation": "语义：“粗枝大叶”指做事马虎，与“苛求”所要求的精确相反，句意不通。"}, {"text": "漫不经心", "is_correct": false, "explanation": "语义：“漫不经心”指不在意，与“苛求”的严格标准相矛盾。"}, {"text": "随遇而安", "is_correct": false, "explanation": "配价：“随遇而安”描述接受现状的态度，不能作“苛求”的对象。"}], "explanations": {"分秒不差": "“分秒不差”形容时间或事情精确到秒，与“苛求”搭配，表示对时间要求极严。", "粗枝大叶": "语义：“粗枝大叶”指做事马虎，与“苛求”所要求的精确相反，句意不通。", "漫不经心": "语义：“漫不经心”指不在意，与“苛求”的严格标准相矛盾。", "随遇而安": "配价：“随遇而安”描述接受现状的态度，不能作“苛求”的对象。"}, "sentence_index": 0, "correct_answer": "分秒不差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这本书的理解分秒不差。", "explanation": "这里应该用〈精确〉。分秒不差只说时间或事情的准确，“理解”属于认识，要说精确地理解。"}, {"text": "这位画家的性格分秒不差。", "explanation": "这里应该用〈完美〉。分秒不差限于时间和事情的准确，不能用来评价性格。"}, {"text": "这台秤显示的体重分秒不差。", "explanation": "这里应该用〈准确〉。分秒不差只形容时间或事情，体重是数量，要说准确。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分秒不差", "is_correct": true, "explanation": "“到得”后接补语，说明到达的精确程度，“分秒不差”与约定的八点相呼应。"}, {"text": "整洁", "is_correct": false, "explanation": "语义：“整洁”形容外表干净利落，不能描述到达的时刻是否准确。"}, {"text": "凌乱", "is_correct": false, "explanation": "语义：“凌乱”指杂乱无序，形容外表或状态，与到达的准确程度无关。"}, {"text": "粗壮", "is_correct": false, "explanation": "语义：“粗壮”形容身体或物体粗大结实，不能用来说到达的准确程度。"}], "explanations": {"分秒不差": "“到得”后接补语，说明到达的精确程度，“分秒不差”与约定的八点相呼应。", "整洁": "语义：“整洁”形容外表干净利落，不能描述到达的时刻是否准确。", "凌乱": "语义：“凌乱”指杂乱无序，形容外表或状态，与到达的准确程度无关。", "粗壮": "语义：“粗壮”形容身体或物体粗大结实，不能用来说到达的准确程度。"}, "sentence_index": 6, "correct_answer": "分秒不差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项研究的方法分秒不差。", "explanation": "这里应该用〈严谨〉。分秒不差只用于时间或事情的准确，研究方法要说严谨。"}, {"text": "他的体温分秒不差。", "explanation": "这里应该用〈正常〉。分秒不差只形容时间或事情的准确，体温要说正常。"}, {"text": "这件瓷器的工艺分秒不差。", "explanation": "这里应该用〈精致〉。分秒不差形容时间或事情的准确，工艺的精细要说精致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电子钟走分秒不差，邻居都说它很准。", "corrected_sentence": "这台电子钟走得分秒不差，邻居都说它很准。", "error_description": "“走分秒不差”缺少补语标记“得”。应说“走得分秒不差”，“得”引出补语，说明走的准确程度。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天早上分秒不差的出门去上班。", "corrected_sentence": "她每天早上分秒不差地出门去上班。", "error_description": "“分秒不差的出门”误用“的”。“分秒不差”修饰动词“出门”时是状语，应用“地”，应说“分秒不差地出门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
