INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11071, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保护、维护，使不受侵犯或破坏。", "primary_collocate": null, "pronunciation": "bǎo zhàng", "ipa": "pɑʊ˨˩ tʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "最终，企业调整策略，将“核心工作时段”制度化，而非苛求分秒不差，既保障生产效率，又尊重文化惯性。", "target_word": "保障", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "法律保障每个人的合法权利。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府努力保障老百姓的生命安全。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部法律保障了消费者的权益。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家保障每个孩子都有机会上学。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司买了保险，保障员工的健康。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宪法保障公民的言论自由。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察日夜工作，保障城市的安宁。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院保障着老人的合法财产。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同能保障双方的利益不受损害。", "target_word": "保障", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保障了", "label": "体标"}, {"form": "保障着", "label": "体标"}, {"form": "保障过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "保护并维护权利、利益等，使其不受侵犯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '382a3983-b0b3-4d55-b760-74b0ee0cab2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11071, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保障", "is_correct": true, "explanation": "“既…又…”并列，“保障生产效率”与后句的尊重文化相呼应，表示保护效率。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”指舍弃，与“既…又…”要求兼顾的意思相悖，前后矛盾。"}, {"text": "削弱", "is_correct": false, "explanation": "语义：“削弱”指使减弱，与“保障生产效率”的目的相反，句意不通。"}, {"text": "侵犯", "is_correct": false, "explanation": "搭配：“侵犯”的对象是权利或利益，不能说“侵犯生产效率”。"}], "explanations": {"保障": "“既…又…”并列，“保障生产效率”与后句的尊重文化相呼应，表示保护效率。", "放弃": "语义：“放弃”指舍弃，与“既…又…”要求兼顾的意思相悖，前后矛盾。", "削弱": "语义：“削弱”指使减弱，与“保障生产效率”的目的相反，句意不通。", "侵犯": "搭配：“侵犯”的对象是权利或利益，不能说“侵犯生产效率”。"}, "sentence_index": 0, "correct_answer": "保障"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向我保障一定会来。", "explanation": "这里应该用〈保证〉。保障多指保护权利、安全，对人承诺某事要说保证，且常用“向…保证”。"}, {"text": "他每天都认真保障自己的作业。", "explanation": "这里应该用〈完成〉。保障用于安全、权益和供应，作业要说完成。"}, {"text": "他在数学考试中保障了满分。", "explanation": "这里应该用〈取得〉。保障指保护、维护，使不受侵犯或破坏，成绩要说取得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11071, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保障", "is_correct": true, "explanation": "“宪法”作主语，“保障公民的言论自由”指法律加以保护，与句意相符。"}, {"text": "剥夺", "is_correct": false, "explanation": "语义：“剥夺”指夺去，与宪法保护公民权利的作用相反。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、程度，不能用于“言论自由”这类权利。"}, {"text": "缩短", "is_correct": false, "explanation": "搭配：“缩短”用于时间、距离、过程，不能说缩短言论自由。"}], "explanations": {"保障": "“宪法”作主语，“保障公民的言论自由”指法律加以保护，与句意相符。", "剥夺": "语义：“剥夺”指夺去，与宪法保护公民权利的作用相反。", "提高": "搭配：“提高”用于水平、程度，不能用于“言论自由”这类权利。", "缩短": "搭配：“缩短”用于时间、距离、过程，不能说缩短言论自由。"}, "sentence_index": 6, "correct_answer": "保障"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他保障了这些责任。", "explanation": "这里应该用〈承担〉。保障的对象是权利、利益和安全，责任要说承担。"}, {"text": "他马上保障了这个问题。", "explanation": "这里应该用〈解决〉。保障指使人或物保持安全，问题要说解决。"}, {"text": "他很快保障了童年的烦恼。", "explanation": "这里应该用〈遗忘〉。保障用于安全和利益，烦恼这类心理感受不能用保障，应说遗忘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警方加强巡逻，了保障居民的财产安全。", "corrected_sentence": "警方加强巡逻，保障居民的财产安全。", "error_description": "“了”误放在动词“保障”之前。“了”不能放在动词前，此处不需要表示完成，应删去“了”，说“保障居民的财产安全”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宪法保障着了公民的言论自由。", "corrected_sentence": "宪法保障着公民的言论自由。", "error_description": "“保障”后不能同时用“着”和“了”。这里说法律持续保护，应删去“了”，说“保障着公民的言论自由”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
