INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11072, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11072, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "物体保持自身原有运动状态或静止状态的性质，是物体本身的一种属性，与是否受力无关。", "primary_collocate": null, "pronunciation": "guàn xìng", "ipa": "kwan⁵¹ ɕiŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "高速列车紧急制动时，车厢仍会因惯性继续向前冲，所以制动距离必须提前精确计算。", "target_word": "惯性", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "飞船关闭推进器后，仍会凭借惯性保持原有速度滑行，因此轨道修正必须依赖精确的数据。", "target_word": "惯性", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "列车突然启动时，站着的乘客会因为惯性而向后倾，所以司机必须平稳地加速。", "target_word": "惯性", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "车突然停下，人因为惯性向前倒。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车刹车时，乘客会因为惯性向前冲。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物体都有惯性，所以很难马上停下来。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头很重，惯性也大，不容易推动。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球离开手以后，靠惯性继续向前滚。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "质量越大，物体的惯性越大。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰面光滑，车即使刹车也会因惯性滑出很远才停下。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "惯性力", "label": "复合"}, {"form": "惯性定律", "label": "复合"}, {"form": "惯性思维", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体保持原有运动或静止状态的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc9b4b69-ef94-4dfb-a579-4a5298524f1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "惯例", "is_correct": false, "explanation": "语义：“惯例”指长期形成的做法或规矩，与车厢的运动无关。"}, {"text": "惯性", "is_correct": true, "explanation": "惯性指物体保持原有运动或静止状态的性质，是本词的物理义项。"}, {"text": "方向", "is_correct": false, "explanation": "语义：“方向”指位置或走向，不能使车厢因它向前冲，“因方向向前冲”不通。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不能使车厢向前冲，“因温度向前冲”不通。"}], "explanations": {"惯例": "语义：“惯例”指长期形成的做法或规矩，与车厢的运动无关。", "惯性": "惯性指物体保持原有运动或静止状态的性质，是本词的物理义项。", "方向": "语义：“方向”指位置或走向，不能使车厢因它向前冲，“因方向向前冲”不通。", "温度": "搭配：“温度”不能使车厢向前冲，“因温度向前冲”不通。"}, "sentence_index": 0, "correct_answer": "惯性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车受到了很大的惯性，所以一下子就停住了。", "explanation": "这里应该用〈外力〉。外力是施加在物体上的力，可以说“受到”；惯性是物体保持运动状态的性质，不是外来的力，不能说“受到”。"}, {"text": "这辆车的惯性太快，刹车来不及。", "explanation": "这里应该用〈速度〉。速度说物体运动的快慢，可以说“快”；惯性是保持运动状态的性质，不能用快慢来形容。"}, {"text": "冰面的惯性很小，车很难停下来。", "explanation": "这里应该用〈摩擦〉。冰面摩擦力小，车才难停；惯性是物体自身的性质，不是冰面的性质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”一般说深浅，不说“大”，“颜色也大”不通。"}, {"text": "惯性", "is_correct": true, "explanation": "惯性指物体保持原有运动或静止状态的性质，“石头很重，惯性也大”符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能被推动，与“不容易推动”的语境矛盾。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“方向”不说大小，“方向也大”不通。"}], "explanations": {"颜色": "搭配：“颜色”一般说深浅，不说“大”，“颜色也大”不通。", "惯性": "惯性指物体保持原有运动或静止状态的性质，“石头很重，惯性也大”符合句意。", "声音": "语义：声音不能被推动，与“不容易推动”的语境矛盾。", "方向": "搭配：“方向”不说大小，“方向也大”不通。"}, "sentence_index": 6, "correct_answer": "惯性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冰上的车很难停，因为惯性太小。", "explanation": "这里应该用〈阻力〉。冰面阻力小，车才难停；惯性太小反而容易停，与句意矛盾。"}, {"text": "这辆车有很强的惯性，一加速就跑得很快。", "explanation": "这里应该用〈动力〉。动力能推动车加速；惯性是保持运动或静止状态的性质，不能使车加速，两者不能互换。"}, {"text": "这辆车的惯性很重，所以很难停。", "explanation": "这里应该用〈质量〉。惯性是性质，不能用“重”来形容；“重”说的是质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车有很惯性，所以刹车时要提前。", "corrected_sentence": "车有惯性，所以刹车时要提前。", "error_description": "错误：“车有很惯性”，正确：“车有惯性”。“惯性”是名词，不能直接用程度副词“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车的一个惯性很大，刹车要提前。", "corrected_sentence": "车的惯性很大，刹车要提前。", "error_description": "错误：“车的一个惯性很大”，正确：“车的惯性很大”。“惯性”是抽象名词，不能用量词“个”计量，应直接说“车的惯性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
