INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11073, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指通过互联网或网络，在发送信息和接收信息之间几乎没有延迟的通信方式。", "primary_collocate": null, "pronunciation": "jí shí tōng xùn", "ipa": "tɕi³⁵ ʂɻ̩³⁵ tʰʊŋ⁵⁵ ɕyn⁵¹", "syllable_count": 4, "sentences": [{"text": "即时通讯与远程协作工具，无形中推广了“即时响应”的新守时性标准，模糊了地理时区与文化时区的双重界限。", "target_word": "即时通讯", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们用即时通讯和朋友聊天。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要求大家用即时通讯发消息，不要打电话。", "target_word": "即时通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种即时通讯很方便，发出去就能收到回话。", "target_word": "即时通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈刚学会用即时通讯，常给我发照片。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了即时通讯，远方的家人也能马上收到消息。", "target_word": "即时通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时同事们用即时通讯讨论问题。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢用即时通讯，不喜欢发邮件。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在即时通讯里回答了学生的问题。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即时通讯让沟通变得更快。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "即时通讯软件", "label": "复合词"}], "register": "中性", "sense_fingerprint": "网络上发出和收到信息几乎没有延迟的通信方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51183fcd-ff4c-496a-b5ac-da5409e35aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11073, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "即时通讯", "is_correct": true, "explanation": "正确：作主语，指这类通信工具，与“远程协作工具”并列，句意通顺。"}, {"text": "面对面会议", "is_correct": false, "explanation": "语义：“面对面”与句中的“远程”相悖，不能与“远程协作工具”并列。"}, {"text": "纸质信件", "is_correct": false, "explanation": "语义：纸质信件不能即时送达，与句中“即时响应”的标准相矛盾。"}, {"text": "传统邮政", "is_correct": false, "explanation": "搭配：“传统邮政”无法推广“即时响应”的守时标准，搭配不当。"}], "explanations": {"即时通讯": "正确：作主语，指这类通信工具，与“远程协作工具”并列，句意通顺。", "面对面会议": "语义：“面对面”与句中的“远程”相悖，不能与“远程协作工具”并列。", "纸质信件": "语义：纸质信件不能即时送达，与句中“即时响应”的标准相矛盾。", "传统邮政": "搭配：“传统邮政”无法推广“即时响应”的守时标准，搭配不当。"}, "sentence_index": 0, "correct_answer": "即时通讯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我下载了一只即时通讯。", "explanation": "这里应该用〈款〉。即时通讯指一种通讯软件，量词应用“款”或“个”，“只”一般用于动物或成对的东西。"}, {"text": "即时通讯今天请假了，没来上班。", "explanation": "这里应该用〈同事〉。即时通讯是通信方式或软件，不是人，不能“请假”“上班”。"}, {"text": "请在这份即时通讯上签字，然后交给我。", "explanation": "这里应该用〈合同〉。即时通讯是通信方式或软件，不是需要签字的文件，“签字”应搭配合同、协议等文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "即时通讯", "is_correct": true, "explanation": "正确：作“用”的宾语，指一种通讯工具，可以用来开会讨论。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不能用来讨论问题，与“讨论问题”的语义不合。"}, {"text": "信封", "is_correct": false, "explanation": "搭配：信封不是讨论的工具，“用信封讨论问题”搭配不当。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套与“讨论问题”毫不相干，句子无法成立。"}], "explanations": {"即时通讯": "正确：作“用”的宾语，指一种通讯工具，可以用来开会讨论。", "闹钟": "语义：闹钟不能用来讨论问题，与“讨论问题”的语义不合。", "信封": "搭配：信封不是讨论的工具，“用信封讨论问题”搭配不当。", "手套": "语义：手套与“讨论问题”毫不相干，句子无法成立。"}, "sentence_index": 6, "correct_answer": "即时通讯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用即时通讯寄了一个包裹给同学。", "explanation": "这里应该用〈快递〉。即时通讯只能传送消息，不能运送实物，寄包裹要用快递或邮寄。"}, {"text": "这台即时通讯很重，搬起来很累。", "explanation": "这里应该用〈手机〉。即时通讯是软件或服务，没有重量，不能用“很重”和“搬”来形容，应说“手机很重，搬起来很累”。"}, {"text": "我的即时通讯今天没来上课。", "explanation": "这里应该用〈同学〉。即时通讯是通信方式，不是人，不能说它“没来上课”，应指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每晚用即时通讯的和朋友聊天。", "corrected_sentence": "他每晚用即时通讯和朋友聊天。", "error_description": "多余的“的”：“用即时通讯”后面直接接“和朋友聊天”，中间不能加“的”，应说“用即时通讯和朋友聊天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开会时同事们用一只即时通讯解决问题。", "corrected_sentence": "开会时同事们用一种即时通讯解决问题。", "error_description": "量词错误：“即时通讯”指通讯工具，应搭配“种”，“只”用于动物或成对的东西，应说“用一种即时通讯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11074, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11074, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11074, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指距离很远，或通过电子设备连接远处。", "primary_collocate": null, "pronunciation": "yuǎn chéng", "ipa": "ɥɛn˨˩˦ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "即时通讯与远程协作工具，无形中推广了“即时响应”的新守时性标准，模糊了地理时区与文化时区的双重界限。", "target_word": "远程", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们公司现在可以远程办公了。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用视频远程看病。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在家远程上课，不用去学校。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑可以远程控制。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远程会议九点开始，请准时上线。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸出差时，我们常常远程聊天。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术人员远程修好了我的手机。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远程教育让山区的孩子也能学习。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用远程方式检查作业。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "远程教育", "label": "复合"}, {"form": "遠程", "label": "繁体"}], "register": "中性", "sense_fingerprint": "借助网络或设备在远处进行的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a94ae4-79af-4eab-97ed-f48899b3b919') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远程", "is_correct": true, "explanation": "远程：借助网络或设备在远处进行，此处修饰“协作工具”。"}, {"text": "古老", "is_correct": false, "explanation": "语义：“古老”指年代久远，与前文的“即时”相矛盾。"}, {"text": "平坦", "is_correct": false, "explanation": "搭配：“平坦”形容地面或道路，不能用来修饰协作工具。"}, {"text": "亲密", "is_correct": false, "explanation": "搭配：“亲密”形容人与人之间的关系，不能用来修饰工具。"}], "explanations": {"远程": "远程：借助网络或设备在远处进行，此处修饰“协作工具”。", "古老": "语义：“古老”指年代久远，与前文的“即时”相矛盾。", "平坦": "搭配：“平坦”形容地面或道路，不能用来修饰协作工具。", "亲密": "搭配：“亲密”形容人与人之间的关系，不能用来修饰工具。"}, "sentence_index": 0, "correct_answer": "远程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他远程扶起了摔倒的老人。", "explanation": "这里应该用〈亲手〉。扶人需要身体直接接触，不是借助网络或设备完成的事，也不是远距离的事，应说亲手扶起老人。"}, {"text": "他远程给了我一个拥抱。", "explanation": "这里应该用〈当面〉。拥抱需要身体直接接触，不能借助网络或设备远程完成，应说当面拥抱。"}, {"text": "社区工作人员远程给老人喂药。", "explanation": "这里应该用〈亲手〉。喂药需要人在身边直接操作，不能远程完成，应说亲手喂药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远程", "is_correct": true, "explanation": "远程：借助网络或设备在远处进行，此处指通过设备聊天。"}, {"text": "同城", "is_correct": false, "explanation": "语义：同城指在同一座城市，与“爸爸出差”的情况矛盾。"}, {"text": "面对面", "is_correct": false, "explanation": "语义：面对面指直接见面，与“爸爸出差”的情况矛盾。"}, {"text": "亲笔", "is_correct": false, "explanation": "搭配：“亲笔”修饰书信或文字，不能用来修饰“聊天”。"}], "explanations": {"远程": "远程：借助网络或设备在远处进行，此处指通过设备聊天。", "同城": "语义：同城指在同一座城市，与“爸爸出差”的情况矛盾。", "面对面": "语义：面对面指直接见面，与“爸爸出差”的情况矛盾。", "亲笔": "搭配：“亲笔”修饰书信或文字，不能用来修饰“聊天”。"}, "sentence_index": 6, "correct_answer": "远程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他远程给奶奶剪了头发。", "explanation": "这里应该用〈亲手〉。剪头发需要人在身边直接动手，不能借助网络或设备远程完成，应说亲手给奶奶剪头发。"}, {"text": "妈妈远程给孩子洗了一个澡。", "explanation": "这里应该用〈亲手〉。远程只修饰可以借助设备完成的活动，给孩子洗澡需要身体直接接触，应说亲手给孩子洗澡。"}, {"text": "他远程握了朋友的手。", "explanation": "这里应该用〈当面〉。握手需要双方身体直接接触，远程只用于借助设备完成的事，应说当面握手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师可以很远程调试这台机器。", "corrected_sentence": "工程师可以远程调试这台机器。", "error_description": "“远程”作状语修饰“调试”，前面不能再加“很”。应说“远程调试”，“很远程”是错误搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们已经远程办公两年着。", "corrected_sentence": "他们已经远程办公两年了。", "error_description": "句末应用“了”，不能用“着”。“已经……两年了”表示到现在为止已完成的时长；“着”表示动作正在持续的状态，与“已经”不相合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
