INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11076, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指在人的意识或感觉不到的情况下，不知不觉地发生或产生影响。", "primary_collocate": null, "pronunciation": "wú xíng zhōng", "ipa": "u³⁵ ɕiŋ³⁵ ʈʂʊŋ⁵⁵", "syllable_count": 3, "sentences": [{"text": "即时通讯与远程协作工具，无形中推广了“即时响应”的新守时性标准，模糊了地理时区与文化时区的双重界限。", "target_word": "无形中", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他每天听中文歌，无形中学会了不少词。", "target_word": "无形中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在无形中学着大人说话。", "target_word": "无形中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的鼓励无形中给了我很大的信心。", "target_word": "无形中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "常和朋友聊天，无形中提高了我的口语。", "target_word": "无形中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着说话，无形中让大家放松了。", "target_word": "无形中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在中国的几年里，无形中我也习惯了早起。", "target_word": "无形中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的广告无形中影响了很多年轻人。", "target_word": "无形中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸总是早起，无形中我也养成了早起的习惯。", "target_word": "无形中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了很多电影后，他的英语无形中变好了。", "target_word": "无形中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人没有察觉的情况下不知不觉产生影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51183fcd-ff4c-496a-b5ac-da5409e35aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11076, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无形中", "is_correct": true, "explanation": "正确：作状语，表示不知不觉地推广，句意通顺。"}, {"text": "愤怒地", "is_correct": false, "explanation": "语义：“愤怒”是情绪，不能修饰推广标准这类客观行为，句意不通。"}, {"text": "大张旗鼓地", "is_correct": false, "explanation": "语义：“大张旗鼓”指公开而声势浩大，与“无形中”不知不觉的意思正相反，不能修饰句中的推广。"}, {"text": "当场", "is_correct": false, "explanation": "语义：“当场”指就在那个时间地点立刻发生，不能修饰“推广……标准”这类逐步产生的影响。"}], "explanations": {"无形中": "正确：作状语，表示不知不觉地推广，句意通顺。", "愤怒地": "语义：“愤怒”是情绪，不能修饰推广标准这类客观行为，句意不通。", "大张旗鼓地": "语义：“大张旗鼓”指公开而声势浩大，与“无形中”不知不觉的意思正相反，不能修饰句中的推广。", "当场": "语义：“当场”指就在那个时间地点立刻发生，不能修饰“推广……标准”这类逐步产生的影响。"}, "sentence_index": 0, "correct_answer": "无形中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我特意无形中去超市买了一箱牛奶。", "explanation": "这里的“无形中”表示不知不觉，与有意识安排的行动相矛盾，应去掉“无形中”。"}, {"text": "他知道自己错了，无形中向大家道歉了。", "explanation": "道歉必须有意识地做出，“无形中”只用于不知不觉发生的事，应说“主动道歉”。"}, {"text": "我想了很久，决定无形中辞职。", "explanation": "这里的“无形中”表示不知不觉，而经过深思的选择必须有意识地做出，二者相互矛盾，应去掉“无形中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无形中", "is_correct": true, "explanation": "正确：作状语，表示几年间不知不觉地养成习惯，与“几年里”呼应。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“习惯……早起”需要时间养成，“立刻”与“几年里”的渐进过程搭配不当。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“习惯”的长期性矛盾。"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”指突然发生，与“住在中国的几年里”的渐变过程相悖。"}], "explanations": {"无形中": "正确：作状语，表示几年间不知不觉地养成习惯，与“几年里”呼应。", "立刻": "搭配：“习惯……早起”需要时间养成，“立刻”与“几年里”的渐进过程搭配不当。", "偶尔": "语义：“偶尔”表示不常发生，与“习惯”的长期性矛盾。", "猛然": "语义：“猛然”指突然发生，与“住在中国的几年里”的渐变过程相悖。"}, "sentence_index": 6, "correct_answer": "无形中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你无形中把窗户关上。", "explanation": "这里的“无形中”表示不知不觉，而要求他人做事是有意识的行为，二者矛盾，应去掉“无形中”。"}, {"text": "他无形中对老师撒了谎。", "explanation": "这里的“无形中”表示不知不觉，而欺骗他人是有意的行为，二者矛盾，应去掉“无形中”。"}, {"text": "我无形中提前三天通知了全班。", "explanation": "这里的“无形中”表示不知不觉，而“有意去做”的事与之矛盾，应去掉“无形中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门课没有作业，我无形中地学会了很多。", "corrected_sentence": "这门课没有作业，我无形中学会了很多。", "error_description": "多余的“地”：“无形中”本身是副词，后面不能再加“地”。正确说法是“无形中学会了很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年锻炼以后，他的身体无形中地变好了。", "corrected_sentence": "这几年锻炼以后，他的身体无形中变好了。", "error_description": "多余的“地”：“无形中”是副词，后面不能再加“地”。正确说法是“他的身体无形中变好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11078, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11078, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11078, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对某种号召、要求等表示同意并采取行动。", "primary_collocate": null, "pronunciation": "xiǎng yìng", "ipa": "ɕiaŋ˨˩˦ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "与此同时，部分发展中国家亦积极响应这一倡议，陆续出台了配套的国内政策。", "target_word": "响应", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "即时通讯与远程协作工具，无形中让人们习惯于对同事的工作请求即时响应，这种新的守时标准模糊了地理时区与文化时区的双重界限。", "target_word": "响应", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "很多市民响应政府的号召，节约用水。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们热烈响应学校的号召，积极报名参加。", "target_word": "响应", "complexity_tier": "T3", "furigana": "xiǎng yìng", "sentence_source": "generated"}, {"text": "我们要响应环保号召，少用塑料袋。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都响应他的提议，一起去植树。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师号召大家读书，同学们积极响应。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司响应国家号召，招了很多新人。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一个响应了这次捐书的号召。", "target_word": "响应", "complexity_tier": "T3", "furigana": "xiǎng yìng", "sentence_source": "generated"}, {"text": "社区发出号召后，居民很快响应了。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "响应了", "label": "完成体"}, {"form": "响应过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "响应：对号召、要求等表示赞同并采取行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af392f55-520a-41c6-8a55-f0d8a216dfb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "响应", "is_correct": true, "explanation": "正确。“积极响应这一倡议”指主动表示赞同并采取行动，与句意相符。"}, {"text": "声响", "is_correct": false, "explanation": "语义：“声响”指声音，不能用来表示对倡议的行动，句子不通。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：“病毒”是生物或程序，不能用来表示对倡议的行动，与句意不合。"}, {"text": "灯光", "is_correct": false, "explanation": "搭配：“积极”后应接表示行动的词，“灯光”不能与“积极”搭配。"}], "explanations": {"响应": "正确。“积极响应这一倡议”指主动表示赞同并采取行动，与句意相符。", "声响": "语义：“声响”指声音，不能用来表示对倡议的行动，句子不通。", "病毒": "语义：“病毒”是生物或程序，不能用来表示对倡议的行动，与句意不合。", "灯光": "搭配：“积极”后应接表示行动的词，“灯光”不能与“积极”搭配。"}, "sentence_index": 0, "correct_answer": "响应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师问我作业写得怎样，我很快响应了。", "explanation": "这里应该用〈答复〉。“答复”用于回答询问或来信，“响应”指对号召、要求采取行动，不用于答复问题。"}, {"text": "他在辩论中响应了对方的论点。", "explanation": "这里应该用〈反驳〉。“反驳”用于驳斥对方的观点或论点，“响应”指对号召、要求采取行动，不用于论点。"}, {"text": "他很快响应了这道数学题。", "explanation": "这里应该用〈解答〉。“解答”用于解决问题、习题，“响应”不能用于题目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "响应", "is_correct": true, "explanation": "正确。“同学们积极响应”指同学们对老师的号召积极行动，句意通顺。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或光灭掉，不能用来描述同学们的行动，句子不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“积极”不修饰“睡觉”，“同学们积极睡觉”与号召读书的语境相悖。"}, {"text": "报废", "is_correct": false, "explanation": "语义：“报废”指器物不能再使用，不能用来描述人的行动。"}], "explanations": {"响应": "正确。“同学们积极响应”指同学们对老师的号召积极行动，句意通顺。", "熄灭": "语义：“熄灭”指火或光灭掉，不能用来描述同学们的行动，句子不通。", "睡觉": "搭配：“积极”不修饰“睡觉”，“同学们积极睡觉”与号召读书的语境相悖。", "报废": "语义：“报废”指器物不能再使用，不能用来描述人的行动。"}, "sentence_index": 6, "correct_answer": "响应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学发来的消息，我当天就响应了。", "explanation": "这里应该用〈回复〉。“回复”用于答复消息、来信，“响应”指对号召、要求采取行动，不用于消息。"}, {"text": "有人骂他，他立刻响应了。", "explanation": "这里应该用〈回击〉。“回击”指对辱骂、攻击予以还击，“响应”不表示还击。"}, {"text": "朋友寄来一封信，他一周后才响应。", "explanation": "这里应该用〈回信〉。“回信”指写信答复来信，“响应”不用于书信往来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区发出号召后，大家都没有响应掉。", "corrected_sentence": "社区发出号召后，大家都没有响应。", "error_description": "错误：“响应掉”。“响应”后不能接结果补语“掉”，“掉”多用于消失、脱落的动作，应去掉“掉”，说“没有响应”。", "correct_sentence_indices": [0, 2, 4]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板发出号召后，员工们很快响应了了。", "corrected_sentence": "老板发出号召后，员工们很快响应了。", "error_description": "错误：“响应了了”。动态助词“了”只用一个，正确为“响应了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11080, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清楚", "is_correct": true, "explanation": "清楚与模糊构成反义，指事物或表达明白、不含糊。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹形容场面喧闹，与模糊无反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地，与模糊无反义关系。"}, {"text": "富有", "is_correct": false, "explanation": "富有形容拥有很多或充足，与模糊无反义关系。"}], "correct_answer": "清楚", "explanations": {"清楚": "清楚与模糊构成反义，指事物或表达明白、不含糊。", "热闹": "热闹形容场面喧闹，与模糊无反义关系。", "柔软": "柔软形容质地，与模糊无反义关系。", "富有": "富有形容拥有很多或充足，与模糊无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11080, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清晰", "is_correct": true, "explanation": "清晰与模糊构成反义，指轮廓分明、表达明确。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速形容速度快，与模糊无反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢形容性格，与模糊无反义关系。"}, {"text": "宽广", "is_correct": false, "explanation": "宽广形容面积或范围大，与模糊无反义关系。"}], "correct_answer": "清晰", "explanations": {"清晰": "清晰与模糊构成反义，指轮廓分明、表达明确。", "迅速": "迅速形容速度快，与模糊无反义关系。", "勇敢": "勇敢形容性格，与模糊无反义关系。", "宽广": "宽广形容面积或范围大，与模糊无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11080, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物轮廓不清、印象不深或表达不明确。", "primary_collocate": null, "pronunciation": "mó hu", "ipa": "mwɔ˧˥ xu", "syllable_count": 2, "sentences": [{"text": "这份合同中关于违约责任的条款表述十分模糊，双方因此在纠纷发生后各执一词。", "target_word": "模糊", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "复杂的跨国供应链将生产环节层层外包，导致环境责任模糊，监管链条断裂。", "target_word": "模糊", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他的回答很模糊，我还是不知道该怎么办。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题的答案太模糊了，老师让我再写一遍。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的事，我只有模糊的印象。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条规定写得很模糊，大家的看法都不一样。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得太模糊了，请说清楚一点。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这件事，他的态度一直很模糊，没人知道他支持谁。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次旅行已经过去很久，很多细节都模糊了。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个词的意思有点模糊，要看上下文。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "模模糊糊", "label": "重叠"}], "register": "中性", "sense_fingerprint": "形容词；事物、印象或表达不清楚、不明确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc9b4b69-ef94-4dfb-a579-4a5298524f1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11080, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "模糊", "is_correct": true, "explanation": "正确答案。模糊指轮廓不清、印象不深或表达不明确。"}, {"text": "蘑菇", "is_correct": false, "explanation": "第二音节声母不同：蘑菇的 g 与模糊的 h 不同。蘑菇指食用菌。"}, {"text": "磨合", "is_correct": false, "explanation": "第二音节声调不同：磨合的 hé 为第二声，模糊的 hu 为轻声。磨合指互相适应。"}, {"text": "迷糊", "is_correct": false, "explanation": "第一音节韵母不同：迷糊的 i 与模糊的 o 不同。迷糊指头脑不清醒。"}], "explanations": {"模糊": "正确答案。模糊指轮廓不清、印象不深或表达不明确。", "蘑菇": "第二音节声母不同：蘑菇的 g 与模糊的 h 不同。蘑菇指食用菌。", "磨合": "第二音节声调不同：磨合的 hé 为第二声，模糊的 hu 为轻声。磨合指互相适应。", "迷糊": "第一音节韵母不同：迷糊的 i 与模糊的 o 不同。迷糊指头脑不清醒。"}, "sentence_index": null, "correct_answer": "模糊"}, "level_3": {"options": [{"text": "模糊", "is_correct": true, "explanation": "模糊：表述不明确，所以双方理解不同、各执一词，符合句意。"}, {"text": "准确", "is_correct": false, "explanation": "语义：条款表述准确就不会各执一词，与后句矛盾。"}, {"text": "优美", "is_correct": false, "explanation": "搭配：“优美”形容文学语言或风景，不用来评价合同条款。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”指价格高，不能形容条款的表述。"}], "explanations": {"模糊": "模糊：表述不明确，所以双方理解不同、各执一词，符合句意。", "准确": "语义：条款表述准确就不会各执一词，与后句矛盾。", "优美": "搭配：“优美”形容文学语言或风景，不用来评价合同条款。", "昂贵": "语义：“昂贵”指价格高，不能形容条款的表述。"}, "sentence_index": 0, "correct_answer": "模糊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人很模糊，做事常常出错。", "explanation": "这里应该用〈糊涂〉。糊涂形容人头脑不清、办事不明白；模糊形容事物的轮廓、印象或表达不清，不用来说人的头脑或办事能力。"}, {"text": "今天的天气很模糊，太阳又大又亮。", "explanation": "这里应该用〈晴朗〉。太阳又大又亮说明天气好；模糊指轮廓或表达不清，与句意矛盾。"}, {"text": "他跑步跑得很模糊，比赛时总是输。", "explanation": "模糊不用来形容动作的快慢，这里应该说〈快〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模糊", "is_correct": true, "explanation": "模糊：说话不清楚，与后句“请说清楚一点”相合。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“你说得太清楚了”与后句“请说清楚一点”矛盾，说话者不会要求别人把已经清楚的话再说清楚。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不能用来形容说话的内容。"}, {"text": "浑浊", "is_correct": false, "explanation": "搭配：“浑浊”多用于水、空气等，不用来形容说话。"}], "explanations": {"模糊": "模糊：说话不清楚，与后句“请说清楚一点”相合。", "清楚": "语义：“你说得太清楚了”与后句“请说清楚一点”矛盾，说话者不会要求别人把已经清楚的话再说清楚。", "热闹": "搭配：“热闹”形容场面或气氛，不能用来形容说话的内容。", "浑浊": "搭配：“浑浊”多用于水、空气等，不用来形容说话。"}, "sentence_index": 6, "correct_answer": "模糊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的内存很模糊，正好是八个G。", "explanation": "这里应该用〈确切〉。模糊指轮廓或印象不清；内存容量是确定的数字，要用“确切”来形容，不能说模糊。"}, {"text": "我的身高很模糊，已经超过一米八了。", "explanation": "身高是可以量出的数值，模糊不用来描述身高，这里应该说〈高〉。"}, {"text": "这个司机很模糊，开车总是走错路。", "explanation": "这里应该用〈糊涂〉。糊涂形容人头脑不清、办事不明白，模糊不用来形容人的头脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张照片得模糊，看不清人脸。", "corrected_sentence": "这张照片很模糊，看不清人脸。", "error_description": "错误：“得”不能直接放在主语与形容词之间，这里应用程度副词“很”。正确：“很模糊”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的字写很模糊，老师看不懂。", "corrected_sentence": "他的字写得很模糊，老师看不懂。", "error_description": "错误：“写很模糊”，正确：“写得很模糊”。描述动作的结果或程度时，动词后要用“得”引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
