INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11081, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地理是研究地球表面自然现象和人文现象的空间分布、相互关系及其发展规律的科学。", "primary_collocate": null, "pronunciation": "dì lǐ", "ipa": "ti˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "同学们都说，地理是最有意思的科目。", "target_word": "地理", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "我们在地理课上学到了世界各地的时区划分。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最喜欢的课是地理。", "target_word": "地理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学好地理要多看地图。", "target_word": "地理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地理老师给我们看了一张世界地图。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地理考试里有很多关于河流和山的问题。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对地理很感兴趣，课后常常看地图。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地理研究的是地球表面的自然和人文现象。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学学的是地理，现在在中学教书。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地理和历史都是我们这学期要考的科目。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地理学", "label": "复合"}, {"form": "地理课", "label": "复合"}], "register": "通用", "sense_fingerprint": "研究地球表面自然与人文现象的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eea9ae5a-a1c2-46b4-ba5e-281e3260ca2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11081, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地理", "is_correct": true, "explanation": "正确：“地理”读 dì lǐ，指地球表面的自然与人文状况。"}, {"text": "治理", "is_correct": false, "explanation": "声母不同：zhì（第四声）与 dì（第四声）的声母 zh 与 d 不同，意思是管理、整治。"}, {"text": "地雷", "is_correct": false, "explanation": "韵母与声调不同：léi（第二声）与 lǐ（第三声）不同，意思是埋在地下的爆炸装置。"}, {"text": "地利", "is_correct": false, "explanation": "声调不同：lì（第四声）与 lǐ（第三声）声调不同，意思是地理上的有利条件。"}], "explanations": {"地理": "正确：“地理”读 dì lǐ，指地球表面的自然与人文状况。", "治理": "声母不同：zhì（第四声）与 dì（第四声）的声母 zh 与 d 不同，意思是管理、整治。", "地雷": "韵母与声调不同：léi（第二声）与 lǐ（第三声）不同，意思是埋在地下的爆炸装置。", "地利": "声调不同：lì（第四声）与 lǐ（第三声）声调不同，意思是地理上的有利条件。"}, "sentence_index": null, "correct_answer": "地理"}, "level_3": {"options": [{"text": "地理", "is_correct": true, "explanation": "正确：“地理”指地理学科，可以作“科目”，与“最有意思的科目”相配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指冷热阴晴，不是学科，不能作科目。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不是学科，不能作科目。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指身体的重量，不能作科目，与“最有意思的科目”不搭配。"}], "explanations": {"地理": "正确：“地理”指地理学科，可以作“科目”，与“最有意思的科目”相配。", "天气": "语义：“天气”指冷热阴晴，不是学科，不能作科目。", "颜色": "语义：“颜色”指色彩，不是学科，不能作科目。", "体重": "搭配：“体重”指身体的重量，不能作科目，与“最有意思的科目”不搭配。"}, "sentence_index": 0, "correct_answer": "地理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地理的人口很少，大多数人住在山里。", "explanation": "这里应该用〈地区〉。“地理”指学科或地表的自然状况，说某个区域的人口要用“地区”。"}, {"text": "这张地理很详细，每个城市都标出来了。", "explanation": "这里应该用〈地图〉。“地理”是学科，不指纸上的图，“这张”后面要接“地图”。"}, {"text": "这里的地理很温和，一年四季都很舒服。", "explanation": "这里应该用〈气候〉。“地理”指地表的自然与人文状况，不能用来形容冷热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11081, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地理", "is_correct": true, "explanation": "正确：“对地理很感兴趣”指对该学科有兴趣，后句“课后常常看地图”与之呼应。"}, {"text": "台阶", "is_correct": false, "explanation": "搭配：“感兴趣”的对象一般是学科、爱好或事物类别，“台阶”不能作感兴趣的对象。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不能作为感兴趣的对象。"}, {"text": "门口", "is_correct": false, "explanation": "搭配：“门口”指位置，不能说“对门口很感兴趣”。"}], "explanations": {"地理": "正确：“对地理很感兴趣”指对该学科有兴趣，后句“课后常常看地图”与之呼应。", "台阶": "搭配：“感兴趣”的对象一般是学科、爱好或事物类别，“台阶”不能作感兴趣的对象。", "窗户": "语义：“窗户”是建筑部件，不能作为感兴趣的对象。", "门口": "搭配：“门口”指位置，不能说“对门口很感兴趣”。"}, "sentence_index": 6, "correct_answer": "地理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的地理很多，每天都很热闹。", "explanation": "这里应该用〈人口〉。“地理”指学科或地形分布，说人数多少要用“人口”。"}, {"text": "这条地理很长，走一圈要半个小时。", "explanation": "这里应该用〈街道〉。“地理”不能用“这条”来计量，街道的长短要用“街道”。"}, {"text": "这座楼的地理很稳，地震也不怕。", "explanation": "这里应该用〈结构〉。“地理”指地形分布，楼房稳不稳要用“结构”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这学期选了一个地理，每周上三节课。", "corrected_sentence": "他这学期选了一门地理，每周上三节课。", "error_description": "量词错误：“地理”作为课程要用“门”，不能用“个”；正确为“一门地理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹最喜欢的科目地理，她每周都去上课。", "corrected_sentence": "妹妹最喜欢的科目是地理，她每周都去上课。", "error_description": "漏了判断动词“是”：“最喜欢的科目是地理”中的“是”不能省略，错句直接把“地理”接在名词后，不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11082, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11082, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "时区是指地球上使用相同标准时间的区域，每个时区大致按经度划分，相邻时区通常相差一小时。", "primary_collocate": null, "pronunciation": "shí qū", "ipa": "ʂɻ̩³⁵ tɕʰy⁵⁵", "syllable_count": 2, "sentences": [{"text": "即时通讯与远程协作工具，无形中推广了“即时响应”的新守时性标准，模糊了地理时区与文化时区的双重界限。", "target_word": "时区", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "中国只有一个时区，叫北京时间。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "美国有好几个时区。", "target_word": "时区", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北京和伦敦不在同一个时区。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出国旅行要先改手机上的时区。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机飞过三个时区后，我很累。", "target_word": "时区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同时区的同事很难一起开会。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你现在在哪个时区？", "target_word": "时区", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每次换时区都睡不好觉。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "相邻的两个时区通常差一个小时。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "地球上使用相同标准时间的区域，按经度划分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51183fcd-ff4c-496a-b5ac-da5409e35aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11082, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时区", "is_correct": true, "explanation": "正确：时区指地球上使用相同标准时间的区域。"}, {"text": "市区", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是市区，即城市内部的区域。"}, {"text": "时期", "is_correct": false, "explanation": "qī 与 qū 的韵母不同（ī 与 ū），意思是时期，即一段时间。"}, {"text": "失去", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）、qù（第四声）与 qū（第一声）声调都不同，意思是失去。"}, {"text": "拾取", "is_correct": false, "explanation": "声调混淆：shí qǔ 与 shí qū 仅第二字声调不同，意思是拾取，即捡起来。"}], "explanations": {"时区": "正确：时区指地球上使用相同标准时间的区域。", "市区": "shì（第四声）与 shí（第二声）声调不同，意思是市区，即城市内部的区域。", "时期": "qī 与 qū 的韵母不同（ī 与 ū），意思是时期，即一段时间。", "失去": "shī（第一声）与 shí（第二声）、qù（第四声）与 qū（第一声）声调都不同，意思是失去。", "拾取": "声调混淆：shí qǔ 与 shí qū 仅第二字声调不同，意思是拾取，即捡起来。"}, "sentence_index": null, "correct_answer": "时区"}, "level_3": {"options": [{"text": "时区", "is_correct": true, "explanation": "正确：“地理时区”指按经度划分的时区，与“文化时区”相对。"}, {"text": "语言", "is_correct": false, "explanation": "语义：地理界限不按语言划分，“地理语言”说不通。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：地理界限不由饮食习惯决定，填入“饮食”后句子不成立。"}, {"text": "节日", "is_correct": false, "explanation": "搭配：“地理”多修饰山川、地形，不能说“地理节日”。"}], "explanations": {"时区": "正确：“地理时区”指按经度划分的时区，与“文化时区”相对。", "语言": "语义：地理界限不按语言划分，“地理语言”说不通。", "饮食": "语义：地理界限不由饮食习惯决定，填入“饮食”后句子不成立。", "节日": "搭配：“地理”多修饰山川、地形，不能说“地理节日”。"}, "sentence_index": 0, "correct_answer": "时区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北京和伦敦的时区是八个小时。", "explanation": "这里应该用〈时差〉。时差指两地时间相差的小时数，时区是划分地区的范围，不能说“是八个小时”。"}, {"text": "我从北京飞到伦敦，一共花了十二个小时的时区。", "explanation": "这里应该用〈时间〉。“花了十二个小时”指经历的时长，时区是划分区域的概念，不能表示时长。"}, {"text": "今天的时区很冷，要多穿衣服。", "explanation": "这里应该用〈天气〉。天气才有冷热，时区是按经度划分的区域，不能说“很冷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11082, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时区", "is_correct": true, "explanation": "正确：时区指地球上使用相同标准时间的区域。"}, {"text": "诗曲", "is_correct": false, "explanation": "声调混淆：shī qǔ 与 shí qū 仅声调不同，意思是诗与曲，即诗歌和歌曲。"}, {"text": "诗趣", "is_correct": false, "explanation": "声调混淆：shī qù 与 shí qū 仅声调不同，意思是诗的趣味，即诗歌的韵味。"}, {"text": "尸躯", "is_correct": false, "explanation": "声调混淆：shī qū 与 shí qū 仅第一字声调不同，意思是尸体。"}, {"text": "识趣", "is_correct": false, "explanation": "shí 相同，qù（第四声）与 qū（第一声）只有声调不同，意思是识趣，即懂得分寸。"}], "explanations": {"时区": "正确：时区指地球上使用相同标准时间的区域。", "诗曲": "声调混淆：shī qǔ 与 shí qū 仅声调不同，意思是诗与曲，即诗歌和歌曲。", "诗趣": "声调混淆：shī qù 与 shí qū 仅声调不同，意思是诗的趣味，即诗歌的韵味。", "尸躯": "声调混淆：shī qū 与 shí qū 仅第一字声调不同，意思是尸体。", "识趣": "shí 相同，qù（第四声）与 qū（第一声）只有声调不同，意思是识趣，即懂得分寸。"}, "sentence_index": null, "correct_answer": "时区"}, "level_3": {"options": [{"text": "时区", "is_correct": true, "explanation": "正确：“不同时区的同事”指所在的时区不同，因此很难一起开会。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”与能否一起开会无关，“不同味道的同事”说不通。"}, {"text": "字体", "is_correct": false, "explanation": "语义：“字体”是文字的样式，不能说明同事之间的关系，句子不通。"}, {"text": "花纹", "is_correct": false, "explanation": "搭配：“花纹”多修饰物品，不修饰“同事”。"}], "explanations": {"时区": "正确：“不同时区的同事”指所在的时区不同，因此很难一起开会。", "味道": "语义：“味道”与能否一起开会无关，“不同味道的同事”说不通。", "字体": "语义：“字体”是文字的样式，不能说明同事之间的关系，句子不通。", "花纹": "搭配：“花纹”多修饰物品，不修饰“同事”。"}, "sentence_index": 6, "correct_answer": "时区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上的时区停了。", "explanation": "这里应该用〈时钟〉。时钟会走会停，时区是划分地区的概念，不会停。"}, {"text": "我们约定的时区到了。", "explanation": "这里应该用〈时刻〉。时刻指某个具体的时间点，约定的时刻可以到，时区不能“到”。"}, {"text": "我的时区慢了十分钟。", "explanation": "这里应该用〈手表〉。手表会走快或走慢，时区是地区的划分，不会走慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中国和美国隔着好几只时区。", "corrected_sentence": "中国和美国隔着好几个时区。", "error_description": "量词错误：时区应使用量词“个”，“只”不能用于时区。正确说法是“好几个时区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不同的两只时区很难一起开会。", "corrected_sentence": "不同的两个时区很难一起开会。", "error_description": "量词错误：时区应使用量词“个”，“只”一般用于动物。正确说法是“两个时区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11083, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11083, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11083, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指两个部分或两个方面；属性上具有两重性。", "primary_collocate": null, "pronunciation": "shuāng chóng", "ipa": "ʂwɑŋ˥ ʈʂʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "即时通讯与远程协作工具，无形中推广了“即时响应”的新守时性标准，模糊了地理时区与文化时区的双重界限。", "target_word": "双重", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这件事给他带来了双重压力。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有双重国籍，可以住在两个国家。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司对员工和客人用双重标准。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是老师，也是作家，有双重身份。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败对球队是双重打击。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决定有双重影响，好坏都有。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天上班又带孩子，双重负担很重。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行对这笔钱做了双重检查。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话有双重含义，我没听懂。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "雙重", "label": "繁体"}], "register": "中性", "sense_fingerprint": "修饰名词，指涉及两个部分或两个方面的，如双重身份、双重压力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51183fcd-ff4c-496a-b5ac-da5409e35aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11083, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "双重", "is_correct": true, "explanation": "正确：“双重界限”指两个时区概念之间的两层界限。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多修饰声音、笑容，不修饰“界限”。"}, {"text": "圆形", "is_correct": false, "explanation": "语义：“圆形”指形状，不能用来描述两个概念之间的界限，句子不通。"}, {"text": "绿色", "is_correct": false, "explanation": "语义：“绿色”描述外观颜色，与抽象的“界限”不搭。"}], "explanations": {"双重": "正确：“双重界限”指两个时区概念之间的两层界限。", "甜美": "搭配：“甜美”多修饰声音、笑容，不修饰“界限”。", "圆形": "语义：“圆形”指形状，不能用来描述两个概念之间的界限，句子不通。", "绿色": "语义：“绿色”描述外观颜色，与抽象的“界限”不搭。"}, "sentence_index": 0, "correct_answer": "双重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天吃双重的早饭。", "explanation": "这里应该用〈双份〉。双份指两份食物，表示分量加倍；双重指两层或两个方面，不能表示份量。"}, {"text": "她们是双重姐妹。", "explanation": "这里应该用〈双胞胎〉。双胞胎指同时出生的两个人；双重指两层或两个方面，不能指人。"}, {"text": "他用双重的手抬起了箱子。", "explanation": "这里应该用〈双手〉。双手指两只手，是名词；双重表示两层或两个方面，不能指手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "双重", "is_correct": true, "explanation": "正确：“双重影响”指同一件事带来两方面的作用，好坏都有。"}, {"text": "方形", "is_correct": false, "explanation": "语义：“方形”指形状，不能修饰“影响”，句子不通。"}, {"text": "红色", "is_correct": false, "explanation": "语义：“红色”描述颜色，不能用来形容“影响”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多修饰声音，不修饰“影响”。"}], "explanations": {"双重": "正确：“双重影响”指同一件事带来两方面的作用，好坏都有。", "方形": "语义：“方形”指形状，不能修饰“影响”，句子不通。", "红色": "语义：“红色”描述颜色，不能用来形容“影响”。", "清脆": "搭配：“清脆”多修饰声音，不修饰“影响”。"}, "sentence_index": 6, "correct_answer": "双重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "双重的代表都到了。", "explanation": "这里应该用〈双方〉。双方指两个人或两个团体；双重指两层或两个方面，不能指代人。"}, {"text": "他拿到了双重的工资。", "explanation": "这里应该用〈双倍〉。双倍指数量加倍，表示两倍的工资；双重不能表示金额翻倍。"}, {"text": "她睁着双重的眼睛看着天空。", "explanation": "这里应该用〈双眼〉。双眼指两只眼睛，是人体器官的数量；双重不能指眼睛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份工作对她来说是很双重挑战。", "corrected_sentence": "这份工作对她来说是双重挑战。", "error_description": "程度错误：“双重”表示两层或两个方面，是非等级形容词，不能受“很”修饰。正确说法是“双重挑战”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有双重了国籍，在两个国家都能工作。", "corrected_sentence": "她有双重国籍，在两个国家都能工作。", "error_description": "语法错误：“了”插在“双重”和“国籍”之间，应说“双重国籍”，不能说“双重了国籍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
