INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物之间的分界或不同范围之间的边线。", "primary_collocate": null, "pronunciation": "jiè xiàn", "ipa": "tɕjɛ˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "即时通讯与远程协作工具，无形中推广了“即时响应”的新守时性标准，模糊了地理时区与文化时区的双重界限。", "target_word": "界限", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工作和休息要有清楚的界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好人和坏人没有绝对的界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间也应该有界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他分不清玩笑和欺负的界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个词的界限很模糊。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种颜色之间没有明显的界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生之间有一条界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学和艺术的界限越来越模糊。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要学会尊重别人的界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "事物、范围、性质之间的分界，多用于抽象的区分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51183fcd-ff4c-496a-b5ac-da5409e35aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "界限", "is_correct": true, "explanation": "正确。界限读作 jiè xiàn，指事物之间的分界。"}, {"text": "接线", "is_correct": false, "explanation": "jiē（第一声）与 jiè（第四声）声调不同，意思是连接线路。"}, {"text": "基线", "is_correct": false, "explanation": "jī 与 jiè 韵母不同（i 与 ie），声调也不同，意思是作为依据的起始线。"}, {"text": "极限", "is_correct": false, "explanation": "jí 与 jiè 韵母不同（i 与 ie），声调也不同，意思是最大限度。"}, {"text": "界面", "is_correct": false, "explanation": "miàn 与 xiàn 声母不同（m 与 x），意思是界面、表面。"}], "explanations": {"界限": "正确。界限读作 jiè xiàn，指事物之间的分界。", "接线": "jiē（第一声）与 jiè（第四声）声调不同，意思是连接线路。", "基线": "jī 与 jiè 韵母不同（i 与 ie），声调也不同，意思是作为依据的起始线。", "极限": "jí 与 jiè 韵母不同（i 与 ie），声调也不同，意思是最大限度。", "界面": "miàn 与 xiàn 声母不同（m 与 x），意思是界面、表面。"}, "sentence_index": null, "correct_answer": "界限"}, "level_3": {"options": [{"text": "界限", "is_correct": true, "explanation": "正确。“模糊”的正是时区与文化之间的双重分界。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是分界，无法被“模糊”成时区与文化的双重划分，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“模糊”不与“味道”搭配，“双重味道”不能指时区的划分。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音与时区、文化的划分无关，句意不通。"}], "explanations": {"界限": "正确。“模糊”的正是时区与文化之间的双重分界。", "颜色": "语义：颜色不是分界，无法被“模糊”成时区与文化的双重划分，句意不通。", "味道": "搭配：“模糊”不与“味道”搭配，“双重味道”不能指时区的划分。", "声音": "语义：声音与时区、文化的划分无关，句意不通。"}, "sentence_index": 0, "correct_answer": "界限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对工作的界限很高。", "explanation": "这里应该用〈标准〉。界限指分界线，不表示水准的高低；应说“对工作的标准很高”。"}, {"text": "两人的界限很大。", "explanation": "这里应该用〈差距〉。界限指分界线，不表示差距的大小；应说“两人的差距很大”。"}, {"text": "我们之间立了一把界限。", "explanation": "这里应该用〈条〉。界限作量词用“条”，“把”多用于有柄的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "界限", "is_correct": true, "explanation": "正确。“没有明显的界限”指两种颜色之间没有清楚的分界。"}, {"text": "分数", "is_correct": false, "explanation": "语义：分数是成绩，不是颜色之间的分界，句意不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气属于人的性情，不能用于两种颜色之间。"}, {"text": "相貌", "is_correct": false, "explanation": "语义：相貌指人的长相，不能用于两种颜色之间的分界。"}], "explanations": {"界限": "正确。“没有明显的界限”指两种颜色之间没有清楚的分界。", "分数": "语义：分数是成绩，不是颜色之间的分界，句意不通。", "脾气": "语义：脾气属于人的性情，不能用于两种颜色之间。", "相貌": "语义：相貌指人的长相，不能用于两种颜色之间的分界。"}, "sentence_index": 6, "correct_answer": "界限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的界限包括前三章。", "explanation": "这里应该用〈范围〉。界限指分界线，不指所包括的区域；应说“考试的范围包括前三章”。"}, {"text": "他对朋友的失望界限很深。", "explanation": "这里应该用〈程度〉。界限表示分界，不表示深浅；应说“失望的程度很深”。"}, {"text": "这座山的界限是三千米。", "explanation": "这里应该用〈高度〉。界限不表示高低或海拔；应说“山的高度是三千米”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学习和生活之间要有一把清楚的界限。", "corrected_sentence": "学习和生活之间要有一条清楚的界限。", "error_description": "量词错误：“界限”应与量词“条”搭配，说“一条界限”，不说“一把界限”；“把”多用于有柄的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他要和那些人清划界限。", "corrected_sentence": "他要和那些人划清界限。", "error_description": "补语位置错误：“清”是“划”的结果补语，应紧跟“划”，说“划清界限”，不说“清划界限”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
