INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11086, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "组织、协调并负责项目从开始到结束全部过程的人员。", "primary_collocate": null, "pronunciation": "xiàng mù jīng lǐ", "ipa": "ɕjɑŋ˥˩ mu˥˩ tɕiŋ˥ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "一位东京的项目经理可能要求雅加达的团队在非工作时间回复邮件，这不仅是时差问题，更是一种隐性的文化霸权——将特定时间伦理全球化。", "target_word": "项目经理", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我的项目经理每天都开会。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目经理给大家安排了工作。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三年前成了项目经理。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目经理请我们明天交报告。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位项目经理很会听别人的意见。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目经理正在和客户打电话。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李很想当项目经理。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目经理说下周要给客户看结果。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题可以先问项目经理。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "項目經理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公司里组织协调项目全过程的负责人员，指职位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51183fcd-ff4c-496a-b5ac-da5409e35aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "项目经理", "is_correct": true, "explanation": "正确。项目经理负责协调项目，可以要求团队在非工作时间回复邮件。"}, {"text": "理发师", "is_correct": false, "explanation": "语义：理发师不负责协调项目，要求团队回复邮件与其身份不符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的职责与项目和邮件无关，句意不通。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生没有职权要求团队回复邮件，句意不通。"}], "explanations": {"项目经理": "正确。项目经理负责协调项目，可以要求团队在非工作时间回复邮件。", "理发师": "语义：理发师不负责协调项目，要求团队回复邮件与其身份不符。", "厨师": "语义：厨师的职责与项目和邮件无关，句意不通。", "小学生": "语义：小学生没有职权要求团队回复邮件，句意不通。"}, "sentence_index": 0, "correct_answer": "项目经理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他三年前成了一只项目经理。", "explanation": "这里应该用〈位〉。指人的职位用“位”，“只”多用于动物或成对的东西。"}, {"text": "我们学校的项目经理每天给学生上数学课。", "explanation": "这里应该用〈老师〉。项目经理负责组织协调项目，不给学生上课；上课的是老师。"}, {"text": "这支球队的项目经理是他。", "explanation": "这里应该用〈领队〉。项目经理指负责项目的人，不能用来称呼球队的负责人；球队的负责人应说“领队”或“教练”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "项目经理", "is_correct": true, "explanation": "正确。项目经理是职位，可以正在和客户打电话。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能打电话，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会打电话，句意不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不会打电话，句意不通。"}], "explanations": {"项目经理": "正确。项目经理是职位，可以正在和客户打电话。", "石头": "语义：石头不能打电话，句意不通。", "窗户": "语义：窗户不会打电话，句意不通。", "黑板": "语义：黑板不会打电话，句意不通。"}, "sentence_index": 6, "correct_answer": "项目经理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "生病了可以先问项目经理。", "explanation": "这里应该用〈医生〉。项目经理负责项目进度，不负责看病，生病应问医生。"}, {"text": "学生的成绩要先问项目经理。", "explanation": "这里应该用〈班主任〉。项目经理不管理学生成绩，应问班主任。"}, {"text": "这道菜怎么做可以先问项目经理。", "explanation": "这里应该用〈厨师〉。项目经理不负责烹饪，做菜的问题应问厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新来了一只项目经理。", "corrected_sentence": "新来了一位项目经理。", "error_description": "量词错误：指人的职位要用“位”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年了当项目经理。", "corrected_sentence": "他去年当了项目经理。", "error_description": "体标位置错误：“了”应紧跟动词“当”，说“当了项目经理”，不说“了当项目经理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
