INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11090, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指对别人的问题、信件或要求给出回答或反应。", "primary_collocate": null, "pronunciation": "huí fù", "ipa": "xweɪ̯˧˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "一位东京的项目经理可能要求雅加达的团队在非工作时间回复邮件，这不仅是时差问题，更是一种隐性的文化霸权——将特定时间伦理全球化。", "target_word": "回复", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我昨天晚上给老师回复了邮件。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他收到信以后，马上回复了我。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你尽快回复我的问题。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板还没有回复我的申请。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都要回复很多客户的消息。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我发了短信，可是他一直没有回复。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有问题可以回复这封邮件。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的微信我已经回复过了。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求我今天下午回复客户。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回复了", "label": "体标（了）"}, {"form": "回复过", "label": "体标（过）"}, {"form": "回覆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对信件、邮件、消息或要求作出答复", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fc4ee6-6dc8-4fd3-8f85-e321ebdc3c7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11090, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回复", "is_correct": true, "explanation": "正确答案：回复 huí fù，指对问题、信件或要求作出答复。"}, {"text": "恢复", "is_correct": false, "explanation": "huī（第一声）与 huí（第二声）声调不同，意思是恢复原状或健康。"}, {"text": "回顾", "is_correct": false, "explanation": "gù 与 fù 声母不同（g 与 f），意思是回头看、回想。"}, {"text": "回护", "is_correct": false, "explanation": "hù 与 fù 声母不同（h 与 f），意思是袒护、包庇。"}, {"text": "回路", "is_correct": false, "explanation": "lù 与 fù 声母不同（l 与 f），意思是电路或往返的路线。"}, {"text": "汇付", "is_correct": false, "explanation": "huì（第四声）与 huí（第二声）声调不同，意思是汇款付款。"}], "explanations": {"回复": "正确答案：回复 huí fù，指对问题、信件或要求作出答复。", "恢复": "huī（第一声）与 huí（第二声）声调不同，意思是恢复原状或健康。", "回顾": "gù 与 fù 声母不同（g 与 f），意思是回头看、回想。", "回护": "hù 与 fù 声母不同（h 与 f），意思是袒护、包庇。", "回路": "lù 与 fù 声母不同（l 与 f），意思是电路或往返的路线。", "汇付": "huì（第四声）与 huí（第二声）声调不同，意思是汇款付款。"}, "sentence_index": null, "correct_answer": "回复"}, "level_3": {"options": [{"text": "回复", "is_correct": true, "explanation": "正确：“回复邮件”是答复来信的常见搭配，与“要求……回复邮件”相符。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”的对象是照片、视频，不能说拍摄邮件。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”指到场所或展览实地去看，邮件不是可以参观的对象。"}, {"text": "出席", "is_correct": false, "explanation": "搭配：“出席”的对象是会议、活动等场合，不能说出席邮件。"}], "explanations": {"回复": "正确：“回复邮件”是答复来信的常见搭配，与“要求……回复邮件”相符。", "拍摄": "搭配：“拍摄”的对象是照片、视频，不能说拍摄邮件。", "参观": "语义：“参观”指到场所或展览实地去看，邮件不是可以参观的对象。", "出席": "搭配：“出席”的对象是会议、活动等场合，不能说出席邮件。"}, "sentence_index": 0, "correct_answer": "回复"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师把昨天的录像回复了一遍。", "explanation": "这里应该用〈回放〉。回复指答复，重新播放录像要用回放。"}, {"text": "他很快回复到了座位上。", "explanation": "这里应该用〈回到〉。回复不表示返回某处，只用于答复或恢复原状，回到座位要用回到。"}, {"text": "老板终于回复了我一笔钱。", "explanation": "这里应该用〈还〉。回复不表示归还钱款，还钱要用还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回复", "is_correct": true, "explanation": "正确：前句说发了短信，“可是”之后应是对短信的回应，“回复”正相符。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭与发短信无关，无法承接“可是”之后的转折。"}, {"text": "赔偿", "is_correct": false, "explanation": "配价：“赔偿”要有被赔的对象或金额，句中没有，且与短信无关。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与对短信的回应无关，句意不通。"}], "explanations": {"回复": "正确：前句说发了短信，“可是”之后应是对短信的回应，“回复”正相符。", "吃饭": "语义：吃饭与发短信无关，无法承接“可是”之后的转折。", "赔偿": "配价：“赔偿”要有被赔的对象或金额，句中没有，且与短信无关。", "睡觉": "语义：睡觉与对短信的回应无关，句意不通。"}, "sentence_index": 6, "correct_answer": "回复"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被打了一拳，立刻回复了一拳。", "explanation": "这里应该用〈回击〉。回复指答复，对攻击的还击要用回击。"}, {"text": "这位球员终于回复了球场。", "explanation": "这里应该用〈回归〉。回复不表示重新回到某处，球员重返球场要用回归。"}, {"text": "他用行动回复了父母的养育之恩。", "explanation": "这里应该用〈回报〉。回复指答复，对恩情的报答要用回报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天已经回复了了老师的邮件。", "corrected_sentence": "我昨天已经回复了老师的邮件。", "error_description": "“了”重复：“回复”后只需一个完成标记“了”，“回复了老师的邮件”中不能再多加一个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直没有回复了我的邮件。", "corrected_sentence": "他一直没有回复我的邮件。", "error_description": "“没有”否定句中，“回复”后不能再加“了”，应说“没有回复”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
