INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11092, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不同地区之间因经度不同而产生的时间差异。", "primary_collocate": null, "pronunciation": "shí chā", "ipa": "ʂʅ˧˥ ʈʂʰa˥", "syllable_count": 2, "sentences": [{"text": "一位东京的项目经理可能要求雅加达的团队在非工作时间回复邮件，这不仅是时差问题，更是一种隐性的文化霸权——将特定时间伦理全球化。", "target_word": "时差", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "北京和东京有一个小时的时差。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚到美国，还在倒时差。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有时差，我们只能晚上视频。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机去欧洲，要花几天才能适应时差。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国和法国的时差很大。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为时差整夜没睡好。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内没有时差，全国都用北京时间。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国旅行时，我总是先查一下时差。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在英国工作，我们有八个小时的时差。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倒时差", "label": "复合"}, {"form": "时差反应", "label": "复合"}, {"form": "時差", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不同地区因经度不同而产生的时间差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fc4ee6-6dc8-4fd3-8f85-e321ebdc3c7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时差", "is_correct": true, "explanation": "正确：“这不仅是时差问题”指问题的根源在时间差，与后文“更是文化霸权”的转折相符。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温与邮件的非工作时间安排无关，“这不仅是气温问题”句意不通。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压是电学概念，与跨国团队工作时间的安排无关，“这不仅是电压问题”句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与回复邮件的时间安排无关，句意不通。"}], "explanations": {"时差": "正确：“这不仅是时差问题”指问题的根源在时间差，与后文“更是文化霸权”的转折相符。", "气温": "语义：气温与邮件的非工作时间安排无关，“这不仅是气温问题”句意不通。", "电压": "语义：电压是电学概念，与跨国团队工作时间的安排无关，“这不仅是电压问题”句意不通。", "价格": "语义：价格与回复邮件的时间安排无关，句意不通。"}, "sentence_index": 0, "correct_answer": "时差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的时差是两个小时。", "explanation": "这里应该用〈时长〉。时差是两地钟点的差距，电影的长短要用时长。"}, {"text": "现在的时差是下午三点。", "explanation": "这里应该用〈时间〉。时差是两地钟点的差距，表示现在的钟点要用时间。"}, {"text": "晚上八点到十点是这家店最忙的时差。", "explanation": "这里应该用〈时段〉。时差只指两地钟点的差距，一段营业繁忙的时间要用时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时差", "is_correct": true, "explanation": "正确：“因为时差整夜没睡好”指时差造成的不适，与句意相符。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体与睡眠无关，“因为字体整夜没睡好”句意不通。"}, {"text": "电容", "is_correct": false, "explanation": "语义：电容是电子元件，与睡眠无关，“因为电容整夜没睡好”句意不通。"}, {"text": "邮编", "is_correct": false, "explanation": "语义：邮编是邮政编码，与睡眠无关，句意不通。"}], "explanations": {"时差": "正确：“因为时差整夜没睡好”指时差造成的不适，与句意相符。", "字体": "语义：字体与睡眠无关，“因为字体整夜没睡好”句意不通。", "电容": "语义：电容是电子元件，与睡眠无关，“因为电容整夜没睡好”句意不通。", "邮编": "语义：邮编是邮政编码，与睡眠无关，句意不通。"}, "sentence_index": 6, "correct_answer": "时差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆列车的时差每小时是三百公里。", "explanation": "这里应该用〈时速〉。时差指两地钟点的差距，每小时行驶多少公里要用时速。"}, {"text": "这段美好的时差让我难忘。", "explanation": "这里应该用〈时光〉。时差只指钟点之差，一段美好的日子要用时光。"}, {"text": "这班火车的时差是早上八点。", "explanation": "这里应该用〈时刻〉。时差是两地钟点的差距，火车的发车时间点要用时刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "北京和伦敦的时差很多。", "corrected_sentence": "北京和伦敦的时差很大。", "error_description": "“时差”的程度应说“很大”，不能说“很多”，时差表示钟点的差距，不是可以计数的事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "订机票前，他先算好了时差的。", "corrected_sentence": "订机票前，他先算好了时差。", "error_description": "多加“的”：“时差”是宾语，句末不能用“的”收尾，应说“算好了时差”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
