INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11094, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11094, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一国凭借其军事、经济等优势，在国际关系中强行控制、支配其他国家的行为或格局。", "primary_collocate": null, "pronunciation": "bà quán", "ipa": "pa˥˩ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "某大国借助经济与技术优势，在国际标准制定中强行推行本国规则，这不仅是贸易问题，更是一种隐性的霸权。", "target_word": "霸权", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "一国若长期垄断关键技术标准，便可能形成科技霸权，使他国在不知不觉中丧失自主选择的空间。", "target_word": "霸权", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "大国不应该靠霸权欺负小国。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家反对霸权，希望世界更公平。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家一直在世界上推行霸权。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上有的帝国靠霸权统治了很多地方。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上说，我们不接受任何国家的霸权。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小国联合起来，才能对抗大国的霸权。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "霸权会让国际关系变得不公平。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者写了一本书，研究霸权的历史。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "霸權", "label": "繁体"}, {"form": "霸权主义", "label": "复合"}], "register": "书面", "sense_fingerprint": "名词；大国凭实力控制、支配他国的行为或格局", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc9b4b69-ef94-4dfb-a579-4a5298524f1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "霸权", "is_correct": true, "explanation": "霸权：强国凭实力强行支配他国，与“强行推行本国规则”的语境相合。"}, {"text": "邮件", "is_correct": false, "explanation": "语义：“邮件”是通讯文件，不能指一种隐性的支配现象。"}, {"text": "团队", "is_correct": false, "explanation": "搭配：“团队”指一群人，不能指一种隐性的支配现象。"}, {"text": "经理", "is_correct": false, "explanation": "语义：“经理”指管理人员，不能指一种隐性的支配现象。"}], "explanations": {"霸权": "霸权：强国凭实力强行支配他国，与“强行推行本国规则”的语境相合。", "邮件": "语义：“邮件”是通讯文件，不能指一种隐性的支配现象。", "团队": "搭配：“团队”指一群人，不能指一种隐性的支配现象。", "经理": "语义：“经理”指管理人员，不能指一种隐性的支配现象。"}, "sentence_index": 0, "correct_answer": "霸权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是班里的霸权，谁都不敢说话。", "explanation": "这里应该用〈霸主〉。霸权指强国对他国的支配，不用于班里的个人。"}, {"text": "这只猫在家里推行霸权，所有的食物都归它。", "explanation": "霸权指国家之间的支配，不用于家里的宠物，这里应该说〈霸道〉。"}, {"text": "我们学校的食堂很霸权，每天都提前卖完饭菜。", "explanation": "霸权不用来形容食堂的经营，这里应该说〈热门〉或〈抢手〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "霸权", "is_correct": true, "explanation": "霸权：强国对他国的支配，与“不接受”的语境相合。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“接受”不能与“生日”搭配，“不接受任何国家的生日”不通。"}, {"text": "时差", "is_correct": false, "explanation": "语义：时差是时间上的差异，不是可以被接受或拒绝的对象。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐与国家之间的关系无关，不是需要拒绝的对象。"}], "explanations": {"霸权": "霸权：强国对他国的支配，与“不接受”的语境相合。", "生日": "搭配：“接受”不能与“生日”搭配，“不接受任何国家的生日”不通。", "时差": "语义：时差是时间上的差异，不是可以被接受或拒绝的对象。", "早餐": "语义：早餐与国家之间的关系无关，不是需要拒绝的对象。"}, "sentence_index": 6, "correct_answer": "霸权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的性格很霸权，谁都要听他的。", "explanation": "这里应该用〈霸道〉。霸道形容人的性格蛮横，霸权指国家之间的支配。"}, {"text": "这家小店很霸权，所有顾客都得听老板的。", "explanation": "霸权用于国家之间的支配，不用于小店的经营，这里应该说〈专横〉。"}, {"text": "这个教室里的桌子很霸权，谁都不能碰它。", "explanation": "这里应该说〈禁止〉或〈不许〉。霸权指强国对他国的支配，不能用来形容桌子；把它当成“不许别人碰”的意思是误用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只霸权，我们必须反对。", "corrected_sentence": "这是一种霸权，我们必须反对。", "error_description": "错误：“一只霸权”，正确：“一种霸权”。“只”是用于动物等的量词；“霸权”是抽象概念，应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各国都应该反对霸权的主义。", "corrected_sentence": "各国都应该反对霸权主义。", "error_description": "错误：“霸权的主义”，正确：“霸权主义”。“霸权主义”是固定复合词，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
