INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11096, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指具有反思、反省的性质或特点。", "primary_collocate": null, "pronunciation": "fǎn sī xìng", "ipa": "fan²¹⁴ sz̩⁵⁵ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "然而，反思性实践也在兴起。", "target_word": "反思性", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "教育研究者认为，教师若缺乏反思性，便难以在长期的课堂实践中持续改进自己的教学方法。", "target_word": "反思性", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这门课很有反思性，学生要写学习日记。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的文章有很强的反思性，常问自己哪里做错了。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望孩子的作业有反思性，而不只是写答案。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的反思性很强，读完让人重新想自己的生活。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写日记可以提高一个人的反思性。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的反思性让很多观众沉默了。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的领导要有反思性，做错事敢承认。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的发言很有反思性，先说了自己的问题。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反思性思维", "label": "复合"}, {"form": "反思性实践", "label": "复合"}], "register": "书面", "sense_fingerprint": "具有反思、反省的性质或特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc9b4b69-ef94-4dfb-a579-4a5298524f1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理论性", "is_correct": false, "explanation": "语义：“理论性”指理论的性质，与“实践”相对，“理论性实践”自相矛盾，句中要的是反思的特点。"}, {"text": "反思性", "is_correct": true, "explanation": "反思性指具有反思、反省的特点，“反思性实践”指做事后回顾并改进的做法，符合句意。"}, {"text": "衰退性", "is_correct": false, "explanation": "语义：“衰退性”指走向衰落的性质，与“也在兴起”的趋势相反。"}, {"text": "形象性", "is_correct": false, "explanation": "搭配：“形象性”多用于艺术或语言表达，不说“形象性实践”。"}], "explanations": {"理论性": "语义：“理论性”指理论的性质，与“实践”相对，“理论性实践”自相矛盾，句中要的是反思的特点。", "反思性": "反思性指具有反思、反省的特点，“反思性实践”指做事后回顾并改进的做法，符合句意。", "衰退性": "语义：“衰退性”指走向衰落的性质，与“也在兴起”的趋势相反。", "形象性": "搭配：“形象性”多用于艺术或语言表达，不说“形象性实践”。"}, "sentence_index": 0, "correct_answer": "反思性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个动作有很强的反思性，不需要经过思考。", "explanation": "这里应该用〈反射性〉。反射性指身体不经思考的被动反应，如膝跳反射；反思性指人主动思考自己，两者不能互换。"}, {"text": "这种病的反思性很强，常常好了又犯。", "explanation": "这里应该用〈反复性〉。反复性指同样的情况一再出现，多用于病情；反思性指人对自己的反省。"}, {"text": "这种材料的反思性很强，一遇热就变形。", "explanation": "这里应该用〈敏感性〉。敏感性指对外界刺激反应强烈，材料遇热变形说的是敏感，不是反思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "季节性", "is_correct": false, "explanation": "语义：“季节性”指随季节变化的特点，不是人能靠写日记提高的能力。"}, {"text": "偶然性", "is_correct": false, "explanation": "搭配：“提高”用于能力、水平，不说“提高偶然性”。"}, {"text": "地方性", "is_correct": false, "explanation": "语义：“地方性”指地域特色，不指一个人的内在特点。"}, {"text": "反思性", "is_correct": true, "explanation": "反思性指反省自己的特点，“提高反思性”是常见搭配，符合句意。"}], "explanations": {"季节性": "语义：“季节性”指随季节变化的特点，不是人能靠写日记提高的能力。", "偶然性": "搭配：“提高”用于能力、水平，不说“提高偶然性”。", "地方性": "语义：“地方性”指地域特色，不指一个人的内在特点。", "反思性": "反思性指反省自己的特点，“提高反思性”是常见搭配，符合句意。"}, "sentence_index": 6, "correct_answer": "反思性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫的反思性很强，看见客人就跑开。", "explanation": "这里应该用〈警觉性〉。反思性指人对自己的思考与反省；猫没有这种自我反省，这里说的是对陌生人的警觉。"}, {"text": "这场比赛的反思性很强，两队都很拼。", "explanation": "这里应该用〈竞争性〉。竞争性指双方争胜，比赛的特点是竞争，不是自我反省。"}, {"text": "这条新闻的反思性很强，今天就失效了。", "explanation": "这里应该用〈时效性〉。时效性指有效的时间长短，新闻说的是时效，不是反思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师很反思性，每节课后都会记录自己的不足。", "corrected_sentence": "这位老师很有反思性，每节课后都会记录自己的不足。", "error_description": "“反思性”是名词，表示具有某种性质，应说“很有反思性”。“很反思性”缺少“有”，是错误用法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有很反思性，做错事从不找借口。", "corrected_sentence": "她有很强的反思性，做错事从不找借口。", "error_description": "错误：“有很反思性”，正确：“有很强的反思性”。“很”只能修饰形容词，不能直接修饰名词“反思性”，中间需要加形容词“强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
