INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11097, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过思考来改进实际做法的过程", "primary_collocate": null, "pronunciation": "shí jiàn", "ipa": "ʂɻ̩˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "然而，反思性实践也在兴起。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "老师每天都会反思自己的教学实践。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次实践后，我们都要想一想哪里可以改进。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把工作实践写成笔记，再慢慢改进。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过认真思考，他的教学实践越来越好。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反思自己的实践，才能找到问题。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师常常和同事讨论各自的实践。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生每周都会回顾自己的实践，看看哪里需要改变。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的实践需要不断思考和调整。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对自己的教学实践有很深的思考。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "實踐", "label": "繁体"}], "register": "书面", "sense_fingerprint": "名词，指经过反思、不断改进做法的实际过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38845469-7ba0-4215-b3c1-2b01ad8b31c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11097, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实践", "is_correct": true, "explanation": "正确答案。实践（shí jiàn）指通过思考改进实际做法的过程。"}, {"text": "时间", "is_correct": false, "explanation": "“时间”（shí jiān）与“实践”（shí jiàn）只有第二个音节声调不同（jiān 第一声，jiàn 第四声），意思是时间。"}, {"text": "事件", "is_correct": false, "explanation": "“事件”（shì jiàn）与“实践”（shí jiàn）只有第一个音节声调不同（shì 第四声，shí 第二声），意思是事件。"}, {"text": "实现", "is_correct": false, "explanation": "“实现”（shí xiàn）与“实践”（shí jiàn）只有第二个音节声母不同（x 与 j），意思是变成现实。"}, {"text": "石匠", "is_correct": false, "explanation": "“石匠”（shí jiàng）与“实践”（shí jiàn）只有第二个音节韵尾不同（-ng 与 -n），意思是石匠。"}], "explanations": {"实践": "正确答案。实践（shí jiàn）指通过思考改进实际做法的过程。", "时间": "“时间”（shí jiān）与“实践”（shí jiàn）只有第二个音节声调不同（jiān 第一声，jiàn 第四声），意思是时间。", "事件": "“事件”（shì jiàn）与“实践”（shí jiàn）只有第一个音节声调不同（shì 第四声，shí 第二声），意思是事件。", "实现": "“实现”（shí xiàn）与“实践”（shí jiàn）只有第二个音节声母不同（x 与 j），意思是变成现实。", "石匠": "“石匠”（shí jiàng）与“实践”（shí jiàn）只有第二个音节韵尾不同（-ng 与 -n），意思是石匠。"}, "sentence_index": null, "correct_answer": "实践"}, "level_3": {"options": [{"text": "实践", "is_correct": true, "explanation": "正确。“反思性实践”是通行说法，指反思后改进做法的实际过程，与“兴起”搭配自然。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“反思性”修饰的是人的思考和做法，河流不能被反思，句子不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子设备，不能“反思”，“反思性手机”与句意冲突。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语色彩很重，不适合这句书面语。"}], "explanations": {"实践": "正确。“反思性实践”是通行说法，指反思后改进做法的实际过程，与“兴起”搭配自然。", "河流": "语义：“反思性”修饰的是人的思考和做法，河流不能被反思，句子不通。", "手机": "语义：手机是电子设备，不能“反思”，“反思性手机”与句意冲突。", "玩意儿": "语域：“玩意儿”口语色彩很重，不适合这句书面语。"}, "sentence_index": 0, "correct_answer": "实践"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行是我最难忘的实践。", "explanation": "这里应该用〈经历〉。“实践”指通过思考改进做法的过程，指一次亲身遭遇的旅行要用“经历”。"}, {"text": "他今天的实践很好，一直在笑。", "explanation": "这里应该用〈心情〉。“实践”指通过思考改进做法的过程，不能表示人的情绪；高兴不高兴要用“心情”。"}, {"text": "这台机器的实践坏了，需要修理。", "explanation": "这里应该用〈零件〉。“实践”指通过思考改进做法的过程，不能指机器的部件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实践", "is_correct": true, "explanation": "正确。“各自的实践”指每个人自己的做法，正是“讨论”的对象。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“讨论”的对象是做法、想法，“天空”不能被同事讨论，句子不通。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“讨论”一般不跟“力气”这类体力搭配，“讨论各自的力气”不是习惯说法。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是自然现象，不是人可以讨论各自拥有的东西，与句意不符。"}], "explanations": {"实践": "正确。“各自的实践”指每个人自己的做法，正是“讨论”的对象。", "天空": "语义：“讨论”的对象是做法、想法，“天空”不能被同事讨论，句子不通。", "力气": "搭配：“讨论”一般不跟“力气”这类体力搭配，“讨论各自的力气”不是习惯说法。", "雨水": "语义：雨水是自然现象，不是人可以讨论各自拥有的东西，与句意不符。"}, "sentence_index": 6, "correct_answer": "实践"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他读了很多教育实践。", "explanation": "这里应该用〈理论〉。“读”的对象是书面的理论，“实践”指通过反思改进做法的过程，不能用“读”来说。"}, {"text": "这件衣服的实践很漂亮。", "explanation": "这里应该用〈颜色〉。“实践”指通过思考改进做法的过程，不能描述衣服的外观。"}, {"text": "他不停地实践这个问题，希望找到答案。", "explanation": "这里应该用〈思考〉。“实践”指通过实际做法来改进，不是在脑中琢磨问题；想一个问题要用“思考”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师们比较了三只不同的教学实践。", "corrected_sentence": "老师们比较了三种不同的教学实践。", "error_description": "“实践”指做法，计量时用“种”，不能用“只”（“只”多用于动物或单个物品）。应说“三种不同的教学实践”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她教学实践总能给学生带来启发。", "corrected_sentence": "她的教学实践总能给学生带来启发。", "error_description": "“教学实践”前面要加定语标记“的”，应说“她的教学实践”。漏掉“的”，“她教学”会被读成动词短语，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11099, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11099, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11099, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "思想、认识等触及事物本质的程度。", "primary_collocate": null, "pronunciation": "shēn dù", "ipa": "ʂən˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "真正有价值的学术讨论，不在于罗列材料，而在于能否触及问题的深度。", "target_word": "深度", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这篇文章很有深度，我看了两遍。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的看法很有深度，大家都点头。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的深度不够，没有说清问题。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问的问题很有深度，我想了很久。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对这件事的看法有深度，不是随便说的。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影没有深度，只是让人笑一笑。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要讨论这个问题的深度，不能只看表面。", "target_word": "深度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想让文章有更多深度，所以改了三次。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的新闻不但要快，还要有深度。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "深度：思想、认识触及事物本质的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '461c370f-be46-4e41-96a9-fb0d343458d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11099, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深度", "is_correct": true, "explanation": "正确：这里的“深度”指讨论触及问题本质的程度，与“不在于罗列材料”的语境相合。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”指长短，不能说明讨论触及本质的程度，句意不通。"}, {"text": "宽度", "is_correct": false, "explanation": "语义：“宽度”指左右之间的距离，与讨论是否触及本质无关。"}, {"text": "热度", "is_correct": false, "explanation": "搭配：“热度”指受关注的程度，与“罗列材料”和“触及问题”的对比不符。"}], "explanations": {"深度": "正确：这里的“深度”指讨论触及问题本质的程度，与“不在于罗列材料”的语境相合。", "长度": "语义：“长度”指长短，不能说明讨论触及本质的程度，句意不通。", "宽度": "语义：“宽度”指左右之间的距离，与讨论是否触及本质无关。", "热度": "搭配：“热度”指受关注的程度，与“罗列材料”和“触及问题”的对比不符。"}, "sentence_index": 0, "correct_answer": "深度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的深度有五十页，很长。", "explanation": "这里应该用〈篇幅〉。深度说事物深浅或认识触及本质的程度，文章的长短要用“篇幅”或“页数”。"}, {"text": "这首歌的深度有五分钟，很好听。", "explanation": "这里应该用〈时长〉。深度说事物深浅或认识触及本质的程度，歌曲的长短要用“时长”。"}, {"text": "这篇作文的深度是八百字。", "explanation": "这里应该用〈字数〉。深度指思想、认识触及本质的程度，文章有多少字要用「字数」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11099, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深度", "is_correct": true, "explanation": "正确：“没有深度”指电影缺少思想内涵，与“只是让人笑一笑”形成对照。"}, {"text": "时间", "is_correct": false, "explanation": "语义：电影不能用“时间”来评价有没有内涵，“没有时间”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，不能用于评价电影。"}, {"text": "行情", "is_correct": false, "explanation": "搭配：“行情”说市场价格的走势，不用来评价电影的内涵。"}], "explanations": {"深度": "正确：“没有深度”指电影缺少思想内涵，与“只是让人笑一笑”形成对照。", "时间": "语义：电影不能用“时间”来评价有没有内涵，“没有时间”说不通。", "体重": "语义：“体重”指人或动物的重量，不能用于评价电影。", "行情": "搭配：“行情”说市场价格的走势，不用来评价电影的内涵。"}, "sentence_index": 6, "correct_answer": "深度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的深度很大，员工超过一千人。", "explanation": "这里应该用〈规模〉。深度说事物深浅或认识触及本质的程度，说企业大小要用“规模”。"}, {"text": "这批零件的深度有三十斤，客户都满意。", "explanation": "这里应该用〈重量〉。深度说思想、认识触及本质的程度，不能用“斤”来计量。"}, {"text": "这份报告的深度有二十页，老师很满意。", "explanation": "这里应该用〈篇幅〉。深度指认识触及本质的程度，报告有多长要用「篇幅」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书很深度，值得反复读。", "corrected_sentence": "这本书很有深度，值得反复读。", "error_description": "错误：“很深度”；正确：“很有深度”。“深度”是名词，作谓语时要用“有深度”，“很”后面不能直接接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇论文不有深度，老师不太满意。", "corrected_sentence": "这篇论文没有深度，老师不太满意。", "error_description": "错误：「不有深度」；正确：「没有深度」。「有」的否定形式是「没有」，不说「不有」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
