INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指通过训练、教育或纪律来塑造人的行为、思想，使其符合某种规范。", "primary_collocate": null, "pronunciation": "guī xùn", "ipa": "kweɪ̯˥ ɕyn˥˩", "syllable_count": 2, "sentences": [{"text": "北欧部分企业开始推行“无会议星期五”与“深度工作时段”，试图从内部解构过度时间规训，重新拥抱一种更具人文温度的时间哲学。", "target_word": "规训", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "学校的规训让孩子学会了遵守纪律。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队里的规训非常严格。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期的规训会改变一个人的想法。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家写过一本关于规训的书。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认为工厂的规训让工人变得像机器。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不喜欢家里太多的规训。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种规训从小学就开始了。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会通过规训让人们遵守规矩。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上班打卡也是一种对时间的规训。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自我规训", "label": "复合"}, {"form": "規訓", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用纪律和训练塑造人的行为与思想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fc4ee6-6dc8-4fd3-8f85-e321ebdc3c7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规训", "is_correct": true, "explanation": "正确：“规训”指通过纪律和训练塑造人的行为与思想，与“过度时间”搭配，符合句意。"}, {"text": "草地", "is_correct": false, "explanation": "语义：“草地”是场地，不能被“解构”，与“过度时间”的抽象语境冲突。"}, {"text": "火锅", "is_correct": false, "explanation": "语义：“火锅”是食物，句子讨论的是对时间的约束，“过度时间火锅”不成立。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“过度时间”后接的是抽象的约束类名词，不与“面包”搭配。"}], "explanations": {"规训": "正确：“规训”指通过纪律和训练塑造人的行为与思想，与“过度时间”搭配，符合句意。", "草地": "语义：“草地”是场地，不能被“解构”，与“过度时间”的抽象语境冲突。", "火锅": "语义：“火锅”是食物，句子讨论的是对时间的约束，“过度时间火锅”不成立。", "面包": "搭配：“过度时间”后接的是抽象的约束类名词，不与“面包”搭配。"}, "sentence_index": 0, "correct_answer": "规训"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想规训一下这个电脑程序的错误。", "explanation": "这里应该用〈修正〉。规训是对人的行为与思想的纪律塑造，不能用于程序错误。"}, {"text": "这次失败给他留下了深刻的规训。", "explanation": "这里应该用〈教训〉。规训指纪律与训练的塑造，不指从失败中得到的经验。"}, {"text": "这场规训非常精彩。", "explanation": "这里应该用〈比赛〉。规训是对人的纪律塑造，不指体育竞赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规训", "is_correct": true, "explanation": "正确：“规训”指用纪律约束人，与“太多的”和“孩子不喜欢”的语境相符。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：“海拔”指地面高度，家里不会有“太多的海拔”，句意不通。"}, {"text": "地震", "is_correct": false, "explanation": "语义：“地震”是自然灾害，不能说家里有“太多的地震”让孩子不喜欢。"}, {"text": "氧气", "is_correct": false, "explanation": "搭配：“氧气”一般说“充足”或“稀薄”，不说“太多的氧气”让孩子不喜欢。"}], "explanations": {"规训": "正确：“规训”指用纪律约束人，与“太多的”和“孩子不喜欢”的语境相符。", "海拔": "语义：“海拔”指地面高度，家里不会有“太多的海拔”，句意不通。", "地震": "语义：“地震”是自然灾害，不能说家里有“太多的地震”让孩子不喜欢。", "氧气": "搭配：“氧气”一般说“充足”或“稀薄”，不说“太多的氧气”让孩子不喜欢。"}, "sentence_index": 6, "correct_answer": "规训"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门规训很有意思。", "explanation": "这里应该用〈课程〉。规训指纪律与训练对人的塑造，不指学科课程。"}, {"text": "他花了一下午把漏水的水管规训好了。", "explanation": "这里应该用〈修理〉。规训是对人的行为与思想的纪律塑造，不能用于修理水管。"}, {"text": "这部规训很感人。", "explanation": "这里应该用〈小说〉。规训是纪律的塑造，不是可以“感人”的文学作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校对学生进行了一把规训。", "corrected_sentence": "学校对学生进行了一次规训。", "error_description": "量词错误：“规训”是抽象名词，应说“一次”或“一种”，不能用“把”（“把”多用于有柄的器具）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从小就接受了过严格的规训。", "corrected_sentence": "他从小就接受过严格的规训。", "error_description": "体标错误：“了”与“过”不能同时用在“接受”后，只用“过”，应说“接受过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
