INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11103, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "张开双臂围住别人，表示亲热或欢迎；也比喻热情地接受（新事物）。", "primary_collocate": null, "pronunciation": "yōng bào", "ipa": "jʊŋ˥ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "北欧部分企业开始推行“无会议星期五”与“深度工作时段”，试图从内部解构过度时间规训，重新拥抱一种更具人文温度的时间哲学。", "target_word": "拥抱", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "妈妈张开双臂，拥抱了刚回家的孩子。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场里，他紧紧拥抱着多年未见的朋友。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，队员们互相拥抱，大家都哭了。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一看到爸爸，就跑过去拥抱他。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们张开手臂，热情拥抱新来的老师。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友见面时，他们热情地拥抱在一起。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把哭泣的妹妹轻轻拥抱在怀里。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎回家！奶奶笑着拥抱了我。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他张开双臂，拥抱了远道而来的朋友。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拥抱了", "label": "体标"}, {"form": "拥抱着", "label": "体标"}, {"form": "拥抱过", "label": "体标"}, {"form": "擁抱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "张开双臂围住人，表亲热或欢迎，也可比喻热情接受新事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fc4ee6-6dc8-4fd3-8f85-e321ebdc3c7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11103, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拥抱", "is_correct": true, "explanation": "正确：“拥抱”在此指热情地接纳，与“重新”和“一种时间哲学”搭配，符合句意。"}, {"text": "推开", "is_correct": false, "explanation": "语义：“推开”表示用力使分离，与“重新接纳一种哲学”的语境相反。"}, {"text": "拨打", "is_correct": false, "explanation": "搭配：“拨打”多用于电话，不说“拨打一种哲学”。"}, {"text": "翻修", "is_correct": false, "explanation": "搭配：“翻修”用于房屋等建筑，不能用于“时间哲学”。"}], "explanations": {"拥抱": "正确：“拥抱”在此指热情地接纳，与“重新”和“一种时间哲学”搭配，符合句意。", "推开": "语义：“推开”表示用力使分离，与“重新接纳一种哲学”的语境相反。", "拨打": "搭配：“拨打”多用于电话，不说“拨打一种哲学”。", "翻修": "搭配：“翻修”用于房屋等建筑，不能用于“时间哲学”。"}, "sentence_index": 0, "correct_answer": "拥抱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拥抱了窗户。", "explanation": "这里应该用〈打开〉。“拥抱”的对象是人，张开双臂围住的不能是门窗。"}, {"text": "他每天早上拥抱一杯牛奶。", "explanation": "这里应该用〈喝〉。“拥抱”是张开双臂围住或热情接受，喝牛奶要用“喝”。"}, {"text": "农民拥抱了一棵白菜。", "explanation": "这里应该用〈拔〉。“拥抱”指张开双臂围住人，拔白菜要用“拔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11103, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥抱", "is_correct": true, "explanation": "正确：“拥抱”表示热情地抱在一起，与“热情地”和“见面时”的语境相符。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体不适的表现，与“热情地”见面的场景不符。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：“背诵”的对象是课文、诗词，不能说“背诵在一起”。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”表示悲伤，与“热情地”见面的语境矛盾。"}], "explanations": {"拥抱": "正确：“拥抱”表示热情地抱在一起，与“热情地”和“见面时”的语境相符。", "咳嗽": "语义：“咳嗽”是身体不适的表现，与“热情地”见面的场景不符。", "背诵": "搭配：“背诵”的对象是课文、诗词，不能说“背诵在一起”。", "哭泣": "语义：“哭泣”表示悲伤，与“热情地”见面的语境矛盾。"}, "sentence_index": 6, "correct_answer": "拥抱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天拥抱桌子。", "explanation": "这里应该用〈擦〉。“拥抱”的对象是人，擦桌子要用“擦”。"}, {"text": "他用力拥抱门。", "explanation": "这里应该用〈推〉。“拥抱”的对象是人，推门要用“推”。"}, {"text": "妈妈用洗衣机拥抱了衣服。", "explanation": "这里应该用〈洗〉。“拥抱”是张开双臂围住，用洗衣机处理衣服要用“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拥抱了住多年未见的朋友。", "corrected_sentence": "他拥抱住了多年未见的朋友。", "error_description": "补语“住”的位置错误：应说“拥抱住了”，结果补语要紧跟动词，不能说“拥抱了住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在车站拥抱着了从外地回来的哥哥。", "corrected_sentence": "她在车站拥抱了从外地回来的哥哥。", "error_description": "“着”与“了”混用：“着”表示动作持续，“了”表示动作完成，两者不能并用。动作已完成，应说“拥抱了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
