INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11104, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "表示在程度上更进一步地具有某种性质。", "primary_collocate": null, "pronunciation": "gèng jù", "ipa": "kɤŋ˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "北欧部分企业开始推行“无会议星期五”与“深度工作时段”，试图从内部解构过度时间规训，重新拥抱一种更具人文温度的时间哲学。", "target_word": "更具", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个方案比那个更具说服力。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新手机的设计比旧的更具特色。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份新工作更具挑战性，我很想试试。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的菜比别家更具地方特色。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的第二本书比第一本更具价值。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比起第一次，这次的比赛更具吸引力。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的新歌比旧歌更具个性，听的人更多。", "target_word": "更具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新方法更具可行性，也更省钱。", "target_word": "更具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市的机会更具吸引力，所以年轻人都去了。", "target_word": "更具", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "更具：程度上更进一步地具有某种性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '461c370f-be46-4e41-96a9-fb0d343458d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更具", "is_correct": true, "explanation": "正确：“一种更具人文温度的时间哲学”，“更具”表示更有某种性质，与句意相合。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”用于可计量的事物，不说“测量人文温度”。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除人文温度”与“重新拥抱”的语义相反，句意说不通。"}, {"text": "缩短", "is_correct": false, "explanation": "配价：“缩短”要求带长度或时长类的宾语，不能带“人文温度”。"}], "explanations": {"更具": "正确：“一种更具人文温度的时间哲学”，“更具”表示更有某种性质，与句意相合。", "测量": "搭配：“测量”用于可计量的事物，不说“测量人文温度”。", "删除": "语义：“删除人文温度”与“重新拥抱”的语义相反，句意说不通。", "缩短": "配价：“缩短”要求带长度或时长类的宾语，不能带“人文温度”。"}, "sentence_index": 0, "correct_answer": "更具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的营业额更具两成。", "explanation": "这里应该用〈增加〉。更具表示事物具有某种性质或特色，营业额的增长要用“增加”。"}, {"text": "这个月的销量更具一成。", "explanation": "这里应该用〈提高〉。更具说的是性质或特色，销量的上升要用“提高”。"}, {"text": "这项措施的成本更具了一半。", "explanation": "这里应该用〈降低〉。更具表示具有某种性质，不能带“了一半”这样的数量表达；成本下降要说“降低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更具", "is_correct": true, "explanation": "正确：“这次的比赛更具吸引力”，“更具”表示比原来更有吸引力，与句意相合。"}, {"text": "收割", "is_correct": false, "explanation": "语义：“收割吸引力”不成立，“收割”只用于庄稼等。"}, {"text": "计算", "is_correct": false, "explanation": "搭配：“计算”要求带可计量的对象，不说“计算吸引力”。"}, {"text": "切割", "is_correct": false, "explanation": "语义：“切割”针对实体物件，“切割吸引力”与句意不符。"}], "explanations": {"更具": "正确：“这次的比赛更具吸引力”，“更具”表示比原来更有吸引力，与句意相合。", "收割": "语义：“收割吸引力”不成立，“收割”只用于庄稼等。", "计算": "搭配：“计算”要求带可计量的对象，不说“计算吸引力”。", "切割": "语义：“切割”针对实体物件，“切割吸引力”与句意不符。"}, "sentence_index": 6, "correct_answer": "更具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府更具市场监管。", "explanation": "这里应该用〈加强〉。更具说的是事物具有某种性质，监管力度的增强要用“加强”。"}, {"text": "这家工厂的废品更具一半。", "explanation": "这里应该用〈减少〉。更具不能带数量短语，废品数量的减少要用“减少”。"}, {"text": "这条线路更具五公里。", "explanation": "这里应该用〈延长〉。更具表示性质或特色，线路长度的增加要用“延长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款手机的屏幕更具了质感，看起来很舒服。", "corrected_sentence": "这款手机的屏幕更具质感，看起来很舒服。", "error_description": "错误：“更具了质感”；正确：“更具质感”。“更具”表示具有某种性质，不能带“了”表示完成，直接说“更具质感”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区环境优美，更具的居住价值。", "corrected_sentence": "这个小区环境优美，更具居住价值。", "error_description": "错误：“更具的居住价值”；正确：“更具居住价值”。“更具”是动词，后面直接带宾语，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
