INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11105, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人文指人类社会的各种文化现象，包括文学、历史、哲学、艺术等，强调人的精神、价值和创造。", "primary_collocate": null, "pronunciation": "rén wén", "ipa": "ʐən˧˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "北欧部分企业开始推行“无会议星期五”与“深度工作时段”，试图从内部解构过度时间规训，重新拥抱一种更具人文温度的时间哲学。", "target_word": "人文", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座城市的人文历史很丰富。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学学习人文，对历史和文学很感兴趣。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校很重视人文教育。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古老的寺庙是当地重要的人文景观。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了欧洲的自然和人文。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇的人文环境很好，人们都很友好。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习人文知识，能让人想得更深。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多关于人文的展览。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书让我更了解各地的人文。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人文主义", "label": "复合"}, {"form": "人文精神", "label": "复合"}, {"form": "人文学科", "label": "复合"}], "register": "书面", "sense_fingerprint": "人类社会的文化现象，如文学、历史、哲学、艺术，强调人的精神与价值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fc4ee6-6dc8-4fd3-8f85-e321ebdc3c7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11105, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "效率", "is_correct": false, "explanation": "搭配：“温度”多用来形容人的情感或态度，不能说“效率温度”。"}, {"text": "人文", "is_correct": true, "explanation": "“人文温度”指重视人的精神与价值的温情，与“时间哲学”以人为本的主旨相合。"}, {"text": "数据", "is_correct": false, "explanation": "语义：“数据”是冰冷的数字，与“温度”所表达的人情味相矛盾。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句书面语的语域不合。"}], "explanations": {"效率": "搭配：“温度”多用来形容人的情感或态度，不能说“效率温度”。", "人文": "“人文温度”指重视人的精神与价值的温情，与“时间哲学”以人为本的主旨相合。", "数据": "语义：“数据”是冰冷的数字，与“温度”所表达的人情味相矛盾。", "玩意儿": "语域：“玩意儿”是口语说法，与这句书面语的语域不合。"}, "sentence_index": 0, "correct_answer": "人文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司每年培养出很多人文。", "explanation": "这里应该用〈人才〉。“人文”指人类社会的文化现象，不指有才能的人，不能说“培养出很多人文”。"}, {"text": "这座城市的人文超过一千万。", "explanation": "这里应该用〈人口〉。“人文”指文化现象，不能用来计算人数，数量要说“人口超过一千万”。"}, {"text": "这座湖是人文修建的。", "explanation": "这里应该用〈人工〉。“人文”不指人力造成的事物，说湖是人力修建要用“人工”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11105, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战争", "is_correct": false, "explanation": "语义：“战争”与“环境很好、人们友好”的评价相反，不能描述环境。"}, {"text": "人文", "is_correct": true, "explanation": "“人文环境”指小镇的文化氛围与人情条件，与“人们都很友好”相呼应。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“环境”修饰的是社会或自然条件，“体重”是人的身体指标，不能作环境的定语。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：“噪音”是负面因素，与“环境很好”的评价冲突。"}], "explanations": {"战争": "语义：“战争”与“环境很好、人们友好”的评价相反，不能描述环境。", "人文": "“人文环境”指小镇的文化氛围与人情条件，与“人们都很友好”相呼应。", "体重": "搭配：“环境”修饰的是社会或自然条件，“体重”是人的身体指标，不能作环境的定语。", "噪音": "语义：“噪音”是负面因素，与“环境很好”的评价冲突。"}, "sentence_index": 6, "correct_answer": "人文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的人文有一米九，是班里最高的。", "explanation": "这里应该用〈身高〉。“身高”指人的高矮，说人有多高要用“身高”；“人文”指文化现象，不能用来说身高。"}, {"text": "这次帮忙，我欠了他一个人文。", "explanation": "这里应该用〈人情〉。“人情”指人与人之间的情分，欠人情要用“人情”；“人文”指文化现象，不指情分。"}, {"text": "这家店的人文很旺，每天都排长队。", "explanation": "这里应该用〈人气〉。“人气”指受欢迎的程度或人多的景象，形容店铺要说“人气很旺”；“人文”指文化现象，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在大学学习得人文，对历史很感兴趣。", "corrected_sentence": "他在大学学习了人文，对历史很感兴趣。", "error_description": "补语标记错误：动作完成应用“了”，“得”是补语标记，不能接宾语“人文”，应说“学习了人文”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座老镇地人文环境很美，游客很多。", "corrected_sentence": "这座老镇的人文环境很美，游客很多。", "error_description": "的/地混用：修饰名词要用“的”，“地”只修饰动词或形容词，应说“老镇的人文环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
