INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "温度是物体冷热程度的量度，通常用温度计测量。", "primary_collocate": null, "pronunciation": "wēn dù", "ipa": "wən˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "早上的温度降到零下五度，路面都结冰了。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子里的温度比外面高十度。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的温度是二十五度。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的温度太高，别喝。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的温度很舒服。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的温度会降到零度以下。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的温度可以自己调。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天山上的温度比城里低很多。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶的温度不能太高。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天的温度会升高几度。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "温度计", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体冷热程度的量度，可用温度计测量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd79aa37-f94d-4d21-b269-7476dce0f4e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温度", "is_correct": true, "explanation": "“早上的温度降到零下五度”说明天气很冷，只有“温度”符合语境。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：湿度指空气潮湿的程度，不会降到零下，“湿度降到零下”不成立。"}, {"text": "面积", "is_correct": false, "explanation": "语义：面积指平面的大小，与“降到零下”无关，句意不通。"}, {"text": "密度", "is_correct": false, "explanation": "搭配：“密度”不能说“降到零下”，句意不通。"}], "explanations": {"温度": "“早上的温度降到零下五度”说明天气很冷，只有“温度”符合语境。", "湿度": "语义：湿度指空气潮湿的程度，不会降到零下，“湿度降到零下”不成立。", "面积": "语义：面积指平面的大小，与“降到零下”无关，句意不通。", "密度": "搭配：“密度”不能说“降到零下”，句意不通。"}, "sentence_index": 0, "correct_answer": "温度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的温度很大，空气黏得让人难受。", "explanation": "这里应该用〈湿度〉。温度只说冷热，空气潮湿、发黏要说“湿度很大”。"}, {"text": "他的汉语水平已经达到很高的温度了。", "explanation": "这里应该用〈程度〉。温度只指冷热，不能表示水平达到的高低。"}, {"text": "这个三角形的温度很大。", "explanation": "这里应该用〈角度〉。温度不能用来表示角的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温度", "is_correct": true, "explanation": "“调”可以用于温度，指房间的温度可以自行调节，符合语境。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“调”通常接“温度、亮度”等可调节的量，不说调“重量”。"}, {"text": "体积", "is_correct": false, "explanation": "语义：房间的体积由大小决定，无法自己调节。"}, {"text": "长度", "is_correct": false, "explanation": "语义：房间的长度是固定的，不能自己调节。"}], "explanations": {"温度": "“调”可以用于温度，指房间的温度可以自行调节，符合语境。", "重量": "搭配：“调”通常接“温度、亮度”等可调节的量，不说调“重量”。", "体积": "语义：房间的体积由大小决定，无法自己调节。", "长度": "语义：房间的长度是固定的，不能自己调节。"}, "sentence_index": 6, "correct_answer": "温度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的温度很厚。", "explanation": "这里应该用〈厚度〉。温度只指冷热，不能用来表示物体的厚薄。"}, {"text": "这辆车的温度很快。", "explanation": "这里应该用〈速度〉。温度不能用来形容快慢。"}, {"text": "这口井的温度很深。", "explanation": "这里应该用〈深度〉。温度不能用来表示深浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想测一只温度。", "corrected_sentence": "我想测一下温度。", "error_description": "“一只”是量词，用于动物或个体事物，不能修饰“温度”；这里应说“测一下温度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请温度调低一点。", "corrected_sentence": "请把温度调低一点。", "error_description": "把字句中，“温度”作宾语要放在“把”之后、动词之前，应说“请把温度调低一点”；漏掉“把”直接说“请温度调低一点”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
