INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11107, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "关于世界、人生和知识等根本问题的学问。", "primary_collocate": null, "pronunciation": "zhé xué", "ipa": "ʈʂɤ˧˥ ɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "北欧部分企业开始推行“无会议星期五”与“深度工作时段”，试图从内部解构过度时间规训，重新拥抱一种更具人文温度的时间哲学。", "target_word": "哲学", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他大学读的是哲学专业。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哲学让人思考生命的意义。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对哲学很感兴趣，常常读这方面的书。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师在大学里教哲学。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哲学研究的是世界和人生的大问题。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习哲学，能帮助我们认真思考问题。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书把哲学讲得很容易懂。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，哲学不是考试，而是一种思考方式。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她爱上了哲学，常常想人生的意义。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哲学家", "label": "复合"}, {"form": "哲学系", "label": "复合"}, {"form": "哲學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "研究世界、人生和知识等根本问题的学问或思想体系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fc4ee6-6dc8-4fd3-8f85-e321ebdc3c7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11107, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“时间价格”说不通，“价格”与“人文温度”“重新拥抱”的语境无关。"}, {"text": "哲学", "is_correct": true, "explanation": "“时间哲学”指对时间的根本看法，与前文“人文温度”所表达的人本取向相呼应。"}, {"text": "机器", "is_correct": false, "explanation": "语义：“机器”是设备，不能“更具人文温度”，与“重新拥抱”的语境不合。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：“噪音”是负面的声音，不是一种看待时间的观念，句意不通。"}], "explanations": {"价格": "语义：“时间价格”说不通，“价格”与“人文温度”“重新拥抱”的语境无关。", "哲学": "“时间哲学”指对时间的根本看法，与前文“人文温度”所表达的人本取向相呼应。", "机器": "语义：“机器”是设备，不能“更具人文温度”，与“重新拥抱”的语境不合。", "噪音": "语义：“噪音”是负面的声音，不是一种看待时间的观念，句意不通。"}, "sentence_index": 0, "correct_answer": "哲学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱的哲学很好，省电又安静。", "explanation": "这里应该用〈质量〉。“质量”指产品的好坏，说冰箱好要用“质量”；“哲学”指关于根本问题的学问，不能用来评价产品。"}, {"text": "这个孩子这一年哲学长高了五厘米。", "explanation": "这里应该用〈身高〉。“身高”指人的高矮，说长高了要用“身高”；“哲学”指学问，不能用来说身体的高度。"}, {"text": "这碗面的哲学太咸了。", "explanation": "这里应该用〈味道〉。“味道”指食物的滋味，说咸淡要用“味道”；“哲学”指学问，不能用来形容滋味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11107, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡眠", "is_correct": false, "explanation": "语义：“睡眠”不是可以学习的学科，不能帮助人认真思考问题。"}, {"text": "哲学", "is_correct": true, "explanation": "“学习哲学”能训练人认真思考，与后句“认真思考问题”相呼应。"}, {"text": "面条", "is_correct": false, "explanation": "搭配：“学习”后接的是“学做面条”这类技能，不说“学习面条”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是玩耍用的物品，不是学习的对象，与“认真思考”不合。"}], "explanations": {"睡眠": "语义：“睡眠”不是可以学习的学科，不能帮助人认真思考问题。", "哲学": "“学习哲学”能训练人认真思考，与后句“认真思考问题”相呼应。", "面条": "搭配：“学习”后接的是“学做面条”这类技能，不说“学习面条”。", "玩具": "语义：“玩具”是玩耍用的物品，不是学习的对象，与“认真思考”不合。"}, "sentence_index": 6, "correct_answer": "哲学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的哲学很新鲜。", "explanation": "这里应该用〈食材〉。“食材”指做菜的原料，形容新鲜要说“食材”；“哲学”指学问，不能用来说食物。"}, {"text": "这辆车的哲学很快，一小时能开一百公里。", "explanation": "这里应该用〈速度〉。“速度”指快慢的程度，说车快要用“速度”；“哲学”指学问，不能用来说行驶的快慢。"}, {"text": "这个箱子的哲学很大，一个人搬不动。", "explanation": "这里应该用〈重量〉。“重量”指物体的轻重，说箱子搬不动要用“重量”；“哲学”指学问，不能用来说轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11107, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他大学时读了一本哲学，印象很深。", "corrected_sentence": "他大学时读了一本哲学书，印象很深。", "error_description": "“哲学”是一门学问，不是书，不能直接用“一本”修饰。说读的书要用“一本哲学书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11107, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她讲哲学讲很清楚，大家都听懂了。", "corrected_sentence": "她讲哲学讲得很清楚，大家都听懂了。", "error_description": "补语错误：“讲”后接补语时要用“得”，“讲哲学讲很清楚”应改为“讲哲学讲得很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11110, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11110, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11110, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现代性是指现代社会在文化、生活方式、思想观念等方面所呈现出的特征，通常与追求进步、理性、个人自由等理念相关。", "primary_collocate": null, "pronunciation": "xiàn dài xìng", "ipa": "ɕjɛn˥˩ taɪ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "因此，时间观念的冲突，实则是现代性内部多元价值的博弈。", "target_word": "现代性", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这位作家的小说常常讨论现代性的问题。", "target_word": "现代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的高楼和地铁，都是现代性的表现。", "target_word": "现代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多学者认为，现代性带来了自由，也带来了压力。", "target_word": "现代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书从历史的角度解释什么是现代性。", "target_word": "现代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这座老城里，传统和现代性常常放在一起。", "target_word": "现代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的研究是关于东亚社会的现代性。", "target_word": "现代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教授问我们：现代性对个人生活有什么影响？", "target_word": "现代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代性强调理性和个人自由。", "target_word": "现代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影批评了现代性带来的孤独感。", "target_word": "现代性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "現代性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "现代社会在文化、生活方式和思想观念上的整体特征", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a14a5b5-fb1c-4d38-a80a-0291bb9dc678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现代性", "is_correct": true, "explanation": "这里指现代社会内部的整体特征，与“多元价值的博弈”相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能作为“多元价值的博弈”的范围，二者搭配不当。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法是语言规则，与“时间观念的冲突”无关。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言指地方话，不指价值观念之间的博弈。"}], "explanations": {"现代性": "这里指现代社会内部的整体特征，与“多元价值的博弈”相符。", "天气": "搭配：“天气”不能作为“多元价值的博弈”的范围，二者搭配不当。", "语法": "语义：语法是语言规则，与“时间观念的冲突”无关。", "方言": "语义：方言指地方话，不指价值观念之间的博弈。"}, "sentence_index": 0, "correct_answer": "现代性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位现代性的作家，作品很有个性。", "explanation": "这里应该用〈现代主义〉。现代主义是一种文艺流派，可以修饰作家；现代性指现代社会的整体特征，不能直接用来指人。"}, {"text": "我们新买了一台现代性，放在客厅里。", "explanation": "这里应该用〈种〉。现代性是抽象名词，不能用“台”计量，“台”用于机器等具体物品。"}, {"text": "这张桌子是用现代性做的。", "explanation": "这里应该用〈木头〉。“用……做的”说明材料，现代性是抽象特征，不能作为做桌子的材料；应说用木头做的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现代性", "is_correct": true, "explanation": "这里指东亚社会的整体特征，是研究的对象，与句意相符。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时器具，不能作为社会研究的对象。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或物的重量，不能作为社会研究的主题。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，与社会研究毫无关系。"}], "explanations": {"现代性": "这里指东亚社会的整体特征，是研究的对象，与句意相符。", "闹钟": "语义：闹钟是计时器具，不能作为社会研究的对象。", "体重": "搭配：“体重”指人或物的重量，不能作为社会研究的主题。", "钥匙": "语义：钥匙是开锁的工具，与社会研究毫无关系。"}, "sentence_index": 6, "correct_answer": "现代性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们正在学习唐朝的现代性。", "explanation": "这里应该用〈文化〉。现代性指现代社会的特征，不能指唐朝这样的古代；学习唐朝，应学的是它的文化。"}, {"text": "这座大桥的现代性有五十米长。", "explanation": "这里应该用〈长度〉。现代性是抽象的社会特征，没有长短之分，不能用“米”来计量。"}, {"text": "他的现代性很深刻，大家都很佩服。", "explanation": "这里应该用〈思想〉。“深刻”描述思想或见解，现代性是社会的整体特征，不能用来形容人的深刻程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇论文探讨了很现代性的问题。", "corrected_sentence": "这篇论文探讨了现代性的问题。", "error_description": "“现代性”是名词，前面不能直接加程度副词“很”。错误形式是“很现代性”，正确形式是“现代性”，去掉“很”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一把很特别的现代性。", "corrected_sentence": "这是一种很特别的现代性。", "error_description": "“现代性”是抽象名词，量词应用“种”。错误形式用了“把”，“把”用于有柄的器具，正确形式是“一种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
