INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11111, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能胜任某项工作或事情的主观条件；本领。", "primary_collocate": null, "pronunciation": "néng lì", "ipa": "nɤŋ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "他有能力做好这份工作。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事超过了我的能力。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司很看重员工的工作能力。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的能力很强，大家都信任她。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要根据能力安排工作。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有能力照顾孩子。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理看到了小王的能力。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人要多学习，才能提高能力。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作需要有较高的能力。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作能力得到了老板的认可。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工作能力", "label": "复合"}, {"form": "学习能力", "label": "复合"}], "register": "中性", "sense_fingerprint": "能力：胜任工作或事情的本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bc8c19a-b344-4816-9e61-2e91b5fa9608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能力", "is_correct": true, "explanation": "能力：胜任工作的本领，句中指做好这份工作的本领。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指人的容貌，不能用来做好工作，句子说不通。"}, {"text": "户口", "is_correct": false, "explanation": "语义：“户口”指户籍登记，与做好工作无关，句子说不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与做好工作无关，句子说不通。"}], "explanations": {"能力": "能力：胜任工作的本领，句中指做好这份工作的本领。", "外貌": "体貌：“外貌”指人的容貌，不能用来做好工作，句子说不通。", "户口": "语义：“户口”指户籍登记，与做好工作无关，句子说不通。", "体温": "语义：“体温”指身体的温度，与做好工作无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天都充满能力，工作很有精神。", "explanation": "这里应该用〈能量〉。能力指做事的本领，形容人精神饱满要用“能量”，不能说“充满能力”。"}, {"text": "她能力充沛，早上六点就起床。", "explanation": "这里应该用〈精力〉。“充沛”形容精神、劲头，能力不能充沛，应说“精力充沛”。"}, {"text": "她的能力不支，走两步就喊累。", "explanation": "这里应该用〈体力〉。“不支”形容力气耗尽，能力不能“不支”，应说“体力不支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能力", "is_correct": true, "explanation": "能力：做好工作的本领，句中指经理看到的小王的工作本领。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看到”不能与“声音”搭配，听声音要用“听到”，句子说不通。"}, {"text": "方言", "is_correct": false, "explanation": "语义：“方言”是地方话，看不到，与句子的意思不符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，经理不能看到小王的温度，句子说不通。"}], "explanations": {"能力": "能力：做好工作的本领，句中指经理看到的小王的工作本领。", "声音": "搭配：“看到”不能与“声音”搭配，听声音要用“听到”，句子说不通。", "方言": "语义：“方言”是地方话，看不到，与句子的意思不符。", "温度": "语义：“温度”指冷热程度，经理不能看到小王的温度，句子说不通。"}, "sentence_index": 6, "correct_answer": "能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工作能力很长，已经干了十年。", "explanation": "这里应该用〈经验〉。能力指做事的本领，不能用“很长”来形容；应说“工作经验很丰富”。"}, {"text": "他的工作能力很重，经常要加班。", "explanation": "这里应该用〈任务〉。能力指做事的本领，不能用“很重”来形容；应说“工作任务很重”。"}, {"text": "他的工作能力很响，隔壁都能听见。", "explanation": "这里应该用〈声音〉。能力不能用“很响”来形容；应说“声音很响”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一只很强的工作能力，大家都很佩服。", "corrected_sentence": "她有一种很强的工作能力，大家都很佩服。", "error_description": "错误形式：“一只很强的工作能力”；正确形式：“一种很强的工作能力”。能力是抽象名词，量词用“种”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一把很强的应变能力，老板很满意。", "corrected_sentence": "他有一种很强的应变能力，老板很满意。", "error_description": "错误形式：“一把很强的应变能力”；正确形式：“一种很强的应变能力”。能力是抽象名词，量词用“种”，“把”用于带柄的器具。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
