INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11115, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时间尺度指衡量时间长短的单位或范围，如秒、分钟、年，或地质年代等。", "primary_collocate": null, "pronunciation": "shí jiān chǐ dù", "ipa": "ʂɻ̩˧˥ tɕjɛn˥ ʈʂʰɻ̩˨˩˦ tu˥˩", "syllable_count": 4, "sentences": [{"text": "真正的跨文化能力，不在于强制统一时间尺度，而在于培养“时间敏感性”——理解不同文化如何编织其时间意义之网，并在全球化语境中协商出弹性共存的节奏。", "target_word": "时间尺度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "地质学家用很长的时间尺度来研究山脉。", "target_word": "时间尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一秒和一百万年是不同的时间尺度。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个实验里，时间尺度只有几分钟。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史学家常用世纪作为时间尺度。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气候变化需要用更长的时间尺度来看。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生和地质学家使用的时间尺度很不一样。", "target_word": "时间尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图的时间尺度是从一月到十二月。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看问题时，要先想清楚时间尺度。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对于宇宙来说，人的一生是很短的时间尺度。", "target_word": "时间尺度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "時間尺度", "label": "繁体"}], "register": "书面", "sense_fingerprint": "衡量时间长短的单位或范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a14a5b5-fb1c-4d38-a80a-0291bb9dc678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11115, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间尺度", "is_correct": true, "explanation": "这里指衡量时间长短的范围，与“强制统一”的语境相符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的体貌特征，不能被“强制统一”来作为跨文化能力的对象。"}, {"text": "天花板", "is_correct": false, "explanation": "语义：天花板是建筑结构，与跨文化能力无关。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：“海拔”是高度指标，与“强制统一”的语境搭配不当。"}], "explanations": {"时间尺度": "这里指衡量时间长短的范围，与“强制统一”的语境相符。", "身高": "语义：身高是人的体貌特征，不能被“强制统一”来作为跨文化能力的对象。", "天花板": "语义：天花板是建筑结构，与跨文化能力无关。", "海拔": "搭配：“海拔”是高度指标，与“强制统一”的语境搭配不当。"}, "sentence_index": 0, "correct_answer": "时间尺度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张地图的时间尺度是一厘米代表十公里。", "explanation": "这里应该用〈比例尺〉。比例尺指地图上距离的换算关系，时间尺度只用于衡量时间长短。"}, {"text": "我买了一把时间尺度。", "explanation": "问题在于“买”：时间尺度是抽象的衡量范围，不是可以买卖的商品。"}, {"text": "这个问题的时间尺度是红色的。", "explanation": "时间尺度是抽象的时间范围，不能有颜色，这里的用法与词义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11115, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间尺度", "is_correct": true, "explanation": "这里指医生和地质学家所用的时间范围，“很不一样”说的是不同领域的时间尺度。"}, {"text": "脚趾", "is_correct": false, "explanation": "语义：脚趾是身体部位，不能作为医生和地质学家使用的对象。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪是自然现象，与专业人员所用的衡量范围无关。"}, {"text": "风筝", "is_correct": false, "explanation": "搭配：“使用的风筝”与医生和地质学家的工作不搭，二者的“很不一样”无从比较。"}], "explanations": {"时间尺度": "这里指医生和地质学家所用的时间范围，“很不一样”说的是不同领域的时间尺度。", "脚趾": "语义：脚趾是身体部位，不能作为医生和地质学家使用的对象。", "海浪": "语义：海浪是自然现象，与专业人员所用的衡量范围无关。", "风筝": "搭配：“使用的风筝”与医生和地质学家的工作不搭，二者的“很不一样”无从比较。"}, "sentence_index": 6, "correct_answer": "时间尺度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根绳子的时间尺度是三米。", "explanation": "这里应该用〈长度〉。长度衡量物体的空间长短，可以说“长度是三米”；时间尺度只用于时间，不能衡量绳子。"}, {"text": "今天的时间尺度是三十度。", "explanation": "这里应该用〈温度〉。温度用“度”计量气温，时间尺度衡量时间长短，不能用来表示温度。"}, {"text": "他每天都吃时间尺度当早饭。", "explanation": "这里把时间尺度当成〈食物〉来吃。时间尺度是衡量时间长短的单位或范围，是抽象概念，不能吃；能当早饭吃的应是具体的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个很大时间尺度。", "corrected_sentence": "这是一个很大的时间尺度。", "error_description": "修饰语“很大”与名词之间需要结构助词“的”。错误形式漏掉了“的”，正确形式是“很大的时间尺度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要选一台合适的时间尺度。", "corrected_sentence": "我们要选一种合适的时间尺度。", "error_description": "“时间尺度”是抽象名词，不能用“台”计量，“台”用于机器、设备等具体器械。错误形式用了“台”，正确形式是“一种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
