INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11116, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11116, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指通过长期教育、训练或环境的影响，使某种能力、习惯或品性形成并发展。", "primary_collocate": null, "pronunciation": "péi yǎng", "ipa": "pʰeɪ˧˥ jɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "真正的跨文化能力，不在于强制统一时间尺度，而在于培养“时间敏感性”——理解不同文化如何编织其时间意义之网，并在全球化语境中协商出弹性共存的节奏。", "target_word": "培养", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "父母应该从小培养孩子的好习惯。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校很重视培养学生的阅读能力。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "读书可以培养人的耐心。", "target_word": "培养", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司想培养一批年轻的管理人才。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师培养了很多优秀的学生。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要培养兴趣，先要多试一试。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家人从小就培养他学钢琴。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把女儿培养成了一名医生。", "target_word": "培养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的团队精神需要长期培养。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "培养了", "label": "体标"}, {"form": "培养着", "label": "体标"}, {"form": "培养过", "label": "体标"}, {"form": "培養", "label": "繁体"}], "register": "中性", "sense_fingerprint": "通过长期教育或训练使能力、习惯、品性形成并发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a14a5b5-fb1c-4d38-a80a-0291bb9dc678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "销售", "is_correct": false, "explanation": "搭配：“销售”的对象是商品，不能说销售“时间敏感性”。"}, {"text": "培养", "is_correct": true, "explanation": "“培养”指通过长期训练或教育使能力、品性形成，与“时间敏感性”搭配，符合句意。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”与“而在于……”所强调的积极培养相反，句意矛盾。"}, {"text": "掩盖", "is_correct": false, "explanation": "语义：“掩盖”是遮住、隐藏，与句中要获得“时间敏感性”的意思相反。"}], "explanations": {"销售": "搭配：“销售”的对象是商品，不能说销售“时间敏感性”。", "培养": "“培养”指通过长期训练或教育使能力、品性形成，与“时间敏感性”搭配，符合句意。", "丢弃": "语义：“丢弃”与“而在于……”所强调的积极培养相反，句意矛盾。", "掩盖": "语义：“掩盖”是遮住、隐藏，与句中要获得“时间敏感性”的意思相反。"}, "sentence_index": 0, "correct_answer": "培养"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些年他培养了很多经验。", "explanation": "这里应该用〈积累〉。培养用于能力、习惯、品性，经验要靠积累获得。"}, {"text": "他每天培养钢琴两个小时。", "explanation": "这里应该用〈练习〉。培养指使能力、习惯形成，一段时间的练习要说练习，不说培养。"}, {"text": "他每个月培养一些钱，三年后终于买了房。", "explanation": "这里应该用〈积攒〉。培养用于能力、习惯、品性，钱要靠一点点积攒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收集", "is_correct": false, "explanation": "搭配：“收集”用于物品、资料，不说收集兴趣。"}, {"text": "培养", "is_correct": true, "explanation": "“培养”指通过长期训练使兴趣形成，符合“要……兴趣，先要多试一试”的语境。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与后句“先要多试一试”的鼓励语气相反，句意矛盾。"}, {"text": "打听", "is_correct": false, "explanation": "搭配：“打听”的对象是消息、情况，不能说打听兴趣。"}], "explanations": {"收集": "搭配：“收集”用于物品、资料，不说收集兴趣。", "培养": "“培养”指通过长期训练使兴趣形成，符合“要……兴趣，先要多试一试”的语境。", "放弃": "语义：“放弃”与后句“先要多试一试”的鼓励语气相反，句意矛盾。", "打听": "搭配：“打听”的对象是消息、情况，不能说打听兴趣。"}, "sentence_index": 6, "correct_answer": "培养"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在工地上培养了一座大楼。", "explanation": "这里应该用〈建造〉。培养用于人的能力、习惯、品性，不用于建筑。"}, {"text": "警察正在培养那起案件。", "explanation": "这里应该用〈调查〉。培养的对象是人的能力或品德，不用于案件。"}, {"text": "老师在课堂上培养语法。", "explanation": "这里应该用〈讲授〉。培养指使能力、习惯形成，语法知识要用讲授。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把儿子培养了一名工程师。", "corrected_sentence": "他把儿子培养成了一名工程师。", "error_description": "“培养”后缺少补语“成”，“把……培养成……”不能省略“成”，应写作“培养成了一名工程师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的老师把她培养了成一名作家。", "corrected_sentence": "她的老师把她培养成了一名作家。", "error_description": "“培养成”是动补结构，“了”应放在“成”后，写作“培养成了”，不能插在两者之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
