INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11117, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指生物体或系统对外界刺激或变化反应迅速的特性。", "primary_collocate": null, "pronunciation": "mǐn gǎn xìng", "ipa": "min˨˩˦ kan˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "科学家发现，这种细菌对温度的敏感性非常强。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物对光的敏感性很高。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种仪器对温度变化的敏感性很强。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮肤对冷热的敏感性因人而异。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生测试了病人眼睛对光的敏感性。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "含羞草的叶子有很强的敏感性，一碰就合上。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套系统对外界的小变化也有很高的敏感性。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪大了，耳朵对声音的敏感性会下降。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种传感器的敏感性高，能很快发现震动。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗对气味的敏感性比人强得多。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "生物或系统对外界刺激、变化的反应特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a14a5b5-fb1c-4d38-a80a-0291bb9dc678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11117, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：细菌没有价格，“对温度的价格”说不通。"}, {"text": "敏感性", "is_correct": true, "explanation": "“敏感性”指生物对外界刺激（温度）的反应特性，可以说“敏感性非常强”。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”是空间大小，不能受“对温度的”修饰，也不说“面积非常强”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”与对温度的反应无关，“对温度的年龄”说不通。"}], "explanations": {"价格": "语义：细菌没有价格，“对温度的价格”说不通。", "敏感性": "“敏感性”指生物对外界刺激（温度）的反应特性，可以说“敏感性非常强”。", "面积": "搭配：“面积”是空间大小，不能受“对温度的”修饰，也不说“面积非常强”。", "年龄": "语义：“年龄”与对温度的反应无关，“对温度的年龄”说不通。"}, "sentence_index": 0, "correct_answer": "敏感性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的敏感性很快。", "explanation": "这里应该用〈速度〉。敏感性指对刺激的察觉与反应，不用于说运行快慢。"}, {"text": "这幅画的敏感性很高。", "explanation": "这里应该用〈清晰度〉。敏感性指对刺激的反应能力，不用于描述画面是否清楚。"}, {"text": "这个箱子的敏感性很大。", "explanation": "这里应该用〈容量〉。敏感性指对刺激的反应能力，不用于描述物体的容量大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体积", "is_correct": false, "explanation": "搭配：“很高的体积”形容空间大小，不能形容系统对变化的反应。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”与“对外界的小变化”没有关系，句意不通。"}, {"text": "敏感性", "is_correct": true, "explanation": "“敏感性”指系统对外界小变化的反应特性，与“很高的”搭配，符合句意。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：“亮度”指光线明暗，不能用来描述系统对外界小变化的反应。"}], "explanations": {"体积": "搭配：“很高的体积”形容空间大小，不能形容系统对变化的反应。", "价格": "语义：“价格”与“对外界的小变化”没有关系，句意不通。", "敏感性": "“敏感性”指系统对外界小变化的反应特性，与“很高的”搭配，符合句意。", "亮度": "语义：“亮度”指光线明暗，不能用来描述系统对外界小变化的反应。"}, "sentence_index": 6, "correct_answer": "敏感性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块钢的敏感性有三公斤重。", "explanation": "这里应该用〈重量〉。敏感性指对刺激的反应特性，不能用来说明物体有多重。"}, {"text": "这件衣服的敏感性比较便宜。", "explanation": "这里应该用〈价格〉。敏感性不描述价格高低。"}, {"text": "今天的敏感性很高。", "explanation": "这里应该用〈温度〉。敏感性指对刺激的反应能力，不用于说气温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种鸟对磁场有很高地敏感性。", "corrected_sentence": "这种鸟对磁场有很高的敏感性。", "error_description": "“敏感性”前的修饰语应用“的”，不用“地”（“地”用于修饰动词、形容词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜜蜂对花香有一只很强的敏感性。", "corrected_sentence": "蜜蜂对花香有一种很强的敏感性。", "error_description": "“敏感性”是抽象名词，量词应用“种”，不能用“只”（“只”用于具体的动物等个体）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11119, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
