INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11119, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用绳线编织成的捕鱼或捕鸟的器具；也指形状像网的东西或系统。", "primary_collocate": null, "pronunciation": "wǎng", "ipa": "wɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "渔民把网撒进河里。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛在墙角织了一张网。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿飞进了网里，出不来了。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张网很大，一次能捕很多鱼。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁线路像一张网，连着整个城市。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在这一带布下了一张大网。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网破了一个洞，要补一补。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老渔夫坐在船边补网。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路和公路连成一张网。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用网围住了池塘的一角。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "網", "label": "繁体"}, {"form": "渔网", "label": "复合"}], "register": "中性", "sense_fingerprint": "编织的捕鱼捕鸟器具，或像网一样的系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 围住 (Zipf 3.33), 池塘 (Zipf 3.72), 一角 (Zipf 3.7)']::text[], '3a14a5b5-fb1c-4d38-a80a-0291bb9dc678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11119, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "网", "is_correct": true, "explanation": "正确。网（wǎng）指用绳线编织的捕鱼、捕鸟器具，也指像网的东西或系统。"}, {"text": "王", "is_correct": false, "explanation": "wáng（第二声）与 wǎng（第三声）声调不同，意思是国王。"}, {"text": "忘", "is_correct": false, "explanation": "wàng（第四声）与 wǎng（第三声）声调不同，意思是忘记。"}, {"text": "汪", "is_correct": false, "explanation": "wāng（第一声）与 wǎng（第三声）声调不同，意思是水面宽广的样子。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn 与 wǎng 韵母不同（an 与 ang），意思是盛饭菜的器皿。"}], "explanations": {"网": "正确。网（wǎng）指用绳线编织的捕鱼、捕鸟器具，也指像网的东西或系统。", "王": "wáng（第二声）与 wǎng（第三声）声调不同，意思是国王。", "忘": "wàng（第四声）与 wǎng（第三声）声调不同，意思是忘记。", "汪": "wāng（第一声）与 wǎng（第三声）声调不同，意思是水面宽广的样子。", "碗": "wǎn 与 wǎng 韵母不同（an 与 ang），意思是盛饭菜的器皿。"}, "sentence_index": null, "correct_answer": "网"}, "level_3": {"options": [{"text": "网", "is_correct": true, "explanation": "正确。撒网是渔民捕鱼的动作，“网”指捕鱼的器具。"}, {"text": "帽子", "is_correct": false, "explanation": "搭配：“撒”的对象是细小、能散开的东西，不能把帽子撒进河里。"}, {"text": "鸟", "is_correct": false, "explanation": "语义：鸟是活的动物，渔民不会把它撒进河里。"}, {"text": "船", "is_correct": false, "explanation": "配价：“撒”不能支配船这样的大件物体作宾语。"}], "explanations": {"网": "正确。撒网是渔民捕鱼的动作，“网”指捕鱼的器具。", "帽子": "搭配：“撒”的对象是细小、能散开的东西，不能把帽子撒进河里。", "鸟": "语义：鸟是活的动物，渔民不会把它撒进河里。", "船": "配价：“撒”不能支配船这样的大件物体作宾语。"}, "sentence_index": 0, "correct_answer": "网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用网缝了一件衣服。", "explanation": "这里应该用〈线〉。缝衣服要用针和线，网是捕鱼或捕鸟的器具，不能用来缝衣服。"}, {"text": "他用网画了一幅画。", "explanation": "这里应该用〈笔〉。画画要用笔和颜料，网是捕鱼或捕鸟的器具，不能用来作画。"}, {"text": "渔民用网叉鱼。", "explanation": "这里应该用〈鱼叉〉。叉鱼要用鱼叉，网是用来撒或拉的器具，不能说“用网叉鱼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11119, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "网", "is_correct": true, "explanation": "正确。网（wǎng）指用绳线编织的捕鱼、捕鸟器具，也指像网的东西或系统。"}, {"text": "望", "is_correct": false, "explanation": "wàng（第四声）与 wǎng（第三声）声调不同，意思是看、盼望。"}, {"text": "旺", "is_correct": false, "explanation": "wàng（第四声）与 wǎng（第三声）声调不同，意思是旺盛。"}, {"text": "晚", "is_correct": false, "explanation": "wǎn 与 wǎng 韵母不同（an 与 ang），意思是晚上。"}, {"text": "汪", "is_correct": false, "explanation": "wāng（第一声）与 wǎng（第三声）声调不同，意思是水面宽广的样子。"}], "explanations": {"网": "正确。网（wǎng）指用绳线编织的捕鱼、捕鸟器具，也指像网的东西或系统。", "望": "wàng（第四声）与 wǎng（第三声）声调不同，意思是看、盼望。", "旺": "wàng（第四声）与 wǎng（第三声）声调不同，意思是旺盛。", "晚": "wǎn 与 wǎng 韵母不同（an 与 ang），意思是晚上。", "汪": "wāng（第一声）与 wǎng（第三声）声调不同，意思是水面宽广的样子。"}, "sentence_index": null, "correct_answer": "网"}, "level_3": {"options": [{"text": "网", "is_correct": true, "explanation": "正确。网破了洞，要补，说的是渔网之类的器具。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食物，不是能缝补的器物，“补一补”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“破了一个洞”多用于衣物、布料等，不说石头破了洞。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡破了是碎裂，不能像布料那样“补一补”。"}], "explanations": {"网": "正确。网破了洞，要补，说的是渔网之类的器具。", "饼干": "语义：饼干是食物，不是能缝补的器物，“补一补”说不通。", "石头": "搭配：“破了一个洞”多用于衣物、布料等，不说石头破了洞。", "灯泡": "语义：灯泡破了是碎裂，不能像布料那样“补一补”。"}, "sentence_index": 6, "correct_answer": "网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用网擦了桌子。", "explanation": "这里应该用〈抹布〉。擦桌子要用抹布，网是捕鱼或捕鸟的器具，不能用来擦东西。"}, {"text": "他们用网烧水。", "explanation": "这里应该用〈锅〉。烧水要用锅，网是捕鱼、捕鸟的器具，不能用来烧水。"}, {"text": "他们用网锁住了大门。", "explanation": "这里应该用〈锁〉。锁门要用锁，网不能用来锁门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渔民在河边撒了一只网。", "corrected_sentence": "渔民在河边撒了一张网。", "error_description": "量词错误：网是片状的器具，应用量词“张”。“一只网”错误，应为“一张网”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔民把网补了好。", "corrected_sentence": "渔民把网补好了。", "error_description": "补语位置错误：“补好”是动补结构，“了”应放在补语之后。“补了好”错误，应为“补好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
