INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11121, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11121, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "多个事物或人同时存在，彼此不排斥。", "primary_collocate": null, "pronunciation": "gòng cún", "ipa": "kʊŋ˥˩ tsʰwən˧˥", "syllable_count": 2, "sentences": [{"text": "真正的跨文化能力，不在于强制统一时间尺度，而在于培养“时间敏感性”——理解不同文化如何编织其时间意义之网，并在全球化语境中协商出弹性共存的节奏。", "target_word": "共存", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "未来的研究还需要继续探索如何更好地与这些小昆虫共存。", "target_word": "共存", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "人和动物可以在城市里共存。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新旧文化在这个城市共存。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种语言在这里共存了很多年。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学会与自然共存。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的意见可以共存。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子和高楼在这条街上共存。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传统和现代共存着，很有意思。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家里，几种宗教长期共存。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共存了", "label": "体标"}, {"form": "共存过", "label": "体标"}, {"form": "共存着", "label": "体标"}, {"form": "和平共存", "label": "复合"}], "register": "中性", "sense_fingerprint": "多个事物或人同时存在并且互不排斥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d483ca1-93ac-4b0e-b4cc-1888a4e9895c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11121, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共存", "is_correct": true, "explanation": "共存指多方同时存在、彼此相容，与“协商出弹性……的节奏”相合。"}, {"text": "对抗", "is_correct": false, "explanation": "语义：对抗指相互抵触，与“协商”的语境相反。"}, {"text": "争夺", "is_correct": false, "explanation": "搭配：“争夺”的对象是资源或地位，不能与“节奏”搭配。"}, {"text": "隔离", "is_correct": false, "explanation": "语义：隔离指分开、互不往来，与“协商出……的节奏”冲突。"}], "explanations": {"共存": "共存指多方同时存在、彼此相容，与“协商出弹性……的节奏”相合。", "对抗": "语义：对抗指相互抵触，与“协商”的语境相反。", "争夺": "搭配：“争夺”的对象是资源或地位，不能与“节奏”搭配。", "隔离": "语义：隔离指分开、互不往来，与“协商出……的节奏”冲突。"}, "sentence_index": 0, "correct_answer": "共存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们共存到达了车站。", "explanation": "这里应该用〈同时〉。共存指多者同时并存，不能用来修饰“到达”这一动作。"}, {"text": "他共存工作到深夜。", "explanation": "这里应该用〈继续〉。共存指多者并存，不能表示动作接着进行。"}, {"text": "两个公司决定共存研发新产品。", "explanation": "这里应该用〈合作〉。共存指并存，不能表示一起做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共存", "is_correct": true, "explanation": "“不同的意见可以共存”指不同意见同时存在、互不排斥，与语境相合。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”的对象是影音，不能与“意见”搭配。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙指用火加热食物，与意见无关。"}, {"text": "剪裁", "is_correct": false, "explanation": "语义：剪裁指裁剪布料，不能用于意见。"}], "explanations": {"共存": "“不同的意见可以共存”指不同意见同时存在、互不排斥，与语境相合。", "播放": "搭配：“播放”的对象是影音，不能与“意见”搭配。", "烘焙": "语义：烘焙指用火加热食物，与意见无关。", "剪裁": "语义：剪裁指裁剪布料，不能用于意见。"}, "sentence_index": 6, "correct_answer": "共存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场雨共存了一下午。", "explanation": "这里应该用〈持续〉。共存指多者同时并存，不表示时间延续。"}, {"text": "他共存离开了房间。", "explanation": "这里应该用〈立刻〉。共存指多者并存，不能表示动作马上发生。"}, {"text": "他共存练习这个动作。", "explanation": "这里应该用〈反复〉。共存指并存，不能表示多次重复做某事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个国家可以把和平共存。", "corrected_sentence": "这两个国家可以和平共存。", "error_description": "“共存”是不及物动词，不能用“把”字句；“和平”是修饰语，应直接放在“共存”前，写作“可以和平共存”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两种语言曾经共存着很长时间。", "corrected_sentence": "这两种语言曾经共存过很长时间。", "error_description": "表示经历的助词应为“过”，写作“共存过”；“着”表示持续，与“曾经”的经历语境冲突。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
