INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生活中事件发生的规律性速度或自然的步调", "primary_collocate": null, "pronunciation": "jié zòu", "ipa": "tɕjɛ˧˥ tsou˥˩", "syllable_count": 2, "sentences": [{"text": "一场商务会面可能因一场突如其来的家庭话题而延长，迟到十分钟并不构成冒犯，反而是生活节奏自然延展的一部分。", "target_word": "节奏", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "真正的跨文化能力，不在于强制统一时间尺度，而在于培养“时间敏感性”——理解不同文化如何编织其时间意义之网，并在全球化语境中协商出弹性共存的节奏。", "target_word": "节奏", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "大城市的生活节奏很快。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我喜欢放慢生活的节奏。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到小镇以后，他的生活节奏慢了下来。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作节奏太快，大家都觉得很累。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休后，老人按自己的节奏过日子。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子刚上学，需要时间适应学校的节奏。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乡下的节奏慢，人们不着急。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国旅行时，我们跟着当地人的节奏生活。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "節奏", "label": "繁体"}, {"form": "节奏感", "label": "复合"}], "register": "中性", "sense_fingerprint": "生活、工作中事情进行的快慢步调", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a14a5b5-fb1c-4d38-a80a-0291bb9dc678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11122, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "节奏", "is_correct": true, "explanation": "正确。节奏（jié zòu）指生活中事情的规律性速度或自然步调。"}, {"text": "结构", "is_correct": false, "explanation": "结构（jié gòu）与节奏（jié zòu）第二个音节声母不同（g 与 z），意思是事物各部分的组织和构造。"}, {"text": "间奏", "is_correct": false, "explanation": "间奏（jiān zòu）与节奏（jié zòu）第一个音节韵母和声调不同，意思是乐曲中间的器乐段落。"}, {"text": "接走", "is_correct": false, "explanation": "接走（jiē zǒu）与节奏（jié zòu）两个音节的声调都不同，意思是把人接去别处。"}, {"text": "协奏", "is_correct": false, "explanation": "协奏（xié zòu）与节奏（jié zòu）第一个音节声母不同（x 与 j），意思是几种乐器协同演奏。"}], "explanations": {"节奏": "正确。节奏（jié zòu）指生活中事情的规律性速度或自然步调。", "结构": "结构（jié gòu）与节奏（jié zòu）第二个音节声母不同（g 与 z），意思是事物各部分的组织和构造。", "间奏": "间奏（jiān zòu）与节奏（jié zòu）第一个音节韵母和声调不同，意思是乐曲中间的器乐段落。", "接走": "接走（jiē zǒu）与节奏（jié zòu）两个音节的声调都不同，意思是把人接去别处。", "协奏": "协奏（xié zòu）与节奏（jié zòu）第一个音节声母不同（x 与 j），意思是几种乐器协同演奏。"}, "sentence_index": null, "correct_answer": "节奏"}, "level_3": {"options": [{"text": "节奏", "is_correct": true, "explanation": "正确。“生活节奏”指生活中事情的快慢步调，符合“自然延展”的语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能“自然延展”，与“生活”搭不上。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不能作为生活的延展部分，句子说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“生活”不搭配“价格”作延展的一部分。"}], "explanations": {"节奏": "正确。“生活节奏”指生活中事情的快慢步调，符合“自然延展”的语境。", "颜色": "语义：颜色不能“自然延展”，与“生活”搭不上。", "咖啡": "语义：咖啡不能作为生活的延展部分，句子说不通。", "价格": "搭配：“生活”不搭配“价格”作延展的一部分。"}, "sentence_index": 0, "correct_answer": "节奏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车的节奏每小时一百公里。", "explanation": "这里应该用〈速度〉。速度可以用“每小时一百公里”计量；节奏指快慢步调，不能用数量来算。"}, {"text": "他的生活节奏很暴躁。", "explanation": "这里应该用〈脾气〉。脾气可以暴躁，节奏指生活的步调，不能用“暴躁”来形容。"}, {"text": "工作节奏已经完成了一半。", "explanation": "这里应该用〈进度〉。进度指事情完成的程度，可以说“完成了一半”；节奏是步调，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节奏", "is_correct": true, "explanation": "正确。“按自己的节奏过日子”指按自己的步调生活，符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是身体特征，不能作为过日子的依据。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不能用来“过日子”，句子说不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“按……过日子”不搭配“手机”。"}], "explanations": {"节奏": "正确。“按自己的节奏过日子”指按自己的步调生活，符合语境。", "身高": "语义：身高是身体特征，不能作为过日子的依据。", "名字": "语义：名字不能用来“过日子”，句子说不通。", "手机": "搭配：“按……过日子”不搭配“手机”。"}, "sentence_index": 6, "correct_answer": "节奏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天早上的节奏只有五度。", "explanation": "这里应该用〈温度〉。温度用度数计量；节奏指生活或事情的快慢步调，不能用“五度”来衡量。"}, {"text": "这台电梯的节奏每秒两米。", "explanation": "这里应该用〈速度〉。速度可以用“每秒两米”计量；节奏是步调，不能用距离和时间来算。"}, {"text": "他的节奏增加了三公斤。", "explanation": "这里应该用〈体重〉。体重以公斤计量，可以增加；节奏是快慢步调，不能按重量增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于找回了自己地生活节奏。", "corrected_sentence": "他终于找回了自己的生活节奏。", "error_description": "结构助词误用：“自己”修饰名词“生活节奏”，应用“的”，不能用“地”。“自己地生活节奏”错误，应为“自己的生活节奏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把生活节奏放了慢一些。", "corrected_sentence": "他把生活节奏放慢了一些。", "error_description": "补语位置错误：“放慢”是动补结构，“了”应放在补语之后。“放了慢”错误，应为“放慢了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
