INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11124, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示正是、恰好，用以强调确切、恰到好处，或强调与预期相反的情况。", "primary_collocate": null, "pronunciation": "qià qià", "ipa": "tɕʰja˥˩ tɕʰja˥˩", "syllable_count": 2, "sentences": [{"text": "值得注意的是，口头传统的韧性恰恰源于其流动性。", "target_word": "恰恰", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "当世界越来越“快”，也许最深刻的智慧，恰恰在于学会在差异的时流中从容摆渡。", "target_word": "恰恰", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他想找的人，恰恰就是我。", "target_word": "恰恰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "问题恰恰出在我们没有提前准备。", "target_word": "恰恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的恰恰相反。", "target_word": "恰恰", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们现在最需要的，恰恰是时间。", "target_word": "恰恰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "失败恰恰让他学会了坚持。", "target_word": "恰恰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不是不努力，恰恰相反，他非常努力。", "target_word": "恰恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成功的秘密恰恰是每天坚持练习。", "target_word": "恰恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不是坏事，恰恰是好事。", "target_word": "恰恰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "恰恰：副词，强调正好、恰到好处，常与相反或出人意料的情况相连", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3701140-a2a2-4137-8b61-b34e446ee27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恰恰", "is_correct": true, "explanation": "正确：“韧性恰恰源于其流动性”强调韧性正是来自流动性，与前文的预期相反。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”只修饰形容词或心理动词，不能修饰动词“源于”。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词，不能修饰动词“源于”。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”修饰形容词，不能修饰动词“源于”。"}], "explanations": {"恰恰": "正确：“韧性恰恰源于其流动性”强调韧性正是来自流动性，与前文的预期相反。", "很": "搭配：“很”只修饰形容词或心理动词，不能修饰动词“源于”。", "非常": "搭配：“非常”修饰形容词，不能修饰动词“源于”。", "太": "搭配：“太”修饰形容词，不能修饰动词“源于”。"}, "sentence_index": 0, "correct_answer": "恰恰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大概恰恰有三十岁。", "explanation": "错误：“恰恰”表示确切、正是，不能与表示估计的“大概”同用；应去掉“恰恰”。"}, {"text": "这个班差不多恰恰有四十个人。", "explanation": "错误：“恰恰”表示确切，不能与表示估计的“差不多”同用；应去掉“恰恰”。"}, {"text": "我们几乎恰恰到了山顶。", "explanation": "错误：“恰恰”表示确切，不能与表示接近的“几乎”同用；应去掉“恰恰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恰恰", "is_correct": true, "explanation": "正确：“失败恰恰让他学会了坚持”说明失败正是让他学会坚持的原因，与“恰恰”的含义相符。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，需要后接处置对象，不能放在“失败”之后、“让”之前。"}, {"text": "拼命", "is_correct": false, "explanation": "语义：“拼命”形容尽力、用劲地做某事，不能修饰“让”表示结果，语义不通。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“让他学会了坚持”的结果相矛盾。"}], "explanations": {"恰恰": "正确：“失败恰恰让他学会了坚持”说明失败正是让他学会坚持的原因，与“恰恰”的含义相符。", "把": "语法：“把”是介词，需要后接处置对象，不能放在“失败”之后、“让”之前。", "拼命": "语义：“拼命”形容尽力、用劲地做某事，不能修饰“让”表示结果，语义不通。", "从不": "语义：“从不”表示从来没有，与“让他学会了坚持”的结果相矛盾。"}, "sentence_index": 6, "correct_answer": "恰恰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个数字估计恰恰是一百。", "explanation": "错误：“恰恰”表示确切，不能与表示推测的“估计”同用；应去掉“恰恰”。"}, {"text": "这段路大约恰恰有十公里。", "explanation": "错误：“恰恰”表示确切，不能与表示估计的“大约”同用；应去掉“恰恰”。"}, {"text": "我们等了他一个小时左右，恰恰是一个小时。", "explanation": "错误：前面说“左右”（估计），后面又用“恰恰”（确切），前后矛盾；应去掉“恰恰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这恰恰有我想要的。", "corrected_sentence": "这恰恰是我想要的。", "error_description": "错误：“恰恰有我想要的”，“恰恰”表示正是，后面应接判断词“是”，不能接“有”。正确：“这恰恰是我想要的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次的错误恰恰很不是我造成的。", "corrected_sentence": "这次的错误恰恰不是我造成的。", "error_description": "错误：“恰恰很不是”，“恰恰”表示确切、正是，不能与程度副词“很”同用。正确：“恰恰不是我造成的”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
