INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11125, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "像水流一样消逝的时光。", "primary_collocate": null, "pronunciation": "shí liú", "ipa": "ʂɻ̩˧˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "当世界越来越“快”，也许最深刻的智慧，恰恰在于学会在差异的时流中从容摆渡。", "target_word": "时流", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "时流不停，我们都在慢慢长大。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她望着窗外，想着时流带走的日子。", "target_word": "时流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在时流里，旧事慢慢变成了回忆。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人静静地坐着，听时流从身边走过。", "target_word": "时流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也拦不住时流，只能好好过每一天。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时流如水，一去不回。", "target_word": "时流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这首诗写的是时流，也写人的心情。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在诗里写下了对时流的感慨。", "target_word": "时流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对时流，年轻人总是不太在意。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "文学", "sense_fingerprint": "时流：像流水般逝去的时光", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '461c370f-be46-4e41-96a9-fb0d343458d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11125, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时流", "is_correct": true, "explanation": "时流 shí liú：像流水一样消逝的时光，是本题的答案。"}, {"text": "石榴", "is_correct": false, "explanation": "石榴 shíliu：第二个音节是轻声，与 liú（阳平）声调不同，意思是一种水果。"}, {"text": "十六", "is_correct": false, "explanation": "十六 shíliù：第二个音节是去声，与 liú（阳平）声调不同，意思是数字十六。"}, {"text": "直流", "is_correct": false, "explanation": "直流 zhí liú：声母是 zh，与 shí 的 sh 不同（声调相同），意思是直流电。"}], "explanations": {"时流": "时流 shí liú：像流水一样消逝的时光，是本题的答案。", "石榴": "石榴 shíliu：第二个音节是轻声，与 liú（阳平）声调不同，意思是一种水果。", "十六": "十六 shíliù：第二个音节是去声，与 liú（阳平）声调不同，意思是数字十六。", "直流": "直流 zhí liú：声母是 zh，与 shí 的 sh 不同（声调相同），意思是直流电。"}, "sentence_index": null, "correct_answer": "时流"}, "level_3": {"options": [{"text": "时流", "is_correct": true, "explanation": "时流：像流水般消逝的时光，正好契合“在差异的时流中从容摆渡”的比喻。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会流动，不能在其中“从容摆渡”，与句中的比喻不相容。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“差异的窗户”不成立，窗户不是可以摆渡穿行的场域。"}, {"text": "木板", "is_correct": false, "explanation": "语义：木板是静止的物件，与“摆渡”所需的流动环境不符。"}], "explanations": {"时流": "时流：像流水般消逝的时光，正好契合“在差异的时流中从容摆渡”的比喻。", "石头": "语义：石头不会流动，不能在其中“从容摆渡”，与句中的比喻不相容。", "窗户": "搭配：“差异的窗户”不成立，窗户不是可以摆渡穿行的场域。", "木板": "语义：木板是静止的物件，与“摆渡”所需的流动环境不符。"}, "sentence_index": 0, "correct_answer": "时流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条小溪的时流很急。", "explanation": "这里应该用〈水流〉。时流指像流水般消逝的时光，不指溪水的流动；形容溪水湍急，要用“水流”。"}, {"text": "他用手把时流捏成了一团。", "explanation": "时流是抽象的流动时光，无法用手捏成一团，这里不能这样用。"}, {"text": "我们一起把美好的时流叠好，收进了抽屉。", "explanation": "时流不是衣物，不能叠好收进抽屉，这里不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11125, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时流", "is_correct": true, "explanation": "时流：像水一样流逝的时光，与“一去不回”相合。"}, {"text": "砖块", "is_correct": false, "explanation": "语义：砖块不会流动，不能说“如水，一去不回”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气如水”不是常见比喻，天气也不会“一去不回”。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是静止的物体，与“如水”的流动形象相反。"}], "explanations": {"时流": "时流：像水一样流逝的时光，与“一去不回”相合。", "砖块": "语义：砖块不会流动，不能说“如水，一去不回”。", "天气": "搭配：“天气如水”不是常见比喻，天气也不会“一去不回”。", "电线": "语义：电线是静止的物体，与“如水”的流动形象相反。"}, "sentence_index": 6, "correct_answer": "时流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手把一整天的时流折成了一只纸鹤。", "explanation": "时流是抽象的流动时光，不是可以折叠的纸张，这里不能这样用。"}, {"text": "他用手擦去了桌上的时流。", "explanation": "时流是抽象的时光，不是可以擦拭的东西，这里不能这样用。"}, {"text": "那几年，时流把他的书包压得很重。", "explanation": "时流是抽象的时光，不能用来压重书包，这里不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "回头看，一只时流已经带走了许多旧日子。", "corrected_sentence": "回头看，时流已经带走了许多旧日子。", "error_description": "错误：“一只时流”。时流是抽象的流动，不能用“只”（多用于动物或单件物品）计量。正确说法是去掉量词，或用“一股时流”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "回想起来，时流们过得真快。", "corrected_sentence": "回想起来，时流过得真快。", "error_description": "错误：“时流们”。“们”只用于指人的复数，抽象名词“时流”不能加“们”。正确说法是“时流过得真快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11126, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "慌张", "is_correct": true, "explanation": "慌张：慌乱、不镇定，与“从容”的态度相反。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：指明白、不模糊，与“从容”的态度无关。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软：指质地柔和，与“从容”无关。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：指光线或眼神明亮，与“从容”的态度无关。"}], "correct_answer": "慌张", "explanations": {"慌张": "慌张：慌乱、不镇定，与“从容”的态度相反。", "清楚": "清楚：指明白、不模糊，与“从容”的态度无关。", "柔软": "柔软：指质地柔和，与“从容”无关。", "明亮": "明亮：指光线或眼神明亮，与“从容”的态度无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11126, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "慌张", "is_correct": true, "explanation": "慌张：慌乱、不镇定，与“从容”的态度相反。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙：指表面不光滑，与“从容”无关。"}, {"text": "迟钝", "is_correct": false, "explanation": "迟钝：指反应慢，不是“从容”的反义词。"}, {"text": "浑浊", "is_correct": false, "explanation": "浑浊：指水或空气不清澈，与“从容”无关。"}], "correct_answer": "慌张", "explanations": {"慌张": "慌张：慌乱、不镇定，与“从容”的态度相反。", "粗糙": "粗糙：指表面不光滑，与“从容”无关。", "迟钝": "迟钝：指反应慢，不是“从容”的反义词。", "浑浊": "浑浊：指水或空气不清澈，与“从容”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11126, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容态度镇定，不慌不忙。", "primary_collocate": null, "pronunciation": "cóng róng", "ipa": "tsʰʊŋ˧˥ ɻʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "当世界越来越“快”，也许最深刻的智慧，恰恰在于学会在差异的时流中从容摆渡。", "target_word": "从容", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "她面对考试很从容。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从容地走上台，开始讲话。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到问题时，他总是很从容。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从容地回答了每个问题。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的态度从容，一点儿也不紧张。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间还早，我们可以从容地吃早饭。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从容地把书放进了包里。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试的时候，她回答得很从容。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着他从容的样子，大家也放心了。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "從容", "label": "繁体"}, {"form": "从容不迫", "label": "复合"}], "register": "中性", "sense_fingerprint": "从容：态度镇定，不慌不忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '461c370f-be46-4e41-96a9-fb0d343458d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11126, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从容", "is_correct": true, "explanation": "从容：态度镇定、不慌不忙，与“最深刻的智慧”和“摆渡”的沉稳形象相合。"}, {"text": "粗鲁", "is_correct": false, "explanation": "语义：粗鲁与“最深刻的智慧”相悖，不能用来描述摆渡的方式。"}, {"text": "狂乱", "is_correct": false, "explanation": "语义：狂乱是失控的状态，与“学会……摆渡”所讲的智慧正好相反。"}, {"text": "迟钝", "is_correct": false, "explanation": "搭配：“迟钝”形容人的反应，不修饰“摆渡”的方式。"}], "explanations": {"从容": "从容：态度镇定、不慌不忙，与“最深刻的智慧”和“摆渡”的沉稳形象相合。", "粗鲁": "语义：粗鲁与“最深刻的智慧”相悖，不能用来描述摆渡的方式。", "狂乱": "语义：狂乱是失控的状态，与“学会……摆渡”所讲的智慧正好相反。", "迟钝": "搭配：“迟钝”形容人的反应，不修饰“摆渡”的方式。"}, "sentence_index": 0, "correct_answer": "从容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯热茶很从容。", "explanation": "从容形容人的态度镇定，茶水不能用它来形容，这里应说“很热”。"}, {"text": "这间教室很从容。", "explanation": "这里应该用〈安静〉。从容说的是人的态度，教室是地点，应说“很安静”。"}, {"text": "这把椅子很从容。", "explanation": "从容形容人的态度，椅子不能用它来形容，这里应说“很稳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从容", "is_correct": true, "explanation": "从容：不慌不忙，与“时间还早”的语境相合。"}, {"text": "慌忙", "is_correct": false, "explanation": "语义：慌忙与“时间还早”的前提相矛盾，不说“可以慌忙地吃早饭”。"}, {"text": "仓促", "is_correct": false, "explanation": "语义：仓促表示急迫，与“时间还早”的语境不符。"}, {"text": "急促", "is_correct": false, "explanation": "搭配：“急促”多形容呼吸、声音，不修饰吃饭的样子。"}], "explanations": {"从容": "从容：不慌不忙，与“时间还早”的语境相合。", "慌忙": "语义：慌忙与“时间还早”的前提相矛盾，不说“可以慌忙地吃早饭”。", "仓促": "语义：仓促表示急迫，与“时间还早”的语境不符。", "急促": "搭配：“急促”多形容呼吸、声音，不修饰吃饭的样子。"}, "sentence_index": 6, "correct_answer": "从容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗面条很从容。", "explanation": "从容形容人的态度镇定，面条不能用它来形容，这句不成立。"}, {"text": "山谷里一片从容。", "explanation": "这里应该用〈寂静〉。从容用于人的态度，不能用来描写山谷的安静景象。"}, {"text": "这把雨伞很从容。", "explanation": "从容形容人的态度镇定，雨伞不能用它来形容，这句不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从容的关上了门。", "corrected_sentence": "她从容地关上了门。", "error_description": "错误：“从容的关上了门”；正确：“从容地关上了门”。“从容”修饰动词作状语时，要用“地”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她说话很从容得。", "corrected_sentence": "她说话很从容。", "error_description": "错误：“很从容得”；正确：“很从容”。句末多出的“得”没有补语，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
