INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11127, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用船运载人或物过河。", "primary_collocate": null, "pronunciation": "bǎi dù", "ipa": "pai˨˩˦ tu˥˩", "syllable_count": 2, "sentences": [{"text": "夜里，船夫还在河上一趟趟地摆渡行人。", "target_word": "摆渡", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "老李每天用小船摆渡客人。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河很宽，船夫把我们摆渡到对岸。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里没有桥，要等船夫摆渡我们过河。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨，河边的小船开始摆渡行人了。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前这条河靠一条小船摆渡。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他划着小船，把货物摆渡到河对岸。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，河水太急，船夫不再摆渡了。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渡口的船夫摆渡了一辈子。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摆渡一次要十分钟，一个人收两块钱。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摆渡了", "label": "体标"}, {"form": "摆渡过", "label": "体标"}, {"form": "摆渡船", "label": "复合"}, {"form": "摆渡人", "label": "复合"}, {"form": "擺渡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用船载人或货物渡过河流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a94ae4-79af-4eab-97ed-f48899b3b919') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11127, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摆渡", "is_correct": true, "explanation": "摆渡（bǎi dù）：用船把人或物渡过河，是本词的正确答案。"}, {"text": "拜读", "is_correct": false, "explanation": "拜读（bài dú）两个音节的声调都与摆渡（bǎi dù）不同，意思是恭敬地阅读。"}, {"text": "白度", "is_correct": false, "explanation": "白度（bái dù）第一个音节是第二声，摆渡是第三声；意思是白的程度。"}, {"text": "摆布", "is_correct": false, "explanation": "摆布（bǎi bù）第二个音节声母不同（b 与 d），意思是支配、控制。"}], "explanations": {"摆渡": "摆渡（bǎi dù）：用船把人或物渡过河，是本词的正确答案。", "拜读": "拜读（bài dú）两个音节的声调都与摆渡（bǎi dù）不同，意思是恭敬地阅读。", "白度": "白度（bái dù）第一个音节是第二声，摆渡是第三声；意思是白的程度。", "摆布": "摆布（bǎi bù）第二个音节声母不同（b 与 d），意思是支配、控制。"}, "sentence_index": null, "correct_answer": "摆渡"}, "level_3": {"options": [{"text": "摆渡", "is_correct": true, "explanation": "摆渡：用船运送人或物过河，此处指船夫在河上一趟趟往返摆渡行人。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：砍伐指砍倒树木，与在河上摆渡行人的意思毫无关系。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”后面接车、船等交通工具，不能接“行人”这类人，搭配不合。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙指用火烤制食物，与船夫摆渡行人的意思不相合。"}], "explanations": {"摆渡": "摆渡：用船运送人或物过河，此处指船夫在河上一趟趟往返摆渡行人。", "砍伐": "语义：砍伐指砍倒树木，与在河上摆渡行人的意思毫无关系。", "驾驶": "搭配：“驾驶”后面接车、船等交通工具，不能接“行人”这类人，搭配不合。", "烘焙": "语义：烘焙指用火烤制食物，与船夫摆渡行人的意思不相合。"}, "sentence_index": 0, "correct_answer": "摆渡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用卡车摆渡货物到仓库。", "explanation": "这里应该用〈运送〉。摆渡必须借船跨越水面，陆上用卡车运货不能说摆渡。"}, {"text": "我们游泳摆渡了长江。", "explanation": "这里应该用〈横渡〉。摆渡是借船运送人或物，自己游过去不能说摆渡。"}, {"text": "我们走路摆渡了那座高山。", "explanation": "这里应该用〈翻越〉。摆渡是用船把人或物运过河，走路越过高山不能说摆渡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11127, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摆渡", "is_correct": true, "explanation": "摆渡：借船把货物送过河，符合“划着小船”的语境。"}, {"text": "晾晒", "is_correct": false, "explanation": "语义：晾晒指把东西摊开在阳光下晒干，与划船运货的意思不符。"}, {"text": "挖掘", "is_correct": false, "explanation": "语义：挖掘指挖土或发掘，与划船运货的意思无关。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁指烧坏、毁掉，与把货物送到河对岸的意思完全不符。"}], "explanations": {"摆渡": "摆渡：借船把货物送过河，符合“划着小船”的语境。", "晾晒": "语义：晾晒指把东西摊开在阳光下晒干，与划船运货的意思不符。", "挖掘": "语义：挖掘指挖土或发掘，与划船运货的意思无关。", "烧毁": "语义：烧毁指烧坏、毁掉，与把货物送到河对岸的意思完全不符。"}, "sentence_index": 6, "correct_answer": "摆渡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一座桥摆渡到对岸。", "explanation": "这里应该用〈架设〉。摆渡指借船运送人或可搬运的东西过河，桥是固定的建筑，不能被摆渡，应说架设。"}, {"text": "我们在草原上摆渡了一整天。", "explanation": "这里应该用〈步行〉。摆渡必须借船跨越水面，草原上没有河流，不能用摆渡，陆上行走应说步行。"}, {"text": "他在沙漠里骑着骆驼摆渡了三天。", "explanation": "这里应该用〈行走〉。摆渡必须用船渡过水面，沙漠里骑骆驼不能说摆渡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11127, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人用小船把孩子们摆渡对岸去。", "corrected_sentence": "这位老人用小船把孩子们摆渡到对岸去。", "error_description": "“摆渡”后面缺少表示到达地点的“到”。应说“摆渡到对岸去”，漏掉“到”，句子就不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11127, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老船夫每天学生们摆渡过河上学。", "corrected_sentence": "这位老船夫每天把学生们摆渡过河上学。", "error_description": "宾语位置错误：“学生们”是被摆渡的对象，夹在“每天”与动词之间，会被误读为主语；可用“把”提到动词前说“把学生们摆渡过河”，或改说“摆渡学生们过河”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
