INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11129, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11129, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指人和动物口腔周围的部位，包括嘴唇、牙齿等，用于进食、发音和表达表情。", "primary_collocate": null, "pronunciation": "zuǐ ba", "ipa": "tswei̯ pa", "syllable_count": 2, "sentences": [{"text": "人打哈欠时，嘴巴张得大大的。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打哈欠时，嘴巴张得很大，会吸进很多空气。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "医生说：“请把嘴巴张开，我看看牙。”", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩吃饭时，嘴巴上沾着米饭。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天风大，我的嘴巴有点干。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑的时候，嘴巴弯弯的，很好看。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃东西的时候，请不要说话，嘴巴要闭上。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太冷了，他的嘴巴都冻红了。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗张大嘴巴，露出了白牙。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给宝宝擦了擦嘴巴。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "大嘴巴", "label": "复合"}], "register": "口语", "sense_fingerprint": "人和动物脸上用来吃东西、说话的部位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b139446e-7524-4719-8232-ba3bfc86546e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11129, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嘴巴", "is_correct": true, "explanation": "正确：打哈欠时张开的是嘴巴，与句意相合。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“张”指嘴的开合，眼睛要说“睁”，不能说眼睛张很大。"}, {"text": "胃", "is_correct": false, "explanation": "语义：胃在腹部，打哈欠时不会张开。"}, {"text": "牙齿", "is_correct": false, "explanation": "搭配：“张”用于嘴，牙齿只能露出，不能说张很大。"}], "explanations": {"嘴巴": "正确：打哈欠时张开的是嘴巴，与句意相合。", "眼睛": "搭配：“张”指嘴的开合，眼睛要说“睁”，不能说眼睛张很大。", "胃": "语义：胃在腹部，打哈欠时不会张开。", "牙齿": "搭配：“张”用于嘴，牙齿只能露出，不能说张很大。"}, "sentence_index": 0, "correct_answer": "嘴巴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个瓶子的嘴巴很小，水不容易倒出来。", "explanation": "这里应该用〈瓶口〉。嘴巴只指人或动物脸上的部位，瓶子的口不能说嘴巴。"}, {"text": "他用嘴巴看书，看得很认真。", "explanation": "这里应该用〈眼睛〉。嘴巴用来吃东西和说话，看书要用眼睛。"}, {"text": "他用嘴巴听声音，所以听得很清楚。", "explanation": "这里应该用〈耳朵〉。嘴巴的作用是吃东西和说话，听声音要用耳朵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11129, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘴巴", "is_correct": true, "explanation": "正确：吃东西时要闭上的是嘴巴，与句意相合。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“闭上”不用于书，书要说“合上”。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：耳朵不参与吃东西或说话，句中要闭上的是嘴。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“闭上”不用于手，手要说“放下”或“握住”。"}], "explanations": {"嘴巴": "正确：吃东西时要闭上的是嘴巴，与句意相合。", "书": "搭配：“闭上”不用于书，书要说“合上”。", "耳朵": "语义：耳朵不参与吃东西或说话，句中要闭上的是嘴。", "手": "搭配：“闭上”不用于手，手要说“放下”或“握住”。"}, "sentence_index": 6, "correct_answer": "嘴巴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用嘴巴踢球，每天都很开心。", "explanation": "这里应该用〈脚〉。踢球要用脚，嘴巴不能用来踢球。"}, {"text": "他唱歌唱累了，嘴巴哑了。", "explanation": "这里应该用〈嗓子〉。“哑”指声音沙哑，应说嗓子哑，不能说嘴巴哑。"}, {"text": "小狗摇着嘴巴，很高兴。", "explanation": "这里应该用〈尾巴〉。“摇”是尾巴的动作，嘴巴不能摇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他张开一只嘴巴，吃了一口西瓜。", "corrected_sentence": "他张开嘴巴，吃了一口西瓜。", "error_description": "错误：“一只嘴巴”；正确：“张开嘴巴”。嘴巴的量词是“张”，用“只”是量词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11129, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈用毛巾给宝宝擦了擦一条嘴巴。", "corrected_sentence": "妈妈用毛巾给宝宝擦了擦嘴巴。", "error_description": "错误：“一条嘴巴”；正确：“擦了擦嘴巴”。嘴巴的量词是“张”，不能用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11134, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低", "is_correct": true, "explanation": "低：与“高”构成反义，指温度低。"}, {"text": "远", "is_correct": false, "explanation": "远与“高”不构成反义，远的反义是近。"}, {"text": "干净", "is_correct": false, "explanation": "干净与“高”不构成反义，干净的反义是脏。"}, {"text": "轻", "is_correct": false, "explanation": "轻与“高”不构成反义，轻的反义是重。"}], "correct_answer": "低", "explanations": {"低": "低：与“高”构成反义，指温度低。", "远": "远与“高”不构成反义，远的反义是近。", "干净": "干净与“高”不构成反义，干净的反义是脏。", "轻": "轻与“高”不构成反义，轻的反义是重。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11134, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低", "is_correct": true, "explanation": "低：与“高”构成反义，指温度低。"}, {"text": "宽", "is_correct": false, "explanation": "宽与“高”不构成反义，宽的反义是窄。"}, {"text": "厚", "is_correct": false, "explanation": "厚与“高”不构成反义，厚的反义是薄。"}, {"text": "粗", "is_correct": false, "explanation": "粗与“高”不构成反义，粗的反义是细。"}], "correct_answer": "低", "explanations": {"低": "低：与“高”构成反义，指温度低。", "宽": "宽与“高”不构成反义，宽的反义是窄。", "厚": "厚与“高”不构成反义，厚的反义是薄。", "粗": "粗与“高”不构成反义，粗的反义是细。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11134, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示温度或热量程度大的状态", "primary_collocate": null, "pronunciation": "gāo", "ipa": "kɑʊ˥", "syllable_count": 1, "sentences": [{"text": "中午的气温很高，大家都待在家里。", "target_word": "高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天温度很高，我不想出门。", "target_word": "高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的太阳下，地面温度特别高。", "target_word": "高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水温太高，会烫到手。", "target_word": "高", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子发烧了，体温一直很高。", "target_word": "高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "锅里的油温高了，可以放菜了。", "target_word": "高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间温度太高，快开窗吧。", "target_word": "高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的体温不高，不用太担心。", "target_word": "高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天城市里的气温比山上高。", "target_word": "高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烤箱温度太高，蛋糕会烤黑。", "target_word": "高", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "低", "label": "反义词"}, {"form": "高温", "label": "复合词"}, {"form": "高热", "label": "复合词"}], "register": "中性", "sense_fingerprint": "温度、体温、水温等数值大、热量程度大，如温度高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 水温 (Zipf 3.51), 烫 (Zipf 3.98), 到手 (Zipf 3.66)']::text[], '911ce2b6-7d1d-4794-8ddb-56c9662d33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高", "is_correct": true, "explanation": "高（gāo）：温度、体温等数值大，如“温度高”。"}, {"text": "告", "is_correct": false, "explanation": "gào（第四声）与 gāo（第一声）声调不同，意思是告诉。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo（第三声）与 gāo（第一声）声调不同，意思是做、弄。"}, {"text": "刀", "is_correct": false, "explanation": "dāo（第一声）与 gāo 声母不同（d 与 g），韵母与声调相同，意思是刀子。"}, {"text": "猫", "is_correct": false, "explanation": "māo（第一声）与 gāo 声母不同（m 与 g），韵母与声调相同，意思是猫。"}, {"text": "包", "is_correct": false, "explanation": "bāo（第一声）与 gāo 声母不同（b 与 g），韵母与声调相同，意思是包裹、包子。"}, {"text": "烧", "is_correct": false, "explanation": "shāo（第一声）与 gāo 声母不同（sh 与 g），韵母与声调相同，意思是燃烧、加热。"}], "explanations": {"高": "高（gāo）：温度、体温等数值大，如“温度高”。", "告": "gào（第四声）与 gāo（第一声）声调不同，意思是告诉。", "搞": "gǎo（第三声）与 gāo（第一声）声调不同，意思是做、弄。", "刀": "dāo（第一声）与 gāo 声母不同（d 与 g），韵母与声调相同，意思是刀子。", "猫": "māo（第一声）与 gāo 声母不同（m 与 g），韵母与声调相同，意思是猫。", "包": "bāo（第一声）与 gāo 声母不同（b 与 g），韵母与声调相同，意思是包裹、包子。", "烧": "shāo（第一声）与 gāo 声母不同（sh 与 g），韵母与声调相同，意思是燃烧、加热。"}, "sentence_index": null, "correct_answer": "高"}, "level_3": {"options": [{"text": "高", "is_correct": true, "explanation": "高：“气温很高”说明温度数值大，符合句意。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“快”说速度，不能用来形容温度。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”说分量，与温度无关。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢”说速度，不能用来形容温度。"}], "explanations": {"高": "高：“气温很高”说明温度数值大，符合句意。", "快": "搭配：“快”说速度，不能用来形容温度。", "重": "语义：“重”说分量，与温度无关。", "慢": "搭配：“慢”说速度，不能用来形容温度。"}, "sentence_index": 0, "correct_answer": "高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天的天气很高，我们常去游泳。", "explanation": "这里应该用〈热〉。高用于温度、数值，描述天气炎热要用热，不说天气很高。"}, {"text": "这杯咖啡很高，先放一放。", "explanation": "这里应该用〈热〉。高用于温度、数值，咖啡温度高要说热或烫，不说很高。"}, {"text": "这碗汤很高，小心喝。", "explanation": "这里应该用〈烫〉。高强调数值或程度大，形容食物入口灼热要用烫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11134, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高", "is_correct": true, "explanation": "高（gāo）：温度、体温等数值大，如“体温高”。"}, {"text": "该", "is_correct": false, "explanation": "gāi（第一声）与 gāo 韵母不同（ai 与 ao），声母与声调相同，意思是应该。"}, {"text": "沟", "is_correct": false, "explanation": "gōu（第一声）与 gāo 韵母不同（ou 与 ao），声母与声调相同，意思是水沟。"}, {"text": "糟", "is_correct": false, "explanation": "zāo（第一声）与 gāo 声母不同（z 与 g），韵母与声调相同，意思是糟糕、腐坏。"}, {"text": "稿", "is_correct": false, "explanation": "gǎo（第三声）与 gāo 声调不同，声母与韵母相同，意思是稿子。"}, {"text": "操", "is_correct": false, "explanation": "cāo（第一声）与 gāo 声母不同（c 与 g），韵母与声调相同，意思是操练、操作。"}, {"text": "蒿", "is_correct": false, "explanation": "hāo（第一声）与 gāo 声母不同（h 与 g），韵母与声调相同，意思是蒿草。"}], "explanations": {"高": "高（gāo）：温度、体温等数值大，如“体温高”。", "该": "gāi（第一声）与 gāo 韵母不同（ai 与 ao），声母与声调相同，意思是应该。", "沟": "gōu（第一声）与 gāo 韵母不同（ou 与 ao），声母与声调相同，意思是水沟。", "糟": "zāo（第一声）与 gāo 声母不同（z 与 g），韵母与声调相同，意思是糟糕、腐坏。", "稿": "gǎo（第三声）与 gāo 声调不同，声母与韵母相同，意思是稿子。", "操": "cāo（第一声）与 gāo 声母不同（c 与 g），韵母与声调相同，意思是操练、操作。", "蒿": "hāo（第一声）与 gāo 声母不同（h 与 g），韵母与声调相同，意思是蒿草。"}, "sentence_index": null, "correct_answer": "高"}, "level_3": {"options": [{"text": "高", "is_correct": true, "explanation": "高：“温度太高，快开窗吧”说明温度过热，符合句意。"}, {"text": "冷", "is_correct": false, "explanation": "语义：温度太冷时不需要开窗降温，与“快开窗吧”矛盾。"}, {"text": "凉", "is_correct": false, "explanation": "语义：温度凉时开窗只会更冷，与“快开窗吧”的语境不符。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”不能用来形容温度。"}], "explanations": {"高": "高：“温度太高，快开窗吧”说明温度过热，符合句意。", "冷": "语义：温度太冷时不需要开窗降温，与“快开窗吧”矛盾。", "凉": "语义：温度凉时开窗只会更冷，与“快开窗吧”的语境不符。", "硬": "搭配：“硬”不能用来形容温度。"}, "sentence_index": 6, "correct_answer": "高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯牛奶刚热好，很高，等凉一点再喝。", "explanation": "这里应该用〈烫〉。高说温度或数值大，不用来形容牛奶刚热好时的灼热感，要说烫。"}, {"text": "他的手心很高，握着很舒服。", "explanation": "这里应该用〈暖和〉。高说温度或数值大，手心温暖、摸起来舒服要说暖和，不说很高。"}, {"text": "这把铁勺子刚从锅里拿出来，很高，别直接用手拿。", "explanation": "这里应该用〈热〉。高说温度大，铁勺子刚离开热锅的温度要说热，不说很高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里的气温北方高。", "corrected_sentence": "这里的气温比北方高。", "error_description": "错误：比较句缺少介词“比”，“北方”前要加“比”，不能说“气温北方高”。正确：“这里的气温比北方高”，用“比”引出比较对象。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天的温度高的很，我们别出门了。", "corrected_sentence": "今天的温度高得很，我们别出门了。", "error_description": "助词错误：“高”后表示程度的补语要用“得”，不能用“的”。应说“高得很”，不说“高的很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
