INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11137, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "因困倦或疲劳，不自主地张口深吸气并呼出的动作。", "primary_collocate": "打", "pronunciation": "hā qian", "ipa": "xa˥ tɕʰjɛn", "syllable_count": 2, "sentences": [{"text": "人打哈欠时，嘴巴张得大大的。", "target_word": "哈欠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大脑温度高的时候，人想打哈欠。", "target_word": "哈欠", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "哈欠能让大脑变凉一点。", "target_word": "哈欠", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "神经学研究发现，打哈欠和大脑的功能有关系。", "target_word": "哈欠", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "有时候，别人打哈欠，你也会想打。", "target_word": "哈欠", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "你看别人打哈欠，你的身体就跟着做。", "target_word": "哈欠", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "人在疲惫或无聊时常常打哈欠。", "target_word": "哈欠", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "科学家对哈欠的作用有很多不同的看法。", "target_word": "哈欠", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "深长的哈欠能让进入大脑的血液变凉一点。", "target_word": "哈欠", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "神经学研究进一步揭示了打哈欠的复杂神经通路。", "target_word": "哈欠", "complexity_tier": "T3", "sentence_source": "mined"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "生理现象：因困倦疲劳不自主张口深吸气再呼出的动作", "collocate_grounding": {"status": "corpus_validated", "reason": "corpus_collocations PMI 12.28 >= 5.0", "source": "corpus_collocations", "score": 12.275}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b139446e-7524-4719-8232-ba3bfc86546e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11137, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哈欠", "is_correct": true, "explanation": "正确：“打哈欠”是固定搭配，指困倦时张口深吸气，与“嘴巴张很大”相符。"}, {"text": "雷", "is_correct": false, "explanation": "语义：“打雷”是天气现象，人不能打雷，与句中描写的人的动作不符。"}, {"text": "井", "is_correct": false, "explanation": "语义：“打井”是挖掘工程，与“嘴巴张很大”的人体动作无关，句意不通。"}, {"text": "蜡", "is_correct": false, "explanation": "搭配：“打蜡”用于擦抹器物表面，不用于人，不说“人打蜡”。"}], "explanations": {"哈欠": "正确：“打哈欠”是固定搭配，指困倦时张口深吸气，与“嘴巴张很大”相符。", "雷": "语义：“打雷”是天气现象，人不能打雷，与句中描写的人的动作不符。", "井": "语义：“打井”是挖掘工程，与“嘴巴张很大”的人体动作无关，句意不通。", "蜡": "搭配：“打蜡”用于擦抹器物表面，不用于人，不说“人打蜡”。"}, "sentence_index": 0, "correct_answer": "哈欠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他醒来后伸了个哈欠。", "explanation": "这里应该用〈懒腰〉。伸懒腰是伸展身体，哈欠是张口吸气的动作，不能用“伸”来带“哈欠”。"}, {"text": "他把哈欠写在了本子上。", "explanation": "哈欠是张口吸气的动作，不是能写下来的东西，这里词义不对。"}, {"text": "他把哈欠装进杯子里，带回了家。", "explanation": "哈欠是张口吸气的动作，不是能装进杯子的东西，这里词义不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11137, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哈欠", "is_correct": true, "explanation": "正确：“打哈欠”指疲惫或无聊时张口深吸气，符合句中的语境。"}, {"text": "铁", "is_correct": false, "explanation": "语义：“打铁”是锻造金属的劳动，与人在疲惫或无聊时的状态不搭。"}, {"text": "桩", "is_correct": false, "explanation": "语义：“打桩”是建筑施工，与“人类在疲惫或无聊时”的描写不搭。"}, {"text": "谷", "is_correct": false, "explanation": "搭配：“打谷”指脱粒，不能用来描写人的生理状态，不说“人打谷”。"}], "explanations": {"哈欠": "正确：“打哈欠”指疲惫或无聊时张口深吸气，符合句中的语境。", "铁": "语义：“打铁”是锻造金属的劳动，与人在疲惫或无聊时的状态不搭。", "桩": "语义：“打桩”是建筑施工，与“人类在疲惫或无聊时”的描写不搭。", "谷": "搭配：“打谷”指脱粒，不能用来描写人的生理状态，不说“人打谷”。"}, "sentence_index": 6, "correct_answer": "哈欠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把哈欠放进了冰箱。", "explanation": "哈欠是张口吸气的动作，不是能放进冰箱的东西，这里词义不对。"}, {"text": "他用抹布把桌子上的哈欠擦掉了。", "explanation": "哈欠是动作，不是能擦掉的东西，这里词义不对。"}, {"text": "这首歌的哈欠很动听。", "explanation": "哈欠指张口吸气的动作，不能用来形容歌曲，这里词义不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚才打了一只哈欠。", "corrected_sentence": "他刚才打了一个哈欠。", "error_description": "量词错误：“哈欠”的量词是“个”，“只”用于动物等，不能用来计量哈欠，应改为“一个哈欠”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议上他正在打了一个哈欠。", "corrected_sentence": "会议上他打了一个哈欠。", "error_description": "时态标记冲突：“正在”表示动作进行，与表示完成的“了”不能同用，应删去“正在”，写作“打了一个哈欠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
