INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11142, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或器具撞击、拍击物体。", "primary_collocate": null, "pronunciation": "dǎ", "ipa": "tɑ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他用手打了一下桌子，声音很响。", "target_word": "打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用木棍打了一下墙角的箱子。", "target_word": "打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她随手拿起书本，打了一下飞过来的蚊子。", "target_word": "打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用力打了一下门，想让屋里的人听见。", "target_word": "打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨点打在窗户上，发出噼啪的声音。", "target_word": "打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力打鼓，声音很大。", "target_word": "打", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用锤子把钉子打进墙里。", "target_word": "打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拳击手每天在房间里打沙袋。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿着拍子，用力打蚊子。", "target_word": "打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁匠在炉子旁打铁，火花四处飞。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了", "label": "体标（了）"}, {"form": "打过", "label": "体标（过）"}, {"form": "打着", "label": "体标（着）"}, {"form": "打打", "label": "重叠"}], "register": "中性", "sense_fingerprint": "打：用手或器具撞击、拍击物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 木棍 (Zipf 3.13), 墙角 (Zipf 3.15), 箱子 (Zipf 3.78)','sentence 2 above tier T1: 4 words above tier T1 (max 2): 随手 (Zipf 3.74), 书本 (Zipf 3.8), 飞过 (Zipf 3.65), 蚊子 (Zipf 3.65)','sentence 4 above tier T1: contains vocabulary far above tier T1: 噼 (Zipf 1.82)','sentence 9 above tier T1: 3 words above tier T1 (max 2): 铁匠 (Zipf 3.32), 炉子 (Zipf 3.26), 火花 (Zipf 3.77)']::text[], 'eea9ae5a-a1c2-46b4-ba5e-281e3260ca2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11142, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打", "is_correct": true, "explanation": "正确：打（dǎ），表示用手或器具撞击、拍击。"}, {"text": "大", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是“大”。"}, {"text": "答", "is_correct": false, "explanation": "dá（第二声）与 dǎ 声调不同，意思是“回答”。"}, {"text": "搭", "is_correct": false, "explanation": "dā（第一声）与 dǎ 声调不同，意思是“搭建、搭配”。"}, {"text": "塔", "is_correct": false, "explanation": "tǎ 与 dǎ 声母不同（t 与 d），意思是“塔”。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn 与 dǎ 韵尾不同（多一个 -n），意思是“胆子”。"}], "explanations": {"打": "正确：打（dǎ），表示用手或器具撞击、拍击。", "大": "dà（第四声）与 dǎ（第三声）声调不同，意思是“大”。", "答": "dá（第二声）与 dǎ 声调不同，意思是“回答”。", "搭": "dā（第一声）与 dǎ 声调不同，意思是“搭建、搭配”。", "塔": "tǎ 与 dǎ 声母不同（t 与 d），意思是“塔”。", "胆": "dǎn 与 dǎ 韵尾不同（多一个 -n），意思是“胆子”。"}, "sentence_index": null, "correct_answer": "打"}, "level_3": {"options": [{"text": "打", "is_correct": true, "explanation": "正确：“打”表示用手撞击、拍击，“用手打了一下桌子”语义通顺。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指快速移动，不能表示用手撞击桌子，句意不通。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”指流泪出声，与用手撞击桌子无关。"}, {"text": "长眠", "is_correct": false, "explanation": "语域：“长眠”是书面委婉语，与用手撞击桌子这一动作不符。"}], "explanations": {"打": "正确：“打”表示用手撞击、拍击，“用手打了一下桌子”语义通顺。", "跑": "语义：“跑”指快速移动，不能表示用手撞击桌子，句意不通。", "哭": "语义：“哭”指流泪出声，与用手撞击桌子无关。", "长眠": "语域：“长眠”是书面委婉语，与用手撞击桌子这一动作不符。"}, "sentence_index": 0, "correct_answer": "打"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每个冬天都给儿子打毛衣。", "explanation": "这里“打”表示编织（毛衣），不表示用手或器具撞击、拍击物体。"}, {"text": "我们每天放学后打篮球。", "explanation": "这里“打”表示进行篮球运动，不是用手或器具撞击物体。"}, {"text": "我们明天打车去机场。", "explanation": "这里“打”表示乘坐（出租车），不是用手或器具撞击、拍击物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11142, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "打", "is_correct": true, "explanation": "正确：打（dǎ），表示用手或器具撞击、拍击。"}, {"text": "把", "is_correct": false, "explanation": "bǎ 与 dǎ 声母不同（b 与 d），声调相同，意思是“把（握、拿）”。"}, {"text": "哪", "is_correct": false, "explanation": "nǎ 与 dǎ 声母不同（n 与 d），声调相同，意思是“哪”。"}, {"text": "达", "is_correct": false, "explanation": "dá（第二声）与 dǎ 声调不同，意思是“到达”。"}], "explanations": {"打": "正确：打（dǎ），表示用手或器具撞击、拍击。", "把": "bǎ 与 dǎ 声母不同（b 与 d），声调相同，意思是“把（握、拿）”。", "哪": "nǎ 与 dǎ 声母不同（n 与 d），声调相同，意思是“哪”。", "达": "dá（第二声）与 dǎ 声调不同，意思是“到达”。"}, "sentence_index": null, "correct_answer": "打"}, "level_3": {"options": [{"text": "打", "is_correct": true, "explanation": "正确：“打进墙里”是用锤子把钉子敲入墙内，搭配自然。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”指用火加热食物，与把钉子敲进墙里的情境不符。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”用于线、布等材料，不说“织进墙里”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不用锤子，且“洗进墙里”搭配不当。"}], "explanations": {"打": "正确：“打进墙里”是用锤子把钉子敲入墙内，搭配自然。", "烤": "语义：“烤”指用火加热食物，与把钉子敲进墙里的情境不符。", "织": "搭配：“织”用于线、布等材料，不说“织进墙里”。", "洗": "搭配：“洗”不用锤子，且“洗进墙里”搭配不当。"}, "sentence_index": 6, "correct_answer": "打"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个人打起桌子，慢慢走出了房间。", "explanation": "这里应该用〈抬〉。“打起”没有抬起的意思，搬动桌子要用“抬”。"}, {"text": "她晚上给朋友打电话，聊了很久。", "explanation": "这里“打”表示拨打电话，不是用手或器具撞击物体。"}, {"text": "护士给病人打了一针。", "explanation": "这里“打”表示注射，与撞击、拍击的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用力打着一下鼓，声音很大。", "corrected_sentence": "他用力打了一下鼓，声音很大。", "error_description": "体标错误：动作已经完成应用“了”，“着”表示动作持续，不能与“一下”连用，应说“打了一下鼓”，不能说“打着一下鼓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用锤子把钉子进打木板里。", "corrected_sentence": "他用锤子把钉子打进木板里。", "error_description": "词序错误：结果补语“进”应紧跟动词“打”，应说“打进木板里”，不能说“进打木板里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
