INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11157, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学校里用来上课的房间。", "primary_collocate": null, "pronunciation": "jiào shì", "ipa": "tɕjɑʊ˥˩ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "你在教室里看到同学打哈欠，你可能马上也想打。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "教室里有三十张桌子和椅子。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铃声一响，老师走进教室。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们教室在三楼，离楼梯很近。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，请把教室的灯关了。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室的黑板上写着今天的作业。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间教室很大，坐得下五十个学生。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打扫教室时，我们要先擦黑板。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里很安静，大家正在考试。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了带书，只好回教室去拿。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}], "register": "中性", "sense_fingerprint": "学校里用来上课的房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c766053-6752-423e-a944-839af8b9813c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11157, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "教室", "is_correct": true, "explanation": "正确答案。教室（jiào shì）指学校里用来上课的房间。"}, {"text": "教师", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是老师。"}, {"text": "解释", "is_correct": false, "explanation": "jiě 与 jiào 韵母、声调不同，意思是说明原因。"}, {"text": "就是", "is_correct": false, "explanation": "jiù 与 jiào 韵母不同，意思是就是。"}], "explanations": {"教室": "正确答案。教室（jiào shì）指学校里用来上课的房间。", "教师": "shī（第一声）与 shì（第四声）声调不同，意思是老师。", "解释": "jiě 与 jiào 韵母、声调不同，意思是说明原因。", "就是": "jiù 与 jiào 韵母不同，意思是就是。"}, "sentence_index": null, "correct_answer": "教室"}, "level_3": {"options": [{"text": "教室", "is_correct": true, "explanation": "正确。教室是学生上课、会看到同学打哈欠的房间，与语境相符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是平面，人不能在“黑板里”看到同学。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是场所，不能用“在……里”表示所在地点。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是小物品，不是人可以在里面的地方。"}], "explanations": {"教室": "正确。教室是学生上课、会看到同学打哈欠的房间，与语境相符。", "黑板": "语义：黑板是平面，人不能在“黑板里”看到同学。", "作业": "语义：作业不是场所，不能用“在……里”表示所在地点。", "铅笔": "语义：铅笔是小物品，不是人可以在里面的地方。"}, "sentence_index": 0, "correct_answer": "教室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们教室有很多公司在里面办公。", "explanation": "这里应该用〈办公楼〉。教室是学校里上课的房间，整幢楼租给公司办公的要说办公楼。"}, {"text": "我们教室有十层，每层都有很多房间。", "explanation": "这里应该用〈教学楼〉。教室只是一间房，几层楼、每层房间多要说教学楼。"}, {"text": "我们教室有三千名学生。", "explanation": "这里应该用〈学校〉。教室只是一间房，不能指全校的学生人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11157, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": true, "explanation": "正确。教室是可以容纳很多学生的房间，与“坐得下五十个学生”相符。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：卧室是睡觉的地方，坐不下五十个学生。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，与“坐得下五十个学生”不符。"}, {"text": "洗手间", "is_correct": false, "explanation": "配价：“坐得下五十个学生”要求主语是能让一群人坐下的场所，洗手间不具备这一条件。"}], "explanations": {"教室": "正确。教室是可以容纳很多学生的房间，与“坐得下五十个学生”相符。", "卧室": "语义：卧室是睡觉的地方，坐不下五十个学生。", "厨房": "语义：厨房是做饭的地方，与“坐得下五十个学生”不符。", "洗手间": "配价：“坐得下五十个学生”要求主语是能让一群人坐下的场所，洗手间不具备这一条件。"}, "sentence_index": 6, "correct_answer": "教室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们教室有很多树，夏天很凉快。", "explanation": "这里应该用〈操场〉。树和凉快是室外操场的特点，教室是室内房间。"}, {"text": "这栋教室很漂亮。", "explanation": "这里应该用〈间〉。教室是房间，“栋”用于整幢建筑，不能用来数教室。"}, {"text": "教室里有一张大床，我晚上睡在上面。", "explanation": "这里应该用〈卧室〉。床和晚上睡觉是卧室的特点，教室里摆的是桌椅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下午要去这张教室上课。", "corrected_sentence": "我下午要去这间教室上课。", "error_description": "“教室”是房间，量词应用“间”，不用“张”（“张”用于桌子、纸等平面物）。错误形式：这张教室；正确形式：这间教室。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下课后我把那张教室的门锁好了。", "corrected_sentence": "下课后我把那间教室的门锁好了。", "error_description": "“教室”是房间，量词应用“间”，不用“张”。错误形式：那张教室；正确形式：那间教室。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
