INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指在同一所学校或班级里一起学习的人。", "primary_collocate": null, "pronunciation": "tóng xué", "ipa": "tʰʊŋ˧˥ ɕɥœ˧˥", "syllable_count": 2, "sentences": [{"text": "你在教室里看到同学打哈欠，你可能马上也想打。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我的同学住在学校旁边。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我小学的同学。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，同学给我讲了这道题。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天同学来我家一起做作业。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同学一起去图书馆看书。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位同学今天没有来上课。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同学的妈妈是医生。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的同学今天生病了，我很担心。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，同学借给我一本书。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "同学们", "label": "复数"}, {"form": "老同学", "label": "复合"}], "register": "中性", "sense_fingerprint": "同一所学校或班级里一起学习的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c766053-6752-423e-a944-839af8b9813c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同学", "is_correct": true, "explanation": "正确。同学是在教室里一起上课的人，会打哈欠，语境相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是乘车的人，不会出现在教室里上课。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师在厨房工作，与教室里的上课情境不符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“打哈欠”需要有生命的主语，“窗户”不能打哈欠。"}], "explanations": {"同学": "正确。同学是在教室里一起上课的人，会打哈欠，语境相符。", "乘客": "语义：乘客是乘车的人，不会出现在教室里上课。", "厨师": "语义：厨师在厨房工作，与教室里的上课情境不符。", "窗户": "搭配：“打哈欠”需要有生命的主语，“窗户”不能打哈欠。"}, "sentence_index": 0, "correct_answer": "同学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的同学都很热情，服务很周到。", "explanation": "这里应该用〈服务员〉。同学指一起学习的人，饭店里服务客人的要说服务员。"}, {"text": "公司的同学都很努力地工作。", "explanation": "这里应该用〈员工〉。同学指一起上学的人，公司里一起工作的要说员工。"}, {"text": "我家养了一只同学，它每天叫我起床。", "explanation": "这里应该用〈宠物〉。同学是一起学习的人，家里养的动物是宠物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同学", "is_correct": true, "explanation": "正确。同学是一起上课的人，缺课与“来上课”相符。"}, {"text": "警察", "is_correct": false, "explanation": "语义：警察不是来上课的人，与“没有来上课”的语境不符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机不是学生，不会来上课。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“这位”只能修饰人，不能和“桌子”搭配。"}], "explanations": {"同学": "正确。同学是一起上课的人，缺课与“来上课”相符。", "警察": "语义：警察不是来上课的人，与“没有来上课”的语境不符。", "司机": "语义：司机不是学生，不会来上课。", "桌子": "搭配：“这位”只能修饰人，不能和“桌子”搭配。"}, "sentence_index": 6, "correct_answer": "同学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店的同学把东西卖给顾客。", "explanation": "这里应该用〈售货员〉。同学是一起学习的人，在商店卖东西的是售货员。"}, {"text": "这家医院的同学每天给病人看病。", "explanation": "这里应该用〈医生〉。同学是一起学习的人，在医院给病人看病的是医生。"}, {"text": "同学每天给病人打针，很辛苦。", "explanation": "这里应该用〈护士〉。同学是一起学习的人，给病人打针的是护士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班新来了两只同学。", "corrected_sentence": "我们班新来了两位同学。", "error_description": "“同学”指人，量词应用“位”或“个”，不用“只”（“只”多用于动物）。错误形式：两只同学；正确形式：两位同学。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校的两台同学很友好。", "corrected_sentence": "我们学校的两位同学很友好。", "error_description": "“同学”指人，量词应用“位”或“个”，不用“台”（“台”用于机器等）。错误形式：两台同学；正确形式：两位同学。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11160, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违抗", "is_correct": true, "explanation": "“违抗”与“听从”互为反义，指不服从别人的命令或劝告。"}, {"text": "看", "is_correct": false, "explanation": "“看”指用眼睛，与听从意见之间没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指书写，与听从意见之间没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "“走”指移动，与听从意见之间没有反义关系。"}], "correct_answer": "违抗", "explanations": {"违抗": "“违抗”与“听从”互为反义，指不服从别人的命令或劝告。", "看": "“看”指用眼睛，与听从意见之间没有反义关系。", "写": "“写”指书写，与听从意见之间没有反义关系。", "走": "“走”指移动，与听从意见之间没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11160, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违抗", "is_correct": true, "explanation": "“违抗”与“听从”互为反义，指不服从别人的命令或劝告。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”指快速移动，与听从意见之间没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”指发出歌声，与听从意见之间没有反义关系。"}, {"text": "喝", "is_correct": false, "explanation": "“喝”指把液体咽下去，与听从意见之间没有反义关系。"}], "correct_answer": "违抗", "explanations": {"违抗": "“违抗”与“听从”互为反义，指不服从别人的命令或劝告。", "跑": "“跑”指快速移动，与听从意见之间没有反义关系。", "唱": "“唱”指发出歌声，与听从意见之间没有反义关系。", "喝": "“喝”指把液体咽下去，与听从意见之间没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11160, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听从、接受别人的意见或劝告。", "primary_collocate": null, "pronunciation": "tīng", "ipa": "tʰiŋ˥", "syllable_count": 1, "sentences": [{"text": "医生说的话，你要听。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不听妈妈的话。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子应该听老师的话。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么不听我的建议？", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听朋友的，明天去看医生。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很固执，谁的话都不听。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听我的，早点回家吧。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的意见，我们要听一听。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她听了我的意见，换了工作。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸总是不听别人的劝。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听了", "label": "体标"}, {"form": "听过", "label": "体标"}, {"form": "听听", "label": "重叠"}, {"form": "听从", "label": "复合"}], "register": "通用", "sense_fingerprint": "听从、接受别人的意见或劝告", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fb865e3-8ed5-4241-8c43-69bb91bb5b7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11160, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "听", "is_correct": true, "explanation": "“听”（tīng）：用耳朵接收声音，也指听从、接受意见。此处指听从劝告。"}, {"text": "停", "is_correct": false, "explanation": "tíng（第二声）与 tīng（第一声）声调不同，意思是停止。"}, {"text": "挺", "is_correct": false, "explanation": "tǐng（第三声）与 tīng（第一声）声调不同，意思是挺直或很。"}, {"text": "顶", "is_correct": false, "explanation": "dǐng 与 tīng 声母、声调都不同，意思是顶部或用头顶。"}, {"text": "盯", "is_correct": false, "explanation": "dīng 与 tīng 声母不同（d 与 t），声调相同，意思是注视。"}], "explanations": {"听": "“听”（tīng）：用耳朵接收声音，也指听从、接受意见。此处指听从劝告。", "停": "tíng（第二声）与 tīng（第一声）声调不同，意思是停止。", "挺": "tǐng（第三声）与 tīng（第一声）声调不同，意思是挺直或很。", "顶": "dǐng 与 tīng 声母、声调都不同，意思是顶部或用头顶。", "盯": "dīng 与 tīng 声母不同（d 与 t），声调相同，意思是注视。"}, "sentence_index": null, "correct_answer": "听"}, "level_3": {"options": [{"text": "听", "is_correct": true, "explanation": "“听”表示听从、接受劝告，与“你要”搭配，符合句意。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”的对象是纸张等具体物品，不能与“话”搭配，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物或药，不能与“话”搭配。"}, {"text": "忘", "is_correct": false, "explanation": "语义：“忘”与医生的嘱咐相反，与“你要”的劝告语气矛盾。"}], "explanations": {"听": "“听”表示听从、接受劝告，与“你要”搭配，符合句意。", "撕": "搭配：“撕”的对象是纸张等具体物品，不能与“话”搭配，句意不通。", "吃": "搭配：“吃”的宾语是食物或药，不能与“话”搭配。", "忘": "语义：“忘”与医生的嘱咐相反，与“你要”的劝告语气矛盾。"}, "sentence_index": 0, "correct_answer": "听"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听了自己的错误，并向大家道歉。", "explanation": "这里应该用〈承认〉。“听”表示照别人的话去做或接受意见，不能以“错误”为对象；对自己的错误要说承认。"}, {"text": "老师听了他的作业，给了九十分。", "explanation": "这里应该用〈批改〉。“听”表示接受别人的意见，不能用于检查、评分作业。"}, {"text": "她在商店听了一件新衣服。", "explanation": "这里应该用〈买〉。“听”表示听从意见，不能以衣服为对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11160, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "听", "is_correct": true, "explanation": "“听”（tīng）：用耳朵接收声音，也指听从、接受意见。此处指听从劝告。"}, {"text": "亭", "is_correct": false, "explanation": "tíng（第二声）与 tīng（第一声）声调不同，意思是亭子。"}, {"text": "艇", "is_correct": false, "explanation": "tǐng（第三声）与 tīng（第一声）声调不同，意思是小船。"}, {"text": "丁", "is_correct": false, "explanation": "dīng 与 tīng 声母不同（d 与 t），声调相同，意思是丁。"}, {"text": "庭", "is_correct": false, "explanation": "tíng（第二声）与 tīng（第一声）声调不同，意思是庭院。"}], "explanations": {"听": "“听”（tīng）：用耳朵接收声音，也指听从、接受意见。此处指听从劝告。", "亭": "tíng（第二声）与 tīng（第一声）声调不同，意思是亭子。", "艇": "tǐng（第三声）与 tīng（第一声）声调不同，意思是小船。", "丁": "dīng 与 tīng 声母不同（d 与 t），声调相同，意思是丁。", "庭": "tíng（第二声）与 tīng（第一声）声调不同，意思是庭院。"}, "sentence_index": null, "correct_answer": "听"}, "level_3": {"options": [{"text": "听", "is_correct": true, "explanation": "“听”表示听从，与“我的”搭配，符合劝告的语气。"}, {"text": "玩", "is_correct": false, "explanation": "搭配：“玩我的”不能表示接受劝告，与后句“早点回家吧”的语气不合。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂我的”是责骂，与劝告的语气正好相反。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“我的”所指的劝告内容不合。"}], "explanations": {"听": "“听”表示听从，与“我的”搭配，符合劝告的语气。", "玩": "搭配：“玩我的”不能表示接受劝告，与后句“早点回家吧”的语气不合。", "骂": "语义：“骂我的”是责骂，与劝告的语气正好相反。", "扔": "语义：“扔”表示丢弃，与“我的”所指的劝告内容不合。"}, "sentence_index": 6, "correct_answer": "听"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听了一杯咖啡。", "explanation": "这里应该用〈喝〉。“听”表示听从意见，不能以饮料为对象。"}, {"text": "我听了一封信给妈妈。", "explanation": "这里应该用〈写〉。“听”表示接受劝告，不能表示写信。"}, {"text": "他把书听到桌子上。", "explanation": "这里应该用〈放〉。“听”表示听从意见，不能表示放置物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于了听妈妈的话。", "corrected_sentence": "他终于听了妈妈的话。", "error_description": "错误在“了”的位置：“了”须紧跟动词，应为“听了”，不能放在“听”前。正确句：“他终于听了妈妈的话。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听不爸爸的劝告。", "corrected_sentence": "他不听爸爸的劝告。", "error_description": "错误在否定词“不”的位置：“不”须放在“听”前。“听不”是可能补语，不能直接带宾语“爸爸的劝告”。正确句：“他不听爸爸的劝告。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
