INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11161, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "疲乏，想睡觉。", "primary_collocate": null, "pronunciation": "kùn", "ipa": "kʰuən˥˩", "syllable_count": 1, "sentences": [{"text": "打哈欠不一定是因为困，可能跟大脑里的“镜像神经元”有关。", "target_word": "困", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "困了就打哈欠，然后去睡觉。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "昨天没睡好，我今天特别困。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你困不困？想睡就去睡吧。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子玩了一天，现在很困。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喝了咖啡以后，我就不困了。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一上课就困，总想趴在桌子上。", "target_word": "困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上十二点了，我已经困得睁不开眼。", "target_word": "困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是困，就先去休息。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么晚了，你不困吗？", "target_word": "困", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯困", "label": "复合"}, {"form": "困倦", "label": "复合"}, {"form": "困意", "label": "复合"}], "register": "口语", "sense_fingerprint": "疲乏想睡觉的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9799fe1c-43b6-4a21-9cbd-d99f80002a08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11161, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "困", "is_correct": true, "explanation": "困（kùn）指疲乏、想睡觉，是本题的目标词。"}, {"text": "捆", "is_correct": false, "explanation": "捆（kǔn）：声调不同（第三声与第四声），意思是用绳子等把东西缠紧。"}, {"text": "混", "is_correct": false, "explanation": "混（hùn）：声母不同（h 与 k），意思是混合、混杂。"}, {"text": "顺", "is_correct": false, "explanation": "顺（shùn）：声母不同（sh 与 k），意思是顺利、顺从。"}], "explanations": {"困": "困（kùn）指疲乏、想睡觉，是本题的目标词。", "捆": "捆（kǔn）：声调不同（第三声与第四声），意思是用绳子等把东西缠紧。", "混": "混（hùn）：声母不同（h 与 k），意思是混合、混杂。", "顺": "顺（shùn）：声母不同（sh 与 k），意思是顺利、顺从。"}, "sentence_index": null, "correct_answer": "困"}, "level_3": {"options": [{"text": "高", "is_correct": false, "explanation": "体貌：“高”描写身高，不能解释这里说的原因。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”指速度慢，无法说明这里的原因。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描写体形，不能作为这种原因。"}, {"text": "困", "is_correct": true, "explanation": "“困”指疲乏、想睡，正是这里讨论的原因，与后文相符。"}], "explanations": {"高": "体貌：“高”描写身高，不能解释这里说的原因。", "慢": "语义：“慢”指速度慢，无法说明这里的原因。", "瘦": "体貌：“瘦”描写体形，不能作为这种原因。", "困": "“困”指疲乏、想睡，正是这里讨论的原因，与后文相符。"}, "sentence_index": 0, "correct_answer": "困"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题很困，我不会做。", "explanation": "这里应该用〈困难〉。“困”指疲乏想睡，形容事情难办要用“困难”。"}, {"text": "这碗汤困得不能喝，我们等一会儿吧。", "explanation": "这里应该用〈烫〉。困指疲乏想睡，汤不能喝是因为烫。"}, {"text": "我对这个问题很困。", "explanation": "这里应该用〈困惑〉。“困”指疲乏，表示不懂、迷惑要用“困惑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11161, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "困", "is_correct": true, "explanation": "困（kùn）指疲乏、想睡觉，是本题的目标词。"}, {"text": "棍", "is_correct": false, "explanation": "棍（gùn）：声母不同（g 与 k），意思是棍子。"}, {"text": "顿", "is_correct": false, "explanation": "顿（dùn）：声母不同（d 与 k），意思是一顿饭、停顿。"}, {"text": "寸", "is_correct": false, "explanation": "寸（cùn）：声母不同（c 与 k），意思是长度单位“寸”。"}], "explanations": {"困": "困（kùn）指疲乏、想睡觉，是本题的目标词。", "棍": "棍（gùn）：声母不同（g 与 k），意思是棍子。", "顿": "顿（dùn）：声母不同（d 与 k），意思是一顿饭、停顿。", "寸": "寸（cùn）：声母不同（c 与 k），意思是长度单位“寸”。"}, "sentence_index": null, "correct_answer": "困"}, "level_3": {"options": [{"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写体形，不能说明上课后的状态。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描写身材，与“总想趴在桌子上”无关。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”指温度高，与上课后想趴下的状态不符。"}, {"text": "困", "is_correct": true, "explanation": "“困”指疲乏、想睡，与后文“总想趴在桌子上”相符。"}], "explanations": {"胖": "体貌：“胖”描写体形，不能说明上课后的状态。", "矮": "体貌：“矮”描写身材，与“总想趴在桌子上”无关。", "烫": "语义：“烫”指温度高，与上课后想趴下的状态不符。", "困": "“困”指疲乏、想睡，与后文“总想趴在桌子上”相符。"}, "sentence_index": 6, "correct_answer": "困"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里太热了，我困得满头大汗。", "explanation": "这里应该用〈热〉。困指疲乏想睡，满头大汗是因为热。"}, {"text": "他的腿被撞了一下，困得叫出声来。", "explanation": "这里应该用〈疼〉。困指疲乏想睡，叫出声来是因为疼。"}, {"text": "我被蚊子咬了一口，困得厉害。", "explanation": "这里应该用〈痒〉。困指疲乏想睡，被蚊子咬后让人难受的是痒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11161, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开了一晚上车，我困不行。", "corrected_sentence": "开了一晚上车，我困得不行。", "error_description": "错误在“得”：“困”带程度补语“不行”时，中间要加“得”，应说“困得不行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11161, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开会的时候我特别困得。", "corrected_sentence": "开会的时候我特别困。", "error_description": "错误形式：“特别困得”；正确形式：“特别困”。“得”要接在“困”后作补语，这里没有补语，不能加“得”，应去掉“得”，说“特别困”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11162, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "醒", "is_correct": true, "explanation": "“醒”与“睡”互为反义，指从睡眠状态恢复清醒。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”指进食，与睡眠之间没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "“走”指移动，与睡眠之间没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指书写，与睡眠之间没有反义关系。"}], "correct_answer": "醒", "explanations": {"醒": "“醒”与“睡”互为反义，指从睡眠状态恢复清醒。", "吃": "“吃”指进食，与睡眠之间没有反义关系。", "走": "“走”指移动，与睡眠之间没有反义关系。", "写": "“写”指书写，与睡眠之间没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11162, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "醒", "is_correct": true, "explanation": "“醒”与“睡”互为反义，指从睡眠状态恢复清醒。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”指快速移动，与睡眠之间没有反义关系。"}, {"text": "喝", "is_correct": false, "explanation": "“喝”指把液体咽下去，与睡眠之间没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "“读”指看书或看文字，与睡眠之间没有反义关系。"}], "correct_answer": "醒", "explanations": {"醒": "“醒”与“睡”互为反义，指从睡眠状态恢复清醒。", "跑": "“跑”指快速移动，与睡眠之间没有反义关系。", "喝": "“喝”指把液体咽下去，与睡眠之间没有反义关系。", "读": "“读”指看书或看文字，与睡眠之间没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11162, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进入睡眠状态，停止活动以恢复体力。", "primary_collocate": null, "pronunciation": "shuì jiào", "ipa": "ʂweɪ̯˥˩ tɕiɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "困了就打哈欠，然后去睡觉。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "昨天我十点就睡觉了。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子已经睡觉了，请小声一点。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天晚上十一点睡觉。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太累了，一回家就睡觉。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉以前，我要先刷牙。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝睡觉的时候很安静。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你该睡觉了，明天还要上班。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在沙发上睡觉了。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上我没睡觉，一直在看书。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "睡了觉", "label": "离合形式"}, {"form": "睡一觉", "label": "离合形式"}, {"form": "睡个觉", "label": "离合形式"}, {"form": "睡觉了", "label": "体标"}], "register": "口语", "sense_fingerprint": "进入睡眠状态，上床入睡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fb865e3-8ed5-4241-8c43-69bb91bb5b7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11162, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "睡觉", "is_correct": true, "explanation": "“睡觉”表示进入睡眠，与“然后去”搭配，符合“困了”的语境。"}, {"text": "打仗", "is_correct": false, "explanation": "语义：“打仗”与“困了就打哈欠”的语境不符，不是睡前的行动。"}, {"text": "辩论", "is_correct": false, "explanation": "语域：“辩论”是正式的讨论活动，与口语化的“困了就打哈欠”语气不合。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与困倦后休息的语境完全不符。"}], "explanations": {"睡觉": "“睡觉”表示进入睡眠，与“然后去”搭配，符合“困了”的语境。", "打仗": "语义：“打仗”与“困了就打哈欠”的语境不符，不是睡前的行动。", "辩论": "语域：“辩论”是正式的讨论活动，与口语化的“困了就打哈欠”语气不合。", "逃跑": "语义：“逃跑”与困倦后休息的语境完全不符。"}, "sentence_index": 0, "correct_answer": "睡觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他整晚睡觉，一直盯着天花板。", "explanation": "这里应该用〈没合眼〉。“睡觉”表示进入睡眠，与“一直盯着天花板”的清醒状态相矛盾。"}, {"text": "他每天睡觉一本书。", "explanation": "这里应该用〈读〉。“睡觉”是不及物动词，后面不能直接带宾语“一本书”。"}, {"text": "他昨晚睡觉看书。", "explanation": "这里应该用〈熬夜〉。“睡觉”表示入睡，不能与“看书”同时进行，表示不睡觉而做事要说“熬夜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": true, "explanation": "“睡觉”表示入睡，与“宝宝……的时候”搭配，描述宝宝睡眠时的状态。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与“很安静”相反，宝宝哭的时候不会安静。"}, {"text": "大喊", "is_correct": false, "explanation": "搭配：“大喊”的状态与“很安静”不搭配，句子描述的是安静状态。"}, {"text": "闹", "is_correct": false, "explanation": "语义：“闹”表示吵闹，与“很安静”正好相反。"}], "explanations": {"睡觉": "“睡觉”表示入睡，与“宝宝……的时候”搭配，描述宝宝睡眠时的状态。", "哭": "语义：“哭”与“很安静”相反，宝宝哭的时候不会安静。", "大喊": "搭配：“大喊”的状态与“很安静”不搭配，句子描述的是安静状态。", "闹": "语义：“闹”表示吵闹，与“很安静”正好相反。"}, "sentence_index": 6, "correct_answer": "睡觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他早上七点就睡觉，然后去上班。", "explanation": "这里应该用〈起床〉。“睡觉”表示入睡，早上要醒着去上班，所以应说起床，不能说睡觉。"}, {"text": "他整夜睡觉，一直在想事情。", "explanation": "这里应该用〈醒着〉。“睡觉”表示入睡，与“一直在想事情”的清醒状态矛盾。"}, {"text": "他一边走路，一边睡觉。", "explanation": "这里应该用〈看手机〉。“睡觉”表示入睡，不能与“走路”同时进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天睡觉了八个小时。", "corrected_sentence": "他昨天睡了八个小时。", "error_description": "“睡觉”是离合词，后面不能直接加“了”和时量成分“八个小时”，应只用“睡”，说“睡了八个小时”。正确句：“他昨天睡了八个小时。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想睡觉一觉。", "corrected_sentence": "我想睡一觉。", "error_description": "“睡觉”是离合词，“一觉”等数量成分要插在“睡”后，不能再接在“睡觉”后面。应为“睡一觉”。正确句：“我想睡一觉。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
