INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11165, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "解释清楚，使对方理解。", "primary_collocate": null, "pronunciation": "shuō míng", "ipa": "ʂwo˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "老师耐心地说明了这个词的用法。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用图片向我们说明这个词的意思。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再说明一下这道题的做法。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有说明自己为什么迟到。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生向病人说明了吃药的方法。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我来说明一下今天的安排。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把新规定向大家说明了一遍。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能说明这件事的原因吗？", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说明了自己的想法，大家都听懂了。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈向孩子说明了过马路要小心的原因。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说明了", "label": "体标"}, {"form": "说明过", "label": "体标"}, {"form": "说明说明", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把事情的原因、方法等讲解清楚，让对方听懂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95905260-0eb1-406d-a3a2-f2ede409b014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11165, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说明", "is_correct": true, "explanation": "正确：“老师耐心地说明了这个词的用法”表示把用法讲清楚，符合句意。"}, {"text": "认为", "is_correct": false, "explanation": "配价：“认为”后接观点或小句，不能直接带“这个词的用法”作宾语，句子不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，“耐心地吃这个词的用法”没有意义。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”表示喜爱，与“耐心地”讲解用法的动作不合，句意不通。"}], "explanations": {"说明": "正确：“老师耐心地说明了这个词的用法”表示把用法讲清楚，符合句意。", "认为": "配价：“认为”后接观点或小句，不能直接带“这个词的用法”作宾语，句子不通。", "吃": "语义：“吃”指进食，“耐心地吃这个词的用法”没有意义。", "喜欢": "语义：“喜欢”表示喜爱，与“耐心地”讲解用法的动作不合，句意不通。"}, "sentence_index": 0, "correct_answer": "说明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师向我们说明了这位新同学。", "explanation": "这里应该用〈介绍〉。“说明”的宾语是道理、情况、方法等内容，不用于人；把人或事物介绍给别人认识要用“介绍”。"}, {"text": "他用画笔说明了秋天的景色。", "explanation": "这里应该用〈描绘〉。“说明”侧重把道理讲清楚，用画笔画出景物要用“描绘”。"}, {"text": "他用道理说明了我，我改变了主意。", "explanation": "这里应该用〈说服〉。“说明”是讲清道理让对方明白，不能用来使人改变想法；使人同意、改变主意要用“说服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11165, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说明", "is_correct": true, "explanation": "正确：“向大家说明了一遍”表示把规定讲清楚，符合句意。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”不能与“规定”和“向大家”搭配，“挂了一遍”说不通。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”指击打，“向大家打了一遍”与句意不符。"}, {"text": "忘", "is_correct": false, "explanation": "配价：“忘”带宾语后不能再接“向大家”这样的间接对象，句子不成立。"}], "explanations": {"说明": "正确：“向大家说明了一遍”表示把规定讲清楚，符合句意。", "挂": "搭配：“挂”不能与“规定”和“向大家”搭配，“挂了一遍”说不通。", "打": "语义：“打”指击打，“向大家打了一遍”与句意不符。", "忘": "配价：“忘”带宾语后不能再接“向大家”这样的间接对象，句子不成立。"}, "sentence_index": 6, "correct_answer": "说明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她说明了一首很好听的歌。", "explanation": "这里应该用〈唱〉。“说明”的宾语是道理、原因、方法，不能是歌曲；唱歌要用“唱”。"}, {"text": "奶奶说明了一个很长的故事。", "explanation": "这里应该用〈讲述〉。“说明”用于讲清道理、原因、方法，讲故事、经历要用“讲述”。"}, {"text": "他说明了一个很大的苹果。", "explanation": "这里应该用〈吃〉。“说明”的宾语是道理、情况、方法，不能是苹果；吃东西要用“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11165, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这个规则说明很清楚。", "corrected_sentence": "他把这个规则说明得很清楚。", "error_description": "错误：“说明”后缺少补语标记“得”。正确：“说明得很清楚”，“得”引出补语“很清楚”，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11165, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我向说明了这件事的经过。", "corrected_sentence": "我向他说明了这件事的经过。", "error_description": "错误：介词“向”后缺少宾语。正确：“向他说明了这件事的经过”，“向”后要带上说话的对象“他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
