INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11166, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生物体正常的生命活动和器官的作用。", "primary_collocate": null, "pronunciation": "shēng lǐ gōng néng", "ipa": "ʂəŋ˥ li˨˩ kʊŋ˥ nɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "这说明打哈欠可能是一种很古老的生理功能。", "target_word": "生理功能", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "尽管哈欠的生理功能逐渐明朗，其神经化学基础仍存争议。", "target_word": "生理功能", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "睡觉是人体重要的生理功能。", "target_word": "生理功能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心跳和呼吸都是基本的生理功能。", "target_word": "生理功能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人老了，身体的生理功能会慢慢下降。", "target_word": "生理功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药可能会影响肝脏的生理功能。", "target_word": "生理功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了他的各项生理功能。", "target_word": "生理功能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动能让身体的生理功能保持良好。", "target_word": "生理功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病时，人的生理功能会发生变化。", "target_word": "生理功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛有看东西的生理功能。", "target_word": "生理功能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "生理现象", "label": "复合"}, {"form": "生理需求", "label": "复合"}], "register": "书面", "sense_fingerprint": "生物体的生命活动与器官作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9799fe1c-43b6-4a21-9cbd-d99f80002a08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生理功能", "is_correct": true, "explanation": "正确：生理功能指生物体的作用，符合“打哈欠”的语境。"}, {"text": "交通工具", "is_correct": false, "explanation": "语义：打哈欠不是交通工具，句意不通。"}, {"text": "调味品", "is_correct": false, "explanation": "语义：打哈欠不是调味品，句意不通。"}, {"text": "机械结构", "is_correct": false, "explanation": "语义：机械结构指机器的构造，不能用来说打哈欠。"}], "explanations": {"生理功能": "正确：生理功能指生物体的作用，符合“打哈欠”的语境。", "交通工具": "语义：打哈欠不是交通工具，句意不通。", "调味品": "语义：打哈欠不是调味品，句意不通。", "机械结构": "语义：机械结构指机器的构造，不能用来说打哈欠。"}, "sentence_index": 0, "correct_answer": "生理功能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的生理功能很多。", "explanation": "这里应该用〈性能〉。生理功能指生物体正常的生命活动和器官的作用，机器只能说性能，不能说生理功能。"}, {"text": "这个人有很强的沟通生理功能。", "explanation": "这里应该用〈能力〉。生理功能指身体器官的作用，不能用于说社交技能。"}, {"text": "心脏是人体一个重要的生理功能。", "explanation": "这里应该用〈器官〉。生理功能指生命活动和器官的作用，心脏本身是器官，不能说它是一种生理功能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生理功能", "is_correct": true, "explanation": "正确：生理功能指身体器官的作用，符合“检查”的对象。"}, {"text": "作业", "is_correct": false, "explanation": "语义：医生检查的是身体机能，不会检查作业，句意冲突。"}, {"text": "课程", "is_correct": false, "explanation": "语义：医生不检查课程，与句子的医疗语境不符。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“检查”一般不用于“心情”，不能说检查心情。"}], "explanations": {"生理功能": "正确：生理功能指身体器官的作用，符合“检查”的对象。", "作业": "语义：医生检查的是身体机能，不会检查作业，句意冲突。", "课程": "语义：医生不检查课程，与句子的医疗语境不符。", "心情": "搭配：“检查”一般不用于“心情”，不能说检查心情。"}, "sentence_index": 6, "correct_answer": "生理功能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布料的生理功能很好。", "explanation": "这里应该用〈质地〉。生理功能指生物体的作用，布料没有生理功能，只能说质地。"}, {"text": "这家饭店的生理功能很好。", "explanation": "这里应该用〈服务〉。饭店没有生理功能，生理功能只用于生物体。"}, {"text": "这篇论文的生理功能很高。", "explanation": "这里应该用〈质量〉。论文不是生物体，不能说生理功能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只生理功能对人体很重要。", "corrected_sentence": "这项生理功能对人体很重要。", "error_description": "错误形式：“这只生理功能”；正确形式：“这项生理功能”。“只”用于动物，或成对物品中的单个，“生理功能”应使用量词“项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "睡觉是人体一条重要的生理功能。", "corrected_sentence": "睡觉是人体一项重要的生理功能。", "error_description": "错误形式：“一条生理功能”；正确形式：“一项生理功能”。“生理功能”的量词用“项”或“种”，不用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11167, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "睡觉", "is_correct": true, "explanation": "正确：“起床”指醒后离开床铺，“睡觉”指入睡躺下，二者意思相反。"}, {"text": "洗脸", "is_correct": false, "explanation": "无反义关系：“洗脸”是起床后的活动，与“起床”不是相对的意义。"}, {"text": "吃饭", "is_correct": false, "explanation": "无反义关系：“吃饭”是起床后可能进行的事，与“起床”并不相对。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”是醒来后的活动，与“起床”不构成反义。"}], "correct_answer": "睡觉", "explanations": {"睡觉": "正确：“起床”指醒后离开床铺，“睡觉”指入睡躺下，二者意思相反。", "洗脸": "无反义关系：“洗脸”是起床后的活动，与“起床”不是相对的意义。", "吃饭": "无反义关系：“吃饭”是起床后可能进行的事，与“起床”并不相对。", "散步": "无反义关系：“散步”是醒来后的活动，与“起床”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11167, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "睡觉", "is_correct": true, "explanation": "正确：“起床”指醒后离开床铺，“睡觉”指入睡躺下，二者意思相反。"}, {"text": "洗澡", "is_correct": false, "explanation": "无反义关系：“洗澡”是起床后常做的事，与“起床”并不相对。"}, {"text": "读书", "is_correct": false, "explanation": "无反义关系：“读书”是醒来后的活动，与“起床”不构成反义。"}, {"text": "跑步", "is_correct": false, "explanation": "无反义关系：“跑步”是起床后的锻炼，与“起床”不是相对的意义。"}], "correct_answer": "睡觉", "explanations": {"睡觉": "正确：“起床”指醒后离开床铺，“睡觉”指入睡躺下，二者意思相反。", "洗澡": "无反义关系：“洗澡”是起床后常做的事，与“起床”并不相对。", "读书": "无反义关系：“读书”是醒来后的活动，与“起床”不构成反义。", "跑步": "无反义关系：“跑步”是起床后的锻炼，与“起床”不是相对的意义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11167, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指人睡醒后离开床铺的动作或过程。", "primary_collocate": null, "pronunciation": "qǐ chuáng", "ipa": "tɕʰi˨˩ ʈʂʰwaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他睡得很沉，妈妈叫了三次，他才起床。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早上六点起床。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上睡得晚，今天起床很难。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟还没起床，妈妈已经做好早饭了。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我可以晚点儿起床。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起床以后，我先喝一杯水。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闹钟响了，可是他没有起床。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你几点起床？我七点起床。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天天冷，大家都不想起床。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶年纪大了，每天五点就起床。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起床了", "label": "体标"}, {"form": "起床气", "label": "复合"}], "register": "中性", "sense_fingerprint": "人睡醒后离开床铺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95905260-0eb1-406d-a3a2-f2ede409b014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11167, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起床", "is_correct": true, "explanation": "正确：“妈妈叫了三次，他才起床”指睡醒后离开床铺，符合句意。"}, {"text": "下班", "is_correct": false, "explanation": "语义：“下班”指结束工作离开单位，与“睡得很沉，妈妈叫了三次”的情境不合，句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”指参加测验，与睡得很沉、被叫醒的情境无关，句意不通。"}, {"text": "放学", "is_correct": false, "explanation": "语义：“放学”指学校放学，与睡得很沉、被叫醒的情境不合，句意不通。"}], "explanations": {"起床": "正确：“妈妈叫了三次，他才起床”指睡醒后离开床铺，符合句意。", "下班": "语义：“下班”指结束工作离开单位，与“睡得很沉，妈妈叫了三次”的情境不合，句意不通。", "考试": "语义：“考试”指参加测验，与睡得很沉、被叫醒的情境无关，句意不通。", "放学": "语义：“放学”指学校放学，与睡得很沉、被叫醒的情境不合，句意不通。"}, "sentence_index": 0, "correct_answer": "起床"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从椅子上起床，走到窗前。", "explanation": "这里应该用〈起身〉。“起床”只指睡醒后离开床铺，从椅子上站起来要用“起身”。"}, {"text": "老师让大家起床回答问题。", "explanation": "这里应该用〈起立〉。“起床”只指离开床铺，课堂上让学生站起来要用“起立”。"}, {"text": "他太累了，就在沙发上起床休息。", "explanation": "这里应该用〈躺下〉。“起床”指从床铺上醒来离开，在沙发上休息应说“躺下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11167, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起床", "is_correct": true, "explanation": "正确：“闹钟响了，可是他没有起床”，“可是”引出转折，表示闹钟响后他仍未离开床铺，符合句意。"}, {"text": "升旗", "is_correct": false, "explanation": "语义：“升旗”是升国旗的仪式，与闹钟响后的动作不合，句意不通。"}, {"text": "行礼", "is_correct": false, "explanation": "语义：“行礼”指敬礼、鞠躬等礼节动作，与闹钟响的语境不合。"}, {"text": "发言", "is_correct": false, "explanation": "搭配：“发言”指当众讲话，不能与“闹钟响了”的情境搭配，句子不成立。"}], "explanations": {"起床": "正确：“闹钟响了，可是他没有起床”，“可是”引出转折，表示闹钟响后他仍未离开床铺，符合句意。", "升旗": "语义：“升旗”是升国旗的仪式，与闹钟响后的动作不合，句意不通。", "行礼": "语义：“行礼”指敬礼、鞠躬等礼节动作，与闹钟响的语境不合。", "发言": "搭配：“发言”指当众讲话，不能与“闹钟响了”的情境搭配，句子不成立。"}, "sentence_index": 6, "correct_answer": "起床"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶摔了一跤，马上起床，没有受伤。", "explanation": "这里应该用〈爬起来〉。“起床”指睡醒后离开床铺，摔倒后从地上重新站起要用“爬起来”。"}, {"text": "客人一进门，大家都起床欢迎。", "explanation": "这里应该用〈站起来〉。“起床”只指离开床铺，坐着的人站起来要用“站起来”。"}, {"text": "奶奶每天晚上九点就起床了。", "explanation": "这里应该用〈上床〉。“起床”指早上醒来离开床铺，晚上睡觉前进入床铺要用“上床”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11167, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天六点半就起床了了。", "corrected_sentence": "我今天六点半就起床了。", "error_description": "错误：“了”重复出现。正确：“起床了”，句末只用一个“了”，不能说“起床了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11167, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天没起床了，所以迟到了。", "corrected_sentence": "他昨天没起床，所以迟到了。", "error_description": "错误：否定词“没”与“了”不能同用在“起床”上。正确：“没起床”，否定句中不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11172, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11172, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11172, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "疲劳指身体或精神感到累，没有力气。", "primary_collocate": null, "pronunciation": "pí láo", "ipa": "pʰi˧˥ lɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "当我们疲劳或注意力下降时，大脑会发出信号，引发打哈欠的动作。", "target_word": "疲劳", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "当个体处于轻度疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "疲劳", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "连续工作十小时，他感到很疲劳。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车太久会让人疲劳。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看起来很疲劳，需要睡一觉。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长途旅行以后，大家都很疲劳。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子玩了一天，已经很疲劳了。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他疲劳得一回家就睡着了。", "target_word": "疲劳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感到疲劳的时候，喝杯热茶会舒服些。", "target_word": "疲劳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，人疲劳时不要学习太久。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "疲勞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体或精神累、没有力气的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c05f1681-2c75-46d9-9afe-d9f49a74d5c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11172, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "疲劳", "is_correct": true, "explanation": "正确答案。疲劳指身体或精神累，没有力气。"}, {"text": "皮毛", "is_correct": false, "explanation": "máo（第二声）与 láo（第二声）声母不同（m 与 l），意思是皮毛，不是累。"}, {"text": "皮薄", "is_correct": false, "explanation": "báo（第二声）与 láo 声母不同（b 与 l），意思是皮很薄，不是累。"}, {"text": "皮袍", "is_correct": false, "explanation": "páo（第二声）与 láo 声母不同（p 与 l），意思是毛皮做的长衣，不是累。"}], "explanations": {"疲劳": "正确答案。疲劳指身体或精神累，没有力气。", "皮毛": "máo（第二声）与 láo（第二声）声母不同（m 与 l），意思是皮毛，不是累。", "皮薄": "báo（第二声）与 láo 声母不同（b 与 l），意思是皮很薄，不是累。", "皮袍": "páo（第二声）与 láo 声母不同（p 与 l），意思是毛皮做的长衣，不是累。"}, "sentence_index": null, "correct_answer": "疲劳"}, "level_3": {"options": [{"text": "疲劳", "is_correct": true, "explanation": "正确答案。这里需要表示身体或精神累、没有力气的状态，与注意力下降、打哈欠的语境相符。"}, {"text": "精力充沛", "is_correct": false, "explanation": "语义：精力充沛与注意力下降相反，而且不会引发打哈欠，句子自相矛盾。"}, {"text": "清醒", "is_correct": false, "explanation": "语义：清醒正与注意力下降相反，“清醒或注意力下降”的说法自相矛盾。"}, {"text": "充足", "is_correct": false, "explanation": "搭配：“充足”多修饰睡眠、水分等，不用来描述人的身体状态，“我们充足”不通。"}], "explanations": {"疲劳": "正确答案。这里需要表示身体或精神累、没有力气的状态，与注意力下降、打哈欠的语境相符。", "精力充沛": "语义：精力充沛与注意力下降相反，而且不会引发打哈欠，句子自相矛盾。", "清醒": "语义：清醒正与注意力下降相反，“清醒或注意力下降”的说法自相矛盾。", "充足": "搭配：“充足”多修饰睡眠、水分等，不用来描述人的身体状态，“我们充足”不通。"}, "sentence_index": 0, "correct_answer": "疲劳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一被大家夸奖，她就疲劳得脸都红了。", "explanation": "这里应该用〈害羞〉。疲劳指身体或精神累，不指被夸奖后的羞涩，这种心态要说害羞。"}, {"text": "他考了第一名，疲劳得跳了起来。", "explanation": "这里应该用〈开心〉。疲劳指累、没有力气，不指得知好成绩后的高兴，要说开心。"}, {"text": "孩子走丢以后，妈妈疲劳得手足无措。", "explanation": "这里应该用〈慌张〉。疲劳说身体或精神累，不说因突发状况而心慌意乱，后者要用慌张。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疲劳", "is_correct": true, "explanation": "正确答案。“已经很疲劳了”表示玩累了，与前面“玩了一天”的语境一致。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”指没有污垢，玩了一天的孩子不会是干净的状态，与句意矛盾。"}, {"text": "清爽", "is_correct": false, "explanation": "搭配：“清爽”多指洗澡后或天气，不用来说玩了一天的孩子。"}, {"text": "健壮", "is_correct": false, "explanation": "语义：“健壮”指身体结实有力，与玩了一天后的状态矛盾，句子不通。"}], "explanations": {"疲劳": "正确答案。“已经很疲劳了”表示玩累了，与前面“玩了一天”的语境一致。", "干净": "语义：“干净”指没有污垢，玩了一天的孩子不会是干净的状态，与句意矛盾。", "清爽": "搭配：“清爽”多指洗澡后或天气，不用来说玩了一天的孩子。", "健壮": "语义：“健壮”指身体结实有力，与玩了一天后的状态矛盾，句子不通。"}, "sentence_index": 6, "correct_answer": "疲劳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师一批评，他就疲劳得哭了起来。", "explanation": "这里应该用〈难过〉。疲劳指身体或精神累，不指因批评而伤心，这种心情要说难过。"}, {"text": "他一看见蛇就很疲劳，躲在门后不敢出来。", "explanation": "这里应该用〈害怕〉。疲劳说身体累，不说看到蛇时的恐惧，这种情绪要说害怕。"}, {"text": "他一赢了比赛，就疲劳地大笑起来。", "explanation": "这里应该用〈得意〉。疲劳指累、想休息，不指赢了之后的自满，这种心态要说得意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几天加班太多，我真的很疲劳着。", "corrected_sentence": "这几天加班太多，我真的很疲劳。", "error_description": "错误：“很”修饰的形容词“疲劳”后又加了持续标记“着”，“很疲劳着”搭配不通。正确：“我真的很疲劳”，句末不加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们忙了一整天，都疲劳站不住了。", "corrected_sentence": "我们忙了一整天，都疲劳得站不住了。", "error_description": "错误：程度补语前漏掉了“得”。正确：“疲劳得站不住了”，“得”引出疲劳的程度结果。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
