INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11173, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11173, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "注意力的意思是，一个人把他的心思和精力集中到一件事情上，不去想别的。", "primary_collocate": null, "pronunciation": "zhù yì lì", "ipa": "ʈʂu˥˩ i˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "当我们疲劳或注意力下降时，大脑会发出信号，引发打哈欠的动作。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "上课的时候，请把注意力放在黑板上。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机会分散孩子的注意力。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看书时注意力很集中。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我太累了，注意力不能集中。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子的注意力只能保持十分钟。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐会影响我的注意力。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏需要很好的注意力。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事吸引了孩子们的注意力。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡够了觉，注意力才会好。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人把心思和精力集中在一件事上的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95905260-0eb1-406d-a3a2-f2ede409b014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11173, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注意力", "is_correct": true, "explanation": "正确。“注意力”指集中心思的能力，疲劳时注意力下降，大脑发出信号引发打哈欠。"}, {"text": "人气", "is_correct": false, "explanation": "语义：“人气”指受欢迎的程度，与疲劳和打哈欠的生理反应无关，句子说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”一般说好坏、大小，不说“下降”，“疲劳或脾气下降”不通顺。"}, {"text": "财产", "is_correct": false, "explanation": "语义：“财产”指拥有的资产，与疲劳引起的大脑信号无关，句意不通。"}], "explanations": {"注意力": "正确。“注意力”指集中心思的能力，疲劳时注意力下降，大脑发出信号引发打哈欠。", "人气": "语义：“人气”指受欢迎的程度，与疲劳和打哈欠的生理反应无关，句子说不通。", "脾气": "搭配：“脾气”一般说好坏、大小，不说“下降”，“疲劳或脾气下降”不通顺。", "财产": "语义：“财产”指拥有的资产，与疲劳引起的大脑信号无关，句意不通。"}, "sentence_index": 0, "correct_answer": "注意力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对历史很有注意力。", "explanation": "这里应该用〈兴趣〉。“注意力”指集中心思的能力，表示对某事的喜爱要用“兴趣”，不能说“有注意力”。"}, {"text": "今天的注意力是三十度。", "explanation": "这里应该用〈温度〉。“三十度”是温度的单位，注意力指集中心思的能力，不能用度数表示。"}, {"text": "他的注意力一年增加了十公斤。", "explanation": "这里应该用〈体重〉。“增加十公斤”说的是重量，注意力指集中心思的能力，不能用公斤来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11173, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注意力", "is_correct": true, "explanation": "正确。听音乐会影响一个人集中心思的能力，这里的“注意力”指这种能力。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，听音乐一般不会影响它，句意不通。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“影响”可以搭配能力、心情等，“名字”不能被“影响”，句子不通。"}, {"text": "购买力", "is_correct": false, "explanation": "语义：“购买力”指买东西的能力，与听音乐无关，句意不通。"}], "explanations": {"注意力": "正确。听音乐会影响一个人集中心思的能力，这里的“注意力”指这种能力。", "体重": "语义：“体重”指身体的重量，听音乐一般不会影响它，句意不通。", "名字": "搭配：“影响”可以搭配能力、心情等，“名字”不能被“影响”，句子不通。", "购买力": "语义：“购买力”指买东西的能力，与听音乐无关，句意不通。"}, "sentence_index": 6, "correct_answer": "注意力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他近视了，注意力只有零点三。", "explanation": "这里应该用〈视力〉。“零点三”是视力的数值，注意力指集中心思，不能用这样的数值表示。"}, {"text": "这辆车的注意力很快。", "explanation": "这里应该用〈速度〉。“快”形容速度，注意力不能说“快”或“慢”，要说速度快。"}, {"text": "这首歌的注意力很优美。", "explanation": "这里应该用〈旋律〉。“优美”形容旋律、景色等，注意力指集中心思，不能用来形容歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上课时，他把注意力放黑板上。", "corrected_sentence": "上课时，他把注意力放在黑板上。", "error_description": "错误：“放”后缺少“在”。正确：“把注意力放在黑板上”，“放在”引出注意力集中的地方。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一看书，注意力就集中的很快。", "corrected_sentence": "他一看书，注意力就集中得很快。", "error_description": "错误：补语前的结构助词应为“得”，不能用“的”。正确：“集中得很快”，“得”引出补语“很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
