INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11175, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用动作、声音、灯光等发出约定的记号，向别人传递消息或指令。", "primary_collocate": null, "pronunciation": "fā chū xìn hào", "ipa": "fa⁵⁵ ʈʂʰu⁵⁵ ɕin⁵¹ xaʊ̯⁵¹", "syllable_count": 4, "sentences": [{"text": "领队在队伍前方挥动小旗，向后面的人发出信号。", "target_word": "发出信号", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "红灯亮了，司机发出信号，让后面的车停下。", "target_word": "发出信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长用灯光向远处的船发出信号。", "target_word": "发出信号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师举起手，向同学发出信号，大家都安静了。", "target_word": "发出信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机转弯前要先发出信号。", "target_word": "发出信号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在山上点火，向救援队发出信号。", "target_word": "发出信号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球场上，教练用手势发出信号，球员马上换人。", "target_word": "发出信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察吹哨子，向大家发出信号，请车辆停下。", "target_word": "发出信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约好用手电筒发出信号。", "target_word": "发出信号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车进站前，工作人员会发出信号。", "target_word": "发出信号", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "發出信號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用动作、声音或灯光传递约定的记号或指令", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95905260-0eb1-406d-a3a2-f2ede409b014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11175, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发出信号", "is_correct": true, "explanation": "正确。领队挥旗向后面的人传递约定的记号，符合“发出信号”的意思。"}, {"text": "产生梦境", "is_correct": false, "explanation": "语义：“产生梦境”指做梦，与挥旗传递记号的动作无关，句意不通。"}, {"text": "吃掉糖果", "is_correct": false, "explanation": "搭配：“吃掉糖果”与“挥动小旗，向后面的人”不搭，句意不通。"}, {"text": "散发香味", "is_correct": false, "explanation": "语义：“散发香味”指发出气味，与挥旗示意的动作无关，句意不通。"}], "explanations": {"发出信号": "正确。领队挥旗向后面的人传递约定的记号，符合“发出信号”的意思。", "产生梦境": "语义：“产生梦境”指做梦，与挥旗传递记号的动作无关，句意不通。", "吃掉糖果": "搭配：“吃掉糖果”与“挥动小旗，向后面的人”不搭，句意不通。", "散发香味": "语义：“散发香味”指发出气味，与挥旗示意的动作无关，句意不通。"}, "sentence_index": 0, "correct_answer": "发出信号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在考场上认真发出信号，把题目全部做完了。", "explanation": "这里应该用〈作答〉。“发出信号”是用动作或声音向别人示意约定的记号，不能用来表示答题。"}, {"text": "他把合同用邮件发出信号给了客户。", "explanation": "这里应该用〈发送〉。合同是文件，用邮件传送要用“发送”；“发出信号”只能示意约定的记号。"}, {"text": "他向大家发出信号了一个很长的故事。", "explanation": "这里应该用〈讲述〉。“发出信号”只能传递简单的约定记号或指令，不能带“故事”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11175, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发出信号", "is_correct": true, "explanation": "正确。教练用手势示意，球员看到后马上换人，符合“发出信号”的意思。"}, {"text": "唱国歌", "is_correct": false, "explanation": "语义：“唱国歌”不是用来传递换人指令的手势，句意不通。"}, {"text": "关上窗户", "is_correct": false, "explanation": "语义：“关上窗户”与球场上的换人无关，句子说不通。"}, {"text": "喝掉汽水", "is_correct": false, "explanation": "搭配：“用手势”后接的是表示意思的动作，“喝掉汽水”不能用手势完成。"}], "explanations": {"发出信号": "正确。教练用手势示意，球员看到后马上换人，符合“发出信号”的意思。", "唱国歌": "语义：“唱国歌”不是用来传递换人指令的手势，句意不通。", "关上窗户": "语义：“关上窗户”与球场上的换人无关，句子说不通。", "喝掉汽水": "搭配：“用手势”后接的是表示意思的动作，“喝掉汽水”不能用手势完成。"}, "sentence_index": 6, "correct_answer": "发出信号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在舞台上发出信号了一首很好听的歌。", "explanation": "这里应该用〈唱〉。“发出信号”只能示意约定的记号，不能带“歌”作宾语。"}, {"text": "消防队发出信号了伤亡人员的详细名单。", "explanation": "这里应该用〈公布〉。“发出信号”只能示意，不能带“名单”作宾语。"}, {"text": "妈妈发出信号他的作文写得好。", "explanation": "这里应该用〈夸奖〉。夸奖要用语言称赞，“发出信号”只能示意约定的记号，不能这样带内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11175, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渔船在夜里从岸上发出信号，报告位置。", "corrected_sentence": "渔船在夜里向岸上发出信号，报告位置。", "error_description": "介词错误。“向岸上”表示信号发给的对象，“从岸上”说成信号来自岸上，与“报告位置”的意思相反，应说“向岸上发出信号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11175, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他按下按钮，向救援队发出信号的，请求救援。", "corrected_sentence": "他按下按钮，向救援队发出信号，请求救援。", "error_description": "“的”误用。“的”须修饰后面的中心名词；此处“的”后直接接逗号，没有中心语，句子不通。应删去“的”，改为“向救援队发出信号，请求救援”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11177, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长久", "is_correct": true, "explanation": "正确：“短暂”指时间很短，“长久”指时间很长，二者构成反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容清晰、明白，与时间长短无关，不是“短暂”的反义词。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容声音小或不活跃，与时间长短无关。"}, {"text": "高大", "is_correct": false, "explanation": "无关：“高大”形容高和大，与时间长短无关。"}], "correct_answer": "长久", "explanations": {"长久": "正确：“短暂”指时间很短，“长久”指时间很长，二者构成反义关系。", "清楚": "无关：“清楚”形容清晰、明白，与时间长短无关，不是“短暂”的反义词。", "安静": "无关：“安静”形容声音小或不活跃，与时间长短无关。", "高大": "无关：“高大”形容高和大，与时间长短无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11177, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长久", "is_correct": true, "explanation": "正确：“短暂”指时间很短，“长久”指时间很长，二者构成反义关系。"}, {"text": "缓慢", "is_correct": false, "explanation": "无关：“缓慢”形容速度慢，是“迅速”的反义词，与“短暂”无关。"}, {"text": "严肃", "is_correct": false, "explanation": "无关：“严肃”形容态度庄重，与时间长短无关。"}, {"text": "宽大", "is_correct": false, "explanation": "无关：“宽大”形容面积或空间大，与时间长短无关。"}], "correct_answer": "长久", "explanations": {"长久": "正确：“短暂”指时间很短，“长久”指时间很长，二者构成反义关系。", "缓慢": "无关：“缓慢”形容速度慢，是“迅速”的反义词，与“短暂”无关。", "严肃": "无关：“严肃”形容态度庄重，与时间长短无关。", "宽大": "无关：“宽大”形容面积或空间大，与时间长短无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11177, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指时间短、持续的时间不长。", "primary_collocate": null, "pronunciation": "duǎn zàn", "ipa": "twan²¹⁴ tsan⁵¹", "syllable_count": 2, "sentences": [{"text": "这个动作可以帮助我们短暂地提高警觉。", "target_word": "短暂", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "人生很短暂，要好好珍惜时间。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车在这个小站只有短暂的停留。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的雨很短暂，一会儿就停了。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快乐的时间总是很短暂。", "target_word": "短暂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的假期很短暂，只有两天。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "美好的春天太短暂了。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议中间有一个短暂的休息。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在北京短暂地住过一段时间。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "短暂的休息以后，比赛又开始了。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "短暫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "时间短，持续不久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95905260-0eb1-406d-a3a2-f2ede409b014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11177, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短暂", "is_correct": true, "explanation": "正确：“短暂地”修饰“提高警觉”，说明这个动作只起很短时间的作用，符合句意。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：“沙哑”形容嗓音粗糙难听，不能用来修饰“提高警觉”。"}, {"text": "圆滑", "is_correct": false, "explanation": "语义：“圆滑”指处世灵活、待人周到，与“警觉”所指的注意状态无关。"}, {"text": "清闲", "is_correct": false, "explanation": "语义：“清闲”指没有事情、悠闲自在，一般不作状语修饰“提高警觉”，与句意不合。"}], "explanations": {"短暂": "正确：“短暂地”修饰“提高警觉”，说明这个动作只起很短时间的作用，符合句意。", "沙哑": "语义：“沙哑”形容嗓音粗糙难听，不能用来修饰“提高警觉”。", "圆滑": "语义：“圆滑”指处世灵活、待人周到，与“警觉”所指的注意状态无关。", "清闲": "语义：“清闲”指没有事情、悠闲自在，一般不作状语修饰“提高警觉”，与句意不合。"}, "sentence_index": 0, "correct_answer": "短暂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这封信写得很短暂。", "explanation": "这里应该用〈简短〉。短暂说时间的长短，信件、文字等篇幅的长短要用“简短”。"}, {"text": "这支铅笔很短暂。", "explanation": "这里应该用〈短小〉。短暂只用于时间，物体的长短、大小要用“短小”。"}, {"text": "他的个子很短暂。", "explanation": "这里应该用〈矮〉。短暂只用于时间的长短，人的高矮要用“矮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短暂", "is_correct": true, "explanation": "正确：“太短暂了”说春天持续的时间太短，符合句意。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”描述空间的宽度，不用来形容时间的长短。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容态度庄重，与“美好的春天”的感情色彩相矛盾。"}, {"text": "枯燥", "is_correct": false, "explanation": "语义：“枯燥”指单调无趣，与“美好”形成冲突。"}], "explanations": {"短暂": "正确：“太短暂了”说春天持续的时间太短，符合句意。", "狭窄": "搭配：“狭窄”描述空间的宽度，不用来形容时间的长短。", "严肃": "语义：“严肃”形容态度庄重，与“美好的春天”的感情色彩相矛盾。", "枯燥": "语义：“枯燥”指单调无趣，与“美好”形成冲突。"}, "sentence_index": 6, "correct_answer": "短暂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司的短暂目标是明年完成。", "explanation": "这里应该用〈短期〉。“短期目标”指计划的时间段，短暂强调事物本身持续很短，不能修饰“目标”。"}, {"text": "这根木棍很短暂。", "explanation": "这里应该用〈短〉。短暂只用于时间，物体的长短要用“短”。"}, {"text": "她的语气很短暂。", "explanation": "这里应该用〈短促〉。短促形容声音、语气急而短，短暂只说时间的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她短暂的笑了一下，又恢复了平静。", "corrected_sentence": "她短暂地笑了一下，又恢复了平静。", "error_description": "“短暂”修饰动词“笑”时要用状语标记“地”，不能用“的”。写成“短暂的笑了一下”，“的”把“短暂”变成了名词性修饰语，动词“笑”就没有了正确的状语结构，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下午我们有一段短暂地空闲。", "corrected_sentence": "下午我们有一段短暂的空闲。", "error_description": "“一段”后接名词“空闲”，“短暂”修饰名词要用“的”。写成“地”后，“短暂地空闲”是状语结构，不能修饰“一段”，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
