INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对可能发生的危险或变化保持敏锐的注意和警惕。", "primary_collocate": null, "pronunciation": "jǐng jué", "ipa": "tɕiŋ˨˩˦ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "这个动作可以帮助我们短暂地提高警觉。", "target_word": "警觉", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这些研究表明，当某一区域的授粉昆虫数量下降时，植物结实率显著降低，连锁效应还会波及依赖这些植物生存的鸟类与哺乳动物，因此我们应当对生态系统的细微变化保持警觉。", "target_word": "警觉", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "夜里一有声音，他就提高了警觉。", "target_word": "警觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位司机开车时一直保持警觉。", "target_word": "警觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人对陌生电话缺乏警觉。", "target_word": "警觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上一个人走路，要有警觉。", "target_word": "警觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狗的警觉很高，陌生人一靠近就叫。", "target_word": "警觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡能让人暂时恢复警觉。", "target_word": "警觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们对小偷的警觉越来越高。", "target_word": "警觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生提醒我们，对网络骗局要有警觉。", "target_word": "警觉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "警覺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对危险或变化的敏锐注意与警惕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c05f1681-2c75-46d9-9afe-d9f49a74d5c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警觉", "is_correct": true, "explanation": "正确答案。“提高警觉”指增强对危险或变化的注意，与句意相符。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：“提高笑声”说不通，笑声不能像警觉那样被提高，与句中的注意力语境无关。"}, {"text": "友情", "is_correct": false, "explanation": "语义：“提高友情”不符合常规说法，友情与句中“短暂地保持注意”的作用无关。"}, {"text": "愁绪", "is_correct": false, "explanation": "语义：“愁绪”指忧伤的情绪，“提高愁绪”说不通，与句中提高注意力的语境无关。"}], "explanations": {"警觉": "正确答案。“提高警觉”指增强对危险或变化的注意，与句意相符。", "笑声": "语义：“提高笑声”说不通，笑声不能像警觉那样被提高，与句中的注意力语境无关。", "友情": "语义：“提高友情”不符合常规说法，友情与句中“短暂地保持注意”的作用无关。", "愁绪": "语义：“愁绪”指忧伤的情绪，“提高愁绪”说不通，与句中提高注意力的语境无关。"}, "sentence_index": 0, "correct_answer": "警觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对历史很有警觉，常常一看就是一下午。", "explanation": "这里应该用〈兴趣〉。警觉指对危险或变化保持注意，不能用于表示对事物的喜爱。"}, {"text": "他的警觉很有趣，逗得全班都笑了。", "explanation": "这里应该用〈幽默〉。警觉指注意和戒备，不指风趣的言行；逗人发笑要说幽默。"}, {"text": "这首歌充满了警觉，听了让人很快乐。", "explanation": "这里应该用〈欢乐〉。警觉指对危险或变化保持注意，不能表示让人快乐的气氛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警觉", "is_correct": true, "explanation": "正确答案。“狗的警觉很高，陌生人一靠近就叫”描述狗的戒备状态，与句意相符。"}, {"text": "幽默感", "is_correct": false, "explanation": "语义：狗的幽默感与陌生人靠近就叫的反应无关，句意不通。"}, {"text": "知名度", "is_correct": false, "explanation": "搭配：“知名度”指社会知晓程度，不用来说狗的状态。"}, {"text": "信誉", "is_correct": false, "explanation": "语义：“信誉”指可信程度，用来形容狗的戒备状态不通，也与“陌生人靠近就叫”相矛盾。"}], "explanations": {"警觉": "正确答案。“狗的警觉很高，陌生人一靠近就叫”描述狗的戒备状态，与句意相符。", "幽默感": "语义：狗的幽默感与陌生人靠近就叫的反应无关，句意不通。", "知名度": "搭配：“知名度”指社会知晓程度，不用来说狗的状态。", "信誉": "语义：“信誉”指可信程度，用来形容狗的戒备状态不通，也与“陌生人靠近就叫”相矛盾。"}, "sentence_index": 6, "correct_answer": "警觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对音乐很有警觉，每天都练琴到深夜。", "explanation": "这里应该用〈热爱〉。警觉指对危险或变化保持注意，不指对事物的喜爱。"}, {"text": "这位老师的讲课很有警觉，同学们都很喜欢听。", "explanation": "这里应该用〈幽默感〉。警觉指戒备和注意，讲课的风趣要用幽默感。"}, {"text": "他下定了警觉，要戒掉烟。", "explanation": "搭配：“下定决心”是固定搭配，“警觉”不能与“下定”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对身边的变化有一块敏锐的警觉。", "corrected_sentence": "他对身边的变化有一种敏锐的警觉。", "error_description": "错误：抽象名词“警觉”误用了量词“块”。正确：“一种敏锐的警觉”，抽象名词一般用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在陌生地方，他对周围的动静总是保持一根警觉。", "corrected_sentence": "在陌生地方，他对周围的动静总是保持一种警觉。", "error_description": "错误：抽象名词“警觉”误用了量词“根”。正确：“一种警觉”，抽象名词一般用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11181, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11181, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11181, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容天气凉快，使人感到舒适。", "primary_collocate": null, "pronunciation": "liáng shuǎng", "ipa": "ljɑŋ³⁵ ʂwɑŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "天气太热时，人们喜欢坐在树下，吹吹凉爽的风。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天的早晨很凉爽。", "target_word": "凉爽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山里的夏天凉爽又舒服。", "target_word": "凉爽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下了雨以后，天气变得凉爽了。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上的风很凉爽，我们去公园散步吧。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这间房子有空调，里面很凉爽。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们喜欢在凉爽的树荫下休息。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市夏天很凉爽，来旅游的人很多。", "target_word": "凉爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的夜晚凉爽舒服，大家都不想回家。", "target_word": "凉爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天比昨天凉爽多了。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "涼爽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "天气凉快而让人舒适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95905260-0eb1-406d-a3a2-f2ede409b014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11181, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凉爽", "is_correct": true, "explanation": "正确：“凉爽的风”指凉快舒适的风，符合天热时乘凉的语境。"}, {"text": "闷热", "is_correct": false, "explanation": "语义：“闷热”指湿热难受，与天热时去树下乘凉的目的相反。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”形容温度极高，风不会让人想去“吹吹”。"}, {"text": "刺眼", "is_correct": false, "explanation": "搭配：“刺眼”形容光线强烈，不能修饰“风”。"}], "explanations": {"凉爽": "正确：“凉爽的风”指凉快舒适的风，符合天热时乘凉的语境。", "闷热": "语义：“闷热”指湿热难受，与天热时去树下乘凉的目的相反。", "滚烫": "语义：“滚烫”形容温度极高，风不会让人想去“吹吹”。", "刺眼": "搭配：“刺眼”形容光线强烈，不能修饰“风”。"}, "sentence_index": 0, "correct_answer": "凉爽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脸色很凉爽。", "explanation": "这里应该用〈苍白〉。凉爽只形容天气、空气让人舒适的凉，脸色的变化要用“苍白”。"}, {"text": "冬天的早晨很凉爽。", "explanation": "这里应该用〈寒冷〉。凉爽表示舒适的凉，冬天的冷应说“寒冷”。"}, {"text": "这碗汤有点凉爽。", "explanation": "这里应该用〈凉〉。凉爽只用于天气、空气等环境，食物的温度要用“凉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11181, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凉爽", "is_correct": true, "explanation": "正确：“凉爽的树荫下”指树荫下凉快舒适，适合休息。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音响亮爽利，不能修饰“树荫”。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”指分量大或心情压抑，与“休息”的轻松感相矛盾。"}, {"text": "焦黑", "is_correct": false, "explanation": "语义：“焦黑”指被烧成黑色，与可以休息的舒适环境不符。"}], "explanations": {"凉爽": "正确：“凉爽的树荫下”指树荫下凉快舒适，适合休息。", "清脆": "搭配：“清脆”形容声音响亮爽利，不能修饰“树荫”。", "沉重": "语义：“沉重”指分量大或心情压抑，与“休息”的轻松感相矛盾。", "焦黑": "语义：“焦黑”指被烧成黑色，与可以休息的舒适环境不符。"}, "sentence_index": 6, "correct_answer": "凉爽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的结果很凉爽。", "explanation": "这里应该用〈理想〉。凉爽只形容天气、环境让人舒适，比赛的结果要用“理想”。"}, {"text": "正午的沙滩很凉爽。", "explanation": "这里应该用〈酷热〉。凉爽指舒适的凉意，正午的炎热应说“酷热”。"}, {"text": "这场演讲很凉爽。", "explanation": "这里应该用〈精彩〉。凉爽只形容天气、环境让人舒适，演讲的好坏要用“精彩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "入秋以后，天气变得凉爽着。", "corrected_sentence": "入秋以后，天气变得凉爽了。", "error_description": "“变得凉爽”后面要用“了”表示变化已经完成。写成“着”表示状态在持续，与句子所说的变化不符，句子不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏末的早晨凉爽地，很适合跑步。", "corrected_sentence": "夏末的早晨凉爽，很适合跑步。", "error_description": "“凉爽”是形容词，直接作谓语描述“早晨”，不加“地”。加“地”后它变成状语，后面没有中心语，句子残缺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11183, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升温", "is_correct": true, "explanation": "升温指气温升高，与降温（气温降低）方向相反，是反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌是娱乐活动，与降温没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步是日常活动，与降温的气温变化无关，不构成反义。"}, {"text": "刮风", "is_correct": false, "explanation": "刮风描述空气流动，与气温降低不是反义关系。"}], "correct_answer": "升温", "explanations": {"升温": "升温指气温升高，与降温（气温降低）方向相反，是反义关系。", "唱歌": "唱歌是娱乐活动，与降温没有反义关系。", "散步": "散步是日常活动，与降温的气温变化无关，不构成反义。", "刮风": "刮风描述空气流动，与气温降低不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11183, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升温", "is_correct": true, "explanation": "升温指气温升高，与降温（气温降低）方向相反，是反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "读书是学习活动，与降温没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步是体育活动，与气温变化无关，不构成反义。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是体育活动，与降温的气温变化无关，不构成反义。"}], "correct_answer": "升温", "explanations": {"升温": "升温指气温升高，与降温（气温降低）方向相反，是反义关系。", "读书": "读书是学习活动，与降温没有反义关系。", "跑步": "跑步是体育活动，与气温变化无关，不构成反义。", "游泳": "游泳是体育活动，与降温的气温变化无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11183, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指气温降低。", "primary_collocate": null, "pronunciation": "jiàng wēn", "ipa": "tɕjɑŋ˥˩ wən˥", "syllable_count": 2, "sentences": [{"text": "天黑以后会降温，所以我们回家加了件外套。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天有冷空气，我们这里会降温。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚会降温，出门多穿一件衣服。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了雨以后，天气马上降温了。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说周末要降温，我们别去爬山了。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方已经开始降温，早上很冷。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天降温很快，你要小心感冒。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报说，后天会大幅降温。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天突然降温，我没带外套。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天一到，这个城市就开始降温。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "降温了", "label": "完成体"}, {"form": "降过温", "label": "经历体"}, {"form": "降了温", "label": "离合式"}], "register": "中性", "sense_fingerprint": "降温|气温降低|动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631ef3ed-ddad-4c43-9d8e-a459e421b3a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11183, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降温", "is_correct": true, "explanation": "正确：降温指气温降低，与“天黑以后”“加了件外套”的语境一致。"}, {"text": "升温", "is_correct": false, "explanation": "语义：升温指气温升高，与“所以加了件外套”的因果关系相矛盾。"}, {"text": "取暖", "is_correct": false, "explanation": "语义：取暖指人使身体变暖，与“加了件外套”说明天变冷的语境不符。"}, {"text": "发热", "is_correct": false, "explanation": "语义：发热指物体或人产生热量，气温不会发热，且与“加了件外套”矛盾。"}], "explanations": {"降温": "正确：降温指气温降低，与“天黑以后”“加了件外套”的语境一致。", "升温": "语义：升温指气温升高，与“所以加了件外套”的因果关系相矛盾。", "取暖": "语义：取暖指人使身体变暖，与“加了件外套”说明天变冷的语境不符。", "发热": "语义：发热指物体或人产生热量，气温不会发热，且与“加了件外套”矛盾。"}, "sentence_index": 0, "correct_answer": "降温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的难度降温了。", "explanation": "这里应该用〈降低〉。降温指温度或天气变冷，考试难度下降要用降低，“难度降温”说不通。"}, {"text": "这个月的水费降温了。", "explanation": "这里应该用〈下降〉。降温指温度变低，水费减少要用下降，“水费降温”说不通。"}, {"text": "车速降温了。", "explanation": "这里应该用〈减慢〉。降温指温度下降，车速变慢要用减慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11183, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降温", "is_correct": true, "explanation": "正确：降温指气温降低，与“这几天降温很快”和“小心感冒”一致。"}, {"text": "降价", "is_correct": false, "explanation": "搭配：降价用于商品价格，不能说天气降价。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：发烧指人的体温升高，不用于描述天气。"}, {"text": "加温", "is_correct": false, "explanation": "语义：加温是使变暖，与“小心感冒”提示的寒冷天气相反。"}], "explanations": {"降温": "正确：降温指气温降低，与“这几天降温很快”和“小心感冒”一致。", "降价": "搭配：降价用于商品价格，不能说天气降价。", "发烧": "搭配：发烧指人的体温升高，不用于描述天气。", "加温": "语义：加温是使变暖，与“小心感冒”提示的寒冷天气相反。"}, "sentence_index": 6, "correct_answer": "降温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的利润降温了。", "explanation": "这里应该用〈下滑〉。降温只指温度变低，利润下降要用下滑。"}, {"text": "参加活动的人数降温了。", "explanation": "这里应该用〈减少〉。降温不能用于人数，人数变少要用减少。"}, {"text": "他的体重降温了。", "explanation": "这里应该用〈减轻〉。降温指温度降低，体重变少要用减轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上周突然降温着，我们都穿上了毛衣。", "corrected_sentence": "上周突然降温，我们都穿上了毛衣。", "error_description": "错误形式：“降温着”。正确形式：“降温”。原因：“着”表示状态持续，“降温”是一次变化，不能加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一周被降温很快，要多穿点衣服。", "corrected_sentence": "这一周降温很快，要多穿点衣服。", "error_description": "错误形式：“被降温”。正确形式：“降温”。原因：“降温”是不及物动词，表示气温降低，不能用“被”构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
