INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11186, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "神经元是神经系统的基本结构和功能单位，负责接收、整合和传递神经信号。", "primary_collocate": null, "pronunciation": "shén jīng yuán", "ipa": "ʂən˧˥ tɕiŋ˥˥ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "这并不是因为困，而可能和大脑中某些神经元的活动有关。", "target_word": "神经元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些神经元会在我们模仿他人行为时被激活。", "target_word": "神经元", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "功能性磁共振成像（fMRI）显示，当人观察他人打哈欠时，大脑中的神经元会被显著激活，这种神经同步现象被认为是哈欠具有“传染性”的基础。", "target_word": "神经元", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "神经元是神经系统里很小的细胞。", "target_word": "神经元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个神经元都能传递信号。", "target_word": "神经元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人脑里有很多神经元。", "target_word": "神经元", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生用仪器观察神经元的变化。", "target_word": "神经元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "神经元通过电信号互相联系。", "target_word": "神经元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们看了神经元的图片。", "target_word": "神经元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡觉时，神经元也在工作。", "target_word": "神经元", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "神經元", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "神经系统中传递信号的基本细胞单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c05f1681-2c75-46d9-9afe-d9f49a74d5c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神经元", "is_correct": true, "explanation": "神经元：神经系统中传递信号的细胞，“大脑中某些神经元的活动”与句意相符。"}, {"text": "肌肉", "is_correct": false, "explanation": "语义：肌肉属于运动器官，不在大脑中，与“大脑中某些”矛盾。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不是大脑中的结构，与“大脑中某些”矛盾。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏位于胸腔，不在大脑中，与“大脑中的”矛盾。"}], "explanations": {"神经元": "神经元：神经系统中传递信号的细胞，“大脑中某些神经元的活动”与句意相符。", "肌肉": "语义：肌肉属于运动器官，不在大脑中，与“大脑中某些”矛盾。", "眼睛": "语义：眼睛不是大脑中的结构，与“大脑中某些”矛盾。", "心脏": "语义：心脏位于胸腔，不在大脑中，与“大脑中的”矛盾。"}, "sentence_index": 0, "correct_answer": "神经元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的神经元坏了，开不了机。", "explanation": "这里应该用〈芯片〉。神经元是生物神经系统的细胞，不能指电脑里的零件。"}, {"text": "他一紧张，神经元就绷得很紧。", "explanation": "这里应该用〈神经〉。“神经绷紧”形容紧张；神经元是神经细胞，不用来形容紧张的感觉。"}, {"text": "他神经元很好使，一下子就想通了。", "explanation": "这里应该用〈脑子〉。“脑子好使”是口语说法，指头脑反应快；神经元是细胞，不这样用来指头脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神经元", "is_correct": true, "explanation": "神经元：神经细胞，可以用仪器观察其变化，与医学语境相符。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不是生理现象，医生用仪器无法观察它的变化。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲属于艺术作品，不是仪器可以观察的对象。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“仪器观察”的对象是生理或物理现象，“脾气”的变化不用仪器观察。"}], "explanations": {"神经元": "神经元：神经细胞，可以用仪器观察其变化，与医学语境相符。", "故事": "语义：故事不是生理现象，医生用仪器无法观察它的变化。", "歌曲": "语义：歌曲属于艺术作品，不是仪器可以观察的对象。", "脾气": "搭配：“仪器观察”的对象是生理或物理现象，“脾气”的变化不用仪器观察。"}, "sentence_index": 6, "correct_answer": "神经元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一到考试就神经元衰弱，晚上总是睡不着。", "explanation": "这里应该用〈神经衰弱〉。“神经衰弱”是固定说法，指精神疲劳、失眠的病症；神经元是细胞，不能这样组合。"}, {"text": "这人神经元兮兮的，总爱一惊一乍。", "explanation": "这里应该用〈神经兮兮〉。“神经兮兮”形容人过分紧张、疑神疑鬼；神经元是细胞，不能用来形容性格。"}, {"text": "神经元是人体的神经中枢。", "explanation": "这里应该用〈大脑〉。大脑是神经中枢的主要部分（中枢还包括脊髓），神经元只是构成神经系统的细胞，不能指整个中枢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条神经元连接着很多其他细胞。", "corrected_sentence": "这个神经元连接着很多其他细胞。", "error_description": "错误形式：“这条神经元”；正确形式：“这个神经元”。神经元的量词是“个”，“条”用于视神经等长条形的神经，不用于神经元这类细胞。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的大脑里大约有八百六十亿条神经元。", "corrected_sentence": "我们的大脑里大约有八百六十亿个神经元。", "error_description": "错误形式：“八百六十亿条神经元”；正确形式：“八百六十亿个神经元”。神经元是细胞，量词用“个”；“条”多用于神经纤维等长条形结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
