INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11187, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按照已有的样子或做法来学习或复制。", "primary_collocate": null, "pronunciation": "mó fǎng", "ipa": "mɔ˧˥ fɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些神经元会在我们模仿他人行为时被激活。", "target_word": "模仿", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "小孩喜欢模仿大人说话。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他模仿得很像，大家都笑了。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语时，可以先模仿老师的发音。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家常常模仿古代的画法。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿在模仿妈妈做饭。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会模仿名人的声音。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学写字要先模仿，再慢慢有自己的风格。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟总是模仿哥哥走路的样子。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏让孩子模仿动物的叫声。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "模仿了", "label": "完成体"}, {"form": "模仿过", "label": "经历体"}, {"form": "模仿着", "label": "持续体"}, {"form": "模仿者", "label": "复合"}], "register": "中性", "sense_fingerprint": "模仿|按已有样子学习复制|动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631ef3ed-ddad-4c43-9d8e-a459e421b3a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11187, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "模仿", "is_correct": true, "explanation": "模仿 mófǎng：照着别人的样子学做，是正确答案。"}, {"text": "魔法", "is_correct": false, "explanation": "魔法 mófǎ 去掉了 fǎng 末尾的 ng，韵母由 ǎng 变为 ǎ，意思是魔力。"}, {"text": "魔方", "is_correct": false, "explanation": "魔方 mófāng 与 mófǎng 只有第二个字声调不同（第一声与第三声），意思是立方体玩具。"}, {"text": "磨坊", "is_correct": false, "explanation": "磨坊 mòfáng 两个字的声调都与 mófǎng 不同，意思是磨面用的作坊。"}], "explanations": {"模仿": "模仿 mófǎng：照着别人的样子学做，是正确答案。", "魔法": "魔法 mófǎ 去掉了 fǎng 末尾的 ng，韵母由 ǎng 变为 ǎ，意思是魔力。", "魔方": "魔方 mófāng 与 mófǎng 只有第二个字声调不同（第一声与第三声），意思是立方体玩具。", "磨坊": "磨坊 mòfáng 两个字的声调都与 mófǎng 不同，意思是磨面用的作坊。"}, "sentence_index": null, "correct_answer": "模仿"}, "level_3": {"options": [{"text": "模仿", "is_correct": true, "explanation": "正确：模仿指照着他人的行为学做，与神经元在“他人行为”时被激活的语境一致。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿的对象是衣物，不能说穿他人行为。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：放弃的对象通常是计划、权利，不说放弃他人的行为。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：睡觉是不及物动词，后面不能带“他人行为”作宾语。"}], "explanations": {"模仿": "正确：模仿指照着他人的行为学做，与神经元在“他人行为”时被激活的语境一致。", "穿": "搭配：穿的对象是衣物，不能说穿他人行为。", "放弃": "搭配：放弃的对象通常是计划、权利，不说放弃他人的行为。", "睡觉": "配价：睡觉是不及物动词，后面不能带“他人行为”作宾语。"}, "sentence_index": 0, "correct_answer": "模仿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "实验室模仿了地震的环境。", "explanation": "这里应该用〈模拟〉。模仿指照着人的样子学做，按条件造出地震环境要用模拟。"}, {"text": "这部纪录片模仿了社会的问题。", "explanation": "这里应该用〈反映〉。模仿指照着别人的做法学做，描写社会问题要用反映。"}, {"text": "他模仿了这份报告的数据。", "explanation": "这里应该用〈分析〉。模仿是学别人的样子，研究报告数据要用分析，“模仿数据”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11187, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "模仿", "is_correct": true, "explanation": "模仿 mófǎng：照着别人的样子学做，是正确答案。"}, {"text": "模范", "is_correct": false, "explanation": "模范 mófàn：第二字为第四声，韵尾由 ng 变为 n，意思是值得学习的榜样。"}, {"text": "魔方", "is_correct": false, "explanation": "魔方 mófāng 与 mófǎng 只有第二个字声调不同，意思是立方体玩具。"}, {"text": "麻纺", "is_correct": false, "explanation": "麻纺 máfǎng：第一字韵母由 o 变为 a，意思是用麻纤维纺线。"}], "explanations": {"模仿": "模仿 mófǎng：照着别人的样子学做，是正确答案。", "模范": "模范 mófàn：第二字为第四声，韵尾由 ng 变为 n，意思是值得学习的榜样。", "魔方": "魔方 mófāng 与 mófǎng 只有第二个字声调不同，意思是立方体玩具。", "麻纺": "麻纺 máfǎng：第一字韵母由 o 变为 a，意思是用麻纤维纺线。"}, "sentence_index": null, "correct_answer": "模仿"}, "level_3": {"options": [{"text": "模仿", "is_correct": true, "explanation": "正确：模仿指学着名人的样子发出声音，与“很会……名人的声音”一致。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：摸的对象是有形的东西，不能摸声音。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：咳嗽是不及物动词，不能带“名人的声音”作宾语。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：扔的对象是具体物体，不能扔声音。"}], "explanations": {"模仿": "正确：模仿指学着名人的样子发出声音，与“很会……名人的声音”一致。", "摸": "搭配：摸的对象是有形的东西，不能摸声音。", "咳嗽": "配价：咳嗽是不及物动词，不能带“名人的声音”作宾语。", "扔": "搭配：扔的对象是具体物体，不能扔声音。"}, "sentence_index": 6, "correct_answer": "模仿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察模仿了事故的损失。", "explanation": "这里应该用〈统计〉。模仿指学别人的样子，统计事故造成的损失要用统计，“模仿损失”说不通。"}, {"text": "王老师模仿了这次考试的分数。", "explanation": "这里应该用〈公布〉。模仿指照着别人的样子学做，公布考试分数要用公布，“模仿分数”说不通。"}, {"text": "电台模仿了今天的天气。", "explanation": "这里应该用〈播报〉。模仿指学别人的样子，播送天气要用播报，“模仿天气”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她模仿很像，我差点以为是老师。", "corrected_sentence": "她模仿得很像，我差点以为是老师。", "error_description": "错误形式：“模仿很像”。正确形式：“模仿得很像”。原因：动词后带表示程度的补语时，要在动词和补语之间加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她会很模仿动物的叫声。", "corrected_sentence": "她很会模仿动物的叫声。", "error_description": "错误形式：“会很模仿”。正确形式：“很会模仿”。原因：程度副词“很”修饰助动词“会”，要放在“会”前面，不能放在“会”和动词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
