INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11189, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门研究人的心理活动规律，以及心理对行为影响的科学家。", "primary_collocate": null, "pronunciation": "xīn lǐ xué jiā", "ipa": "ɕin˥ li˨˩˦ ɕɥe˧˥ tɕja˥", "syllable_count": 4, "sentences": [{"text": "心理学家发现，人和人之间关系越亲近，越容易互相传染打哈欠。", "target_word": "心理学家", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这位心理学家研究儿童的想法。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐想成为一名心理学家。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理学家说，睡得好心情也会好。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位心理学家写过很多书。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理学家常常听病人说话。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位有名的心理学家。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理学家请孩子们玩了一个小游戏。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了心理学家的建议，我不再紧张了。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请来一位心理学家和家长谈话。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "儿童心理学家", "label": "复合"}], "register": "中性", "sense_fingerprint": "心理学家|研究心理活动规律的科学家|名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631ef3ed-ddad-4c43-9d8e-a459e421b3a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11189, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心理学家", "is_correct": true, "explanation": "心理学家研究人的心理活动规律，可以“发现”这一结论，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会做研究，不能“发现”人际关系与打哈欠之间的规律。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是无生命的物体，不能“发现”任何规律。"}, {"text": "教室", "is_correct": false, "explanation": "配价：“发现”需要一个能认识事物的施事，教室只是地点，不能充当主语。"}], "explanations": {"心理学家": "心理学家研究人的心理活动规律，可以“发现”这一结论，句意通顺。", "石头": "语义：石头不会做研究，不能“发现”人际关系与打哈欠之间的规律。", "窗户": "语义：窗户是无生命的物体，不能“发现”任何规律。", "教室": "配价：“发现”需要一个能认识事物的施事，教室只是地点，不能充当主语。"}, "sentence_index": 0, "correct_answer": "心理学家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "心理学家给病人开了安眠药。", "explanation": "这里应该用〈精神科医生〉。开药需要医学资格，心理学家研究心理活动规律，不开药。"}, {"text": "心理学家观测遥远的星系。", "explanation": "这里应该用〈天文学家〉。观测遥远的星系属于天文学，心理学家研究的是人的心理活动。"}, {"text": "心理学家研究地球板块的运动。", "explanation": "这里应该用〈地质学家〉。板块运动属于地质学，心理学家研究的是人的心理活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11189, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心理学家", "is_correct": true, "explanation": "心理学家是一种职业，与“有名的”搭配，句意通顺。"}, {"text": "路人", "is_correct": false, "explanation": "语义：路人指普通行人，与“有名的”的意思相矛盾。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：陌生人是不认识的人，与“有名的”相矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "量词：“一位”只用于人，不能说“一位有名的桌子”。"}], "explanations": {"心理学家": "心理学家是一种职业，与“有名的”搭配，句意通顺。", "路人": "语义：路人指普通行人，与“有名的”的意思相矛盾。", "陌生人": "语义：陌生人是不认识的人，与“有名的”相矛盾。", "桌子": "量词：“一位”只用于人，不能说“一位有名的桌子”。"}, "sentence_index": 6, "correct_answer": "心理学家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "心理学家帮我修好了汽车。", "explanation": "这里应该用〈修理工〉。心理学家研究人的心理活动，不修汽车。"}, {"text": "心理学家在田里种水稻。", "explanation": "这里应该用〈农民〉。种水稻是农民的工作，心理学家研究的是人的心理。"}, {"text": "心理学家给我们做了一桌菜。", "explanation": "这里应该用〈厨师〉。做菜是厨师的工作，与心理学家的研究无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她长大后想当一只心理学家。", "corrected_sentence": "她长大后想当一名心理学家。", "error_description": "量词错误：“心理学家”指人，量词应用“名”或“位”，“只”用于动物。错误形式是“一只心理学家”，正确形式是“一名心理学家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅当过了心理学家。", "corrected_sentence": "我舅舅当过心理学家。", "error_description": "错误形式：“当过了心理学家”。正确形式：“当过心理学家”。原因：经历体“过”与完成体“了”不能同时用在同一个动词“当”后，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
