INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11191, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用于“越……越……”格式中，表示一方的程度随某个条件的加深而加深，另一方的程度也随之加深。", "primary_collocate": null, "pronunciation": "yuè", "ipa": "ɥe˥˩", "syllable_count": 1, "sentences": [{"text": "供应链越长，用的水越多。", "target_word": "越", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "心理学家发现，人和人之间关系越亲近，越容易互相传染打哈欠。", "target_word": "越", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "雨越下越大，我们回家吧。", "target_word": "越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他越说越快，我听不懂。", "target_word": "越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我越看越喜欢。", "target_word": "越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气越冷，喝热茶的人越多。", "target_word": "越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你越着急，越容易出错。", "target_word": "越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学得越多，会的词越多。", "target_word": "越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路越走越远，天也黑了。", "target_word": "越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子越大，越想自己做事。", "target_word": "越", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "越来越", "label": "复合"}], "register": "通用", "sense_fingerprint": "越……越……，表示程度随条件加深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b139446e-7524-4719-8232-ba3bfc86546e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11191, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "越", "is_correct": true, "explanation": "正确答案：越（yuè，第四声），即本词。"}, {"text": "约", "is_correct": false, "explanation": "约（yuē，第一声）与 yuè 声调不同，意思是大约、约定。"}, {"text": "略", "is_correct": false, "explanation": "略（lüè）声母是 l，与 yuè 的零声母不同，意思是省略、略微。"}, {"text": "血", "is_correct": false, "explanation": "血（xuè）声母是 x，与 yuè 声母不同，意思是血液。"}, {"text": "夜", "is_correct": false, "explanation": "夜（yè）没有 u 介音，与 yuè 韵母不同，意思是夜晚。"}], "explanations": {"越": "正确答案：越（yuè，第四声），即本词。", "约": "约（yuē，第一声）与 yuè 声调不同，意思是大约、约定。", "略": "略（lüè）声母是 l，与 yuè 的零声母不同，意思是省略、略微。", "血": "血（xuè）声母是 x，与 yuè 声母不同，意思是血液。", "夜": "夜（yè）没有 u 介音，与 yuè 韵母不同，意思是夜晚。"}, "sentence_index": null, "correct_answer": "越"}, "level_3": {"options": [{"text": "越", "is_correct": true, "explanation": "与前面的“越长”配对，构成“越……越……”，表示程度随条件加深。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不多”是否定，与前句“越长”的递进关系相反，也无法构成“越……越……”。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，前后没有转折关系，与“供应链越长”的因果递进不符。"}, {"text": "都", "is_correct": false, "explanation": "搭配：“都”表示全部或复数，“用的水”不能用“都”来表示程度增加。"}], "explanations": {"越": "与前面的“越长”配对，构成“越……越……”，表示程度随条件加深。", "不": "语义：“不多”是否定，与前句“越长”的递进关系相反，也无法构成“越……越……”。", "却": "语义：“却”表示转折，前后没有转折关系，与“供应链越长”的因果递进不符。", "都": "搭配：“都”表示全部或复数，“用的水”不能用“都”来表示程度增加。"}, "sentence_index": 0, "correct_answer": "越"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个苹果越红，很好吃。", "explanation": "这里应该用〈很〉。“越”要成对使用（越……越……），单独一个“越”不能表示“很”。"}, {"text": "他越高兴地走了。", "explanation": "这里应该用〈很〉。“越”表示程度随条件加深，必须有前后两个部分，不能单用来修饰一个动作。"}, {"text": "我昨天越去了公园。", "explanation": "这里不应该用“越”。“越”表示程度变化，不能直接放在“去”这样的普通动作前面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11191, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "越", "is_correct": true, "explanation": "正确答案：越（yuè，第四声），即本词。"}, {"text": "业", "is_correct": false, "explanation": "业（yè）没有 u 介音，与 yuè 韵母不同，意思是事业、行业。"}, {"text": "叶", "is_correct": false, "explanation": "叶（yè）与 yuè 韵母不同，少了 u 介音，意思是树叶。"}, {"text": "虐", "is_correct": false, "explanation": "虐（nüè）声母是 n，与 yuè 声母不同，意思是残害、虐待。"}], "explanations": {"越": "正确答案：越（yuè，第四声），即本词。", "业": "业（yè）没有 u 介音，与 yuè 韵母不同，意思是事业、行业。", "叶": "叶（yè）与 yuè 韵母不同，少了 u 介音，意思是树叶。", "虐": "虐（nüè）声母是 n，与 yuè 声母不同，意思是残害、虐待。"}, "sentence_index": null, "correct_answer": "越"}, "level_3": {"options": [{"text": "越", "is_correct": true, "explanation": "与前面的“越着急”配对，构成“越……越……”，表示程度随条件加深。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的经历，与“越着急”所说的即时条件不符。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示时间晚或数量少，与“越着急，越容易出错”的递进关系不符。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”后面一般接“会”“能”等，与“容易”的组合不常见，也不能表示程度递进。"}], "explanations": {"越": "与前面的“越着急”配对，构成“越……越……”，表示程度随条件加深。", "曾经": "语义：“曾经”指过去的经历，与“越着急”所说的即时条件不符。", "才": "语义：“才”表示时间晚或数量少，与“越着急，越容易出错”的递进关系不符。", "只": "搭配：“只”后面一般接“会”“能”等，与“容易”的组合不常见，也不能表示程度递进。"}, "sentence_index": 6, "correct_answer": "越"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服越便宜。", "explanation": "这里应该用〈很〉。没有“越……越……”的前后条件，单个“越”不能表示程度高。"}, {"text": "今天越冷，我不想出门。", "explanation": "这里应该用〈很〉。“越冷”后面没有第二个“越”，不能表示程度随条件加深。"}, {"text": "他越喜欢这本书。", "explanation": "这里应该用〈很〉。“越”要用在“越……越……”格式中，单用不表示“非常”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风越刮越很大，我们快进屋吧。", "corrected_sentence": "风越刮越大，我们快进屋吧。", "error_description": "错误：“越很大”；正确：“越大”。“越”本身表示程度加深，后面不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "东西越便宜，买的人多越。", "corrected_sentence": "东西越便宜，买的人越多。", "error_description": "错误：“多越”；正确：“越多”。“越”要放在形容词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11192, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏远", "is_correct": true, "explanation": "“疏远”与“亲近”意义相反，指关系不密切，是反义词。"}, {"text": "快乐", "is_correct": false, "explanation": "“快乐”描述心情，与“亲近”没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事物头绪多，与“亲近”不构成反义。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”指没有污垢，与“亲近”不构成反义。"}], "correct_answer": "疏远", "explanations": {"疏远": "“疏远”与“亲近”意义相反，指关系不密切，是反义词。", "快乐": "“快乐”描述心情，与“亲近”没有反义关系。", "复杂": "“复杂”形容事物头绪多，与“亲近”不构成反义。", "干净": "“干净”指没有污垢，与“亲近”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11192, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏远", "is_correct": true, "explanation": "“疏远”与“亲近”意义相反，指关系不密切，是反义词。"}, {"text": "懒惰", "is_correct": false, "explanation": "“懒惰”形容做事不勤快，与“亲近”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足，与“亲近”不构成反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”形容表面不光滑，与“亲近”不构成反义。"}], "correct_answer": "疏远", "explanations": {"疏远": "“疏远”与“亲近”意义相反，指关系不密切，是反义词。", "懒惰": "“懒惰”形容做事不勤快，与“亲近”没有反义关系。", "明亮": "“明亮”形容光线充足，与“亲近”不构成反义。", "粗糙": "“粗糙”形容表面不光滑，与“亲近”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11192, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指关系密切，彼此接近。", "primary_collocate": null, "pronunciation": "qīn jìn", "ipa": "tɕʰin˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "心理学家发现，人和人之间关系越亲近，越容易互相传染打哈欠。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我和表姐从小一起长大，关系特别亲近。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我们和邻居越来越亲近了。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有几个亲近的朋友，常常一起吃饭。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事之间关系太亲近，有时不好谈工作。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母和孩子应该保持亲近的关系。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和奶奶最亲近，什么话都对奶奶说。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家人住得近，常来常往，关系很亲近。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不是很亲近，只在聚会上见过几次。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老同学见面，感觉还是那么亲近。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲近了", "label": "体标"}, {"form": "親近", "label": "繁体"}], "register": "中性", "sense_fingerprint": "关系密切、彼此接近的；多说人与人之间的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631ef3ed-ddad-4c43-9d8e-a459e421b3a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲近", "is_correct": true, "explanation": "“亲近”指关系密切，与“关系越……越……”搭配，句意通顺。"}, {"text": "疏远", "is_correct": false, "explanation": "语义：疏远指关系不密切，与“越容易互相传染打哈欠”的结论相反。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：陌生指彼此不熟悉，与后文的结论相矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体貌，不能用来说“关系”的远近。"}], "explanations": {"亲近": "“亲近”指关系密切，与“关系越……越……”搭配，句意通顺。", "疏远": "语义：疏远指关系不密切，与“越容易互相传染打哈欠”的结论相反。", "陌生": "语义：陌生指彼此不熟悉，与后文的结论相矛盾。", "高大": "搭配：“高大”形容体貌，不能用来说“关系”的远近。"}, "sentence_index": 0, "correct_answer": "亲近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汽车慢慢亲近了路口。", "explanation": "这里应该用〈靠近〉。亲近指人与人关系密切，车辆接近路口要用靠近。"}, {"text": "这家餐厅的服务很亲近。", "explanation": "这里应该用〈亲切〉。亲切形容态度或服务让人感到温暖；亲近指人与人之间关系密切，不用于服务。"}, {"text": "期末越来越亲近了。", "explanation": "这里应该用〈临近〉。亲近指人与人之间关系密切，不能用来说时间快到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲近", "is_correct": true, "explanation": "“亲近”指关系密切，与“什么话都对奶奶说”的描述相符。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：冷淡指态度不热情，与“什么话都对奶奶说”相矛盾。"}, {"text": "生疏", "is_correct": false, "explanation": "语义：生疏指不熟悉，与“什么话都对奶奶说”相矛盾。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”指物体坚固，不用来形容人与人之间的关系。"}], "explanations": {"亲近": "“亲近”指关系密切，与“什么话都对奶奶说”的描述相符。", "冷淡": "语义：冷淡指态度不热情，与“什么话都对奶奶说”相矛盾。", "生疏": "语义：生疏指不熟悉，与“什么话都对奶奶说”相矛盾。", "硬": "搭配：“硬”指物体坚固，不用来形容人与人之间的关系。"}, "sentence_index": 6, "correct_answer": "亲近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校亲近地铁站。", "explanation": "这里应该用〈邻近〉。亲近指人与人之间感情上的接近，不能用来描述学校与地铁站的位置。"}, {"text": "两家公司的合作非常亲近。", "explanation": "这里应该用〈紧密〉。亲近用于人与人之间的关系，公司之间的合作一般用“紧密”。"}, {"text": "我慢慢亲近了那扇门。", "explanation": "这里应该用〈接近〉。亲近指人与人之间感情密切，不能用于走近一扇门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们俩很得亲近，常常一起吃饭。", "corrected_sentence": "我们俩很亲近，常常一起吃饭。", "error_description": "错误形式：“很得亲近”。正确形式：“很亲近”。原因：程度副词“很”后面不能直接加“得”，“得”只用在动词或形容词与补语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我和舅舅一直很亲近得。", "corrected_sentence": "我和舅舅一直很亲近。", "error_description": "错误形式：“很亲近得”。正确形式：“很亲近”。原因：“得”后面必须接补语，句末不能单独用“得”，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
