INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11193, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "病原体或类似的状态（如哈欠、情绪）从一个个体转移到另一个个体，使后者出现相同的状态。", "primary_collocate": null, "pronunciation": "chuán rǎn", "ipa": "ʈʂʰwan˧˥ ʐan˨˩˦", "syllable_count": 2, "sentences": [{"text": "心理学家发现，人和人之间关系越亲近，越容易互相传染打哈欠。", "target_word": "传染", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "灵长类动物中广泛存在的哈欠传染现象支持了这一理论，尤其是在亲缘关系较近的个体之间，传染概率显著增高，这提示其可能承载着某种隐性的社会联结功能。", "target_word": "传染", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种病为什么传染得这么快？", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种流感传染了很多人。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病毒很容易传染给孩子。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病会通过血液传染。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种病不会传染。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感冒是通过空气传染的。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里很多人咳嗽，流感传染得很快。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "戴口罩可以减少传染的机会。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传染了", "label": "体标"}, {"form": "传染过", "label": "体标"}, {"form": "传染病", "label": "复合词"}, {"form": "传染源", "label": "复合词"}, {"form": "傳染", "label": "繁体"}], "register": "中性", "sense_fingerprint": "病原体或类似的状态在个体之间转移", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c05f1681-2c75-46d9-9afe-d9f49a74d5c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11193, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传染", "is_correct": true, "explanation": "传染：哈欠等状态在个体之间转移，与“互相”及“关系越亲近越容易”的语境相符。"}, {"text": "回避", "is_correct": false, "explanation": "语义：“回避”与“关系越亲近”的语境相反，不合常理。"}, {"text": "讨厌", "is_correct": false, "explanation": "搭配：“讨厌”的对象通常是人或事，不能与“打哈欠”构成互相发生的动作。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”的对象是值得称赞的人或事，“互相赞美打哈欠”不成立。"}], "explanations": {"传染": "传染：哈欠等状态在个体之间转移，与“互相”及“关系越亲近越容易”的语境相符。", "回避": "语义：“回避”与“关系越亲近”的语境相反，不合常理。", "讨厌": "搭配：“讨厌”的对象通常是人或事，不能与“打哈欠”构成互相发生的动作。", "赞美": "搭配：“赞美”的对象是值得称赞的人或事，“互相赞美打哈欠”不成立。"}, "sentence_index": 0, "correct_answer": "传染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墨水滴进水里，很快就传染开了。", "explanation": "这里应该用〈扩散〉。传染指病原体或哈欠、情绪等状态在个体之间转移，墨水在水中的扩散要用“扩散”。"}, {"text": "野火在草原上传染。", "explanation": "这里应该用〈蔓延〉。传染指病原体或类似状态在个体之间转移，野火在草原上的扩展要用“蔓延”。"}, {"text": "同学把作业传染给老师。", "explanation": "这里应该用〈传递〉。传染的对象是病原体或类似状态，作业的递送用“传递”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11193, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传染", "is_correct": true, "explanation": "传染：病原体或类似状态在个体之间转移，与“不会”搭配，表示不会传给他人。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生物的发育，“这种病不会生长”与句意不合。"}, {"text": "写作", "is_correct": false, "explanation": "配价：“写作”要求施事是人，“这种病”不能作“写作”的主语。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭是人的日常行为，不能用来描述“这种病”。"}], "explanations": {"传染": "传染：病原体或类似状态在个体之间转移，与“不会”搭配，表示不会传给他人。", "生长": "语义：“生长”指生物的发育，“这种病不会生长”与句意不合。", "写作": "配价：“写作”要求施事是人，“这种病”不能作“写作”的主语。", "吃饭": "语义：吃饭是人的日常行为，不能用来描述“这种病”。"}, "sentence_index": 6, "correct_answer": "传染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "伤口发炎后，细菌传染了周围的组织。", "explanation": "这里应该用〈感染〉。细菌侵入组织是感染，传染强调病原体在不同个体之间转移，不指同一身体内的侵入。"}, {"text": "老师把知识传染给学生。", "explanation": "这里应该用〈传授〉。传染只用于病原体或类似状态的转移，知识的传授不能用“传染”。"}, {"text": "警察把人群传染出广场。", "explanation": "这里应该用〈驱赶〉。传染不能表示驱使人群离开，驱赶人群要用“驱赶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把感冒传染了给妹妹。", "corrected_sentence": "他把感冒传染给了妹妹。", "error_description": "错误形式：“传染了给”；正确形式：“传染给了”。“给”与动词连用，“了”应放在“给”之后，表示动作已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候不被这种病传染过。", "corrected_sentence": "我小时候没被这种病传染过。", "error_description": "错误形式：“不被……传染过”；正确形式：“没被……传染过”。表示过去经历的否定要用“没”，不用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11195, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "糊涂", "is_correct": true, "explanation": "正确。糊涂指头脑不明白、不清楚，与清醒是反义词。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音或不吵闹，与清醒在“头脑清楚”这一义项上没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮指光线充足或颜色鲜亮，与清醒没有反义关系。"}, {"text": "宽广", "is_correct": false, "explanation": "宽广指面积大、空间开阔，与清醒没有反义关系。"}], "correct_answer": "糊涂", "explanations": {"糊涂": "正确。糊涂指头脑不明白、不清楚，与清醒是反义词。", "安静": "安静指没有声音或不吵闹，与清醒在“头脑清楚”这一义项上没有反义关系。", "明亮": "明亮指光线充足或颜色鲜亮，与清醒没有反义关系。", "宽广": "宽广指面积大、空间开阔，与清醒没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11195, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "糊涂", "is_correct": true, "explanation": "正确。糊涂指头脑不明白、不清楚，与清醒是反义词。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹指场面喧闹、人多有趣，与清醒没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软指质地不硬，与清醒没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净指没有污物，与清醒没有反义关系。"}], "correct_answer": "糊涂", "explanations": {"糊涂": "正确。糊涂指头脑不明白、不清楚，与清醒是反义词。", "热闹": "热闹指场面喧闹、人多有趣，与清醒没有反义关系。", "柔软": "柔软指质地不硬，与清醒没有反义关系。", "干净": "干净指没有污物，与清醒没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11195, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指人头脑清楚，明白事理，没有迷糊或糊涂。", "primary_collocate": null, "pronunciation": "qīng xǐng", "ipa": "tɕʰiŋ˥ ɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "有的研究说它帮助清醒，有的说它帮助放松。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "喝了一杯咖啡，我头脑清醒多了。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨晚没睡好，上课时一点也不清醒。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一番思考，我的头脑渐渐清醒起来。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷水洗脸能让人很快清醒。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上散散步，头脑会更清醒。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的人必须保持清醒。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想了很久，才清醒地意识到问题所在。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚起床，脑子还不太清醒。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里风很冷，吹了一会儿，我就清醒了。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清醒了", "label": "体标"}, {"form": "清醒清醒", "label": "重叠"}], "register": "中性", "sense_fingerprint": "头脑清楚、不迷糊：睡意或昏沉消失后，或思想上明白事理（头脑清醒、保持清醒）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631ef3ed-ddad-4c43-9d8e-a459e421b3a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11195, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "清醒", "is_correct": true, "explanation": "正确答案。清醒 qīng xǐng 指睡意或迷糊消失后，头脑清楚。"}, {"text": "清新", "is_correct": false, "explanation": "清新 qīng xīn：第一个音节相同，第二个音节 xīn 与 xǐng 的韵尾不同（in 与 ing），声调也不同，意思是清爽新鲜。"}, {"text": "情形", "is_correct": false, "explanation": "情形 qíng xíng：两个音节的声调都与清醒不同（qíng 与 qīng，xíng 与 xǐng），意思是情况。"}, {"text": "庆幸", "is_correct": false, "explanation": "庆幸 qìng xìng：两个音节都只有声调不同，意思是为好事感到幸运。"}, {"text": "清洗", "is_correct": false, "explanation": "清洗 qīng xǐ：第二个音节少了韵尾 -ng（xǐ 与 xǐng），其余相同，意思是洗净。"}], "explanations": {"清醒": "正确答案。清醒 qīng xǐng 指睡意或迷糊消失后，头脑清楚。", "清新": "清新 qīng xīn：第一个音节相同，第二个音节 xīn 与 xǐng 的韵尾不同（in 与 ing），声调也不同，意思是清爽新鲜。", "情形": "情形 qíng xíng：两个音节的声调都与清醒不同（qíng 与 qīng，xíng 与 xǐng），意思是情况。", "庆幸": "庆幸 qìng xìng：两个音节都只有声调不同，意思是为好事感到幸运。", "清洗": "清洗 qīng xǐ：第二个音节少了韵尾 -ng（xǐ 与 xǐng），其余相同，意思是洗净。"}, "sentence_index": null, "correct_answer": "清醒"}, "level_3": {"options": [{"text": "清醒", "is_correct": true, "explanation": "正确。“帮助清醒”指让头脑清楚，与后句“帮助放松”并列，构成两种作用的对比。"}, {"text": "迷糊", "is_correct": false, "explanation": "语义：“迷糊”指头脑不清楚，与前句的正面作用相反，“帮助迷糊”不合语义。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：“紧张”与后句的“放松”意思相反，“帮助紧张”也与上下文的积极作用矛盾。"}, {"text": "疲惫", "is_correct": false, "explanation": "搭配：“帮助”后面接“疲惫”不自然，不能说“帮助疲惫”。"}], "explanations": {"清醒": "正确。“帮助清醒”指让头脑清楚，与后句“帮助放松”并列，构成两种作用的对比。", "迷糊": "语义：“迷糊”指头脑不清楚，与前句的正面作用相反，“帮助迷糊”不合语义。", "紧张": "语义：“紧张”与后句的“放松”意思相反，“帮助紧张”也与上下文的积极作用矛盾。", "疲惫": "搭配：“帮助”后面接“疲惫”不自然，不能说“帮助疲惫”。"}, "sentence_index": 0, "correct_answer": "清醒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这件事讲得很清醒。", "explanation": "这里应该用〈清楚〉。清醒形容人的头脑，讲解、说明是否清楚要用“清楚”。"}, {"text": "阳光很清醒，照得人睁不开眼。", "explanation": "这里应该用〈耀眼〉。清醒只形容人的头脑，阳光的强烈要用“耀眼”。"}, {"text": "这杯柠檬水喝起来很清醒。", "explanation": "这里应该用〈清爽〉。清醒不能形容饮料的口感，喝起来的爽快要用“清爽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11195, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "清醒", "is_correct": true, "explanation": "正确答案。清醒 qīng xǐng 指睡意或迷糊消失后，头脑清楚。"}, {"text": "轻信", "is_correct": false, "explanation": "轻信 qīng xìn：第一个音节相同，第二个音节 xìn 与 xǐng 的韵尾不同（in 与 ing），声调也不同，意思是轻易相信。"}, {"text": "轻型", "is_correct": false, "explanation": "轻型 qīng xíng：第一个音节相同，第二个音节 xíng 与 xǐng 只有声调不同，意思是轻便的类型。"}, {"text": "惊醒", "is_correct": false, "explanation": "惊醒 jīng xǐng：声母 j 与 q 不同（不送气与送气），其余相同，意思是受惊后醒来。"}], "explanations": {"清醒": "正确答案。清醒 qīng xǐng 指睡意或迷糊消失后，头脑清楚。", "轻信": "轻信 qīng xìn：第一个音节相同，第二个音节 xìn 与 xǐng 的韵尾不同（in 与 ing），声调也不同，意思是轻易相信。", "轻型": "轻型 qīng xíng：第一个音节相同，第二个音节 xíng 与 xǐng 只有声调不同，意思是轻便的类型。", "惊醒": "惊醒 jīng xǐng：声母 j 与 q 不同（不送气与送气），其余相同，意思是受惊后醒来。"}, "sentence_index": null, "correct_answer": "清醒"}, "level_3": {"options": [{"text": "清醒", "is_correct": true, "explanation": "正确。“保持清醒”指开车时头脑清楚、注意力集中，符合“必须”的要求。"}, {"text": "散漫", "is_correct": false, "explanation": "语义：“散漫”指纪律松弛、注意力分散，与开车需要专注的要求相反。"}, {"text": "慌乱", "is_correct": false, "explanation": "搭配：“保持”通常搭配“冷静”“镇定”等，不说“保持慌乱”。"}, {"text": "糊涂", "is_correct": false, "explanation": "语义：头脑糊涂的人开车有危险，“必须保持糊涂”与常识相矛盾。"}], "explanations": {"清醒": "正确。“保持清醒”指开车时头脑清楚、注意力集中，符合“必须”的要求。", "散漫": "语义：“散漫”指纪律松弛、注意力分散，与开车需要专注的要求相反。", "慌乱": "搭配：“保持”通常搭配“冷静”“镇定”等，不说“保持慌乱”。", "糊涂": "语义：头脑糊涂的人开车有危险，“必须保持糊涂”与常识相矛盾。"}, "sentence_index": 6, "correct_answer": "清醒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条小溪的水很清醒，能看见底下的石头。", "explanation": "这里应该用〈清澈〉。清醒只形容人的头脑，水的透明要用“清澈”。"}, {"text": "这张桌子擦得很清醒。", "explanation": "这里应该用〈干净〉。清醒只形容人的头脑，桌子擦得洁净要用“干净”。"}, {"text": "森林里的空气很清醒。", "explanation": "这里应该用〈清新〉。空气的清爽要用“清新”，清醒不用于形容空气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚起床，脑子还没清醒了。", "corrected_sentence": "他刚起床，脑子还没清醒。", "error_description": "错误：“没……清醒了”。否定句中“没”与“了”不能同用，句末不加“了”。正确为“还没清醒”，表示尚未恢复清醒。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他睡了一觉，慢慢清醒过去了。", "corrected_sentence": "他睡了一觉，慢慢清醒过来了。", "error_description": "错误：“清醒过去”。“过去”表示离开说话人所在之处，不能表示从迷糊到清醒的变化；正确为“清醒过来”，表示恢复清醒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11196, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧张", "is_correct": true, "explanation": "正确。紧张指身体或精神处于绷紧状态，与放松是反义词。"}, {"text": "观察", "is_correct": false, "explanation": "观察指仔细看或留意，与放松没有反义关系。"}, {"text": "进行", "is_correct": false, "explanation": "进行指持续地做某件事，与放松没有反义关系。"}, {"text": "检查", "is_correct": false, "explanation": "检查指查看是否正确或有无问题，与放松没有反义关系。"}], "correct_answer": "紧张", "explanations": {"紧张": "正确。紧张指身体或精神处于绷紧状态，与放松是反义词。", "观察": "观察指仔细看或留意，与放松没有反义关系。", "进行": "进行指持续地做某件事，与放松没有反义关系。", "检查": "检查指查看是否正确或有无问题，与放松没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11196, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧张", "is_correct": true, "explanation": "正确。紧张指身体或精神处于绷紧状态，与放松是反义词。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫指清除脏物，与放松没有反义关系。"}, {"text": "批评", "is_correct": false, "explanation": "批评指指出缺点或错误，与放松没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理指使损坏的东西恢复正常，与放松没有反义关系。"}], "correct_answer": "紧张", "explanations": {"紧张": "正确。紧张指身体或精神处于绷紧状态，与放松是反义词。", "打扫": "打扫指清除脏物，与放松没有反义关系。", "批评": "批评指指出缺点或错误，与放松没有反义关系。", "修理": "修理指使损坏的东西恢复正常，与放松没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11196, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使身体或精神从紧张状态变为轻松的状态。", "primary_collocate": null, "pronunciation": "fàng sōng", "ipa": "faŋ˥˩ sʊŋ˥", "syllable_count": 2, "sentences": [{"text": "有的研究说它帮助清醒，有的说它帮助放松。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "坐下来，先放松肩膀，再慢慢呼吸。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结束了，你可以放松一下。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让他放松心情，不要想太多。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步以后，要放松腿部的肌肉。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "紧张的时候，深呼吸可以放松身体。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐能放松人的心情。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手放松，不要用力。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完工作，他放松了一会儿。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，别太紧张，放松点儿。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放松了", "label": "体标"}, {"form": "放松过", "label": "体标"}, {"form": "放松放松", "label": "重叠"}], "register": "中性", "sense_fingerprint": "使身体、肌肉或精神由紧张变轻松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631ef3ed-ddad-4c43-9d8e-a459e421b3a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放松", "is_correct": true, "explanation": "正确。“帮助放松”指使身体或心情变得轻松，与前句“帮助清醒”并列，构成对比。"}, {"text": "紧绷", "is_correct": false, "explanation": "搭配：“帮助”后面接“紧绷”这类表示身体状态的动词不自然，“帮助紧绷”不成立。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“失眠”指睡不着，是一种问题而不是好处，“帮助失眠”与句中“帮助”表示的积极作用不符。"}, {"text": "分心", "is_correct": false, "explanation": "语义：“分心”指注意力被扰乱，与“帮助清醒”的作用方向相反。"}], "explanations": {"放松": "正确。“帮助放松”指使身体或心情变得轻松，与前句“帮助清醒”并列，构成对比。", "紧绷": "搭配：“帮助”后面接“紧绷”这类表示身体状态的动词不自然，“帮助紧绷”不成立。", "失眠": "语义：“失眠”指睡不着，是一种问题而不是好处，“帮助失眠”与句中“帮助”表示的积极作用不符。", "分心": "语义：“分心”指注意力被扰乱，与“帮助清醒”的作用方向相反。"}, "sentence_index": 0, "correct_answer": "放松"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的视力放松了，看东西越来越模糊。", "explanation": "这里应该用〈下降〉。视力的减退要用“下降”，“放松”指身体或心里由紧张变轻松，不能用于视力。"}, {"text": "他穿着一件很放松的外套。", "explanation": "这里应该用〈宽松〉。衣服的肥大要用“宽松”，“放松”只用于身体或心情的状态。"}, {"text": "他把心里的愤怒放松出来。", "explanation": "这里应该用〈释放〉。愤怒要说“释放”出来，“放松”不能用来表示发泄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放松", "is_correct": true, "explanation": "正确。“音乐能放松人的心情”指音乐使人心情变得轻松。"}, {"text": "惊吓", "is_correct": false, "explanation": "语义：“惊吓”指使人受惊，与“音乐能……人的心情”中音乐的积极作用相反。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：“冻结”用于物体或资金，不能用来处理“心情”。"}, {"text": "僵化", "is_correct": false, "explanation": "语义：“僵化”指失去灵活变化，音乐不会使心情僵化，与句意相反。"}], "explanations": {"放松": "正确。“音乐能放松人的心情”指音乐使人心情变得轻松。", "惊吓": "语义：“惊吓”指使人受惊，与“音乐能……人的心情”中音乐的积极作用相反。", "冻结": "搭配：“冻结”用于物体或资金，不能用来处理“心情”。", "僵化": "语义：“僵化”指失去灵活变化，音乐不会使心情僵化，与句意相反。"}, "sentence_index": 6, "correct_answer": "放松"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把房间的灯放松了。", "explanation": "这里应该用〈关〉。放松指身体或心情由紧张变轻松，关灯要用“关”。"}, {"text": "他轻易放松了这次机会。", "explanation": "这里应该用〈放弃〉。机会要用“放弃”，“放松”不能用于机会。"}, {"text": "吃了药以后，他的疼痛放松了。", "explanation": "这里应该用〈缓解〉。疼痛的减轻要用“缓解”，“放松”不用于形容疼痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在沙发上躺很放松。", "corrected_sentence": "他在沙发上躺得很放松。", "error_description": "错误：“躺很放松”。动词后接描述状态的补语，中间要用“得”连接。正确为“躺得很放松”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他放松的躺在沙发上。", "corrected_sentence": "他放松地躺在沙发上。", "error_description": "错误：“放松的躺”。修饰动词的状语要用“地”，“的”用于名词前。正确为“放松地躺”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
