INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11197, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示确定、毫无疑问，或对某件事有把握。", "primary_collocate": null, "pronunciation": "kěn dìng", "ipa": "kʰən˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "但可以肯定的是，打哈欠不只是一种习惯，而是身体自然调节的一部分。", "target_word": "肯定", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我不能肯定他今天会不会来。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生还不能肯定这是什么病。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能肯定钥匙放在家里吗？", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察无法肯定那个人是不是他。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我只能肯定一件事：他没说谎。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不太肯定自己有没有关门。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话的语气很肯定，没有一点怀疑。", "target_word": "肯定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不敢肯定明年的天气会怎样。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家还不能肯定这种鸟是否还活着。", "target_word": "肯定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "对事实有把握、确定无疑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f5780da-c6e6-4d29-93fe-0d7e321c3e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11197, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肯定", "is_correct": true, "explanation": "正确：“可以肯定的是”表示确定无疑，符合本句说明事实的语境。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情，不能用来说明某件事是否确定。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“遥远”形容距离或时间，与“可以……的是”的确定判断不相容。"}, {"text": "拉风", "is_correct": false, "explanation": "语域：“拉风”是口语俚语，与这段书面科普说明不协调。"}], "explanations": {"肯定": "正确：“可以肯定的是”表示确定无疑，符合本句说明事实的语境。", "温柔": "语义：“温柔”形容性情，不能用来说明某件事是否确定。", "遥远": "语义：“遥远”形容距离或时间，与“可以……的是”的确定判断不相容。", "拉风": "语域：“拉风”是口语俚语，与这段书面科普说明不协调。"}, "sentence_index": 0, "correct_answer": "肯定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次聚会的时间已经肯定了。", "explanation": "这里应该用〈确定〉。“确定”指已经定下来，用于时间、安排；“肯定”表示对事实有把握或认可，不能这样用。"}, {"text": "我们的目标很肯定。", "explanation": "这里应该用〈明确〉。“明确”指目标清楚；“肯定”表示对事情有把握，不用来形容目标。"}, {"text": "这块石头很肯定。", "explanation": "这里应该用〈坚硬〉。“肯定”指对事情有把握，不用来形容物体的质地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11197, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肯定", "is_correct": true, "explanation": "正确：“不太肯定”表示没有十分把握，接“自己有没有关门”，符合语境。"}, {"text": "乐观", "is_correct": false, "explanation": "语义：“乐观”说对未来的态度，不能表示对已发生之事是否有把握。"}, {"text": "幸福", "is_correct": false, "explanation": "配价：“幸福”是形容词，后面不能接“自己有没有关门”这样的小句。"}, {"text": "牛", "is_correct": false, "explanation": "语域：“牛”是口语俚语，用于此处既不通顺，也与日常叙述不协调。"}], "explanations": {"肯定": "正确：“不太肯定”表示没有十分把握，接“自己有没有关门”，符合语境。", "乐观": "语义：“乐观”说对未来的态度，不能表示对已发生之事是否有把握。", "幸福": "配价：“幸福”是形容词，后面不能接“自己有没有关门”这样的小句。", "牛": "语域：“牛”是口语俚语，用于此处既不通顺，也与日常叙述不协调。"}, "sentence_index": 6, "correct_answer": "肯定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张照片的轮廓很肯定。", "explanation": "这里应该用〈清晰〉。“肯定”用于对事实的把握，形容轮廓、线条清楚要用“清晰”。"}, {"text": "这台仪器的数据很肯定。", "explanation": "这里应该用〈精确〉。“肯定”表示对事情有把握，形容数据准确要用“精确”。"}, {"text": "这个房间的温度很肯定。", "explanation": "这里应该用〈稳定〉。“肯定”指对事实有把握，形容温度变化小要用“稳定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说很肯定，我相信他。", "corrected_sentence": "他说得很肯定，我相信他。", "error_description": "补语错误：形容词“肯定”作补语时，“说”后要用“得”，应说“说得很肯定”，不能说“说很肯定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11197, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生还不能肯定了他的病是不是好了。", "corrected_sentence": "医生还不能肯定他的病是不是好了。", "error_description": "体标错误：能愿动词“不能”之后，动词“肯定”不能再带“了”，应说“还不能肯定他的病是不是好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11198, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公开", "is_correct": true, "explanation": "正确：“公开”与“秘密”构成反义，指让人知道、不隐藏。"}, {"text": "清楚", "is_correct": false, "explanation": "非反义：“清楚”形容明白，与“秘密”不构成反义。"}, {"text": "复杂", "is_correct": false, "explanation": "非反义：“复杂”形容繁多难懂，与“秘密”不构成反义。"}, {"text": "完整", "is_correct": false, "explanation": "非反义：“完整”指没有缺失，与“秘密”不构成反义。"}], "correct_answer": "公开", "explanations": {"公开": "正确：“公开”与“秘密”构成反义，指让人知道、不隐藏。", "清楚": "非反义：“清楚”形容明白，与“秘密”不构成反义。", "复杂": "非反义：“复杂”形容繁多难懂，与“秘密”不构成反义。", "完整": "非反义：“完整”指没有缺失，与“秘密”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11198, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公开", "is_correct": true, "explanation": "正确：“公开”与“秘密”构成反义，指让人知道、不隐藏。"}, {"text": "明亮", "is_correct": false, "explanation": "非反义：“明亮”形容光线充足，与“秘密”不构成反义。"}, {"text": "温暖", "is_correct": false, "explanation": "非反义：“温暖”形容气温或感情，与“秘密”不构成反义。"}, {"text": "寂静", "is_correct": false, "explanation": "非反义：“寂静”形容安静无声，与“秘密”不构成反义。"}], "correct_answer": "公开", "explanations": {"公开": "正确：“公开”与“秘密”构成反义，指让人知道、不隐藏。", "明亮": "非反义：“明亮”形容光线充足，与“秘密”不构成反义。", "温暖": "非反义：“温暖”形容气温或感情，与“秘密”不构成反义。", "寂静": "非反义：“寂静”形容安静无声，与“秘密”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11198, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不公开的、不让别人知道的事情或信息。", "primary_collocate": null, "pronunciation": "mì mì", "ipa": "mi˥˩ mi˥˩", "syllable_count": 2, "sentences": [{"text": "未来的研究可能会发现更多关于它的秘密。", "target_word": "秘密", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这是我们两个人的秘密，别告诉别人。", "target_word": "秘密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这个秘密藏了二十年。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能替我保守秘密吗？", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明偷偷告诉我一个秘密。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想让别人知道这个秘密。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我答应他不把这个秘密说出去。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从来没有对我说过自己的秘密。", "target_word": "秘密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日记里写满了她的小秘密。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人发现了他的秘密，他的脸一下子红了。", "target_word": "秘密", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "不公开、不让人知道的事情或信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f5780da-c6e6-4d29-93fe-0d7e321c3e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秘密", "is_correct": true, "explanation": "正确：“关于它的秘密”指尚未为人知的信息，与“研究”的发现相呼应。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：“笑话”是逗人发笑的话，不是研究可以发现的信息。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语，与学术研究的语境不协调。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”指学习或工作任务，与“关于它的”研究对象不相符。"}], "explanations": {"秘密": "正确：“关于它的秘密”指尚未为人知的信息，与“研究”的发现相呼应。", "笑话": "语义：“笑话”是逗人发笑的话，不是研究可以发现的信息。", "八卦": "语域：“八卦”是口语，与学术研究的语境不协调。", "作业": "语义：“作业”指学习或工作任务，与“关于它的”研究对象不相符。"}, "sentence_index": 0, "correct_answer": "秘密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有一只秘密，不能告诉你。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对器物中的一个，不用于“秘密”。"}, {"text": "这个老房子很秘密。", "explanation": "这里应该用〈神秘〉。“秘密”指不让人知道的事，形容地方或气氛的神秘感要用“神秘”。"}, {"text": "这是一把秘密，我从来没说过。", "explanation": "这里应该用〈个〉。“把”多用于有柄的器具，不用于“秘密”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秘密", "is_correct": true, "explanation": "正确：“不把这个秘密说出去”指不让别人知道这件事，符合语境。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不能“说出去”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是物品，不能“说出去”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能“说出去”。"}], "explanations": {"秘密": "正确：“不把这个秘密说出去”指不让别人知道这件事，符合语境。", "苹果": "语义：“苹果”是水果，不能“说出去”。", "雨伞": "语义：“雨伞”是物品，不能“说出去”。", "桌子": "语义：“桌子”是家具，不能“说出去”。"}, "sentence_index": 6, "correct_answer": "秘密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他心里藏着一张秘密。", "explanation": "这里应该用〈个〉。“张”多用于平面的东西，不用于“秘密”。"}, {"text": "这件事你要秘密，别告诉别人。", "explanation": "这里应该用〈保密〉。“秘密”是名词，指不让人知道的事；表示不让别人知道的动作要用“保密”。"}, {"text": "他把秘密挂在墙上。", "explanation": "这里的“挂”只能用于具体物品，“秘密”是抽象的信息，不能挂在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是我的一只秘密，别告诉别人。", "corrected_sentence": "这是我的一个秘密，别告诉别人。", "error_description": "量词错误：“只”多用于动物或成对器物，“秘密”应用“个”，应说“一个秘密”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他心里有一小个秘密，没人知道。", "corrected_sentence": "他心里有一个小秘密，没人知道。", "error_description": "语序错误：数量词与形容词的位置，应说“一个小秘密”，不能说“一小个秘密”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
