INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11199, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容身体或精神非常疲劳，没有力气。", "primary_collocate": null, "pronunciation": "pí bèi", "ipa": "pʰi˧˥ peɪ˥˩", "syllable_count": 2, "sentences": [{"text": "人类在疲惫或无聊时打哈欠，这一看似简单的行为背后，实则蕴含着深刻的生物学与神经学机制。", "target_word": "疲惫", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "加班一周后，他整个人都很疲惫。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她疲惫地坐在沙发上，不想说话。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长途旅行让大家身心疲惫。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着孩子疲惫的脸，妈妈很心疼。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作了一天，疲惫得马上睡着了。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一夜的飞行，我们都疲惫不堪。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说自己一点也不疲惫。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太疲惫的时候，最好早点休息。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疲惫的老人慢慢走回了家。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "疲惫不堪", "label": "复合"}, {"form": "疲惫地", "label": "状语形式"}, {"form": "疲憊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容身体或精神极度劳累、没有力气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6746157-9edb-4c07-be8c-21eb24acfb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11199, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疲惫", "is_correct": true, "explanation": "“疲惫”指劳累后的身心状态，与“打哈欠”的语境相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：打哈欠通常与困倦、厌烦有关，“高兴”的状态与句意不符。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能表示引起哈欠的身体或精神状态。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”指没有污物，不能描述引起哈欠的状态。"}], "explanations": {"疲惫": "“疲惫”指劳累后的身心状态，与“打哈欠”的语境相符。", "高兴": "语义：打哈欠通常与困倦、厌烦有关，“高兴”的状态与句意不符。", "漂亮": "体貌：“漂亮”形容外貌，不能表示引起哈欠的身体或精神状态。", "干净": "语义：“干净”指没有污物，不能描述引起哈欠的状态。"}, "sentence_index": 0, "correct_answer": "疲惫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "司机连续开了十个小时，这台发动机已经很疲惫了。", "explanation": "这里应该用〈过热〉。“疲惫”指人或动物的劳累，不用来形容发动机；发动机运转过久应说“过热”。"}, {"text": "这间屋子很疲惫，地上一点灰也没有。", "explanation": "这里应该用〈干净〉。“疲惫”指人或动物的劳累，不能形容屋子的整洁。"}, {"text": "这道数学题很疲惫，他做了一晚上也没做完。", "explanation": "这里应该用〈难〉。“疲惫”指人的劳累，不用来形容题目的难度，题目难应说“难”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11199, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疲惫", "is_correct": true, "explanation": "“疲惫不堪”是固定说法，与“一夜的飞行”的语境相符。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“不堪”只接负面状态，“热情”是褒义，不能说热情不堪。"}, {"text": "精彩", "is_correct": false, "explanation": "语义：“精彩”形容表演、内容，不能用来描述飞行后的状态。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或眼神，不能描述旅途后的身心状态。"}], "explanations": {"疲惫": "“疲惫不堪”是固定说法，与“一夜的飞行”的语境相符。", "热情": "搭配：“不堪”只接负面状态，“热情”是褒义，不能说热情不堪。", "精彩": "语义：“精彩”形容表演、内容，不能用来描述飞行后的状态。", "明亮": "语义：“明亮”形容光线或眼神，不能描述旅途后的身心状态。"}, "sentence_index": 6, "correct_answer": "疲惫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同的条款很疲惫，大家一看就懂。", "explanation": "这里应该用〈清晰〉。“疲惫”指人的劳累，不用来形容条款的清楚程度。"}, {"text": "近几个月来，经济一直很疲惫，企业都在缩减开支。", "explanation": "这里应该用〈疲软〉。经济、市场不景气用“疲软”，“疲惫”形容人或动物的劳累。"}, {"text": "这个家庭很疲惫，从不为钱发愁。", "explanation": "这里应该用〈富有〉。“疲惫”指人的劳累，不说家庭的富足；“从不为钱发愁”应搭配“富有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他疲惫的走回了家。", "corrected_sentence": "他疲惫地走回了家。", "error_description": "助词错误：形容词修饰动词时用“地”，“疲惫的走”应改为“疲惫地走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们疲惫了地跑回了家。", "corrected_sentence": "孩子们疲惫地跑回了家。", "error_description": "助词错误：“疲惫”作状语修饰动词时用“地”，“了”不能插在二者之间，“疲惫了地跑”应改为“疲惫地跑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11200, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11200, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11200, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "表面上看起来像，实际上可能不是", "primary_collocate": null, "pronunciation": "kàn sì", "ipa": "kʰan⁵¹ sɹ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "由此观之，这些看似消遣的数字空间，实则是社会演化逻辑的加速器。", "target_word": "看似", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "人类在疲惫或无聊时打哈欠，这一看似简单的行为背后，实则蕴含着深刻的生物学与神经学机制。", "target_word": "看似", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这道题看似简单，其实很难。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看似很生气，其实一点儿也不在意。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店看似很小，里面却很大。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看似安静的小镇，晚上特别热闹。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看似便宜的东西，用起来并不省钱。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看似很冷淡，其实心里很热情。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法看似有用，实际上没有效果。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看似结实的桌子，一坐就坏了。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表面像某种样子，实际未必如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c708da23-8b74-483b-bea2-78da0da78450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看似", "is_correct": true, "explanation": "“看似”表示表面上像某种样子，与后文“实则”形成转折，符合句意。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”通常修饰形容词，不宜直接修饰“消遣”，“这些很消遣的数字空间”不通。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”作谓语，句子变成这些东西抛弃了消遣空间，与后文“实则是加速器”不连贯。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”指称赞，与“实则是……加速器”的论述不符，句意不通。"}], "explanations": {"看似": "“看似”表示表面上像某种样子，与后文“实则”形成转折，符合句意。", "很": "语法：“很”通常修饰形容词，不宜直接修饰“消遣”，“这些很消遣的数字空间”不通。", "抛弃": "语义：“抛弃”作谓语，句子变成这些东西抛弃了消遣空间，与后文“实则是加速器”不连贯。", "赞美": "语义：“赞美”指称赞，与“实则是……加速器”的论述不符，句意不通。"}, "sentence_index": 0, "correct_answer": "看似"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事看似发生了，大家都亲眼看见了。", "explanation": "这里应该用〈的确〉。看似只表示外表给人的印象，大家已亲眼看见的事实不能用它来表示推测。"}, {"text": "两个负数相乘，结果看似是正数。", "explanation": "这里应该用〈必然〉。两个负数相乘的符号规律是确定的，看似只表示表面印象，不能用于此处。"}, {"text": "我亲自量过，这块布料看似是三米长。", "explanation": "这里应该用〈确实〉。说话人已亲自测量，结论是确定的，用看似会让人误以为只是印象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看似", "is_correct": true, "explanation": "“看似”表示外表便宜，与“用起来并不省钱”形成转折，符合句意。"}, {"text": "却", "is_correct": false, "explanation": "语法：“却”是表转折的副词，不能直接修饰“便宜的东西”这一名词性短语。"}, {"text": "打算", "is_correct": false, "explanation": "搭配：“打算”后接要做的事情，不能接“便宜的东西”，“打算便宜的东西”不通。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的宾语是活动或组织，不能说“参加便宜的东西”。"}], "explanations": {"看似": "“看似”表示外表便宜，与“用起来并不省钱”形成转折，符合句意。", "却": "语法：“却”是表转折的副词，不能直接修饰“便宜的东西”这一名词性短语。", "打算": "搭配：“打算”后接要做的事情，不能接“便宜的东西”，“打算便宜的东西”不通。", "参加": "搭配：“参加”的宾语是活动或组织，不能说“参加便宜的东西”。"}, "sentence_index": 6, "correct_answer": "看似"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看似有点发烧，想请假去医院。", "explanation": "这里应该用〈好像〉。看似描述从外部看到的样子，说话人谈自己身体的感觉时不能用它。"}, {"text": "他的生日看似是三月五日。", "explanation": "这里应该直接陈述。看似只表示外表给人的印象，生日是身份信息而不是可以看出来的样子，用看似会误导听话人。"}, {"text": "法院看似判他无罪，判决书已经生效了。", "explanation": "这里应该用〈确定〉。判决书已经生效，结果是确定的，看似只表示外表印象，会让结果显得不确定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小镇看似了很远，其实坐车半小时就到了。", "corrected_sentence": "这座小镇看似很远，其实坐车半小时就到了。", "error_description": "错误形式：“看似了”。正确形式：“看似”。原因：“看似”表示外表印象，后面不能加动态助词“了”，应直接接形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子看似的很暗，其实阳光很好。", "corrected_sentence": "这间屋子看似很暗，其实阳光很好。", "error_description": "错误形式：「看似的很暗」。正确形式：「看似很暗」。原因：「看似」后面直接接副词和形容词作谓语，不能加结构助词「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
