INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11201, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "包含、藏有某种道理、意义或情感。", "primary_collocate": null, "pronunciation": "yùn hán zhe", "ipa": "yn˥˩ xan˧˥ ʈʂɤ", "syllable_count": 3, "sentences": [{"text": "人类在疲惫或无聊时打哈欠，这一看似简单的行为背后，实则蕴含着深刻的生物学与神经学机制。", "target_word": "蕴含着", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这首诗蕴含着深深的爱。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古老的故事里蕴含着很多道理。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话蕴含着对朋友的关心。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画蕴含着画家的感情。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的种子蕴含着大大的力量。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个节日都蕴含着不同的文化。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决定蕴含着一定的风险。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的眼神里蕴含着温柔。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "简单的动作中也蕴含着智慧。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蕴含", "label": "基本形式"}, {"form": "蕴含了", "label": "体标"}, {"form": "蕴含过", "label": "体标"}, {"form": "蘊含著", "label": "繁体"}], "register": "书面", "sense_fingerprint": "内部包含、藏有道理、情感等抽象内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6746157-9edb-4c07-be8c-21eb24acfb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11201, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出售着", "is_correct": false, "explanation": "语义：“出售”指把商品卖给别人，“深刻的机制”是抽象的科学内容，无法被出售，与“实则”后的解释不符。"}, {"text": "驾驶着", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车、船、飞机等交通工具，不能与“机制”搭配。"}, {"text": "蕴含着", "is_correct": true, "explanation": "正确：“蕴含着”表示内里藏有深刻的道理或机制，与“看似简单……实则”的语境相符。"}, {"text": "叫卖着", "is_correct": false, "explanation": "语义：“叫卖”指大声招揽顾客、推销商品，与描述生物学原理的语境不符。"}], "explanations": {"出售着": "语义：“出售”指把商品卖给别人，“深刻的机制”是抽象的科学内容，无法被出售，与“实则”后的解释不符。", "驾驶着": "搭配：“驾驶”的对象是车、船、飞机等交通工具，不能与“机制”搭配。", "蕴含着": "正确：“蕴含着”表示内里藏有深刻的道理或机制，与“看似简单……实则”的语境相符。", "叫卖着": "语义：“叫卖”指大声招揽顾客、推销商品，与描述生物学原理的语境不符。"}, "sentence_index": 0, "correct_answer": "蕴含着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个礼堂蕴含着三百人。", "explanation": "这里应该用〈容纳〉。蕴含指东西藏在内部，说场所能装下多少人要用“容纳”。"}, {"text": "昨天路口蕴含着一起车祸。", "explanation": "这里应该用〈发生〉。蕴含指内里藏有抽象的事物，不能用来说事件在某处发生。"}, {"text": "他们在广场上蕴含着婚礼。", "explanation": "这里应该用〈举行〉。蕴含不能用来说举办活动，举办婚礼要用“举行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11201, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸吮着", "is_correct": false, "explanation": "语义：“吸吮”指用嘴吸取液体，与“不同的文化”毫不相干。"}, {"text": "开设着", "is_correct": false, "explanation": "搭配：“开设”的对象是课程、讲座等，不能说“开设文化”。"}, {"text": "驱赶着", "is_correct": false, "explanation": "语义：“驱赶”指赶走人或动物，与抽象的文化内容不相符。"}, {"text": "蕴含着", "is_correct": true, "explanation": "正确：“蕴含着”表示每个节日内部藏有不同的文化，与句子语境相符。"}], "explanations": {"吸吮着": "语义：“吸吮”指用嘴吸取液体，与“不同的文化”毫不相干。", "开设着": "搭配：“开设”的对象是课程、讲座等，不能说“开设文化”。", "驱赶着": "语义：“驱赶”指赶走人或动物，与抽象的文化内容不相符。", "蕴含着": "正确：“蕴含着”表示每个节日内部藏有不同的文化，与句子语境相符。"}, "sentence_index": 6, "correct_answer": "蕴含着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班蕴含着三十个学生。", "explanation": "这里应该用〈包括〉。蕴含指内里藏着东西，说整体包含各成员要用“包括”。"}, {"text": "他蕴含着很多朋友。", "explanation": "这里应该用〈有〉。蕴含不用来说人拥有朋友，表示拥有某人或某物要用“有”。"}, {"text": "这座城市蕴含着三所大学。", "explanation": "这里应该用〈拥有〉。蕴含指东西藏在内部，说城市设有某类机构要用“拥有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "生活中也蕴含得很多道理。", "corrected_sentence": "生活中也蕴含着很多道理。", "error_description": "错误：“着”被换成了“得”。“蕴含”后应接体标“着”表示持续的状态，“蕴含得很多道理”不成立。正确：“生活中也蕴含着很多道理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份计划里蕴含了着很多机会。", "corrected_sentence": "这份计划里蕴含着很多机会。", "error_description": "错误：“蕴含”后面同时用了“了”和“着”两个体标。正确：只用“着”，即“蕴含着”，表示持续的状态，不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
