INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11203, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示从过去到现在很长的一段时间。", "primary_collocate": null, "pronunciation": "cháng qī yǐ lái", "ipa": "ʈʂʰɑŋ˧˥ tɕʰi˥˥ i˨˩ laɪ˧˥", "syllable_count": 4, "sentences": [{"text": "长期以来，科学界对哈欠的功能提出了多种假说，从增加氧气摄入到调节大脑警觉性，但近年来的研究更倾向于认为，其核心功能在于调节大脑温度。", "target_word": "长期以来", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "长期以来，这个村子的人都靠种茶生活。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，他每天早上六点起床跑步。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，这里的冬天都很冷。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，我们一直用这种方法工作。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，妈妈总是把好吃的留给孩子。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，大家都认为这条河很安全。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题长期以来没有得到解决。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，小王一直想去国外学习。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，这家商店的价格都很便宜。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "时间状语，指从过去一直延续到现在的很长一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6746157-9edb-4c07-be8c-21eb24acfb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暂时", "is_correct": false, "explanation": "语义：“暂时”指短时间内的情况，与“长期以来”表示的持续很久相冲突。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示间或发生，而句中提出多种假说并与“但近年来”对比，说明是持续很久的状况。"}, {"text": "长期以来", "is_correct": true, "explanation": "正确：“长期以来”表示从过去到现在一直持续很久，与后文“但近年来”形成对比，语境相符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指不久之前发生的事，与“长期以来”表示持续很久的意思相反。"}], "explanations": {"暂时": "语义：“暂时”指短时间内的情况，与“长期以来”表示的持续很久相冲突。", "偶尔": "语义：“偶尔”表示间或发生，而句中提出多种假说并与“但近年来”对比，说明是持续很久的状况。", "长期以来": "正确：“长期以来”表示从过去到现在一直持续很久，与后文“但近年来”形成对比，语境相符。", "刚刚": "语义：“刚刚”指不久之前发生的事，与“长期以来”表示持续很久的意思相反。"}, "sentence_index": 0, "correct_answer": "长期以来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他长期以来在北京住过三年。", "explanation": "这里应该用〈以前〉。长期以来强调从过去一直持续到现在，已经结束的经历要用“以前”。"}, {"text": "我们长期以来会搬到北京。", "explanation": "这里应该用〈将来〉。长期以来指过去到现在的持续状态，不能用来说未来的事。"}, {"text": "这几天他长期以来不太高兴。", "explanation": "这里应该用〈近来〉。长期以来表示从过去持续到现在的很长时间，说这几天的情况要用“近来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快就会发生，与“长期以来”所表示的长时间持续相冲突。"}, {"text": "一下子", "is_correct": false, "explanation": "语域：“一下子”是口语色彩较浓的副词，表示时间极短，不适合这段书面语境。"}, {"text": "转眼", "is_correct": false, "explanation": "语义：“转眼”表示一瞬间，与句中“大家都认为”所描述的长期共识相冲突。"}, {"text": "长期以来", "is_correct": true, "explanation": "正确：“长期以来”表示这条河长时间被认为是安全的，与句意相符。"}], "explanations": {"马上": "语义：“马上”表示很快就会发生，与“长期以来”所表示的长时间持续相冲突。", "一下子": "语域：“一下子”是口语色彩较浓的副词，表示时间极短，不适合这段书面语境。", "转眼": "语义：“转眼”表示一瞬间，与句中“大家都认为”所描述的长期共识相冲突。", "长期以来": "正确：“长期以来”表示这条河长时间被认为是安全的，与句意相符。"}, "sentence_index": 6, "correct_answer": "长期以来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "长期以来，我刚满二十岁。", "explanation": "这里应该用〈当时〉。长期以来表示持续很久，说某一时刻的情况要用“当时”。"}, {"text": "长期以来，我刚刚回到家。", "explanation": "这里应删去〈长期以来〉。它表示持续很久，与“刚刚回到家”这类刚发生的事相矛盾。"}, {"text": "长期以来，天气突然下起了大雨。", "explanation": "这里应删去〈长期以来〉。它表示持续很久，与“突然”所表示的瞬间变化相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村的水长期以来了都很干净。", "corrected_sentence": "这个村的水长期以来都很干净。", "error_description": "错误：“了”被加在“长期以来”之后。“长期以来”表示持续的状态，不能带“了”。正确：应删去“了”，即“这个村的水长期以来都很干净”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "长期以来，这个小镇的人将会很友好。", "corrected_sentence": "长期以来，这个小镇的人都很友好。", "error_description": "错误：“将会”表示将来。“长期以来”指从过去一直到现在，不能与表将来的“将会”连用，应改为“都很友好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
