INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11204, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指从事科学研究的人群或科学领域。", "primary_collocate": null, "pronunciation": "kē xué jiè", "ipa": "kʰɤ˥˥ ɕɥe˧˥ tɕje˥˩", "syllable_count": 3, "sentences": [{"text": "长期以来，科学界对哈欠的功能提出了多种假说，从增加氧气摄入到调节大脑警觉性，但近年来的研究更倾向于认为，其核心功能在于调节大脑温度。", "target_word": "科学界", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "科学界对这个发现很感兴趣。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项研究得到了科学界的重视。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学界的朋友们都来参加会议。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学界一直在寻找治疗这种病的方法。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多科学界的人都支持这个计划。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是科学界很有名的人。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学界今年发表了不少新成果。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在科学界，诚实是最重要的。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个结果让整个科学界很吃惊。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "科学研究者的整体或科学这一领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6746157-9edb-4c07-be8c-21eb24acfb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科学界", "is_correct": true, "explanation": "正确：句中指做科学研究的群体，能够对哈欠的功能提出假说。"}, {"text": "哈欠", "is_correct": false, "explanation": "语义：哈欠是一种生理动作，不是人或群体，不能提出假说。"}, {"text": "氧气", "is_correct": false, "explanation": "搭配：“提出假说”的主语应是人或群体，不与“氧气”这类物质名词搭配。"}, {"text": "演艺界", "is_correct": false, "explanation": "语义：演艺界指表演与娱乐行业，并不从事科学研究，不能对哈欠的功能提出假说。"}], "explanations": {"科学界": "正确：句中指做科学研究的群体，能够对哈欠的功能提出假说。", "哈欠": "语义：哈欠是一种生理动作，不是人或群体，不能提出假说。", "氧气": "搭配：“提出假说”的主语应是人或群体，不与“氧气”这类物质名词搭配。", "演艺界": "语义：演艺界指表演与娱乐行业，并不从事科学研究，不能对哈欠的功能提出假说。"}, "sentence_index": 0, "correct_answer": "科学界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我认识一位科学界。", "explanation": "这里应该用〈科学家〉。“位”用于计数人，“科学界”指一群人或一个领域，不能用“一位”计数。"}, {"text": "我们正在学习科学界。", "explanation": "这里应该用〈科学〉。学习的对象是学科知识，“科学界”指人群，不能作为学习的对象。"}, {"text": "他的职业是科学界。", "explanation": "这里应该用〈研究者〉。“科学界”指做研究的人群或研究领域，不能用作职业名称，说明职业要用“研究者”之类的人称名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科学界", "is_correct": true, "explanation": "正确：指科学领域或科学群体，句中说的是其中很有名的人。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人，不能作为“很有名的人”的所属范围。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不能成为“很有名的人”的所属领域。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”是场所名词，不与“是……很有名的人”搭配。"}], "explanations": {"科学界": "正确：指科学领域或科学群体，句中说的是其中很有名的人。", "天气": "语义：天气不是人，不能作为“很有名的人”的所属范围。", "咖啡": "语义：咖啡是饮品，不能成为“很有名的人”的所属领域。", "厨房": "搭配：“厨房”是场所名词，不与“是……很有名的人”搭配。"}, "sentence_index": 6, "correct_answer": "科学界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书放在科学界里。", "explanation": "这里应该用〈图书馆〉。“科学界”指做研究的人群或研究领域，不是能放东西的场所，放书要说“放在图书馆里”之类的实体地点。"}, {"text": "我们要保护这座科学界。", "explanation": "这里应该用〈整个〉。“座”用于大楼、山峰等大型固定物，“科学界”是人群或领域，不能用“座”计数，可说“整个科学界”。"}, {"text": "这家科学界很大。", "explanation": "这里应该用〈整个〉。“家”用于公司、商店等机构，“科学界”不能用“家”计数，可说“整个科学界”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他科学界工作很多年了。", "corrected_sentence": "他在科学界工作很多年了。", "error_description": "错误在于“在”。表示地点的介词“在”不能省略，“科学界”前要加“在”，应说“他在科学界工作很多年了”，不能说“他科学界工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项发现给科学界很重要。", "corrected_sentence": "这项发现对科学界很重要。", "error_description": "错误在于介词“给”。表达对某个群体的影响时，“很重要”前要用“对”，应说“对科学界很重要”，不能用“给”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
