INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11208, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11208, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指人体吸收某种物质，通常指通过饮食摄取养分或药物等。", "primary_collocate": null, "pronunciation": "shè rù", "ipa": "ʂɤ˥˩ ɻu˥˩", "syllable_count": 2, "sentences": [{"text": "长期以来，科学界对哈欠的功能提出了多种假说，从增加氧气摄入到调节大脑警觉性，但近年来的研究更倾向于认为，其核心功能在于调节大脑温度。", "target_word": "摄入", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医生说我每天摄入的盐太多了。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人应该多摄入一些钙。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天摄入过多的糖对身体不好。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人通过呼吸摄入氧气。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子需要摄入足够的蛋白质。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动后要及时摄入水分。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天摄入的热量比较少。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄入太多咖啡因会睡不着。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "营养师建议她多摄入蔬菜里的维生素。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摄入了", "label": "完成体"}, {"form": "摄入过", "label": "经历体"}, {"form": "摄入量", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "人体通过饮食、服药或呼吸吸收养分、药物、氧气等物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6746157-9edb-4c07-be8c-21eb24acfb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11208, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摄入", "is_correct": true, "explanation": "正确：“摄入”表示氧气进入体内，与“从增加氧气……到调节大脑警觉性”的语境相符。"}, {"text": "排出", "is_correct": false, "explanation": "语义：“排出”指从体内排到体外，与“增加氧气”的吸入方向相反。"}, {"text": "喷洒", "is_correct": false, "explanation": "搭配：“喷洒”多接液体或药剂，不说“喷洒氧气”。"}, {"text": "播种", "is_correct": false, "explanation": "语义：“播种”指撒种子，与氧气进入体内无关。"}], "explanations": {"摄入": "正确：“摄入”表示氧气进入体内，与“从增加氧气……到调节大脑警觉性”的语境相符。", "排出": "语义：“排出”指从体内排到体外，与“增加氧气”的吸入方向相反。", "喷洒": "搭配：“喷洒”多接液体或药剂，不说“喷洒氧气”。", "播种": "语义：“播种”指撒种子，与氧气进入体内无关。"}, "sentence_index": 0, "correct_answer": "摄入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他摄入了长时间的寒冷。", "explanation": "这里应该用〈忍受〉。“摄入”只用于吃喝、服药等进入体内的物质，不能用于寒冷这类感受。"}, {"text": "他摄入了这份责任。", "explanation": "这里应该用〈承担〉。“摄入”只用于吃喝、服药等物质，不能用于责任。"}, {"text": "我们摄入了一部电影。", "explanation": "这里应该用〈观看〉。“摄入”不能用于电影等视听内容，观看电影要说“观看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摄入", "is_correct": true, "explanation": "正确：运动后补充水分要用“摄入”，表示饮水吸收，与句意相符。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：水分不能被点燃，与句意不合。"}, {"text": "切开", "is_correct": false, "explanation": "语义：“切开”指用刀分开实物，不能用于水分。"}, {"text": "排放", "is_correct": false, "explanation": "搭配：“排放”多接废水、废气，不说“运动后要及时排放水分”。"}], "explanations": {"摄入": "正确：运动后补充水分要用“摄入”，表示饮水吸收，与句意相符。", "点燃": "语义：水分不能被点燃，与句意不合。", "切开": "语义：“切开”指用刀分开实物，不能用于水分。", "排放": "搭配：“排放”多接废水、废气，不说“运动后要及时排放水分”。"}, "sentence_index": 6, "correct_answer": "摄入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摄入了老师的建议。", "explanation": "这里应该用〈接受〉。“摄入”只用于吃喝、服药等物质，不能用于建议。"}, {"text": "我们摄入了这幅画。", "explanation": "这里应该用〈欣赏〉。“摄入”只表示把物质吃进或喝进去，不能用于画。"}, {"text": "她摄入了很大的压力。", "explanation": "这里应该用〈承受〉。“摄入”不能用于压力，承受压力要说“承受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他要多摄入了一些蔬菜。", "corrected_sentence": "他要多摄入一些蔬菜。", "error_description": "错误在于“了”。“要”表示将来或需要，不与完成的“了”同用，应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天把摄入大量的水。", "corrected_sentence": "他每天摄入大量的水。", "error_description": "错误在于“把”。“把”后面必须先有宾语再接动词，这里“把”直接放在“摄入”前，缺少宾语，句子不成立；应删去“把”，即“他每天摄入大量的水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
