INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11209, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人对外界可能发生的危险或变化保持警惕的心理状态或特性。", "primary_collocate": null, "pronunciation": "jǐng jué xìng", "ipa": "tɕiŋ˨˩˦ tɕɥɛ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "长期以来，科学界对哈欠的功能提出了多种假说，从增加氧气摄入到调节大脑警觉性，但近年来的研究更倾向于认为，其核心功能在于调节大脑温度。", "target_word": "警觉性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "司机长时间开车，警觉性会慢慢下降。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里站岗的士兵必须保持高度的警觉性。", "target_word": "警觉性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡眠不足会降低人的警觉性。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动物在陌生环境里警觉性更高。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喝了咖啡以后，他的警觉性提高了。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师希望孩子在路上有更强的警觉性。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，疲劳会让驾驶员的警觉性变差。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项训练能提高飞行员的警觉性。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗对陌生声音的警觉性很高。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "警覺性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "警觉性|人对危险或变化保持警惕的心理状态或特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '949a9561-3731-44c1-9701-0782248bfe49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警觉性", "is_correct": true, "explanation": "正确：“调节大脑警觉性”指调节人对危险的警惕程度，与前文的假说相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：大脑可以被调节的是状态或功能，“颜色”不能作为调节的对象，句意不通。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：“相貌”指人的外貌，不能作为大脑调节的对象。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”是物体的外形，大脑不能调节它。"}], "explanations": {"警觉性": "正确：“调节大脑警觉性”指调节人对危险的警惕程度，与前文的假说相符。", "颜色": "语义：大脑可以被调节的是状态或功能，“颜色”不能作为调节的对象，句意不通。", "相貌": "体貌：“相貌”指人的外貌，不能作为大脑调节的对象。", "形状": "语义：“形状”是物体的外形，大脑不能调节它。"}, "sentence_index": 0, "correct_answer": "警觉性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的警觉性很强，每天都按时完成工作。", "explanation": "这里应该用〈责任心〉。“警觉性”指对危险或变化的察觉，不指对工作的责任感。"}, {"text": "孩子上课时警觉性很集中。", "explanation": "这里应该用〈注意力〉。“集中”用于注意力，“警觉性”指对危险或变化的察觉，不说“警觉性很集中”。"}, {"text": "他把警觉性放进了书包里。", "explanation": "这里应该用〈课本〉。“放进”的对象须是有形的东西，“警觉性”是抽象的心理特性，不能装进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警觉性", "is_correct": true, "explanation": "正确：“更强的警觉性”指对危险的警惕更强，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，没有强弱之分，句中不能说“更强的体重”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高度，不能说“更强的身高”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”没有强弱之分，句中不能说“更强的价格”。"}], "explanations": {"警觉性": "正确：“更强的警觉性”指对危险的警惕更强，符合句意。", "体重": "语义：“体重”指身体的重量，没有强弱之分，句中不能说“更强的体重”。", "身高": "体貌：“身高”指身体的高度，不能说“更强的身高”。", "价格": "语义：“价格”没有强弱之分，句中不能说“更强的价格”。"}, "sentence_index": 6, "correct_answer": "警觉性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首曲子让人产生很深的警觉性。", "explanation": "这里应该用〈感受〉。“警觉性”指对危险或变化的警惕，不指音乐带来的感受。"}, {"text": "他教孩子写字很有警觉性。", "explanation": "这里应该用〈耐心〉。“警觉性”指对危险或变化的察觉，不指教人时的耐心。"}, {"text": "他对画画很有警觉性，每天放学都画一会儿。", "explanation": "这里应该用〈兴趣〉。“警觉性”指对危险或变化的警惕，不指对某种活动的爱好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "连续工作三天后，他一个警觉性下降了。", "corrected_sentence": "连续工作三天后，他的警觉性下降了。", "error_description": "错误：“警觉性”是抽象名词，不能用量词“个”计数，“一个警觉性”不通。正确：应以领属结构“他的警觉性”表达，将“一个”改为“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老兵有很高地警觉性。", "corrected_sentence": "这位老兵有很高的警觉性。", "error_description": "错误：“很高”修饰名词“警觉性”，应用“的”；此处误用“地”（“地”用于修饰动词）。正确：“有很高的警觉性”，只需把“地”改为“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
