INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11210, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指在某种状态、位置或时间之中。", "primary_collocate": null, "pronunciation": "chǔ yú", "ipa": "ʈʂʰu˨˩˦ y˧˥", "syllable_count": 2, "sentences": [{"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "处于", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个国家正处于快速发展的阶段。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人现在处于昏迷状态。", "target_word": "处于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司目前处于很困难的时期。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市处于两条河之间。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他处于紧张的状态，说不出话来。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛处于关键时刻，大家都很安静。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的产品在市场上处于领先地位。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个小村子处于山的北边。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子处于长身体的时期，要多吃饭。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "處於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "处于|身处某种状态、位置或时期之中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '949a9561-3731-44c1-9701-0782248bfe49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11210, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "处于", "is_correct": true, "explanation": "正确：chǔ yú，表示处在某种状态、位置或时期之中。"}, {"text": "出于", "is_correct": false, "explanation": "chū（第一声）与 chǔ（第三声）声调不同，意思是产生于、出自。"}, {"text": "厨余", "is_correct": false, "explanation": "chú（第二声）与 chǔ（第三声）声调不同，意思是厨房里剩下的食物。"}, {"text": "出浴", "is_correct": false, "explanation": "chū yù（第一声、第四声）与 chǔ yú（第三声、第二声）声调不同，意思是洗澡后从浴池中出来。"}], "explanations": {"处于": "正确：chǔ yú，表示处在某种状态、位置或时期之中。", "出于": "chū（第一声）与 chǔ（第三声）声调不同，意思是产生于、出自。", "厨余": "chú（第二声）与 chǔ（第三声）声调不同，意思是厨房里剩下的食物。", "出浴": "chū yù（第一声、第四声）与 chǔ yú（第三声、第二声）声调不同，意思是洗澡后从浴池中出来。"}, "sentence_index": null, "correct_answer": "处于"}, "level_3": {"options": [{"text": "处于", "is_correct": true, "explanation": "正确：“当个体处于……状态时”表示处在某种状态之中，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能带“状态”作宾语，“吃轻度认知疲劳状态”句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”的对象是具体物品，不能修理“状态”。"}, {"text": "进行", "is_correct": false, "explanation": "配价：“进行”后面要接动作性的宾语，不能接“状态”。"}], "explanations": {"处于": "正确：“当个体处于……状态时”表示处在某种状态之中，符合句意。", "吃": "语义：“吃”不能带“状态”作宾语，“吃轻度认知疲劳状态”句意不通。", "修理": "语义：“修理”的对象是具体物品，不能修理“状态”。", "进行": "配价：“进行”后面要接动作性的宾语，不能接“状态”。"}, "sentence_index": 0, "correct_answer": "处于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他认真处于这件事。", "explanation": "这里应该用〈处理〉。“处于”表示所在的状态或位置，不能用来指对事情的处理。"}, {"text": "我们处于公园里散步。", "explanation": "这里应该用〈在〉：在公园里散步。“处于”只表示所处的状态或位置，不能与“散步”这类动作连用。"}, {"text": "工人处于矿石。", "explanation": "这里应该用〈挖掘〉。“处于”表示所在的状态或位置，不能用来指挖掘矿石。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "处于", "is_correct": true, "explanation": "正确：“比赛处于关键时刻”表示比赛正在关键阶段，符合句意。"}, {"text": "检查", "is_correct": false, "explanation": "语义：“检查”的对象是事物或工作，不能用于“关键时刻”。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”要接具体的商品，不能接“时刻”。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指使物体破裂，不能用于描述时间。"}], "explanations": {"处于": "正确：“比赛处于关键时刻”表示比赛正在关键阶段，符合句意。", "检查": "语义：“检查”的对象是事物或工作，不能用于“关键时刻”。", "购买": "配价：“购买”要接具体的商品，不能接“时刻”。", "打碎": "语义：“打碎”指使物体破裂，不能用于描述时间。"}, "sentence_index": 6, "correct_answer": "处于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈去超市处于蔬菜。", "explanation": "这里应该用〈购买〉。“处于”表示状态或位置，不能用来指买东西。"}, {"text": "他处于汽车去上班。", "explanation": "这里应该用〈乘坐〉：坐汽车去上班。“处于”表示所在的状态或位置，不能表示乘坐交通工具。"}, {"text": "大家热烈处于新同学。", "explanation": "这里应该用〈欢迎〉。“处于”表示状态或位置，不能用来表示对新同学的欢迎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市已经处于了大规模建设的阶段。", "corrected_sentence": "这座城市已经处于大规模建设的阶段。", "error_description": "错误：“处于”后面多加了“了”。“处于”表示所处的状态，不能与“了”连用。正确：“已经处于大规模建设的阶段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村子处于在山谷之中。", "corrected_sentence": "这个村子处于山谷之中。", "error_description": "错误：“处于”本身已经表示位置，后面不能再加“在”。正确：“处于山谷之中”，去掉多余的“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11211, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重度", "is_correct": true, "explanation": "重度与轻度相对，指程度深、严重，与句中程度浅的“轻度”构成反义。"}, {"text": "健康", "is_correct": false, "explanation": "健康指身体状况良好，与程度深浅无关，不与“轻度”构成反义。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮表示外貌好看，与“轻度”的程度义无关，不构成反义。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂指事物构成繁多、难以理清，与“轻度”的程度义不对应。"}], "correct_answer": "重度", "explanations": {"重度": "重度与轻度相对，指程度深、严重，与句中程度浅的“轻度”构成反义。", "健康": "健康指身体状况良好，与程度深浅无关，不与“轻度”构成反义。", "漂亮": "漂亮表示外貌好看，与“轻度”的程度义无关，不构成反义。", "复杂": "复杂指事物构成繁多、难以理清，与“轻度”的程度义不对应。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11211, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重度", "is_correct": true, "explanation": "重度与轻度相对，指程度深、严重，与句中程度浅的“轻度”构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、分明，与“轻度”的程度义无关，不构成反义。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速指速度快，与程度浅、不严重没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "宽敞指空间大，与病情或损伤的程度无关，不是反义词。"}], "correct_answer": "重度", "explanations": {"重度": "重度与轻度相对，指程度深、严重，与句中程度浅的“轻度”构成反义。", "清楚": "清楚指明白、分明，与“轻度”的程度义无关，不构成反义。", "迅速": "迅速指速度快，与程度浅、不严重没有反义关系。", "宽敞": "宽敞指空间大，与病情或损伤的程度无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11211, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指程度浅、不严重。", "primary_collocate": null, "pronunciation": "qīng dù", "ipa": "tɕʰiŋ˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "轻度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他得了轻度感冒，不用请假。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说这是轻度近视。", "target_word": "轻度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "轻度污染的天气里，可以出门散步。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的伤只是轻度擦伤，很快就好了。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人有轻度的听力问题。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "轻度失眠的人可以先试试多运动。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次地震只造成了轻度损坏。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最近有轻度焦虑，晚上睡不好。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "轻度烫伤时，先用冷水冲一冲。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "輕度", "label": "繁体"}], "register": "书面", "sense_fingerprint": "轻度|程度浅、不严重（多修饰病症、损害）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '949a9561-3731-44c1-9701-0782248bfe49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轻度", "is_correct": true, "explanation": "轻度：程度浅，修饰“认知疲劳状态”，表示疲劳较轻，与句中代谢只是减缓、温度只是轻微上升的描述一致。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“健康”指身体良好，与“疲劳状态”矛盾，“健康的认知疲劳状态”说不通。"}, {"text": "清醒", "is_correct": false, "explanation": "语义：“清醒”指头脑清楚，与“认知疲劳”的含义相反，不能修饰这一状态。"}, {"text": "充足", "is_correct": false, "explanation": "搭配：“充足”多修饰睡眠、营养等，不能修饰“认知疲劳状态”。"}], "explanations": {"轻度": "轻度：程度浅，修饰“认知疲劳状态”，表示疲劳较轻，与句中代谢只是减缓、温度只是轻微上升的描述一致。", "健康": "语义：“健康”指身体良好，与“疲劳状态”矛盾，“健康的认知疲劳状态”说不通。", "清醒": "语义：“清醒”指头脑清楚，与“认知疲劳”的含义相反，不能修饰这一状态。", "充足": "搭配：“充足”多修饰睡眠、营养等，不能修饰“认知疲劳状态”。"}, "sentence_index": 0, "correct_answer": "轻度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考完试以后，我终于有了一个轻度的周末。", "explanation": "这里应该用〈轻松〉。轻度指程度浅、不严重，不用来形容周末的状态；没有负担、身心放松要用轻松。"}, {"text": "她背着一个轻度的书包，走得很快。", "explanation": "这里应该用〈轻〉。轻度说程度浅、不严重，不能用来描述物体的重量；书包分量小要用轻。"}, {"text": "他轻度地关上了门，没有吵醒孩子。", "explanation": "这里应该用〈轻轻〉。轻度指程度浅，不用来形容动作的力道；动作轻柔、不出声要用轻轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻度", "is_correct": true, "explanation": "轻度：程度浅，修饰“失眠”，表示失眠不重，与“可以先试试多运动”的建议相合。"}, {"text": "美满", "is_correct": false, "explanation": "语义：“美满”表示圆满幸福，与“失眠”的状态矛盾，“美满失眠”说不通。"}, {"text": "饱满", "is_correct": false, "explanation": "搭配：“饱满”多用于精神、情绪、果实等，不能修饰“失眠”。"}, {"text": "充沛", "is_correct": false, "explanation": "搭配：“充沛”多修饰精力、体力，不能说“充沛的失眠”。"}], "explanations": {"轻度": "轻度：程度浅，修饰“失眠”，表示失眠不重，与“可以先试试多运动”的建议相合。", "美满": "语义：“美满”表示圆满幸福，与“失眠”的状态矛盾，“美满失眠”说不通。", "饱满": "搭配：“饱满”多用于精神、情绪、果实等，不能修饰“失眠”。", "充沛": "搭配：“充沛”多修饰精力、体力，不能说“充沛的失眠”。"}, "sentence_index": 6, "correct_answer": "轻度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一把轻度的椅子，搬起来很方便。", "explanation": "这里应该用〈轻巧〉。轻度指程度浅、不严重，不用来形容物体的重量和灵便；东西轻便好搬要用轻巧。"}, {"text": "她轻度地走进了房间。", "explanation": "这里应该用〈悄悄〉。轻度指程度浅，不用来形容走进房间的动作；无声无息地进门要用悄悄。"}, {"text": "他穿着一件轻度的外套，走在街上。", "explanation": "这里应该用〈轻薄〉。轻度指程度浅，不用来形容衣物的厚薄；衣服薄而轻要用轻薄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我只是一轻度疲劳，多休息就行。", "corrected_sentence": "我只是轻度疲劳，多休息就行。", "error_description": "错误：“轻度”前多出数词“一”，“一轻度疲劳”结构不通，应删去“一”。正确：“我只是轻度疲劳，多休息就行。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的手机屏幕有一轻度划痕，还能用。", "corrected_sentence": "我的手机屏幕有轻度划痕，还能用。", "error_description": "错误：“轻度”前多出数词“一”，“一轻度划痕”结构不通，应删去“一”。正确：“我的手机屏幕有轻度划痕，还能用。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
