INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生物体内新旧物质转化、替换的过程，包括物质合成与分解。", "primary_collocate": null, "pronunciation": "dài xiè", "ipa": "taɪ̯⁵¹ ɕjɛ⁵¹", "syllable_count": 2, "sentences": [{"text": "当个体亲历香蕉皮蜕变为沃土的完整周期，其对“废物”概念的认知边界将发生根本位移——废弃物不再是线性消费的终点，而是循环代谢的中介。", "target_word": "代谢", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "代谢", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "人老了以后，身体的代谢会变慢。", "target_word": "代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动可以让身体的代谢变快。", "target_word": "代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上睡觉时，人体的代谢速度比白天慢。", "target_word": "代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭以后，身体里的代谢会加快。", "target_word": "代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "代谢好的人，不容易变胖。", "target_word": "代谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "细胞通过代谢，把食物变成能量。", "target_word": "代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的代谢有问题，所以很容易发胖。", "target_word": "代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多喝水可以促进身体的代谢。", "target_word": "代谢", "complexity_tier": "T3", "furigana": "duō hē shuǐ kěyǐ cùjìn shēntǐ de dàixiè", "sentence_source": "generated"}], "morphological_forms": [{"form": "新陈代谢", "label": "复合"}, {"form": "代谢物", "label": "复合"}, {"form": "代謝", "label": "繁体"}], "register": "书面", "sense_fingerprint": "生物体内物质的合成、分解与更新过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c708da23-8b74-483b-bea2-78da0da78450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代谢", "is_correct": true, "explanation": "“代谢”指物质转化的过程，与“循环”“中介”搭配，符合句意。"}, {"text": "分子", "is_correct": false, "explanation": "语义：“分子”是具体的物质单位，不是转化过程，与“循环……的中介”不合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与“循环”及“中介”均不搭配，句意不通。"}, {"text": "周期", "is_correct": false, "explanation": "搭配：“循环周期”与“循环”重复，且“周期”不作“中介”的修饰语，搭配不当。"}], "explanations": {"代谢": "“代谢”指物质转化的过程，与“循环”“中介”搭配，符合句意。", "分子": "语义：“分子”是具体的物质单位，不是转化过程，与“循环……的中介”不合。", "颜色": "语义：“颜色”与“循环”及“中介”均不搭配，句意不通。", "周期": "搭配：“循环周期”与“循环”重复，且“周期”不作“中介”的修饰语，搭配不当。"}, "sentence_index": 0, "correct_answer": "代谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到好消息，他的心情发生了很大的代谢。", "explanation": "这里应该用〈变化〉。代谢指生物体内物质的合成与分解，不用于描述心情。"}, {"text": "这把椅子用了十年，代谢很严重。", "explanation": "这里应该用〈磨损〉。代谢是生物体内的物质转化过程，不能用于器物的损耗。"}, {"text": "他的英语代谢很好。", "explanation": "这里应该用〈成绩〉。代谢指生物体内的物质转化，不能用于语言能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代谢", "is_correct": true, "explanation": "“代谢好”指新陈代谢快，所以不容易变胖，符合句意。"}, {"text": "食欲", "is_correct": false, "explanation": "语义：食欲好的人往往吃得多，与“不容易变胖”的因果相反。"}, {"text": "表情", "is_correct": false, "explanation": "语义：表情与体重无关，句子说的是身体状况。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不说“好”，应说“轻”或“重”。"}], "explanations": {"代谢": "“代谢好”指新陈代谢快，所以不容易变胖，符合句意。", "食欲": "语义：食欲好的人往往吃得多，与“不容易变胖”的因果相反。", "表情": "语义：表情与体重无关，句子说的是身体状况。", "体重": "搭配：“体重”不说“好”，应说“轻”或“重”。"}, "sentence_index": 6, "correct_answer": "代谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这笔钱的代谢很慢，存在银行里一年没动过。", "explanation": "这里应该用〈流通〉。代谢指生物体内物质的合成与分解，不能用于资金的流动。"}, {"text": "这块面包放了两天，代谢得长满了毛。", "explanation": "这里应该用〈变质〉。代谢指生物体内物质的转化，用于食物坏掉是误用，应说变质。"}, {"text": "这个班级的代谢很快，学生每学期都要换一批。", "explanation": "这里应该用〈流动〉。代谢指生物体内的物质转化，不用于描述班级里人员的变动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "规律作息能让身体得代谢保持正常。", "corrected_sentence": "规律作息能让身体的代谢保持正常。", "error_description": "错误形式：“身体得代谢”。正确形式：“身体的代谢”。原因：“得”是补语标记，这里作定语应用结构助词“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药能加快身体得代谢。", "corrected_sentence": "这种药能加快身体的代谢。", "error_description": "错误形式：“身体得代谢”。正确形式：“身体的代谢”。原因：“代谢”是名词，“身体”作定语修饰它，要用结构助词“的”，不能用补语标记“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11213, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加剧", "is_correct": true, "explanation": "反义：“减缓”指程度降低，“加剧”指程度加重，二者相对。"}, {"text": "扩散", "is_correct": false, "explanation": "无反义关系：“扩散”指向四周散开，与程度或速度的变化无关。"}, {"text": "保持", "is_correct": false, "explanation": "无反义关系：“保持”指维持原状，不表示程度的降低，也不与“减缓”对立。"}, {"text": "维持", "is_correct": false, "explanation": "无反义关系：“维持”指使某种状态不变，与“减缓”不构成反义。"}], "correct_answer": "加剧", "explanations": {"加剧": "反义：“减缓”指程度降低，“加剧”指程度加重，二者相对。", "扩散": "无反义关系：“扩散”指向四周散开，与程度或速度的变化无关。", "保持": "无反义关系：“保持”指维持原状，不表示程度的降低，也不与“减缓”对立。", "维持": "无反义关系：“维持”指使某种状态不变，与“减缓”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11213, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加快", "is_correct": true, "explanation": "反义：“减缓”指速度降低，“加快”指速度提高，二者正好相反。"}, {"text": "停留", "is_correct": false, "explanation": "无反义关系：“停留”指停在某处，与速度的降低没有对立关系。"}, {"text": "增长", "is_correct": false, "explanation": "无反义关系：“增长”指数量或规模变大，不与速度的降低构成反义。"}, {"text": "分散", "is_correct": false, "explanation": "无反义关系：“分散”指散开或分开，与“减缓”的速度变化无关。"}], "correct_answer": "加快", "explanations": {"加快": "反义：“减缓”指速度降低，“加快”指速度提高，二者正好相反。", "停留": "无反义关系：“停留”指停在某处，与速度的降低没有对立关系。", "增长": "无反义关系：“增长”指数量或规模变大，不与速度的降低构成反义。", "分散": "无反义关系：“分散”指散开或分开，与“减缓”的速度变化无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11213, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指速度、程度等降低或变得缓慢。", "primary_collocate": null, "pronunciation": "jiǎn huǎn", "ipa": "tɕjɛn˨˩˦ xwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "减缓", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "下雨以后，路上的车速减缓了。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进入冬天，树木的生长速度慢慢减缓。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药以后，他的疼痛感减缓了很多。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济增长的速度今年明显减缓。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了山口，风势渐渐减缓了。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷，河水的流动也减缓了。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑了一个小时，他的脚步慢慢减缓。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口增长减缓，学校的学生也少了。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛快结束时，球员的速度明显减缓了。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减缓了", "label": "体标"}, {"form": "減緩", "label": "繁体"}], "register": "书面", "sense_fingerprint": "自身速度或程度下降、变慢（不及物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf62e1-d33e-46df-96e9-4a4484bc7d82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11213, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减缓", "is_correct": true, "explanation": "“代谢活动减缓”指代谢速度降低，与前文“轻度认知疲劳”的状态相符。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“轻度”只能使代谢减慢，不能说完全停止；且后文“局部温度可能轻微上升”需要代谢仍在进行。"}, {"text": "消失", "is_correct": false, "explanation": "语义：“消失”指完全不存在，与“轻度”疲劳只使代谢减慢的情形不符。"}, {"text": "恶化", "is_correct": false, "explanation": "搭配：“恶化”多用于病情、局势等状况，不用于说代谢活动的快慢。"}], "explanations": {"减缓": "“代谢活动减缓”指代谢速度降低，与前文“轻度认知疲劳”的状态相符。", "停止": "语义：“轻度”只能使代谢减慢，不能说完全停止；且后文“局部温度可能轻微上升”需要代谢仍在进行。", "消失": "语义：“消失”指完全不存在，与“轻度”疲劳只使代谢减慢的情形不符。", "恶化": "搭配：“恶化”多用于病情、局势等状况，不用于说代谢活动的快慢。"}, "sentence_index": 0, "correct_answer": "减缓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这半年减缓了十斤体重。", "explanation": "这里应该用〈减轻〉。减缓指速度或程度的下降，体重减少要用“减轻”。"}, {"text": "我们班减缓了三个同学。", "explanation": "这里应该用〈减少〉。减缓用于速度或程度，人数减少要用“减少”。"}, {"text": "我们把会议减缓了一个小时。", "explanation": "这里应该用〈推迟〉。减缓不用于日程或时间的延后，会议延后要用“推迟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11213, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减缓", "is_correct": true, "explanation": "“河水的流动也减缓了”与“天气变冷”的语境一致，指流速降低。"}, {"text": "加速", "is_correct": false, "explanation": "语义：天气变冷应使流动变慢，说“加速”与变冷的因果相反。"}, {"text": "增长", "is_correct": false, "explanation": "搭配：“增长”多用于数量、规模，不用于说河水流动的快慢。"}, {"text": "扩张", "is_correct": false, "explanation": "搭配：“扩张”用于范围、规模，不说“流动扩张”来表示速度。"}], "explanations": {"减缓": "“河水的流动也减缓了”与“天气变冷”的语境一致，指流速降低。", "加速": "语义：天气变冷应使流动变慢，说“加速”与变冷的因果相反。", "增长": "搭配：“增长”多用于数量、规模，不用于说河水流动的快慢。", "扩张": "搭配：“扩张”用于范围、规模，不说“流动扩张”来表示速度。"}, "sentence_index": 6, "correct_answer": "减缓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这份报告减缓成了一页。", "explanation": "这里应该用〈压缩〉。减缓指速度或程度的变化，篇幅缩减要用“压缩”。"}, {"text": "这次演出的票价减缓了不少。", "explanation": "这里应该用〈降低〉。减缓强调变化的速度，价格下降要用“降低”。"}, {"text": "妈妈减缓了孩子的零食，每天只让他吃一块。", "explanation": "这里应该用〈限制〉。减缓用于速度或程度，控制零食的数量要用“限制”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天黑以后，风势慢慢减缓着了。", "corrected_sentence": "天黑以后，风势慢慢减缓了。", "error_description": "体标错误：“着”和“了”不能同时用在“减缓”后。表示变化已经完成，应说“减缓了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汽车进入弯道以后，车速慢慢减缓的了。", "corrected_sentence": "汽车进入弯道以后，车速慢慢减缓了。", "error_description": "助词错误：“减缓”后多出“的了”，只需用“了”，应写作“车速慢慢减缓了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11215, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11215, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11215, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示程度不深，数量不多。", "primary_collocate": null, "pronunciation": "qīng wēi", "ipa": "tɕʰiŋ˥ weɪ˥", "syllable_count": 2, "sentences": [{"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "轻微", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今天下午气温轻微下降，天还是很热。", "target_word": "轻微", "complexity_tier": "T3", "furigana": "jīntiān xiàwǔ qìwēn qīngwēi xiàjiàng, tiān hái shì hěn rè.", "sentence_source": "generated"}, {"text": "地震时，房子轻微晃动了几下。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他紧张得手轻微地发抖。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的价格轻微下降，变化不大。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车子轻微震动着，我很快睡着了。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很小，树叶只是轻微摇动。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃药以后，他的体温轻微降低了。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船在水面上轻微地摇晃着。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音轻微颤抖，好像有点害怕。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "作状语，修饰动作或变化，表示幅度很小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '949a9561-3731-44c1-9701-0782248bfe49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11215, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轻微", "is_correct": true, "explanation": "轻微：形容词作状语，修饰“上升”，表示幅度小，与句中温度只是小幅变化的描述一致。"}, {"text": "彻底", "is_correct": false, "explanation": "搭配：“彻底”表示从根本上、完全地，多修饰“解决”“改变”，不能修饰温度的上升。"}, {"text": "完全", "is_correct": false, "explanation": "搭配：“完全”修饰程度，“完全上升”不是温度变化的常见说法，与句中描述不搭。"}, {"text": "绝对", "is_correct": false, "explanation": "语义：“绝对”表示确定无疑，与句中“可能”的推测语气矛盾。"}], "explanations": {"轻微": "轻微：形容词作状语，修饰“上升”，表示幅度小，与句中温度只是小幅变化的描述一致。", "彻底": "搭配：“彻底”表示从根本上、完全地，多修饰“解决”“改变”，不能修饰温度的上升。", "完全": "搭配：“完全”修饰程度，“完全上升”不是温度变化的常见说法，与句中描述不搭。", "绝对": "语义：“绝对”表示确定无疑，与句中“可能”的推测语气矛盾。"}, "sentence_index": 0, "correct_answer": "轻微"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他轻微地考了一百分，大家都很惊讶。", "explanation": "这里应该用〈优异〉。轻微表示程度不深、数量不多，不能用来形容成绩的高低；成绩很好要用优异。"}, {"text": "她轻微地生了一场大病，住了半个月的院。", "explanation": "这里应该用〈严重〉。轻微表示程度不深，与“大病”“住院”矛盾；描述病情重要用严重。"}, {"text": "我们轻微地吃了一顿丰盛的晚餐。", "explanation": "这里应该用〈痛快〉。轻微表示程度不深，不能用来形容尽兴吃喝的状态；吃得尽兴要用痛快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻微", "is_correct": true, "explanation": "轻微：形容词作状语，修饰“摇动”，表示幅度小，与“风很小”相合。"}, {"text": "猛烈", "is_correct": false, "explanation": "语义：“猛烈”表示力量大，与“风很小”和“只是”矛盾，树叶不会因此猛烈摇动。"}, {"text": "大幅", "is_correct": false, "explanation": "语义：“大幅”表示幅度很大，与“风很小”和“只是”的语境矛盾，树叶不会大幅摇动。"}, {"text": "急速", "is_correct": false, "explanation": "语义：“急速”表示速度快，与“只是”和“风很小”的语境相矛盾。"}], "explanations": {"轻微": "轻微：形容词作状语，修饰“摇动”，表示幅度小，与“风很小”相合。", "猛烈": "语义：“猛烈”表示力量大，与“风很小”和“只是”矛盾，树叶不会因此猛烈摇动。", "大幅": "语义：“大幅”表示幅度很大，与“风很小”和“只是”的语境矛盾，树叶不会大幅摇动。", "急速": "语义：“急速”表示速度快，与“只是”和“风很小”的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "轻微"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "远处传来轻微的灯光，照亮了一片田野。", "explanation": "这里应该用〈微弱〉。轻微表示程度不深、数量少，不用来形容光线的暗淡；光线暗弱要用微弱。"}, {"text": "这份工作做完以后，我的心情很轻微。", "explanation": "这里应该用〈轻松〉。轻微说的是程度不深，不能用来形容心情；心里没有负担要用轻松。"}, {"text": "现场有一种轻微的气氛，大家都很兴奋。", "explanation": "这里应该用〈热烈〉。轻微表示程度不深，不能用来形容现场的气氛；场面火热要用热烈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她轻微的摇了摇头，表示不同意。", "corrected_sentence": "她轻微地摇了摇头，表示不同意。", "error_description": "错误形式：“轻微的摇了摇头”。正确形式：“轻微地摇了摇头”。“轻微”修饰动词“摇”时是副词，要用“地”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他轻微得咳嗽了两声，没什么大事。", "corrected_sentence": "他轻微地咳嗽了两声，没什么大事。", "error_description": "错误形式：“轻微得咳嗽了两声”。正确形式：“轻微地咳嗽了两声”。“轻微”作状语修饰动词“咳嗽”时要用“地”，“得”不能用作状语标记。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
