INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11216, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（意味、情谊等）深远而长久，多用于“意味深长”。", "primary_collocate": null, "pronunciation": "shēn cháng", "ipa": "ʂən˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他说的话意味深长，大家听了都若有所思。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "两家的情谊深长，几十年从未断过。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "他说的这番话意义深长，我想了很久。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "这个故事寓意深长，值得大家读一读。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑了笑，说了一句意义深长的话。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "爷爷的教导意义深长，我一直记在心里。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "这部电影的结局意义深长，让人想了很久。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "他们的友谊深长，几十年都互相帮助。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "这首诗的情意深长，读后让人感动。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句老话意义深长，年轻人要多想想。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "形容意味、情谊深远而长久，常见于意味深长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '949a9561-3731-44c1-9701-0782248bfe49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11216, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深长", "is_correct": true, "explanation": "正确答案。深长指意味、情谊等深远而长久。"}, {"text": "生长", "is_correct": false, "explanation": "生长读 shēng zhǎng：shēng（后鼻音 -ng）与 shēn（前鼻音 -n）不同，zhǎng 与 cháng 也不同。意思是生物的发育长大。"}, {"text": "深重", "is_correct": false, "explanation": "深重读 shēn zhòng：zhòng 与 cháng 声母、韵母、声调都不同。意思是程度深、分量大（如灾难深重）。"}, {"text": "深沉", "is_correct": false, "explanation": "chén（-en）与 cháng（-ang）韵母不同，意思是深沉（感情、心思不外露）。"}], "explanations": {"深长": "正确答案。深长指意味、情谊等深远而长久。", "生长": "生长读 shēng zhǎng：shēng（后鼻音 -ng）与 shēn（前鼻音 -n）不同，zhǎng 与 cháng 也不同。意思是生物的发育长大。", "深重": "深重读 shēn zhòng：zhòng 与 cháng 声母、韵母、声调都不同。意思是程度深、分量大（如灾难深重）。", "深沉": "chén（-en）与 cháng（-ang）韵母不同，意思是深沉（感情、心思不外露）。"}, "sentence_index": null, "correct_answer": "深长"}, "level_3": {"options": [{"text": "深长", "is_correct": true, "explanation": "正确。意味深长指含意深远，与“大家听了都若有所思”相合。"}, {"text": "平淡", "is_correct": false, "explanation": "语义：意味平淡则不会引人深思，与“若有所思”矛盾。"}, {"text": "轻松", "is_correct": false, "explanation": "搭配：“轻松”不修饰“意味”，且与“若有所思”矛盾。"}, {"text": "短暂", "is_correct": false, "explanation": "搭配：“短暂”多修饰时间，不修饰“意味”。"}], "explanations": {"深长": "正确。意味深长指含意深远，与“大家听了都若有所思”相合。", "平淡": "语义：意味平淡则不会引人深思，与“若有所思”矛盾。", "轻松": "搭配：“轻松”不修饰“意味”，且与“若有所思”矛盾。", "短暂": "搭配：“短暂”多修饰时间，不修饰“意味”。"}, "sentence_index": 0, "correct_answer": "深长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次经历给我留下了深长的印象。", "explanation": "这里应该用〈深刻〉。深长多指意味、情谊，“印象”要用深刻。"}, {"text": "这项改革对教育的影响十分深长。", "explanation": "这里应该用〈深远〉。深长多指意味、情谊，“影响”一般用深远。"}, {"text": "我们要做深长的打算，不能只看眼前。", "explanation": "这里应该用〈长远〉。深长不用来形容打算或计划，“打算”要用长远。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深长", "is_correct": true, "explanation": "正确。意义深长指含意深远，与“让人想了很久”相符。"}, {"text": "简单", "is_correct": false, "explanation": "语义：意义简单，不需要想很久，与后文矛盾。"}, {"text": "短暂", "is_correct": false, "explanation": "搭配：“短暂”多修饰时间，不修饰“意义”。"}, {"text": "浅薄", "is_correct": false, "explanation": "语义：意义浅薄则无须想很久，与后文矛盾。"}], "explanations": {"深长": "正确。意义深长指含意深远，与“让人想了很久”相符。", "简单": "语义：意义简单，不需要想很久，与后文矛盾。", "短暂": "搭配：“短暂”多修饰时间，不修饰“意义”。", "浅薄": "语义：意义浅薄则无须想很久，与后文矛盾。"}, "sentence_index": 6, "correct_answer": "深长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的成绩进步得很深长。", "explanation": "这里应该用〈显著〉。深长指意味、情谊深远，不用来形容“进步”。"}, {"text": "他对这个问题的研究很深长。", "explanation": "这里应该用〈深入〉。深长多指意味、情谊，“研究”要用深入。"}, {"text": "两国的关系十分深长。", "explanation": "这里应该用〈密切〉。深长多指意味、情谊，“关系”一般用密切或深厚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人的话意味深长过，我记了很久。", "corrected_sentence": "老人的话意味深长，我记了很久。", "error_description": "错误：“深长过”，在形容词后加了“过”。正确：“意味深长”。“过”只能接在动词后表示经历，不能接形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师的一席话意义得深长，我至今记得。", "corrected_sentence": "老师的一席话意义深长，我至今记得。", "error_description": "错误：“意义得深长”，多加了“得”。正确：“意义深长”。“得”只接在动词后引出补语，“意义”后直接接形容词作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
