INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11217, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指水或其他液体从一个地方流过另一个地方。", "primary_collocate": null, "pronunciation": "liú jīng", "ipa": "ljoʊ˧˥ tɕiŋ˥˥", "syllable_count": 2, "sentences": [{"text": "为了让电子设备保持稳定，工程师设计了一条冷却管路，使低温冷却液在水泵的推动下持续流经发热的芯片，再把热量带到散热器上。", "target_word": "流经", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "有时候，一条干净的河，流经工业区后就变得又黑又臭。", "target_word": "流经", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "长江流经很多大城市。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄河流经九个省份。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小河流经我们学校门口。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血液流经心脏，再流向全身。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水流经村子以后，流进大海。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自来水流经长长的管子，才到我家。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热水流经暖气管，房间就暖和了。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水从山坡流经果园，汇入了小溪。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流经了", "label": "体标"}, {"form": "流經", "label": "繁体"}], "register": "书面", "sense_fingerprint": "水或液体从一处流过另一处（经过某地）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf62e1-d33e-46df-96e9-4a4484bc7d82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流经", "is_correct": true, "explanation": "正确：“流经”指液体从某处穿过，与冷却液在管路中持续经过芯片的语境一致。"}, {"text": "堆积", "is_correct": false, "explanation": "语义：“堆积”指积聚不动，与冷却液持续流动带走热量的设计相反。"}, {"text": "停留", "is_correct": false, "explanation": "语法与语义：“停留”是不及物动词，不能直接带“发热的芯片”作宾语，且与冷却液必须持续流动的目的矛盾。"}, {"text": "聚集", "is_correct": false, "explanation": "搭配：“聚集”多用于人或物聚在一处，不用于描述液体在管路中经过芯片。"}], "explanations": {"流经": "正确：“流经”指液体从某处穿过，与冷却液在管路中持续经过芯片的语境一致。", "堆积": "语义：“堆积”指积聚不动，与冷却液持续流动带走热量的设计相反。", "停留": "语法与语义：“停留”是不及物动词，不能直接带“发热的芯片”作宾语，且与冷却液必须持续流动的目的矛盾。", "聚集": "搭配：“聚集”多用于人或物聚在一处，不用于描述液体在管路中经过芯片。"}, "sentence_index": 0, "correct_answer": "流经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天流经北京去上海。", "explanation": "这里应该用〈路过〉。流经只用于水或其他液体，人路过某地要用“路过”。"}, {"text": "小路流经树林，通向山顶。", "explanation": "这里应该用〈穿过〉。流经指液体从某地流过，小路穿越树林要用“穿过”。"}, {"text": "他流经了很多困难。", "explanation": "这里应该用〈经历〉。流经只用于液体，抽象的困难不能流经。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流经", "is_correct": true, "explanation": "“河水流经村子”指河水从村子中穿过，与后文“流进大海”连贯。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”的对象是田地、庄稼，不说浇灌村子。"}, {"text": "喷射", "is_correct": false, "explanation": "搭配：“喷射”指液体向外猛烈射出，不能用来表示河水平稳地经过村子。"}, {"text": "灌溉", "is_correct": false, "explanation": "搭配：“灌溉”用于给田地供水，不用于村子。"}], "explanations": {"流经": "“河水流经村子”指河水从村子中穿过，与后文“流进大海”连贯。", "浇灌": "搭配：“浇灌”的对象是田地、庄稼，不说浇灌村子。", "喷射": "搭配：“喷射”指液体向外猛烈射出，不能用来表示河水平稳地经过村子。", "灌溉": "搭配：“灌溉”用于给田地供水，不用于村子。"}, "sentence_index": 6, "correct_answer": "流经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一路流经了好几个城市。", "explanation": "这里应该用〈经过〉。流经只用于水或其他液体，人一路经过城市要用“经过”。"}, {"text": "这辆公共汽车每天流经我家门口。", "explanation": "这里应该用〈经过〉。流经只用于水或其他液体，车辆从某地经过要用“经过”。"}, {"text": "这座大楼流经了广场。", "explanation": "这里应该用〈位于〉。流经指液体从某处流过，大楼不能流经，表示位置要用“位于”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水被流经那片竹林，最后流进小溪。", "corrected_sentence": "雨水流经那片竹林，最后流进小溪。", "error_description": "被字句错误：“流经”前不能加“被”。表示水从某地流过，应说“雨水流经那片竹林”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山里的泉水流经在石缝，慢慢流到山下。", "corrected_sentence": "山里的泉水流经石缝，慢慢流到山下。", "error_description": "介词错误：“流经”后面直接带处所宾语，不能再加“在”。应写作“流经石缝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
