INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11218, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11218, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鼻腔是呼吸道的起始部分，位于鼻子内部，具有过滤、加温和湿润空气的功能。", "primary_collocate": null, "pronunciation": "bí qiāng", "ipa": "pi˧˥ tɕʰjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "鼻腔", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "空气先进入鼻腔，再进入喉咙。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感冒时，我的鼻腔很不舒服。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用小灯检查了他的鼻腔。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鼻腔里的毛可以挡住灰尘。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷空气进入鼻腔后会变暖。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花粉进入鼻腔，他开始打喷嚏。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鼻腔发炎时，呼吸会很难受。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用盐水清洗了鼻腔。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鼻腔里有一层湿润的黏膜。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人体呼吸道起始部分，鼻子内部的空腔", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '949a9561-3731-44c1-9701-0782248bfe49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鼻腔", "is_correct": true, "explanation": "正确。鼻腔是空气进入呼吸道的通道，与口腔并列，符合“空气流经”。"}, {"text": "胃", "is_correct": false, "explanation": "语义：空气不经过胃，与“空气流经……与口腔”的呼吸通道不符。"}, {"text": "血管", "is_correct": false, "explanation": "搭配：“流经”与“空气”搭配指呼吸通道，“血管”一般与“血液”搭配。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：耳朵不是空气通向身体的通道，与“口腔”并列也不合。"}], "explanations": {"鼻腔": "正确。鼻腔是空气进入呼吸道的通道，与口腔并列，符合“空气流经”。", "胃": "语义：空气不经过胃，与“空气流经……与口腔”的呼吸通道不符。", "血管": "搭配：“流经”与“空气”搭配指呼吸通道，“血管”一般与“血液”搭配。", "耳朵": "语义：耳朵不是空气通向身体的通道，与“口腔”并列也不合。"}, "sentence_index": 0, "correct_answer": "鼻腔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的鼻腔长得很像爸爸。", "explanation": "这里应该用〈鼻子〉。鼻腔在鼻子内部，看不见，描述相貌要用“鼻子”。"}, {"text": "他的鼻腔上长了一颗痣。", "explanation": "这里应该用〈鼻尖〉。痣长在外露的皮肤上，鼻腔在内部，不能长痣。"}, {"text": "他的鼻腔上架着一副眼镜。", "explanation": "这里应该用〈鼻梁〉。眼镜架在外露的鼻梁上，鼻腔是内部空腔，不能架眼镜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鼻腔", "is_correct": true, "explanation": "正确。花粉进入鼻腔后引起打喷嚏，符合句意。"}, {"text": "膝盖", "is_correct": false, "explanation": "语义：花粉不会进入膝盖，也不会引起打喷嚏。"}, {"text": "手指", "is_correct": false, "explanation": "语义：花粉进入手指不会引起打喷嚏。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：花粉多说“落在”或“沾在”鞋子上，不说“进入”鞋子。"}], "explanations": {"鼻腔": "正确。花粉进入鼻腔后引起打喷嚏，符合句意。", "膝盖": "语义：花粉不会进入膝盖，也不会引起打喷嚏。", "手指": "语义：花粉进入手指不会引起打喷嚏。", "鞋子": "搭配：花粉多说“落在”或“沾在”鞋子上，不说“进入”鞋子。"}, "sentence_index": 6, "correct_answer": "鼻腔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生检查了他的一条鼻腔。", "explanation": "这里不能用〈条〉。条用于河流、道路等长条形事物，鼻腔应用“个”或“侧”。"}, {"text": "他的一块鼻腔被堵住了。", "explanation": "这里不能用〈块〉。块用于块状的东西，鼻腔应用“个”或“侧”。"}, {"text": "他的一根鼻腔不通气。", "explanation": "这里不能用〈根〉。根用于细长的东西（如鼻毛），鼻腔应用“个”或“侧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冷空气在鼻腔进入肺部。", "corrected_sentence": "冷空气从鼻腔进入肺部。", "error_description": "错误：“在鼻腔进入肺部”，介词用错。表示气流经由鼻腔这一通道进入，要用“从”。正确：“从鼻腔进入肺部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "感冒时，我把鼻腔很难受。", "corrected_sentence": "感冒时，我的鼻腔很难受。", "error_description": "错误：“把”字句中“把”后的名词之后必须接动词，此处直接接形容词短语“很难受”。正确：“感冒时，我的鼻腔很难受。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
