INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11219, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指嘴的内部空腔，包含牙齿、舌头、颊黏膜等结构，是消化道的起始部分。", "primary_collocate": null, "pronunciation": "kǒu qiāng", "ipa": "kʰoʊ̯˨˩ t͡ɕʰjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "口腔", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "口腔里有牙齿、舌头和黏膜。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用小灯检查他的口腔。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "口腔是消化道的起点，食物先从这里进入。", "target_word": "口腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟会伤害口腔，也会伤害肺。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的口腔里长了一个溃疡，吃饭很疼。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "唾液由口腔中的腺体分泌，帮助消化食物。", "target_word": "口腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查时，医生需要观察患者的口腔状况。", "target_word": "口腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "口腔健康和全身健康有密切关系。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牙科医生先清洁口腔，再补牙。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "口腔溃疡", "label": "复合"}, {"form": "口腔科", "label": "复合"}], "register": "书面", "sense_fingerprint": "口腔：嘴的内部空腔，含牙齿、舌头、黏膜，消化道起点（解剖学义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c91e02e-2f48-4be3-84f2-455e61d61713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11219, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口腔", "is_correct": true, "explanation": "正确。句中“鼻腔与口腔”并列，口腔指嘴的内部空腔，空气可以经鼻腔和口腔流入。"}, {"text": "血管", "is_correct": false, "explanation": "语义：空气流经的是呼吸通道，不流经血管，“流经血管”与句意不符。"}, {"text": "大脑", "is_correct": false, "explanation": "语义：空气不会流经大脑，且“大脑”已在句中出现，与“流经”搭配不通。"}, {"text": "鼻腔", "is_correct": false, "explanation": "搭配：“鼻腔与鼻腔”重复，鼻腔已作为前一项出现，不能再与它并列。"}], "explanations": {"口腔": "正确。句中“鼻腔与口腔”并列，口腔指嘴的内部空腔，空气可以经鼻腔和口腔流入。", "血管": "语义：空气流经的是呼吸通道，不流经血管，“流经血管”与句意不符。", "大脑": "语义：空气不会流经大脑，且“大脑”已在句中出现，与“流经”搭配不通。", "鼻腔": "搭配：“鼻腔与鼻腔”重复，鼻腔已作为前一项出现，不能再与它并列。"}, "sentence_index": 0, "correct_answer": "口腔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他咧开口腔笑了。", "explanation": "这里应该用〈嘴〉。咧嘴指嘴的外部动作，口腔是嘴里面的空腔，看不见也咧不开。"}, {"text": "感冒以后，他的口腔哑了，说话很费力。", "explanation": "这里应该用〈嗓子〉。“哑”形容声音，应说“嗓子哑了”，口腔本身不会哑。"}, {"text": "他的口腔很硬，不肯让步。", "explanation": "这里应该用〈口气〉。口腔是嘴里的空腔，说话的语气硬要用“口气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口腔", "is_correct": true, "explanation": "正确。唾液腺位于口腔中，“口腔中的腺体”指的正是口腔。"}, {"text": "胃", "is_correct": false, "explanation": "语义：唾液不由胃分泌，胃的腺体分泌胃液，与“唾液”不符。"}, {"text": "食道", "is_correct": false, "explanation": "语义：唾液不来自食道，食道是输送食物的管道，不分泌唾液。"}, {"text": "肝脏", "is_correct": false, "explanation": "语义：肝脏分泌胆汁，不分泌唾液，与句中“唾液”冲突。"}], "explanations": {"口腔": "正确。唾液腺位于口腔中，“口腔中的腺体”指的正是口腔。", "胃": "语义：唾液不由胃分泌，胃的腺体分泌胃液，与“唾液”不符。", "食道": "语义：唾液不来自食道，食道是输送食物的管道，不分泌唾液。", "肝脏": "语义：肝脏分泌胆汁，不分泌唾液，与句中“唾液”冲突。"}, "sentence_index": 6, "correct_answer": "口腔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "牙医先拔掉他的口腔，再补牙。", "explanation": "这里应该用〈牙齿〉。“拔”用于可以脱落或去掉的牙齿，口腔是整个空腔，不能拔。"}, {"text": "他伸出口腔，让医生检查。", "explanation": "这里应该用〈舌头〉。伸出的是舌头，口腔是空腔，不能伸出。"}, {"text": "他的口腔很灵，听见了门响。", "explanation": "这里应该用〈耳朵〉。“灵”用于耳朵等感觉器官，口腔是嘴里的空腔，不能听见声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士用棉签仔细清理了他的一颗口腔。", "corrected_sentence": "护士用棉签仔细清理了他的口腔。", "error_description": "错误：“他的一颗口腔”。正确：去掉量词“一颗”，应说“他的口腔”。“颗”用于圆小的东西，口腔不用“颗”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生让他张大口腔，说“啊”。", "corrected_sentence": "医生让他张大嘴，说“啊”。", "error_description": "错误：“张大口腔”。正确：应说“张大嘴”。“张大”的对象是嘴这个外部器官，口腔是嘴里面的空腔，不能“张大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11222, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加热", "is_correct": true, "explanation": "反义：加热使物体温度升高，与“使物体温度降低”的冷却相对。"}, {"text": "清洗", "is_correct": false, "explanation": "无关：清洗指去除污物，与温度变化无关。"}, {"text": "研究", "is_correct": false, "explanation": "无关：研究指探究事物，与温度无关。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：搬运指移动物体，与温度无关。"}], "correct_answer": "加热", "explanations": {"加热": "反义：加热使物体温度升高，与“使物体温度降低”的冷却相对。", "清洗": "无关：清洗指去除污物，与温度变化无关。", "研究": "无关：研究指探究事物，与温度无关。", "搬运": "无关：搬运指移动物体，与温度无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11222, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加热", "is_correct": true, "explanation": "反义：加热使物体温度升高，与“使物体温度降低”相对。"}, {"text": "翻译", "is_correct": false, "explanation": "无关：翻译指转换语言，与温度无关。"}, {"text": "修理", "is_correct": false, "explanation": "无关：修理指修复损坏的东西，与温度无关。"}, {"text": "装饰", "is_correct": false, "explanation": "无关：装饰指美化物体，与温度无关。"}], "correct_answer": "加热", "explanations": {"加热": "反义：加热使物体温度升高，与“使物体温度降低”相对。", "翻译": "无关：翻译指转换语言，与温度无关。", "修理": "无关：修理指修复损坏的东西，与温度无关。", "装饰": "无关：装饰指美化物体，与温度无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11222, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使物体的温度降低。", "primary_collocate": null, "pronunciation": "lěng què", "ipa": "ləŋ˨˩ t͡ɕʰɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "冷却", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他用扇子冷却热汤。", "target_word": "冷却", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风扇可以冷却机器里的热空气。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先把热粥冷却一下，再给孩子喝。", "target_word": "冷却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发动机需要用水来冷却。", "target_word": "冷却", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂用冷水冷却刚出炉的钢。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空调冷却了房间里的空气。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑里的小风扇负责冷却芯片。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把热牛奶倒进杯子，用冰块冷却它。", "target_word": "冷却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验员用液氮冷却金属样品。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷却了", "label": "体标"}, {"form": "冷却过", "label": "体标"}, {"form": "冷却水", "label": "复合"}, {"form": "冷却剂", "label": "复合"}, {"form": "冷卻", "label": "繁体"}], "register": "书面", "sense_fingerprint": "冷却：（及物）用某种方式使物体温度降低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c91e02e-2f48-4be3-84f2-455e61d61713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷却", "is_correct": true, "explanation": "正确。“有效冷却进入脑部的血液”指使血液降温，与句意一致。"}, {"text": "加热", "is_correct": false, "explanation": "语义：加热使温度升高，与句中为了调控热量而降温的目的相反。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：煮沸是把液体烧开，血液不能煮沸，与句意冲突。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：“冻结血液”会使血液凝固，与“热调控”不符，也不是降温的常见说法。"}], "explanations": {"冷却": "正确。“有效冷却进入脑部的血液”指使血液降温，与句意一致。", "加热": "语义：加热使温度升高，与句中为了调控热量而降温的目的相反。", "煮沸": "语义：煮沸是把液体烧开，血液不能煮沸，与句意冲突。", "冻结": "搭配：“冻结血液”会使血液凝固，与“热调控”不符，也不是降温的常见说法。"}, "sentence_index": 0, "correct_answer": "冷却"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试，他的成绩冷却了不少。", "explanation": "这里应该用〈下降〉。“冷却”指使物体温度降低，成绩变差要说“成绩下降”。"}, {"text": "这段路的距离冷却了。", "explanation": "这里应该用〈缩短〉。“冷却”指温度下降，距离变短要用“缩短”。"}, {"text": "他冷却了脚步，慢慢地走进了教室。", "explanation": "这里应该用〈放慢〉。“冷却”指物体温度下降，脚步不能冷却，应说“放慢脚步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷却", "is_correct": true, "explanation": "正确。空调使房间里的空气降温，与句意一致。"}, {"text": "研究", "is_correct": false, "explanation": "语义：空调不会研究空气，与句意冲突。"}, {"text": "发酵", "is_correct": false, "explanation": "语义：发酵需要微生物作用，空调不会让空气发酵。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：空调不搬运空气，“搬运房间里的空气”说不通。"}], "explanations": {"冷却": "正确。空调使房间里的空气降温，与句意一致。", "研究": "语义：空调不会研究空气，与句意冲突。", "发酵": "语义：发酵需要微生物作用，空调不会让空气发酵。", "搬运": "搭配：空调不搬运空气，“搬运房间里的空气”说不通。"}, "sentence_index": 6, "correct_answer": "冷却"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这段录音的声音冷却了一些。", "explanation": "这里应该用〈调低〉。“冷却”指物体温度下降，声音的大小要说“调低”。"}, {"text": "他冷却了作业，两个小时才写完。", "explanation": "这里应该用〈做〉。“冷却”指物体温度下降，作业要说“做作业”。"}, {"text": "他的呼吸冷却了，很快就平静下来。", "explanation": "这里应该用〈平复〉。“冷却”指物体温度下降，呼吸恢复平稳要说“平复”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用冷水把鸡蛋冷却了过。", "corrected_sentence": "他用冷水把鸡蛋冷却了。", "error_description": "错误：“冷却了过”。正确：应说“冷却了”，“了”和“过”不能同时用在同一个动词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人用冷风把刚焊好的钢板冷却的很快。", "corrected_sentence": "工人用冷风把刚焊好的钢板冷却得很快。", "error_description": "错误：“冷却的很快”。正确：应说“冷却得很快”，表示程度的补语要用“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
