INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11223, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11223, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指人或动物头部包含大脑、小脑等神经中枢的区域。", "primary_collocate": null, "pronunciation": "nǎo bù", "ipa": "nɑʊ̯˨˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "脑部", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医生用机器检查他的脑部。", "target_word": "脑部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "脑部受伤的人可能会忘记事情。", "target_word": "脑部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片显示他的脑部没有问题。", "target_word": "脑部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "脑部手术需要很长时间，医生非常小心。", "target_word": "脑部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车一定要戴头盔，保护脑部。", "target_word": "脑部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的脑部有一个小肿瘤，需要治疗。", "target_word": "脑部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡觉时，脑部的血流会发生变化。", "target_word": "脑部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位科学家正在研究老年人的脑部。", "target_word": "脑部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的脑部在三岁以前发育得很快。", "target_word": "脑部", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "脑部手术", "label": "复合"}, {"form": "脑部损伤", "label": "复合"}, {"form": "腦部", "label": "繁体"}], "register": "书面", "sense_fingerprint": "脑部：人或动物头部含大脑、小脑等神经中枢的区域（医学解剖义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c91e02e-2f48-4be3-84f2-455e61d61713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11223, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰块", "is_correct": false, "explanation": "语义：血液不会流进冰块，冰块是固态的水，不是人体组织，句中讲的是人体的热调控。"}, {"text": "脑部", "is_correct": true, "explanation": "正确：脑部是头里大脑、小脑等神经中枢所在的区域，血液可以流入，与句中的下丘脑、关键区域相合。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“进入”后接的应是身体的器官或血管，空气不能接收血液。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是家具，不属于人体，血液不会流进课桌。"}], "explanations": {"冰块": "语义：血液不会流进冰块，冰块是固态的水，不是人体组织，句中讲的是人体的热调控。", "脑部": "正确：脑部是头里大脑、小脑等神经中枢所在的区域，血液可以流入，与句中的下丘脑、关键区域相合。", "空气": "搭配：“进入”后接的应是身体的器官或血管，空气不能接收血液。", "课桌": "语义：课桌是家具，不属于人体，血液不会流进课桌。"}, "sentence_index": 0, "correct_answer": "脑部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脑部很灵活，学什么都快。", "explanation": "这里应该用〈脑子〉。脑部是医学书面词，指头里神经中枢所在的区域；形容人思维灵活，口语里用“脑子”。"}, {"text": "这位科学家发明了脑部。", "explanation": "语义：“发明”的对象是人造的东西或方法，脑部是人体器官，不能被发明。"}, {"text": "医生检查了一只脑部，结果很正常。", "explanation": "量词：〈只〉用于动物，或成对器官中的一个；脑部不能用“只”计量，这里应直接说“检查脑部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11223, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不是身体的器官，不会长出肿瘤。"}, {"text": "脑部", "is_correct": true, "explanation": "正确：脑部是人体器官，可以长肿瘤，与“需要治疗”的语境相合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述的是身体的外形，不是可以长肿瘤的器官。"}, {"text": "态度", "is_correct": false, "explanation": "搭配：“态度”是抽象的心理状态，不能说“有一个小肿瘤”。"}], "explanations": {"天空": "语义：天空不是身体的器官，不会长出肿瘤。", "脑部": "正确：脑部是人体器官，可以长肿瘤，与“需要治疗”的语境相合。", "身材": "体貌：身材描述的是身体的外形，不是可以长肿瘤的器官。", "态度": "搭配：“态度”是抽象的心理状态，不能说“有一个小肿瘤”。"}, "sentence_index": 6, "correct_answer": "脑部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脑部很清醒，考试没有出错。", "explanation": "这里应该用〈头脑〉。脑部是医学用语，指头里神经中枢所在的区域；形容人思维清楚，口语用“头脑”。"}, {"text": "妈妈去超市买了一些脑部。", "explanation": "语义：脑部是人体器官，不是超市里出售的商品，这里不能说“买”。"}, {"text": "他用脑部弹钢琴。", "explanation": "语义：弹钢琴要靠手指，脑部不能充当演奏的工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生检查了他的脑部们。", "corrected_sentence": "医生检查了他的脑部。", "error_description": "错误形式“脑部们”，正确形式“脑部”。“们”只附在指人的名词或代词后面表示复数，脑部是器官名称，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告说明他的一份脑部正常。", "corrected_sentence": "这份报告说明他的脑部正常。", "error_description": "错误形式“一份脑部”，正确形式“脑部”。“份”用于报告、饭菜等，不用来计量人体器官，这里直接说“他的脑部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
