INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11224, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "血液是在心脏和血管中循环流动的红色液体，负责运输氧气、营养物质，并帮助排除废物、调节体温和防御疾病。", "primary_collocate": null, "pronunciation": "xuè yè", "ipa": "ɕɥɛ˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "血液", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "心脏推动血液流向全身。", "target_word": "血液", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "红细胞在血液里运送氧气。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生抽取了一些血液做检查。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "献血时，血液会流进专用的血袋里。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白细胞是血液中防御疾病的细胞。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动以后，血液流动得更快，身体也会变热。", "target_word": "血液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贫血的人，血液里缺少红细胞。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "血液在血管里循环流动，不会停下来。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "护士正在检查他的血液里有没有细菌。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一滴血液", "label": "量词"}], "register": "书面", "sense_fingerprint": "血液|心脏血管中循环流动的红色液体，运输氧气营养、排除废物、防御疾病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c91e02e-2f48-4be3-84f2-455e61d61713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽油", "is_correct": false, "explanation": "语义：汽油不是人体内循环的液体，不能进入脑部的血管。"}, {"text": "血液", "is_correct": true, "explanation": "正确：血液在血管中循环，能够流入脑部，与句中的冷却、热调控语境相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是固体，不会流进脑部，句中讲的是流动的液体。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：“进入脑部的”后应接在体内循环的液体，颜料不能这样搭配。"}], "explanations": {"汽油": "语义：汽油不是人体内循环的液体，不能进入脑部的血管。", "血液": "正确：血液在血管中循环，能够流入脑部，与句中的冷却、热调控语境相合。", "石头": "语义：石头是固体，不会流进脑部，句中讲的是流动的液体。", "颜料": "搭配：“进入脑部的”后应接在体内循环的液体，颜料不能这样搭配。"}, "sentence_index": 0, "correct_answer": "血液"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的伤口还在流血液。", "explanation": "这里应该用〈血〉。“流血”是固定说法，“血液”是书面的整体概念，不说“流血液”。"}, {"text": "医生抽了一条血液做检查。", "explanation": "量词：〈条〉用于细长的东西，血液是液体，应说“一管血液”或“一些血液”。"}, {"text": "他每天喝一杯血液补身体。", "explanation": "语义：血液在血管里循环，不是可以喝的饮品，“喝”与血液搭配错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河水", "is_correct": false, "explanation": "语义：河水流动与运动后身体变热无关，而且不是人体内的液体。"}, {"text": "血液", "is_correct": true, "explanation": "正确：血液在运动时流动加快，身体也随之变热，与句意相合。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口不能“流动得更快”而使身体变热，句意不通。"}, {"text": "公路", "is_correct": false, "explanation": "搭配：“流动”多用于液体、人群、资金，不说“公路流动”。"}], "explanations": {"河水": "语义：河水流动与运动后身体变热无关，而且不是人体内的液体。", "血液": "正确：血液在运动时流动加快，身体也随之变热，与句意相合。", "人口": "语义：人口不能“流动得更快”而使身体变热，句意不通。", "公路": "搭配：“流动”多用于液体、人群、资金，不说“公路流动”。"}, "sentence_index": 6, "correct_answer": "血液"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的血液很快就愈合了。", "explanation": "这里应该用〈伤口〉。“愈合”说的是伤口或皮肤，血液是液体，不会愈合。"}, {"text": "这家餐厅的招牌菜是血液。", "explanation": "语义：血液是人体里的液体，不是可以上桌的菜品，“招牌菜”与血液不搭。"}, {"text": "护士一个一个地数着他的血液。", "explanation": "语义：血液是液体，不能逐个计数，“一个一个地数”与血液搭配错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士给他抽了一个血液做检查。", "corrected_sentence": "护士给他抽了一管血液做检查。", "error_description": "错误形式“一个血液”，正确形式“一管血液”。血液是液体，计量要用“管”“滴”等容器或份量词，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "护士抽了他的血液们去化验。", "corrected_sentence": "护士抽了他的血液去化验。", "error_description": "错误形式“血液们”，正确形式“血液”。“们”只附在指人的名词或代词后面，血液是物质名词，不能加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "下丘脑是大脑的一部分，负责调节体温、饥饿、口渴、情绪和激素分泌等基本生理功能。", "primary_collocate": null, "pronunciation": "xià qiū nǎo", "ipa": "ɕja˥˩ tɕʰjoʊ˥ naʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "下丘脑", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "下丘脑位于大脑的底部。", "target_word": "下丘脑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下丘脑能调节体温，让身体不太冷也不太热。", "target_word": "下丘脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肚子饿了的感觉来自下丘脑。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下丘脑出了问题，人可能会一直很口渴。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下丘脑还能控制身体分泌激素。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生检查他的下丘脑有没有问题。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下丘脑很小，但它的作用很大。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人什么时候想睡觉，也和下丘脑有关。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "情绪紧张时，下丘脑会让心跳变快。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "下丘腦", "label": "繁体"}], "register": "书面", "sense_fingerprint": "下丘脑|大脑的一部分，调节体温、饥渴、情绪和激素分泌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c91e02e-2f48-4be3-84f2-455e61d61713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哈欠", "is_correct": false, "explanation": "语义：哈欠是一种动作，不是可以进行热调控的区域，与“关键区域”不符。"}, {"text": "下丘脑", "is_correct": true, "explanation": "正确：下丘脑是调节体温的脑区，与前文“热调控”的语境相合。"}, {"text": "激素", "is_correct": false, "explanation": "语义：激素是化学物质，不是区域，“对激素等关键区域的热调控”说不通。"}, {"text": "血液", "is_correct": false, "explanation": "语义：血液是体液，不是区域，不能说“血液等关键区域”。"}], "explanations": {"哈欠": "语义：哈欠是一种动作，不是可以进行热调控的区域，与“关键区域”不符。", "下丘脑": "正确：下丘脑是调节体温的脑区，与前文“热调控”的语境相合。", "激素": "语义：激素是化学物质，不是区域，“对激素等关键区域的热调控”说不通。", "血液": "语义：血液是体液，不是区域，不能说“血液等关键区域”。"}, "sentence_index": 0, "correct_answer": "下丘脑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下丘脑由左右两个半球组成。", "explanation": "这里应该用〈大脑〉。左右两个半球指的是整个大脑；下丘脑只是大脑底部的一个小区域，不能这样说。"}, {"text": "下丘脑负责传递感觉信息。", "explanation": "这里应该用〈丘脑〉。传递感觉信息是丘脑的功能；下丘脑主要负责调节体温和饥饿。"}, {"text": "下丘脑分泌生长激素。", "explanation": "这里应该用〈脑垂体〉。生长激素由脑垂体分泌；下丘脑是释放激素来调控脑垂体，本身不分泌生长激素。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：医生检查的是身体，“天气”不是可以检查有没有问题的对象。"}, {"text": "下丘脑", "is_correct": true, "explanation": "正确：“他的下丘脑”指人体器官，与“医生检查”的语境相合。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“他的声音有没有问题”与“医生检查”人体内部器官的语境不符，且声音不是身体部位。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“检查”与医生搭配的对象是人体，“汽车”不能与之搭配。"}], "explanations": {"天气": "语义：医生检查的是身体，“天气”不是可以检查有没有问题的对象。", "下丘脑": "正确：“他的下丘脑”指人体器官，与“医生检查”的语境相合。", "声音": "语义：“他的声音有没有问题”与“医生检查”人体内部器官的语境不符，且声音不是身体部位。", "汽车": "搭配：“检查”与医生搭配的对象是人体，“汽车”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "下丘脑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体检报告显示，他的一只下丘脑有些异常。", "explanation": "这里应该用〈个〉。下丘脑是不成对的器官，“只”多用于动物或成对的器官。"}, {"text": "医生在图上指着一条下丘脑说明位置。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，下丘脑是块状结构，不能用“条”。"}, {"text": "老师在图上标出了一幅下丘脑的位置。", "explanation": "这里应该用〈个〉。“幅”用于画或图，下丘脑是器官，不能这样计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人的下丘脑们都位于大脑底部。", "corrected_sentence": "人的下丘脑都位于大脑底部。", "error_description": "错误形式“下丘脑们”，正确形式“下丘脑”。“们”只用于指人的名词，下丘脑是器官，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生在图上指出了这只下丘脑的位置。", "corrected_sentence": "医生在图上指出了这个下丘脑的位置。", "error_description": "错误形式“这只下丘脑”，正确形式“这个下丘脑”。下丘脑是不成对的器官，量词应用“个”，“只”多用于动物或成对的器官。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
