INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11227, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一定范围内的空间或地方。", "primary_collocate": null, "pronunciation": "qū yù", "ipa": "tɕʰy˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "这个区域不能停车。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住的区域很安静。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家不要进入危险区域。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区域的商店很多。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上红色的区域是公园。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这个区域工作了五年。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面是儿童活动区域，请慢行。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市分成了三个区域。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟区域在楼外面。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们参观了实验区域。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "區域", "label": "繁体"}], "register": "中性", "sense_fingerprint": "区域：有一定范围的空间或地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f024bdf7-0d89-40d8-a324-f9e3513e83de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11227, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人口", "is_correct": false, "explanation": "语义：人口指一地的人数，不是可以停车的地方，「这个人口不能停车」说不通。"}, {"text": "区域", "is_correct": true, "explanation": "区域指一定范围的空间，「这个区域」指可以划为禁停范围的地方，与「不能停车」相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听觉信息，不指空间，「这个声音不能停车」说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，不是空间，「这个颜色不能停车」说不通。"}], "explanations": {"人口": "语义：人口指一地的人数，不是可以停车的地方，「这个人口不能停车」说不通。", "区域": "区域指一定范围的空间，「这个区域」指可以划为禁停范围的地方，与「不能停车」相符。", "声音": "语义：声音是听觉信息，不指空间，「这个声音不能停车」说不通。", "颜色": "语义：颜色是视觉属性，不是空间，「这个颜色不能停车」说不通。"}, "sentence_index": 0, "correct_answer": "区域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇作文的区域太少，只写了一段。", "explanation": "这里应该用〈字数〉。区域指空间或地方，作文篇幅多少要用字数，不能说「区域太少」。"}, {"text": "他在数学区域发表过很多论文。", "explanation": "这里应该用〈领域〉。区域指空间或地方，专业研究的范围要用领域，不能说「在数学区域」。"}, {"text": "这只区域的商店很多。", "explanation": "量词错误：「只」用于动物等，不用于区域，应说「这个区域」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气指气象状况，不指供儿童活动的场所，「儿童活动天气」说不通。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事是叙述性的作品，不指可以慢行的路段，句子语义不通。"}, {"text": "区域", "is_correct": true, "explanation": "区域指一定范围的地方，前方是儿童活动的范围，所以要慢行，与语境相符。"}, {"text": "课程", "is_correct": false, "explanation": "语义：课程指教学内容或学习安排，不指路段，「前面是儿童活动课程」说不通。"}], "explanations": {"天气": "语义：天气指气象状况，不指供儿童活动的场所，「儿童活动天气」说不通。", "故事": "语义：故事是叙述性的作品，不指可以慢行的路段，句子语义不通。", "区域": "区域指一定范围的地方，前方是儿童活动的范围，所以要慢行，与语境相符。", "课程": "语义：课程指教学内容或学习安排，不指路段，「前面是儿童活动课程」说不通。"}, "sentence_index": 6, "correct_answer": "区域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这学期的区域很多，我每天都很忙。", "explanation": "这里应该用〈课程〉。区域指空间范围，说学习内容的数量要用课程。"}, {"text": "我们的午饭区域是十二点。", "explanation": "这里应该用〈时间〉。区域指空间或地方，说几点要用时间，不能说「午饭区域是十二点」。"}, {"text": "他在公司担任一个重要区域。", "explanation": "这里应该用〈职务〉。担任的是职务、职位，区域指空间，不能说「担任区域」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府在河边划定了一把禁烟区域。", "corrected_sentence": "政府在河边划定了一个禁烟区域。", "error_description": "量词错误：「区域」不能用「把」（「把」用于有柄或可握的东西），应说「一个禁烟区域」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校划分了两运动区域。", "corrected_sentence": "学校划分了两个运动区域。", "error_description": "量词缺失：数词「两」后面要加量词，应说「两个运动区域」，不能直接说「两运动区域」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
