INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11230, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将热量散发出去，使物体温度降低。", "primary_collocate": null, "pronunciation": "sàn rè", "ipa": "san˥˩ ʐɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这种机制类似于计算机的散热系统，在处理器过热时启动风扇以维持最佳运行状态。", "target_word": "散热", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "夏天手机用久了要散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里的风扇是用来散热的。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间窗户小，不好散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗太热的时候会张嘴散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔记本放在桌上，散热会更快。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器散热很好，不会发烫。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开风扇给电脑散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属散热比木头快。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天穿浅色衣服，身体更容易散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "散热器", "label": "复合"}, {"form": "散熱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "散热：把热量散发出去，使物体温度降低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f024bdf7-0d89-40d8-a324-f9e3513e83de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加热", "is_correct": false, "explanation": "语义：加热是使物体升温，与「处理器过热时启动风扇」的降温功能相反。"}, {"text": "保温", "is_correct": false, "explanation": "语义：保温是防止热量散失，与「过热时启动风扇」的降温功能矛盾。"}, {"text": "散热", "is_correct": true, "explanation": "散热指把热量散发出去，与「处理器过热时启动风扇以降温」的功能一致。"}, {"text": "发热", "is_correct": false, "explanation": "搭配：「发热系统」不是常用说法，系统多指散热、冷却类功能，与「计算机的……系统」搭配不当。"}], "explanations": {"加热": "语义：加热是使物体升温，与「处理器过热时启动风扇」的降温功能相反。", "保温": "语义：保温是防止热量散失，与「过热时启动风扇」的降温功能矛盾。", "散热": "散热指把热量散发出去，与「处理器过热时启动风扇以降温」的功能一致。", "发热": "搭配：「发热系统」不是常用说法，系统多指散热、冷却类功能，与「计算机的……系统」搭配不当。"}, "sentence_index": 0, "correct_answer": "散热"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的旋律慢慢散热了。", "explanation": "这里应该用〈飘荡〉。旋律在空中回荡要说飘荡，散热指热量散发，不能用于声音。"}, {"text": "食物在胃里需要慢慢散热，才能被吸收。", "explanation": "这里应该用〈消化〉。散热指热量散发、温度降低，食物在胃里的分解要用消化。"}, {"text": "雾气慢慢散热。", "explanation": "这里应该用〈消散〉。消散指雾气、烟等逐渐散去，不指热量散发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冒烟", "is_correct": false, "explanation": "语义：冒烟是产生烟雾，与「很好，不会发烫」的语境矛盾。"}, {"text": "通电", "is_correct": false, "explanation": "搭配：「通电」指接通电源，不能用「很好」评价其性能，与句子语境不合。"}, {"text": "散热", "is_correct": true, "explanation": "散热指把热量散发出去，「散热很好，不会发烫」描述机器的散热性能，与语境相符。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：点燃是使东西燃烧，与「不会发烫」的语境矛盾。"}], "explanations": {"冒烟": "语义：冒烟是产生烟雾，与「很好，不会发烫」的语境矛盾。", "通电": "搭配：「通电」指接通电源，不能用「很好」评价其性能，与句子语境不合。", "散热": "散热指把热量散发出去，「散热很好，不会发烫」描述机器的散热性能，与语境相符。", "点燃": "语义：点燃是使东西燃烧，与「不会发烫」的语境矛盾。"}, "sentence_index": 6, "correct_answer": "散热"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花园里散热着阵阵花香。", "explanation": "这里应该用〈散发〉。散发指气味等向外发出，与热量无关，不能用「散热」。"}, {"text": "湖面上的笑声慢慢散热了。", "explanation": "这里应该用〈散去〉。笑声向四周消失要说散去，散热指热量散发，不能用于声音。"}, {"text": "人群很快散热了。", "explanation": "这里应该用〈散开〉。散开指人群离开聚集的位置，不指热量散发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电脑需要尽快散热地。", "corrected_sentence": "这台电脑需要尽快散热。", "error_description": "结构错误：“散热”是动词，后面不能加状语标记“地”，“地”只能放在动词前面修饰动作，应说“尽快散热”，不说“散热地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冰箱后面要留一点空间散热热量。", "corrected_sentence": "冰箱后面要留一点空间散热。", "error_description": "结构错误：「散热」是动宾式，本身已含宾语「热」，后面不能再带「热量」作宾语，应说「留一点空间散热」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
