INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11232, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "温度超过正常或合适的范围。", "primary_collocate": null, "pronunciation": "guò rè", "ipa": "kuo˥˩ ʐɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这种机制类似于计算机的散热系统，在处理器过热时启动风扇以维持最佳运行状态。", "target_word": "过热", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "电脑用久了，处理器会过热。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器过热了，要马上关掉。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天手机放在车里容易过热。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发动机过热时，车会自己停下。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池过热很危险，别再充电了。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑过热了，所以风扇转得很响。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么我的手机总是过热？", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器过热会坏，要放在通风的地方。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔记本玩游戏时很容易过热。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过热了", "label": "体标"}, {"form": "過熱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机器或设备温度高于正常范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f024bdf7-0d89-40d8-a324-f9e3513e83de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷却", "is_correct": false, "explanation": "语义：处理器冷却后不需要风扇加速，与“过热时启动风扇”的语境相反。"}, {"text": "停机", "is_correct": false, "explanation": "语义：处理器停机后不再运行，“维持最佳运行状态”的前提就不成立。"}, {"text": "过热", "is_correct": true, "explanation": "过热：温度超过正常范围，此时启动风扇可以帮助散热。"}, {"text": "损坏", "is_correct": false, "explanation": "搭配：“损坏”与句中“维持最佳运行状态”的目标相矛盾，不能用于此处。"}], "explanations": {"冷却": "语义：处理器冷却后不需要风扇加速，与“过热时启动风扇”的语境相反。", "停机": "语义：处理器停机后不再运行，“维持最佳运行状态”的前提就不成立。", "过热": "过热：温度超过正常范围，此时启动风扇可以帮助散热。", "损坏": "搭配：“损坏”与句中“维持最佳运行状态”的目标相矛盾，不能用于此处。"}, "sentence_index": 0, "correct_answer": "过热"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子过热了，要交额外的费用。", "explanation": "这里应该用〈超重〉。箱子超出重量要说超重，“过热”只说温度超过正常范围。"}, {"text": "这批蔬菜的农药过热了，不能卖。", "explanation": "这里应该用〈超标〉。含量超出标准要说超标，农药没有温度，不能说过热。"}, {"text": "他的血压过热了，需要去医院。", "explanation": "这里应该用〈升高〉。血压是数值，要说升高，“过热”只用于温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关机", "is_correct": false, "explanation": "搭配：关机后风扇不再转动，与“转得很响”不搭配。"}, {"text": "静音", "is_correct": false, "explanation": "语义：“静音”与“风扇转得很响”正好相反，句意矛盾。"}, {"text": "停电", "is_correct": false, "explanation": "语义：停电后风扇不会转，“所以风扇转得很响”说不通。"}, {"text": "过热", "is_correct": true, "explanation": "过热：温度超过正常范围，风扇因此加速转动，声音变响。"}], "explanations": {"关机": "搭配：关机后风扇不再转动，与“转得很响”不搭配。", "静音": "语义：“静音”与“风扇转得很响”正好相反，句意矛盾。", "停电": "语义：停电后风扇不会转，“所以风扇转得很响”说不通。", "过热": "过热：温度超过正常范围，风扇因此加速转动，声音变响。"}, "sentence_index": 6, "correct_answer": "过热"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段假期过热了，大家都很忙。", "explanation": "“过热”只说物体或设备的温度超过正常范围，假期没有温度，句中不能这样用。"}, {"text": "这道题的答案过热了，老师很满意。", "explanation": "答案是抽象的内容，不会发热，“过热”不能用来形容它。"}, {"text": "他的成绩过热了，老师很惊讶。", "explanation": "成绩是数字，不谈冷热，“过热”用于说设备或物体的温度，这里用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "手机放在车里，被过热了。", "corrected_sentence": "手机放在车里，过热了。", "error_description": "结构错误：「过热」是不及物的，不能用「被」，应说「过热了」，不能说「被过热了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器刚刚过热了着，所以自动关了机。", "corrected_sentence": "这台机器刚刚过热了，所以自动关了机。", "error_description": "体标错误：“过热”后用“了”，不能再加“着”，应说“过热了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
