INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11234, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "风扇是一种利用电动机带动叶片旋转，从而产生气流，用于通风降温的电器设备。", "primary_collocate": null, "pronunciation": "fēng shàn", "ipa": "fɤŋ˥ ʂan˥˩", "syllable_count": 2, "sentences": [{"text": "这种机制类似于计算机的散热系统，在处理器过热时启动风扇以维持最佳运行状态。", "target_word": "风扇", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "电脑里的风扇可以给处理器降温。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风扇坏了，电脑很快就会过热。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台风扇由电动机带动叶片。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机箱里装了两个风扇。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风扇转得太慢，热气出不去。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请定期清理电脑里的风扇灰尘。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风扇会把热空气吹出机箱。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务器的风扇声音很大。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了一个更安静的风扇。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "电风扇", "label": "复合"}, {"form": "風扇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电动机带动叶片、用于设备通风降温的装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f024bdf7-0d89-40d8-a324-f9e3513e83de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风扇", "is_correct": true, "explanation": "“风扇”能在处理器过热时启动，帮助散热，与句意相符。"}, {"text": "键盘", "is_correct": false, "explanation": "语义：键盘不能降温，启动它无法维持处理器的散热状态。"}, {"text": "硬盘", "is_correct": false, "explanation": "语义：硬盘不负责散热，启动它不能解决处理器过热的问题。"}, {"text": "电池", "is_correct": false, "explanation": "搭配：“启动”多用于设备，电池一般说“充电”或“供电”，不说“启动电池”。"}], "explanations": {"风扇": "“风扇”能在处理器过热时启动，帮助散热，与句意相符。", "键盘": "语义：键盘不能降温，启动它无法维持处理器的散热状态。", "硬盘": "语义：硬盘不负责散热，启动它不能解决处理器过热的问题。", "电池": "搭配：“启动”多用于设备，电池一般说“充电”或“供电”，不说“启动电池”。"}, "sentence_index": 0, "correct_answer": "风扇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用风扇吸地毯上的灰尘，很方便。", "explanation": "这里应该用〈吸尘器〉。风扇只能吹风，不能把灰尘吸走；吸灰尘要用吸尘器。"}, {"text": "天太黑了，快把风扇打开，好看清楚。", "explanation": "这里应该用〈电灯〉。风扇只能吹风，不能照明；要看清楚得开电灯。"}, {"text": "这台加热器能让房间变暖，这台风扇也能。", "explanation": "这里应该用〈暖气〉。风扇只能吹出气流，不能让房间变暖；让房间变暖要用暖气，而不是风扇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风扇", "is_correct": true, "explanation": "“风扇”是电脑里会积灰的部件，与“电脑里的”相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不在电脑里，与“电脑里的”矛盾。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调不装在电脑里，与句中的“电脑里的”不符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不在电脑里，与“电脑里的”矛盾，句意不通。"}], "explanations": {"风扇": "“风扇”是电脑里会积灰的部件，与“电脑里的”相符。", "冰箱": "语义：冰箱不在电脑里，与“电脑里的”矛盾。", "空调": "语义：空调不装在电脑里，与句中的“电脑里的”不符。", "蛋糕": "语义：蛋糕不在电脑里，与“电脑里的”矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "风扇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把风扇的温度调到二十六度，屋里很凉快。", "explanation": "这里应该用〈空调〉。风扇没有温度设置，调温度要用空调。"}, {"text": "风扇能把食物冷藏，很省电。", "explanation": "这里应该用〈冰箱〉。风扇只能吹风，不能冷藏食物；冷藏要用冰箱。"}, {"text": "这台风扇能烧开水，烧水很快。", "explanation": "这里应该用〈电热水壶〉。风扇吹风不能烧水，烧开水要用电热水壶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条风扇声音很小。", "corrected_sentence": "这台风扇声音很小。", "error_description": "量词错误：风扇是电器，应用量词“台”（或“个”），“条”用于细长的东西，不能用于风扇。错误形式“这条风扇”应改为“这台风扇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张风扇坏了，要换一台。", "corrected_sentence": "这台风扇坏了，要换一台。", "error_description": "量词错误：风扇应用量词“台”，“张”用于平面的东西，如纸、桌子，不能用于风扇。错误形式“这张风扇”应改为“这台风扇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
