INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11237, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指可以通行的道路或途径。", "primary_collocate": null, "pronunciation": "tōng lù", "ipa": "tʰʊŋ˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "神经学研究进一步揭示了打哈欠的复杂神经通路。", "target_word": "通路", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "更引人深思的是，某些强效抗精神病药物因影响多巴胺通路，常以“病理性哈欠”作为副作用，每日可达数十次之多，这反而为研究其神经机制提供了临床窗口。", "target_word": "通路", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "科学家找到了大脑里的一条新通路。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条神经通路和疼痛有关。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药物会影响大脑里的通路，让人想睡觉。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，这条通路出了问题，手就不能动。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们为两国贸易打开了新的通路。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "信号沿着这条通路传到大脑。", "target_word": "通路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们画出这条神经通路。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究人员想知道，信息怎样走完整条通路。", "target_word": "通路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "书面", "sense_fingerprint": "神经、信号或交流等抽象的通行途径", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72cbc8a3-f65d-4a49-8ed5-26d393ab6de6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11237, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通路", "is_correct": true, "explanation": "通路（tōng lù）：可以通行的路径，此处指神经传导的通路。"}, {"text": "同路", "is_correct": false, "explanation": "同路（tóng lù）与通路（tōng lù）第一音节声调不同（第二声），意思是同行、同道。"}, {"text": "东路", "is_correct": false, "explanation": "东路（dōng lù）与通路（tōng lù）声母不同（d 与 t），意思是东边的道路。"}, {"text": "铜炉", "is_correct": false, "explanation": "铜炉（tóng lú）与通路（tōng lù）两个音节的声调都不同，意思是铜制的炉子。"}], "explanations": {"通路": "通路（tōng lù）：可以通行的路径，此处指神经传导的通路。", "同路": "同路（tóng lù）与通路（tōng lù）第一音节声调不同（第二声），意思是同行、同道。", "东路": "东路（dōng lù）与通路（tōng lù）声母不同（d 与 t），意思是东边的道路。", "铜炉": "铜炉（tóng lú）与通路（tōng lù）两个音节的声调都不同，意思是铜制的炉子。"}, "sentence_index": null, "correct_answer": "通路"}, "level_3": {"options": [{"text": "通路", "is_correct": true, "explanation": "通路：指神经中传导信号的路径，与“复杂神经”搭配，符合句意。"}, {"text": "乐章", "is_correct": false, "explanation": "语义：乐章是音乐的段落，与神经系统无关，不能填入“复杂神经”之后。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种植花草的地方，不是神经结构。"}, {"text": "菜谱", "is_correct": false, "explanation": "搭配：“神经”后接的是结构类名词，“菜谱”不能与之组合。"}], "explanations": {"通路": "通路：指神经中传导信号的路径，与“复杂神经”搭配，符合句意。", "乐章": "语义：乐章是音乐的段落，与神经系统无关，不能填入“复杂神经”之后。", "花园": "语义：花园是种植花草的地方，不是神经结构。", "菜谱": "搭配：“神经”后接的是结构类名词，“菜谱”不能与之组合。"}, "sentence_index": 0, "correct_answer": "通路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用这根通路给手机充电。", "explanation": "这里应该用〈充电线〉。给手机供电的线要说充电线，通路指可以通行的路径。"}, {"text": "他凭这张通路进了大楼。", "explanation": "这里应该用〈通行证〉。“通路”指可以通行的路径，不是证件；凭证件进门要说“通行证”。"}, {"text": "我们乘通路下楼去了。", "explanation": "这里应该用〈电梯〉。乘坐升降设备上下楼要说电梯，通路指可以通行的路径。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11237, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通路", "is_correct": true, "explanation": "通路：贸易往来的途径，与“打开了新的”搭配，符合句意。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：疾病与两国贸易无关，不能被“打开”为新的途径。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是致病的微生物，与贸易往来毫无关系。"}, {"text": "花瓣", "is_correct": false, "explanation": "搭配：“打开”后接“花瓣”指花开，与“为两国贸易”组合不搭。"}], "explanations": {"通路": "通路：贸易往来的途径，与“打开了新的”搭配，符合句意。", "疾病": "语义：疾病与两国贸易无关，不能被“打开”为新的途径。", "病毒": "语义：病毒是致病的微生物，与贸易往来毫无关系。", "花瓣": "搭配：“打开”后接“花瓣”指花开，与“为两国贸易”组合不搭。"}, "sentence_index": 6, "correct_answer": "通路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的通路很清楚，讲得很有条理。", "explanation": "这里应该用〈思路〉。“通路”指路径，说话或想法有条理要说“思路清楚”。"}, {"text": "我们去通路洗手吧。", "explanation": "这里应该用〈洗手间〉。“通路”指可以通行的路，不是能洗手的地方；去厕所要说“洗手间”。"}, {"text": "他把钱存进了通路。", "explanation": "这里应该用〈账户〉。“通路”指可以通行的路，不能存钱；存钱要用银行账户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11237, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究人员画出了一只神经通路的示意图。", "corrected_sentence": "研究人员画出了一条神经通路的示意图。", "error_description": "量词错误：“通路”是条状的路径，应说“一条神经通路”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11237, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生在图上标出了这只神经通路。", "corrected_sentence": "医生在图上标出了这条神经通路。", "error_description": "量词错误：“通路”是条状的路径，应说“这条神经通路”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
